        /// <summary>自检用（B3）：这一格的**场上视图**现在是不是被藏起来了（飞行期间 = true）。
        /// 判据 = 「整棵子树里一个 enabled 的 `Renderer` 都没有」（我们只关渲染器、不关 GameObject ——
        /// 见 `HideBoardViewForFlight` 的 doc），⛔ 不是 `activeSelf`。</summary>
        public bool AiDeployBoardViewHiddenForTest(int owner, int slot)
        {
            var views = owner == _me ? _myUnits : _foeUnits;
            CardView v;
            if (views == null || !views.TryGetValue(slot, out v) || v == null) return false;
            var rs = v.gameObject.GetComponentsInChildren<Renderer>(true);
            for (int i = 0; i < rs.Length; i++) if (rs[i] != null && rs[i].enabled) return false;
            return rs.Length > 0;
        }

        /// <summary>自检用（B3）：这一格**正在飞的那个 transform**（手牌卡背优先；否则场上视图；
        /// 都没在飞 = null）。断言位移时必须读它 —— ⛔ 别读 `FoeUnits[slot]`（手牌载体那一路它被隐藏着）。
        /// <para>🆕 2026-10-19（`W57`）：**0.4 s 交接之后落体换成了场上视图**（卡背已隐藏）⇒
        /// 过了交接就报场上视图（按 `_aiDeployHandedOff` 判，⛔ 别只看 `_aiDeployFlyingHand`）。</para>
        public Transform AiDeployFlightCarrierForTest(int owner, int slot)
        {
            int key = HpKey(owner, slot);
            ImageQuad q;
            if (_aiDeployFlyingHand.TryGetValue(key, out q) && q != null && !_aiDeployHandedOff.Contains(key))
                return q.transform;
            CardView v;
            if (_aiDeployFlying.TryGetValue(key, out v) && v != null) return v.transform;
            return null;
        }

        /// <summary>还没播的事件，按到点时刻排好（自检排查用：16 条里到底排了些什么）</summary>
        public string TimelineDump()
        {
            var sb = new System.Text.StringBuilder();
            for (int i = 0; i < _timeline.Count && i < 24; i++)
            {
                var e = _timeline[i].evt;
                // 🔴 **2026-10-22（`W64`）**：同族的空守卫（自检口）。cue 的 `evt` 恒 null，
                //   原来这里会抛 `NullReferenceException` —— 而它正是**排查真机问题时**要用的口，
                //   在最需要它的时候炸掉。空的那一条改印它自己的 cue 名（有的话）。
                //   判据 → `资料/普查产出_1022/W64_PendingExitFor空引用诊断.md` §①/§⑤。
                if (e == null)
                {
                    sb.Append("      @").Append(_timeline[i].at.ToString("F2")).Append(" cue");
                    if (!string.IsNullOrEmpty(_timeline[i].cueVfx)) sb.Append(' ').Append(_timeline[i].cueVfx);
                    sb.Append('\n');
                    continue;
                }
                sb.Append("      @").Append(_timeline[i].at.ToString("F2")).Append(' ').Append(e.Kind)
                  .Append(" P").Append(e.Player + 1).Append('@').Append(e.Slot);
                if (e.Kind == EvtKind.Attack) sb.Append(" →P").Append(e.TargetPlayer + 1).Append('@').Append(e.TargetSlot);
                if (e.Kind == EvtKind.Retaliation) sb.Append(" 反击→P").Append(e.TargetPlayer + 1).Append('@').Append(e.TargetSlot)
                                                    .Append(e.Ranged ? " 远程" : " 近战");
                if (!string.IsNullOrEmpty(e.CardId)) sb.Append(' ').Append(e.CardId);
                sb.Append('\n');
            }
            return sb.ToString();
        }

        /// <summary>
        /// 推进事件时间线。Play 模式由 `Update` 每帧推；**批处理没有帧循环**，
        /// 自检里由 `BattleScene.Step()` 显式推。
        /// </summary>
        public void AdvanceTimeline(float dt)
        {
            _clock += dt;

            // 结算面板的「开门」视频也吃这个 dt —— 它和事件时间线一样，
            // 真机靠 `Update`、批处理靠 `BattleScene.Step` 手动推（同一个泵，不另开一条路）
            if (_endPanel != null) _endPanel.Advance(dt);
            // 单位语音条的气泡停留时间也走这个泵（同一个理由）
            if (_unitChat != null) _unitChat.Advance(dt);
            // 🆕 2026-10-16（`T01`）：**进战斗黑场的 1.25 s 淡出**也走这个泵 ——
            //   原版是 DOTween 的 `DOFade`（帧驱动）；批处理没有帧循环 ⇒ 不推的话它**永远不褪**。
            TickLoadingFade(dt);

            // 🆕 2026-10-20（战斗线 `T12`）：**开局运镜**也走这个泵 —— 原版是 `Animation` 组件自己按帧跑，
            //   批处理没有帧循环 ⇒ 不推的话相机永远停在起点（同上面黑场那一条的理由）。
            //   ⚠️ 位置紧挨黑场：原版 `StartBattleSequence` 就是「先 `LoadingFade`、紧接着 `cameraAnim.Play()`」，
            //      两条同帧起播 —— 前 1.25 s 的飞入被黑场盖住，观众看到的是后半段飞入 + 黑场淡出。
            if (_cameraIntro != null) _cameraIntro.Tick(dt);

            // 🆕 2026-10-16（`T06` · 战斗 BGM）：**三条强度分轨的查档与淡变**也走这个泵
            //   （原版在 `BattleMusicManager.Update` 里跑；批处理没有帧循环 ⇒ 不推它 BGM 永远停在开场那一档）。
            //   ⚠️ 判据 = `min(双方督军【当前生命】)`，**每帧**传进去（查档节流在 `BattleMusic.Tick` 里）。
            if (_music != null) _music.Tick(dt, BattleMusic.HeroMinHealth(Ctx));

            // 🆕 2026-09-29：准星的淡入淡出也走这个泵（原版在 `TargetReticleController.Update` 里，
            //   批处理没有帧循环 ⇒ 不推的话准星会卡在半透明上，截图与断言都不对）。
            if (reticle != null) reticle.TickFade(dt);

            // 🆕 2026-09-29：**瞄准时的「抬手/后撤」**也走这个泵（原版在 `CardScript.Update` 里跑，
            //   只有 `cardState == inPlayAminingAttack` 那一支）。同一条理由：批处理没有帧循环。
            TickTargetingLean(dt);

            // 🆕 2026-10-19（战斗线 B1 · 偏差 6）：**技能拍的「起→终位移」**也走这个泵 ——
            //   原版在 `CardAnimController.Update` 里按 deltaTime 推（`CardAnimController__Update.c`）；
            //   批处理没有帧循环 ⇒ 挂错地方就成了「只在一种环境下活」的实现（同上面那几条）。
            TickAbilityVfxMoves(dt);

            // 🆕 2026-10-19（T05 · `A2081`）：**飞行单位的抬升与上下浮动**也走这个泵 ——
            //   原版 `FlyingCardController` 是 `MonoBehaviour`、靠 `Update` 每帧推；批处理没有帧循环
            //   ⇒ 挂 `Update` 就成了「只在一种环境下活」的实现（同上面那几条，本线准则 §六·6）。
            TickFlyingUnits(dt);

            // 🆕 2026-10-23（`W63` 收口）：**卡体动画层**也走这个泵 —— 判据/口径同上面那一条
            //   （原版 `Card3DAnimationController` 是 `MonoBehaviour`，批处理没有帧循环）。
            //   ⚠️ 必须排在 `TickFlyingUnits` **之后**：这一层会 `ToggleFlying` 去改飞行状态机，
            //   同一帧里先让飞行那台走一步、再让动画层决定要不要把它按下去。
            TickCardAnims(dt);

            // 🆕 2026-09-29：**AI 那条准星演出**也走这个泵（原版靠 `TargetReticleController` 的
            //    `DOMove` 帧循环推进；批处理没有帧循环 ⇒ 不推就永远演不完、AI 回合会**卡死**）。
            TickAiTargetingAnim(dt);

            // 🆕 2026-10-18（A939）：**战后脚本**（`onVictory` 那 13 条聊天/电台）也走这个泵 ——
            //  同 `TickIntroMonologue` 的理由：真机靠 `Update`、批处理靠 `BattleScene.Step` 显式推。
            TickPostBattleScript(dt);

            // 🆕 2026-10-15（`A2109` 第 1 条）：**提示条**（原版 `BattleTipController` 那条队列）也走这个泵 ——
            //   同上，真机靠 `Update`、批处理靠 `Step` 推；挂错地方就是个只在一种环境下活的实现。
            TickTipBanner(dt);

            // 🆕 2026-09-18：**开局独白也走这个泵**。            // 🔴 **不能挂在 `Update` 里** —— 批处理**没有帧循环**，`Update` 根本不跑，
            //    而自检是靠 `BattleScene.Step → AdvanceTimeline` 推的（`Step` 的注释里写着这个坑）。
            //    挂在 `Update` 里的话，真包能跑、**自检永远推不动**，那就是个只在一种环境下活的实现。
            // ⚠️ 必须排在 `_unitChat.Advance` **之后** —— 它判「上一条播完没有」靠的就是气泡的最新状态。
            TickIntroMonologue();

            // 🆕 2026-09-30（§25）：**进攻卡的 reveal 动画**也走这个泵（原版那条协程靠 Unity 的
            //   `yield WaitForSeconds` 自己走；批处理没有帧循环 ⇒ 不推就永远走不完、
            //   `ApplyOffensiveEnvOnce` 一辈子不会被调到）。同 `TickIntroMonologue` 的理由与位置。
            TickOffensiveReveal(dt);

            // 🆕 2026-09-18：`ChatPopup` 的淡入淡出 + `ChatButton` 的 4 秒冷却。
            //    🔴 **和独白同一条理由挂在这里**：批处理没有帧循环，`Update` 不跑，
            //       挂在 `Update` 里就成了「真包能跑、自检永远推不动」的实现。
            if (_chatPopup != null) _chatPopup.Advance(dt);
            if (_chatCooldown > 0f) _chatCooldown = Mathf.Max(0f, _chatCooldown - dt);

            // 🆕 2026-10-18（§8b · 2b）：**错误横幅**（原版 `UI Error Message Controller` 那三条 tween）
            //   也走这个泵 —— 同 `TickOvertime` 的理由：批处理没有帧循环，挂在 `Update` 里就
            //   「真包能跑、自检永远推不动」。三段时长（0.15 / 2.0 / 0.25）在 `ErrorMessageBanner` 里。
            // 🔴 2026-10-20（W57 · `T09` 步骤 A3-a）现核：**这一句就是横幅唯一的「关闭」路径**。
            //   原版没有点击关闭（`Background` / TMP 两层 `m_RaycastTarget = 0`，模板上也没有任何 Pointer 接口；
            //   判据 → `ErrorMessageBanner.cs` 文件头 ⑫）⇒ ⛔ 别给它挂 `Button` / `BattleHudButton`，
            //   也别在这里加命中/沿。要加就是**原版没有的新行为**（A3-a 报告 §三）。
            if (_errorBanner != null) _errorBanner.Advance(dt);

            // ⚠️ 取**「到点的事件里最早的那条」**，而不是只看队头：
            //    队头要是排在未来（上一局的残留、或者新一批事件的起始时刻比待播的那条还早），
            //    后面那些**早就该播**的会一直堵着（2026-09-13 撞到过，见 `Begin` 里那段注释）。
            //    同时到点的按「先来先播」——扫的时候用严格小于，所以并列时保留下标小的那条。
            //    条数很少（几十条），线性扫足够。
            int guard = 0;
            while (guard++ < 256)
            {
                int best = -1;
                for (int i = 0; i < _timeline.Count; i++)
                    if (_timeline[i].at <= _clock && (best < 0 || _timeline[i].at < _timeline[best].at))
                        best = i;
                if (best < 0) break;

                var p = _timeline[best];
                _timeline.RemoveAt(best);
                // 🆕 2026-10-19（B6）：**只补播一件特效的 cue**（多候选取候选按 `t` 错开）——
                //   它**不是事件**：语音/音效/手感/血账/视图同步那些事件级副作用**一件都不跑**
                //   （它们已经在事件那一拍跑过了）。见 `PendingSignal.cueVfx` 的 doc。
                if (!string.IsNullOrEmpty(p.cueVfx))
                {
                    // 🆕 2026-10-23（`新账-82④`）：走共用口（到点把**排期时**的 AnimFX 卡上下文换回去）
                    FireCueVfx(p);
                    continue;
                }
                // 🆕 2026-10-21（W61 第 1 批）：**到点跑一次的回调 cue**（命中帧那一拍 / 攻击 VFX 的延迟实例化）。
                //   与 `cueVfx` 同一个口径：它不是事件、不跑事件级副作用。
                if (p.cueAction != null) { p.cueAction(); continue; }
                PlaySignal(p.evt, p.drawFromEnd, p.points, p.pointIndex,
                           p.beat, p.beatVfx, p.beatSp, p.beatEp, p.beatPt, p.beatTail,
                           p.beatMove, p.beatOtv, p.beatTs, p.beatTm, p.beatEase,
                           p.cueUnitDamage, p.cueMeleeHit, p.beatData, p.hitOfAttack, p.hitAmount,
                           p.collectDeath, p.hitOfCounter, p.skillAnimAt, p.attackEvent);
            }

            // 🆕 2026-10-19（偏差 1 的残余④）：**登场那一拍到了 ⇒ 把视图补建出来**。
            //   ⚠️ 放在播完这一帧的**循环之后**：`PlaySignal` 里不直接 `SyncBoard`（那会在遍历时间线
            //     的过程中改视图表）；这里一次性补两边的棋盘。
            if (_syncAfterDeploy)
            {
                _syncAfterDeploy = false;
                SyncBoard(_me, _myUnits, true);
                SyncBoard(1 - _me, _foeUnits, false);
            }

            // 🆕 2026-10-19（战斗线 W 第 2 条）：每帧收一次闸 —— 判据与「为什么不能只看队列空」
            //   全在 `TickBlockingWindow` 的 doc。
            TickBlockingWindow();

            // 🔴 **2026-10-24（执行代理 `W1` · `R2` §7·①落点 3）：回放「推下一手」挂在这个泵的末尾。**
            //   为什么是这里：本方法是**唯一**的「时间真的走了一帧」的口（真机 `Update` / 批处理
            //   `BattleScene.Step` 都到这儿）⇒ 回放的节奏天然与画面同步。
            //   ⚠️ 必须排在 `_syncAfterDeploy` 那一段**之后**：否则「补建视图」会抢在下一手落地之前/之后错位。
            TickReplayPump();
        }

        // ==================================================================
        //  🆕 2026-10-19（战斗线 W）：**原版 `BattleManager.WaitingForBlockingAction` 的等价闸**
        // ==================================================================
        //  判据（`d:/2/tools/decomp_full/`，逐处读过）：
        //   · `BattleManager__WaitingForBlockingAction.c` —— 原版问的是「动作队列里还有没有阻塞型动作」
        //     （它扫 `+0x350 / +0x358 / +0x368` 三个动作表）。消费它的**五处**：
        //     `BattleManager__CanPlayCard.c:72`（出牌）· `__EndTurnClick.c:47`（结束回合）·
        //     `__ExecuteActiveAbility.c:39`（主动技）· `__Update.c:1033,1060`（两条「确认攻击/技能」分支）。
        //   · `__EndTurnClick.c:47` 那道闸**在播 cue 之前**（闸内的 `if` 里才 `Play2D(EndTurnButton)`）
        //     ⇒ 被闸挡下的那一下**不出声**（我们照抄：静默 return）。
        //  我们这边没有「动作队列」—— 引擎是同步结算的 ⇒ **等价物 = 事件时间线还没演完**：
        //    「排进 `_timeline` 的事件一条都没剩」**且**「最后一条 cue 的时长也走完了」才放行。
        //  ⚠️ **只看「队列空」不够**：`AdvanceTimeline` 把条目弹出来只是**起播**，补间/粒子还在跑
        //     （`PlaySignal` 是 fire-and-forget）⇒ 必须再等一个 `EventTiming.DurationOf`。
        //  ⚠️ **安全阀** `BlockingMaxSeconds`：真卡住（事件表出 bug / 回放长时间暂停）时**不许把玩家锁死**；
        //     超时**出声**（本仓红线：不许静默失败）并放行。
        // ------------------------------------------------------------------

        /// <summary>开始/延长这一轮「演出未收尾」窗口。<paramref name="quietAt"/> = 这一批事件
        /// **最后一条 cue 的收尾时刻**（由 `PlaySignals` 按同一套 `EventTiming` 算出来）。</summary>
        void BeginBlockingWindow(float quietAt)
        {
            if (quietAt > _blockingQuietAt) _blockingQuietAt = quietAt;
            // 安全阀量的是「卡住多久」而不是「这一局动作链多长」⇒ 每来一批新事件就重新起算
            //（AI 连续出牌 / 教程脚本长链都可能远超 20 s，但那不是卡住）。
            _blockingSince = _clock;
            if (_blocking) return;
            _blocking = true;
        }

        /// <summary>每帧（`AdvanceTimeline` 末尾）收一次：队列空 **且** 最后一条 cue 走完 ⇒ 放行；
        /// 超过安全阀 ⇒ 出声并放行。</summary>
        void TickBlockingWindow()
        {
            if (!_blocking) return;
            if (_clock - _blockingSince > BlockingMaxSeconds)
            {
                Debug.LogWarning($"[Battle] `WaitingForBlockingAction` 连续拦了 {_clock - _blockingSince:F1} s"
                               + $"（> {BlockingMaxSeconds} s 安全阀）⇒ 放行 —— 排着 {_timeline.Count} 条、"
                               + $"最后一条的收尾时刻 {_blockingQuietAt:F2}（当前 {_clock:F2}）。"
                               + "这多半是事件表卡住 / 回放长时间暂停 —— 如实报出来，别静默锁死玩家。");
                _blocking = false;
                _blockingQuietAt = _clock;
                return;
            }
            if (_timeline.Count == 0 && _clock >= _blockingQuietAt) _blocking = false;
        }

        // ---- 第 1 条：血量「可见时刻」的账 --------------------------------------------------
        //
        //  根因（`资料/普查产出_1018/R_战斗表现链路对拍.md` 偏差 1）：引擎把一次动作**同步**算完
        //  （血已经是终值），`SyncBoard` 同一帧 `SetData` 就是终值 ⇒ 血条先跳、挨打动作后到。
        //  原版：`_ResolveMultiDamage…:136-168` 在**每个目标**的受击那一拍才改 HP。
        //
        //  我们的等价物 = **把「引擎已扣/已加、还没演到」的差值记在账上**：
        //   · 排时间线时 `NotePendingHp(e)` 记一笔（`Hit` 记 `+e.Amount` —— 那是**扣血前**发的
        //     `actual`，见 `RuleCore.ApplyDamage` / `EmitHit`；🆕 2026-10-20 `W58`：`Heal` 记
        //     **`−e.Amount`** —— 引擎已经加过血，要让画面先显示旧血）⇒ `SyncBoard` 把差值加回去 = **旧血**；
        //   · 事件轮到播的那一刻 `CompletePendingHpBeat(e)` 减掉这一笔并重刷视图 = **血量在受击/治疗帧才跳**
        //     （顺带 `CardView.SetData` 自己的 `CaptureStatChanges` 会在这一刻闪红 —— 正是原版
        //      `CardTextCountersController.DoColorChange` 的可见时刻）。
        //  ⚠️ **只对「排时间线这一刻还在场上」的单位记账**：阵亡单位的 `Board[slot]` 已是 null（它走
        //     `PendingExitFor` 的消散），血条随消散走，不打这条账。
        //  ⚠️ **身份守卫**：棋盘是「连续无洞」模型（插人/补位会挪格号），所以事件里的 `Slot` 可能已经
        //     换成了别人 ⇒ 用 `e.CardId`（= `UnitState.Name`，与 `EmitUnit` 同源）比一下，不符**不记账**
        //     （宁可让那一格的血早跳，也不要把别人的血算错 —— 静默算错比早跳糟）。
        //  🔴 **2026-10-19（B5）：账按【卡实例 id】记，且【第一判据 = `BattleEvent.InstanceId`】**（E12 已落）：
        //     · **记账**：事件自己带着实例号 ⇒ 直接记那一份（连「事件格号已经换过人」都认不错）；
        //     · **销账**：同样先看事件实例号 ⇒ 直接销那一份，再按它**现在**的格子刷卡面
        //       （旧口径按格号记 ⇒ 同名换格后旧血加到换上来那张卡上、被打那张永远停在旧值）。
        //     · `InstanceId == 0`（引擎没写 / 手工造的事件）才退回「(座位, 格号) + 名字」的旧口径 —— 如实保留。
        // ------------------------------------------------------------------

        /// <summary>排时间线时给「挨打/治疗」记一笔账（规则见上面那一段）。</summary>
        void NotePendingHp(BattleEvent e)
        {
            // 🆕 2026-10-20（`W58`）：**治疗也走这本账**（`EvtKind.Heal`，引擎已经加过血 ⇒ 记 **−实际量**，
            //   让 `SyncBoard` 先显示旧血，轮到那一拍才跳）。负数 `Hit` = 幸存者广播（不显示、
            //   原版是**立即**写血）⇒ **不记账**（否则幸存者的血会晚 0.75 s 才跳）。
            int delta;
            if (e == null) return;
            if (e.Kind == EvtKind.Heal)
            {
                if (e.Amount <= 0) return;
                delta = -e.Amount;
            }
            else if (e.Kind == EvtKind.Hit)
            {
                if (e.Amount <= 0) return;
                delta = e.Amount;
            }
            else return;
            if (Ctx == null || Ctx.Players == null) return;
            if (e.Player < 0 || e.Player >= Ctx.Players.Length) return;
            if (!BoardSpec.IsValid(e.Slot)) return;
            int id;
            string name;
            if (e.InstanceId != 0)
            {
                // 🔴 **第一判据 = E12 的实例号**（`BattleEvent.InstanceId`）：事件指向哪一份就记哪一份 ——
                //   连「记账那一刻事件格号已经换过人」都认不错（这正是格号口径拆不掉的错源）。
                id = e.InstanceId;
                int where;
                if (!TryFindInstanceSlot(e.Player, id, out where)) return;   // 那一份不在场（阵亡/回手）⇒ 不打账
                var at = Ctx.Players[e.Player].Board[where];
                name = at != null ? at.Name : e.CardId;
            }
            else
            {
                // 退路（`InstanceId == 0` = 引擎没写）：按 (座位, 格号) 找单位 —— 旧口径。
                // ⚠️ 同名换格 + 事件格号已过时时**仍可能认错人**；E12 的字段一到就不再走这里。
                var u = Ctx.Players[e.Player].Board[e.Slot];
                if (u == null) return;
                if (!string.IsNullOrEmpty(e.CardId) && u.Name != e.CardId) return;   // 那一格已经换人了
                if (u.Instance == null) return;
                id = u.Instance.Id;
                name = u.Name;
            }
            PendingHpEntry ent;
            if (!_pendingHp.TryGetValue(id, out ent))
                ent = new PendingHpEntry { owner = e.Player, name = name };
            ent.amount += delta;
            ent.owner = e.Player;
            ent.name = name;
            ent.slotAtNote = e.Slot;
            _pendingHp[id] = ent;
            int key = HpKey(e.Player, e.Slot);
            List<KeyValuePair<int, int>> q;
            if (!_pendingHpBySlot.TryGetValue(key, out q))
            {
                q = new List<KeyValuePair<int, int>>(2);
                _pendingHpBySlot[key] = q;
            }
            q.Add(new KeyValuePair<int, int>(id, delta));
            PendingHpProbe("note", e.Player, e.Slot, id, delta, name);
        }

        /// <summary>事件轮到播的那一刻：把这一笔从账上减掉、并按「剩下的账」重刷**那张牌现在那一格**的卡面。
        /// 这就是「血量在受击帧才跳」的落地那一句。
        /// <para>🔴 **2026-10-19（B5）**：**第一判据 = `e.InstanceId`**（E12 已把它写进事件）——
        /// 事件自己说「打的是哪一份」⇒ 直接销那一份的账、刷它**现在**那一格（同名换格也不会串）。
        /// `InstanceId == 0`（手工造的事件 / 引擎没写）才退回按 `(座位, 事件格号)` 的 **FIFO**，
        /// 再退到「当前站在这一格的实例 / 按记账格号 + 名字」—— 旧口径，如实保留。</para></summary>
        void CompletePendingHpBeat(BattleEvent e)
        {
            // 🆕 2026-10-20（`W58`）：与 `NotePendingHp` **同一对**判据 —— 治疗（`EvtKind.Heal`）
            // 记的是 **−实际量**；负数 `Hit`（幸存者广播）不进这本账。
            int delta;
            if (e == null) return;
            if (e.Kind == EvtKind.Heal)
            {
                if (e.Amount <= 0) return;
                delta = -e.Amount;
            }
            else if (e.Kind == EvtKind.Hit)
            {
                if (e.Amount <= 0) return;
                delta = e.Amount;
            }
            else return;
            int key = HpKey(e.Player, e.Slot);
            int id = 0, amount = delta;
            bool have = false;
            List<KeyValuePair<int, int>> q;
            if (e.InstanceId != 0)
            {
                // 🔴 主路径：事件自己带着实例号 ⇒ 不猜、不按格号对账。
                id = e.InstanceId;
                have = true;
                DropPendingHpQueueEntry(key, id);   // 同一笔在按槽的 FIFO 里也挂过 ⇒ 摘掉，别让退路再用它
            }
            else if (_pendingHpBySlot.TryGetValue(key, out q) && q != null && q.Count > 0)
            {
                id = q[0].Key;
                amount = q[0].Value;          // 用**记账时**那个金额（不是事件这次的）—— 两边本就同序同值
                q.RemoveAt(0);
                if (q.Count == 0) _pendingHpBySlot.Remove(key);
                have = true;
            }
            else
            {
                // 退路：这一格没有按槽记的队列（例如 `SyncBoard` 已经把它按新格号挪走 / 旧口径的账）
                if (Ctx == null || Ctx.Players == null) return;
                if (e.Player < 0 || e.Player >= Ctx.Players.Length || !BoardSpec.IsValid(e.Slot)) return;
                // 退路 ①：**现在站在这一格**的实例（旧口径）。⚠️ 换过人时这就是原口径 —— 宁可早跳，不串账。
                var cur = Ctx.Players[e.Player].Board[e.Slot];
                if (cur != null && cur.Instance != null && _pendingHp.ContainsKey(cur.Instance.Id))
                {
                    id = cur.Instance.Id;
                    have = true;
                }
                else
                {
                    // 退路 ②：队列被 `DropPendingHpForSlot` 按新格号挪走了 ⇒ 按「记账时的格号 + 名字」
                    //   把那一笔找回来（这时就该刷**它现在**那一格）。⛔ 这是退路，不是主路径。
                    foreach (var kv in _pendingHp)
                    {
                        if (kv.Value.owner != e.Player) continue;
                        if (kv.Value.slotAtNote != e.Slot) continue;
                        if (!string.IsNullOrEmpty(e.CardId) && kv.Value.name != e.CardId) continue;
                        id = kv.Key;
                        have = true;
                        break;
                    }
                }
            }
            if (have && e.InstanceId == 0 && !_pendingHp.ContainsKey(id))
            {
                // 退路找出来的那一份账已经不在了（被清理过）⇒ 退回「现在站在这一格的实例」。
                // ⚠️ **主路径（事件自带实例号）不走这里** —— 事件已经指名道姓，账没了就是没了
                //   （多半是那一下把它打死了），⛔ 别去扣别人头上的账。
                have = false;
                amount = delta;
                if (Ctx != null && Ctx.Players != null && e.Player >= 0 && e.Player < Ctx.Players.Length
                    && BoardSpec.IsValid(e.Slot))
                {
                    var cur2 = Ctx.Players[e.Player].Board[e.Slot];
                    if (cur2 != null && cur2.Instance != null) { id = cur2.Instance.Id; have = true; }
                }
            }
            if (!have) return;
            PendingHpEntry ent;
            if (!_pendingHp.TryGetValue(id, out ent)) return;
            ent.amount -= amount;
            int owner = ent.owner;
            if (ent.amount <= 0) _pendingHp.Remove(id);   // ≤0：减到 0 正常；<0 说明对账有偏差，同样收掉（别让它变负血）
            else _pendingHp[id] = ent;
            PendingHpProbe("complete", owner, e.Slot, id, -amount, ent.name);
            RefreshInstanceData(owner, id);
        }

        /// <summary>按实例 id 找它**现在**在哪一格并刷那一格的卡面（账跟着牌走，不跟格号走）。
        /// 不在场上 / 视图不在 ⇒ 什么都不做（⛔ 不新建视图）。</summary>
        void RefreshInstanceData(int owner, int instanceId)
        {
            int slot;
            if (!TryFindInstanceSlot(owner, instanceId, out slot)) return;
            RefreshUnitData(owner, slot);
        }

        /// <summary>某个实例现在在哪个格（扫该玩家的棋盘；不在场 = false）。</summary>
        bool TryFindInstanceSlot(int owner, int instanceId, out int slot)
        {
            slot = -1;
            if (Ctx == null || Ctx.Players == null) return false;
            if (owner < 0 || owner >= Ctx.Players.Length) return false;
            var board = Ctx.Players[owner].Board;
            if (board == null) return false;
            for (int s = 0; s < board.Length; s++)
            {
                var u = board[s];
                if (u != null && u.Instance != null && u.Instance.Id == instanceId) { slot = s; return true; }
            }
            return false;
        }

        /// <summary>主路径销账时（`e.InstanceId` 直接给出实例）把同一笔在按槽 FIFO 里的那条也摘掉 ——
        /// 不摘的话退路以后会拿它再销一次（同一笔被减两遍 ⇒ 血少算）。只摘**第一条同实例**的。</summary>
        void DropPendingHpQueueEntry(int key, int id)
        {
            List<KeyValuePair<int, int>> q;
            if (!_pendingHpBySlot.TryGetValue(key, out q) || q == null) return;
            for (int i = 0; i < q.Count; i++)
            {
                if (q[i].Key != id) continue;
                q.RemoveAt(i);
                break;
            }
            if (q.Count == 0) _pendingHpBySlot.Remove(key);
        }

        /// <summary>格位空了 ⇒ 把「按格记的 FIFO」摘掉。账**跟着实例走**：
        ///   · 那个实例已经不在场（阵亡 / 回手）⇒ 账作废（它不会再演到这一拍，留着会让血永远停在旧值）；
        ///   · 它挪到别的格去了 ⇒ 把那一笔挂到它**现在**那一格的队列上（销账仍能按旧事件格找到它）。
        /// ⚠️ 只在 `SyncBoard` 看到「这一格是空的」时调 —— 正常换格（两格都有人）不走这里。</summary>
        void DropPendingHpForSlot(int owner, int slot)
        {
            int key = HpKey(owner, slot);
            List<KeyValuePair<int, int>> q;
            if (!_pendingHpBySlot.TryGetValue(key, out q)) return;
            _pendingHpBySlot.Remove(key);
            if (q == null) return;
            for (int i = 0; i < q.Count; i++)
            {
                int id = q[i].Key, amt = q[i].Value;
                int nowSlot;
                if (!TryFindInstanceSlot(owner, id, out nowSlot))
                {
                    _pendingHp.Remove(id);   // 人已经不在场 ⇒ 这一笔永远演不到，作废
                    PendingHpProbe("void", owner, slot, id, amt, "（不在场 ⇒ 作废）");
                    continue;
                }
                int nk = HpKey(owner, nowSlot);
                List<KeyValuePair<int, int>> nq;
                if (!_pendingHpBySlot.TryGetValue(nk, out nq))
                {
                    nq = new List<KeyValuePair<int, int>>(2);
                    _pendingHpBySlot[nk] = nq;
                }
                nq.Add(new KeyValuePair<int, int>(id, amt));
                PendingHpProbe("move", owner, nowSlot, id, amt, "（挪格 ⇒ 账跟人走）");
            }
        }

        /// <summary>把某一格按「引擎值 + 账上还没演到的那一笔」刷回卡面。
        /// 场上没有那一格 / 视图不在 ⇒ 什么都不做（⛔ 不新建视图 —— 那是 `SyncBoard` 的活）。</summary>
        void RefreshUnitData(int owner, int slot)
        {
            if (Ctx == null || Ctx.Players == null) return;
            if (owner < 0 || owner >= Ctx.Players.Length || !BoardSpec.IsValid(slot)) return;
            var u = Ctx.Players[owner].Board[slot];
            if (u == null) return;
            var views = owner == _me ? _myUnits : _foeUnits;
            CardView v;
            if (views == null || !views.TryGetValue(slot, out v) || v == null) return;
            v.SetData(ToBoardCardData(u, owner, slot));
        }

        // ---- 第 1 条的残余④：**新上场的单位先别建视图** ------------------------------------
        //  判据与等价物 → `_pendingDeploy` 的 doc。这里只有三件：记账 / 销账 / 查询（含身份守卫）。

        /// <summary>引擎把单位放到这一格上、而 `Deploy` 还没演到时记一笔（身份守卫同 `NotePendingHp`）。
        /// 🔴 2026-10-19（B6）：**第一判据 = `e.InstanceId`**（同名的另一份不算「这一格已经换人了」）；
        /// `InstanceId == 0` 才退回「按卡名」那条老口径。</summary>
        void NotePendingDeploy(BattleEvent e)
        {
            if (e == null || e.Kind != EvtKind.Deploy) return;
            if (Ctx == null || Ctx.Players == null) return;
            if (e.Player < 0 || e.Player >= Ctx.Players.Length) return;
            if (!BoardSpec.IsValid(e.Slot)) return;
            var u = Ctx.Players[e.Player].Board[e.Slot];
            if (u == null) return;                                         // 已被自己的效果弄走 ⇒ 不必压
            int key = HpKey(e.Player, e.Slot);

            if (e.InstanceId != 0)
            {
                // 这一格现在站着的是**不是**这条事件部署的那一份 ⇒ 不记（与改前那条名字守卫同义，
                // 但**同名两张分得开**：名字相同、实例不同 ⇒ 不是同一张，⛔ 别把它的视图压掉）。
                if (u.InstanceId != e.InstanceId) return;
                _pendingDeploy[key] = e.InstanceId;
                _pendingDeployByName.Remove(key);      // 同一格只留一种口径（别让两条路各记一笔）
                return;
            }

            // 退路：事件没带实例号（手搓 / 没有实例）⇒ 沿用改前的名字口径。
            if (!string.IsNullOrEmpty(e.CardId) && u.Name != e.CardId) return;   // 那一格已经换人了
            _pendingDeployByName[key] = u.Name;
            _pendingDeploy.Remove(key);
        }

        /// <summary>`Deploy` 演到这一拍 ⇒ 销账，并让 `AdvanceTimeline` 之后补一次 `SyncBoard`（把视图建出来）。
        /// 🔴 2026-10-19（B6）：**按实例 id 销账** —— 账上那一笔不是这条事件的人（同一批里这一格又换过手）
        /// ⇒ **不销、也不放视图**（那一笔会由它自己那条 `Deploy` 销掉）。</summary>
        void CompletePendingDeploy(BattleEvent e)
        {
            if (e == null || e.Kind != EvtKind.Deploy) return;
            int key = HpKey(e.Player, e.Slot);
            if (e.InstanceId != 0)
            {
                int expectId;
                if (!_pendingDeploy.TryGetValue(key, out expectId)) return;   // 没记过（玩家自己打出的那张）
                if (expectId != e.InstanceId) return;                        // 这一笔不是这条事件的人 ⇒ 留着
                _pendingDeploy.Remove(key);
            }
            else
            {
                if (!_pendingDeployByName.Remove(key)) return;
            }
            _syncAfterDeploy = true;

            // 🆕 2026-10-19（战斗线 B2 · 偏差 8）：**AI 出的牌也要有落位演出**（原版 AI 走同一个
            //   `_ResolvePlayCardFromHand`）。订一张飞行票 ⇒ `SyncBoard` 建视图时从敌方手牌飞进格位；
            //   落地那两条 cue 也押到飞行终点（起飞那两条在 `StartAiDeployFlight` 里播）。
            //   ⚠️ 只认「这一手真是从手牌打出来的」那张票（`_aiTicketName` 身份守卫 + 时间窗）。
            //   🔴 **2026-10-19（B3）就地订正（铁律 5）**：这一行原来写「触发产物 / 效果召唤**不飞**
            //      （原版那两条是 `_ResolveCardAutoSummoned`，没有这段手牌飞行）」—— **两句都不准确**：
            //      · **效果召唤**走的是 `_ResolveSummonUnit`（`SummonMinion` 直接落在格位上，
            //        没有手牌飞行）⇒「不飞」的结果对，但**引错了判据**；
            //      · `_ResolveCardAutoSummoned`（`autoPlayFromHand` = 卡面 `from your deck`）**有**
            //        手牌那一段（`CardScript.PlayEnemyCard/PlayPlayerCard` → `MoveIntoFieldFromHand`）
            //        ⇒ 它**应该飞**，只是引擎的 `Deploy` 事件**不带「怎么进来的」这一位**，
            //        驱动层今天分不出它和普通召唤 ⇒ **已知缺口，接口需求见 B3 报告 §三·2**。
            //      · **教程脚本**自己打的牌现在也有票了（`CaptureTutorialPlayTicket`）⇒ 会飞。
            if (animateFeel && e.Player != _me && AiTicketMatches(e))
            {
                _aiDeployFlights[key] = new AiPlayTicket { handIdx = _aiTicketHandIdx };
                _aiDeployLandingCue[key] = e;
                _aiTicketHandIdx = -1; _aiTicketName = null; _aiTicketAt = -999f;
            }
            // 🆕 2026-10-19（B5）：**`autoPlayFromHand` 的手牌飞行**（B4 只补了听感，画面还没飞）。
            //   判据 = 原版 `BattleManager._ResolveCardAutoSummoned_d__511__MoveNext.c:104,122,187`
            //   → `CardScript.PlayEnemyCard/PlayPlayerCard` → `MoveIntoFieldFromHand` —— 与真人出牌
            //   **同一段**手牌起飞；我们引擎那条路（`EffectResolver` 的 `op.AutoPlay`）是
            //   「先进手牌 → `SetupCardInHand` → 立刻拿掉 → `DeployFree(fromHand:true)`」，
            //   而整段是同步算完的 ⇒ 那张牌**从来没在画面上落到手里**。
            //   ⇒ 起点用**它若在手里会占的那一格**：它被 `Add` 进去时是**最后一张**（紧接着就 `Remove`）
            //     ⇒ 索引 = 当前手牌张数（= 追加前的张数）、张数 = 当前张数 + 1。
            //   ⚠️ 记账用同一个 `_aiDeployFlights` 票箱（消费端 `SyncBoard`/`PlayBattleSfx` 按 `HpKey`
            //     通用，不看座位；`StartAiDeployFlight` 按 `owner` 选手牌布局）—— ⛔ 别另造第二套。
            //   ⚠️ 两个玩家侧的例外（如实记）：
            //      · 玩家的普通出牌走 `CardInteraction` 那条拖拽飞行（`DeployFrom = HandPlayed`）；
            //      · 满场打不出去时 `EffectResolver` 把牌**塞回手牌**（那一支不发 `Deploy`）⇒ 不到这里。
            else if (animateFeel && e.DeployFrom == DeploySource.AutoPlayFromHand)
            {
                var autoHand = Ctx.Players[e.Player].Hand;
                _aiDeployFlights[key] = new AiPlayTicket
                {
                    handIdx = autoHand != null ? autoHand.Count : 0,
                    // 🆕 W：这条票要走「居中展示」那半拍 + 两条起飞 cue 分两拍（判据见 `StartAiDeployFlight`）。
                    autoPlay = true,
                };
                _aiDeployLandingCue[key] = e;
            }
        }

        /// <summary>这张 `Deploy` 是不是「AI 刚刚从手牌打出的那一张」（判据见 `CompletePendingDeploy`）。</summary>
        bool AiTicketMatches(BattleEvent e)
        {
            if (_aiTicketHandIdx < 0 || _aiTicketAt < -100f) return false;
            if (_clock - _aiTicketAt > AiTicketWindow) return false;
            return !string.IsNullOrEmpty(_aiTicketName) && e.CardId == _aiTicketName;
        }

        /// <summary>🆕 2026-10-19（B2 · 偏差 8）：**在 `SimpleAI.ExecuteAction` 之前**记下「这一手打的是
        /// 手牌第几张、那张叫什么」。生产里只有两条入口（`DriveAiTurn` / `FinishAiTargetingAnim`）——
        /// 必须**先**记：动作一执行，那张牌就已经离开手牌了。
        /// ⚠️ 只有 `PlayCard` 才记；其余动作（攻击 / 技能 / 结束回合）**把票清空**（免得上一手的票被误认）。</summary>
        void CaptureAiPlayTicket(AiAction act)
        {
            _aiTicketHandIdx = -1; _aiTicketName = null; _aiTicketAt = -999f;
            if (Ctx == null || act == null || act.Kind != AiActionKind.PlayCard) return;
            var hand = Ctx.Players[1 - _me].Hand;
            if (act.HandIdx < 0 || act.HandIdx >= hand.Count) return;
            var inst = hand[act.HandIdx];
            if (inst == null || inst.Card == null) return;
            _aiTicketHandIdx = act.HandIdx;
            _aiTicketName = inst.Card.Name;
            _aiTicketAt = _clock;
        }

        /// <summary>🆕 2026-10-19（B4）：**远端人类对手**的出牌票（`ApplyLoggedAction` 的消费约定）。
        /// 判据只此一处 —— ⛔ 别在调用点再写一遍 `actor != _me && kind == PlayCard`。</summary>
        void NoteRemotePlayTicket(int actor, int kind, int handIdx)
        {
            if (actor == _me || kind != (int)AiActionKind.PlayCard) return;
            CaptureAiPlayTicket(new AiAction { Kind = AiActionKind.PlayCard, HandIdx = handIdx });
        }
        /// <summary>自检：只跑「记票」那一半（不落引擎动作）。</summary>
        public void SimulateRemotePlayTicketForTest(int actor, int handIdx)
        {
            NoteRemotePlayTicket(actor, (int)AiActionKind.PlayCard, handIdx);
        }
        public int AiPlayTicketHandIdxForTest { get { return _aiTicketHandIdx; } }
        public string AiPlayTicketNameForTest { get { return _aiTicketName; } }

        /// <summary>这一格是不是「还没演到的登场」（<paramref name="u"/> = 现在站在那一格的单位）。
        /// 身份不符 ⇒ **当场把账作废**（连续棋盘会挪格号；宁可早出现，也别把别人的视图压掉）。
        /// 🔴 2026-10-19（B6）：**第一判据 = 卡实例 id**（`_pendingDeploy`），`InstanceId == 0` 那一档
        /// 才查名字表（`_pendingDeployByName`）。同名两张 + 换格 ⇒ 只有实例 id 分得开。</summary>
        bool IsPendingDeploy(int owner, int slot, UnitState u)
        {
            int key = HpKey(owner, slot);
            int expectId;
            if (_pendingDeploy.TryGetValue(key, out expectId))
            {
                if (u == null || u.InstanceId != expectId)
                {
                    _pendingDeploy.Remove(key);
                    return false;
                }
                return true;
            }
            string expect;
            if (!_pendingDeployByName.TryGetValue(key, out expect)) return false;
            if (u == null || (!string.IsNullOrEmpty(expect) && u.Name != expect))
            {
                _pendingDeployByName.Remove(key);
                return false;
            }
            return true;
        }

        /// <summary>本帧有没有「等到登场那一拍、要补建视图」的格子（见 `CompletePendingDeploy`）。</summary>
        bool _syncAfterDeploy;

        /// <summary>`ToCardData` + 账上那一笔。**场上卡唯一的一份**（⛔ 别在别处再拼一次）。</summary>
        CardData ToBoardCardData(UnitState u, int owner, int slot)
        {
            // 🆕 2026-10-24（`W20`）：`isPlayer` 决定「敌方伏击整排徽标不画」那道闸
            //   （原版 `BattleCardUI__UpdateTraitIcons.c:40-46`）—— 场上卡唯一的一份卡面数据在这里。
            var d = ToCardData(u, owner == _me ? _myFaction : _foeFaction, owner == _me);
            // 🔴 B5：账按**实例 id** 查（见 `_pendingHp` 的 doc）—— 格号只用于视图定位，不是账的键。
            PendingHpEntry pend;
            if (u != null && u.Instance != null && _pendingHp.TryGetValue(u.Instance.Id, out pend) && pend.amount != 0)
                d.health += pend.amount;
            return d;
        }

        /// <summary>
        /// 丢掉还没播的事件。**只给「一口气跑完几百回合」那种脚本推进用** ——
        /// 那种路径下每回合的几十条事件会堆到一起，一次全点着既慢又看不出什么。
        /// </summary>
        public void DropSignals()
        {
            if (Ctx == null) return;
            // 🔴🆕 2026-10-19（战斗线 B2 · 偏差 10）：**产品里没有任何「跳过」入口**（与原版一致）——
            //   原版的跳过只存在于**回放**模式：`BattleManager__ReplaySkipAnims.c` 返回
            //   `matchType == 0xa0 /* replay */ && BattleManager+0x521`，那个位由
            //   `ClickPauseReplay` / `ClickPlayReplay` 写（`__ClickPauseReplay.c:10` 置 1、`__ClickPlayReplay.c:10` 清 0），
            //   实况战斗那条路**没有人写它**。⇒ 本方法只该被「一口气跑几百回合」的批处理脚本用到
            //   （判据 → `资料/普查产出_1018/R_战斗表现链路对拍.md` §4 偏差 10；调用点普查 = 只有
            //    `Editor/BattleScene.cs` 的整局压力测试）。
            //   真在产品路径里被调到 = **丢掉玩家的演出**（静默失败的反面）⇒ 出声，别静默。
            if (!Application.isBatchMode && !Application.isEditor)
                Debug.LogWarning("[Battle] `DropSignals()` 在产品运行期被调用了 —— 这会把还没播的演出全部丢掉。"
                               + "原版**实况战斗没有跳过入口**（跳过只在回放模式：`ReplaySkipAnims`），"
                               + "本方法只该被批处理脚本推进用到。");
            Ctx.ClearSignals();
            LastSignals.Clear();
            _timeline.Clear();
            // 🆕 2026-10-19（战斗线 W 第 1、2 条）：丢事件 = 这一段的演出不要了 ⇒ 闸与血量账一起清
            //   （不清闸的话「一口气跑几百回合」那条脚本推进每步都被拦；不清账的话血会少算）。
            _blocking = false;
            _blockingQuietAt = _clock;
            _pendingHp.Clear();
            _pendingHpBySlot.Clear();   // 🔴 B5：同上 —— 按实例记账之后按槽的 FIFO 是第二本账，必须成对清
            PendingHpProbe("clear", -1, -1, 0, 0, "（座位重建：两本账成对清）");
            // 🆕 2026-10-19（B1）：丢事件 = 这一段的演出不要了 ⇒ 新加的三笔（队尾 / 登场账 / 飞行载体）一起清。
            _timelineTailAt = 0f;
            _pendingDeploy.Clear();
            _pendingDeployByName.Clear();   // 🆕 B6：同上，成对清
            _syncAfterDeploy = false;
            // 🆕 2026-10-19（B2）：AI 飞行那两笔 + 起飞票同理。
            _aiDeployFlights.Clear();
            _aiDeployLandingCue.Clear();
            _aiDeployFlying.Clear();
            // 🆕 B3：丢事件同样把正在飞的那张**手牌卡背**收掉（它不在 `_foeHandViews` 表里，
            //   不收就永远挂在 `foeHand` 底下 —— 静默留一件垃圾在画面上）。
            foreach (var kv in _aiDeployFlyingHand) if (kv.Value != null) Kill(kv.Value.gameObject);
            _aiDeployFlyingHand.Clear();
            _aiDeployHandedOff.Clear();        // 🆕 W57：同上（丢事件时交接标记也作废）
            RestoreAllBoardViewVisibility();   // 🆕 B3：丢事件 ≠ 把场上那张卡永久藏掉
            _playerTakeoffAt = -999f;
            _playerFlightTakeoffPlayed = false;   // 🆕 B3：同上
            ClearAbilityVfxMoves();
            ClearFlyingUnits();                   // 🆕 2026-10-19（T05 · A2081）：同上
            ClearCardAnims();                     // 🆕 2026-10-23（W63）：卡体动画层同上
        }

        /// <summary>
        /// 🆕 2026-10-15（`T06` · 战斗音响）：**事件驱动**的那几条战斗音效 ——
        /// 原版 `BattleManager.soundCollection` 那一族里**挂在卡动作上**的（另一半天挂在回合骨架上：
        /// 回合开始 / 换牌 / 结束回合 / 计时归零，那几处直接调 `BattleSfx.Play`，不走事件）。
        ///
        /// ⚠️ 一律 `Play2D`（反编译调用点第 4 实参恒为 `0` = `MixerType.FX`）⇒ 不吃世界坐标。
        /// 判据（逐条带调用点）→ `BattleSfx` 的文件头；cue 表 → `Resources/battle_sounds.json`
        /// （键 = **原版字段名**，产出方 `工具/import_battle_sfx.py`）。
        /// ⛔ **别在这里拼 clip 名** —— 字段名 → cue 资产 → clip 那条链全在表里（cue 名 ≠ clip 名）。
        /// </summary>
        public void PlayBattleSfx(BattleEvent e)
        {
            if (e == null || Ctx == null) return;
            if (e.Player < 0 || e.Player > 1) return;

            // 🆕 2026-10-16（`T06` B 组）：「上一次报过的打法档」是**按(座位,格号)记**的 ⇒
            //   格位上**换了单位**（进场 / 阵亡 / 回手）就必须清，否则新单位会被旧单位那一档压住、**不响**。
            if (e.Kind == EvtKind.Deploy || e.Kind == EvtKind.Death || e.Kind == EvtKind.Return)
                _attackTypeSoundAt.Remove(e.Player * 16 + e.Slot);

            switch (e.Kind)
            {
                // 🆕 2026-10-19（W · 偏差 5「专用演出」）：**战术卡打出的那一条音效**。
                //   判据（逐句）：
                //     · 非目标战术卡 —— `BattleManager._ResolvePlayCardFromHand_d__447__MoveNext.c:621-624`
                //       （`SoundAssetCollection.get_PlayMinionFromHand` → `SoundManager.Play2D`）→ `:633 NonTargetSpellPlayed`
                //       → `:638 DissolveWholeCard`；
                //     · 目标战术卡 —— `BattleManager__Update.c:288-291`（拖进场那一刻同一条 `PlayMinionFromHand`，2D），
                //       随后 `MoveIntoFieldFromHand` → `StartSpellFrom` / `StartTargetedSpellAnim` / `DissolveWholeCard`。
                //   ⇒ **两类战术卡都恰好响一次**，且都是 2D。
                //   ⚠️ 只对**非单位卡**（`Play` 对单位卡也会发；单位的 `playMinionFromHand` 已经挂在 `Deploy`
                //      的**起飞拍**上，见 `PlayDeployTakeoffCues`）—— ⛔ 别让它对单位卡再响一遍。
                //   ⚠️ `EvtKind.Play` 是**引擎**发的（`RuleCore.PlayCard`），所以 AI / 教程 / 远端人类出牌
                //      与玩家走同一条，不需要另开入口。
                case EvtKind.Play:
                {
                    var playDef = CardDatabase.Find(_pool, e.CardId,
                                                    e.Player == _me ? _myFaction : _foeFaction);
                    if (playDef != null && !playDef.IsUnit) BattleSfx.Play(BattleSfx.PlayMinionFromHand);
                    else if (playDef == null)
                        // 出声（每张卡一次）：`_pool` 里没有这张卡（教程/自设计阵营）⇒ 判不出「单位还是战术」
                        // ⇒ 这一条 cue 不播。⛔ 别拿「猜一个」代替（会把单位卡多播一下）。
                        BeatSoundOff($"playcue:{e.CardId}",
                            $"`{e.CardId}` 不在卡池里 ⇒ 判不出它是不是战术卡，`playMinionFromHand` 这一条没播"
                          + "（原版战术卡必响一次；单位卡不响 —— 判据见本 case 的注释）。");
                    break;
                }

                // 抽牌落手（原版 `CardScript__DrawCard.c:50`）。⚠️ 它的 `Slot` **恒为 -1**（不在场上）——
                // 本族一律 2D 播放，所以不需要落点。
                // 🆕 2026-10-16（`T06` B 组）：**这一拍原版还响第二条** —— `createCardInHand`
                //    （原版 `CardScript._CreateCardInGame_d__250__MoveNext.c:44-50,78-81`：卡**出现在手牌**那一拍，
                //     先设 `inHandJustCreated(12)` + 贴手牌层，跑完 `DOMove/DORotate/DOScale` 才播）。
                //   ⚠️ **一条未定**（`T06c` §三·2 明说没查清）：它与上面那条是不是**同一拍响两声**
                //     （`_ResolveDrawCard:150` 调 `CreateCardInGame`，而 `CardScript__DrawCard.c:48-50` 另播
                //     collection 那条）—— **两条不是互斥关系**（报告的结论），照「两条都在抽牌这条路上」接。
                //     ⛔ 别为了「听起来不重复」擅自删一条。
                case EvtKind.Draw:
                    BattleSfx.Play(BattleSfx.DrawCardFromDeck);
                    BattleSfx.Play(BattleSfx.CreateCardInHand);
                    break;

                // 单位落到格位 = **卡从手牌飞进战场**那一拍。原版这一拍**响两条**（都在同一个函数里）：
                //   · `moveCardIntoBattle` ← `CardScript__StartMovingFromHand.c:43`（手牌起飞的位移）
                //   · `playMinionFromHand` ← `_ResolvePlayCardFromHand…:397`（`cardType == 0` 才响）
                // ⚠️ 两条**一起挂在 `Deploy` 上**、⛔ **不挂 `Play`**：`Play` 对战术卡也会发（战术卡不离手），
                //    挂它会多响一下；而 `Deploy` 的语义（`BattleEvent.Deploy` 的注释）正是「落到格位上」，
                //    且**效果召唤来的单位也走它** —— 与原版 `_ResolveCardAutoSummoned…:104,122,187` 同形。
                case EvtKind.Deploy:
                    // 🔴🆕 2026-10-19（战斗线 B2 · 偏差 9）：**四条 cue 不再同一拍响** ——
                    //   原版分成「起飞」两拍 + 「落地」两拍，中间隔着 `MinionPlayedIntoField` 的 0.65 s
                    //   （逐值：`DeploySequence.MoveTime 0.3 + TimeToScaleIntoMoving 0.1 + HoldTime 0.05 + LandTime 0.2`）：
                    //     · **起飞** = `moveCardIntoBattle`（`CardScript__StartMovingFromHand.c:43`）
                    //                + `playMinionFromHand`（`_ResolvePlayCardFromHand…:397`）
                    //     · **落地** = `invokeCUE` / `invokeCUELegendary`（`CardScript__CardToMinionAnim.c:13,20-30`）
                    //                + `landOnGround`（`CardScript__LandOnGround.c:26-41`，`Play3D`）
                    //   → 起飞那一对**由飞行开始那一拍播**（玩家 = `OnPlayerDeployFlightStart`；
                    //     AI = `StartAiDeployFlight`；程序化出牌 = `DoPlay` 补），这里只负责落地那一对。
                    // 🔴🆕 **2026-10-19（B3）**：**「没有起飞拍」的那条路改对了** —— 原来这里
                    //   `if (!takeoffDone) PlayDeployTakeoffCues();` 会让**效果召唤**也响那两条，
                    //   而原版召唤那条协程**根本不响它们**：
                    //     · `BattleManager._ResolveSummonUnit_d__510__MoveNext.c` 里
                    //       `SoundAssetCollection.get_MoveCardIntoBattle` / `get_PlayMinionFromHand`
                    //       的调用点 **0 条**（同一份文件 `grep` 过）；
                    //     · 它走 `MinionPlayedIntoField(..., param4 = 0)`，而那个协程在 **state 0**
                    //       就 `LandOnGround`（`CardScript._MinionPlayedIntoField_d__314__MoveNext.c:36-38`）
                    //       ⇒ **落地那两条就在这一拍**，没有「起飞拍」。
                    //   ⇒ 没有起飞票 = 效果召唤/再造这一档 ⇒ **只播落地那两条**。
                    //   ⚠️ **例外（已记账 · 接口需求）**：`autoPlayFromHand`（`from your deck`，我们池里
                    //      2 张：`BL55` / `SW57`）**有**起飞两条 + 一段手牌飞行
                    //      （`BattleManager._ResolveCardAutoSummoned_d__511__MoveNext.c:104,122,187`）。
                    //      引擎的 `Deploy` 事件**不带「这张牌怎么进来的」** ⇒ 驱动层分不出它和普通召唤
                    //      ⇒ 那两张现在会**少两条起飞 cue**；要补得让引擎给事件加一位（见 B3 报告 §三）。
                    {
                        // AI 那条飞行的落地拍：起飞已经响过、落地在飞行终点播 ⇒ 这一拍四条全跳过。
                        // ⚠️ 判据要**两张票同时在场**（`_aiDeployLandingCue` = 押后，`_aiDeployFlights` = 飞行真订上了）；
                        //   只剩前者 = 视图已存在 / 飞行没订成 ⇒ 这张票作废、照旧落地（⛔ 别静默吞掉）。
                        int dkey = HpKey(e.Player, e.Slot);
                        if (_aiDeployLandingCue.ContainsKey(dkey) && _aiDeployFlights.ContainsKey(dkey)) break;
                        _aiDeployLandingCue.Remove(dkey);
                        bool takeoffDone = e.Player == _me && TakeoffCuePending;
                        if (takeoffDone) { _playerTakeoffAt = -999f; _playerFlightTakeoffPlayed = false; }   // 这张票只吃一条
                        // 🆕 2026-10-19（B4 · B3 §三·2 的消费约定）：引擎已经把「怎么进来的」写进事件
                        //   （`BattleEvent.DeployFrom` / `DeploySource`）⇒ **autoPlayFromHand 不该再少两条**：
                        //   原版 `_ResolveCardAutoSummoned_d__511__MoveNext.c:104,122,187` 有起飞 + 落地两拍。
                        //   · `AutoPlayFromHand`：这里补起飞两条。
                        //     🔴 **2026-10-24（`G1`）就地订正（铁律 5）**：本行原来写「**手牌飞行本身还没做**
                        //     —— 那要复用 `StartAiDeployFlight` 的手牌载体，见报告 §五；先保证**听感**与原版条数一致」
                        //     —— **已过期**：`CompletePendingDeploy` 里 `DeployFrom == AutoPlayFromHand` 那一支
                        //     已经会给这张票订飞行（`autoPlay = true`；`StartAiDeployFlight` 会先跑居中展示再飞）。
                        //     ⚠️ **只剩我方**那一档仍走「飞场上样式视图」的退路（那张牌从没落到过手里，
                        //     见 `StartAiDeployFlight` 里 `owner == _me` 的注释），如实记着。
                        //   · `Summon` / `Reanimate` / `Unknown`：只有落地两条（判据见下面那段旧注释；
                        //     reanimate 那条路的反编译链 `ResolveTransformFromRemnant → CardScript.TransformFromRemnant
                        //     → BattleCardUI.ChangeCardToRemnant` **零声音调用点**，但引擎的消费约定是
                        //     「只响落地两条」⇒ 跟 `Summon` 同档，⛔ 别单独猜一套）。
                        if (!takeoffDone && e.DeployFrom == DeploySource.AutoPlayFromHand)
                        {
                            PlayDeployTakeoffCues();
                            _playerTakeoffAt = _clock;
                        }
                        PlayDeployLandingCues(e);
                    }
                    break;

                // 抬手（原版 `CardScript._PrepareAttack_d__353__MoveNext.c:83`）——
                // `BattleEvent.Attack` 的语义就是「伤害之前发」，正好是抬手那一拍。
                // 🆕 2026-10-16（`T06` B 组）：**顺带把「换打法」那一下补齐** —— 原版 AI 那 4 个调用点
                //   在引擎侧、我们没有那条事件 ⇒ 在这里按 `(座位,格号)` 比上一次报过的档（`NoteAttackTypeSound`）。
                case EvtKind.Attack:
                    // 🔴 **2026-10-21（W61 第 2 批 · 第 5 条）**：`MinionInitiatingAttack` **不在这里** ——
                    //   原版它是**攻击动作一开始**响的（`CardScript._PrepareAttack_d__353__MoveNext.c:83`，
                    //   由 `SetupAttack` 起协程、StartCoroutine 的第一帧就 `Play2D`），
                    //   而 `SetupAttack` 在 `_ResolveAttack_d__438__MoveNext.c:838-843` 的
                    //   `WaitForSeconds(attackStepTime × 2.0)` **之前** ⇒ **比动画早 0.2 s**。
                    //   我们这条时间线的 `Attack` 事件本身已经被 `AttackWindUp` 推后了 0.2 ⇒
                    //   这一拍再播就**晚 0.2 s**。改由 `PlaySignals` 排到「攻击动作起点」（见那里）。
                    //   ⛔ 别把这一句加回来（会变成同一击两下 / 晚 0.2 s）。
                    NoteAttackTypeSound(e.Player, e.Slot,
                                        e.Ranged ? UnitState.AttackTypeRanged : UnitState.AttackTypeMelee);
                    break;

                // 治疗（原版 `CardScript._Heal_d__468__MoveNext.c:148`）。
                // ⚠️ 原版紧接其后**无条件**再播一条 `Syphon`（`:154`）—— 而**本 build 那一格是空的**
                //    （亲读 shipped bundle）⇒ 照原版 = **不播**，详见 `BattleSfx` 文件头那 12 条。
                // 🆕 2026-10-20（`W58`）：改由 **`EvtKind.Heal`** 触发（原来挂在「负数 `Hit`」上，
                //    那条旧约定只剩幸存者广播在用 —— 而 Survivor **不响** `MinionHeal`，原版它只走
                //    `UseSurvivor` 自己那条链）。Normal / Syphon **两条都响** `MinionHeal`
                //    （原版 `CardScript.Heal` 对两种 `HealType` 都无条件播这一条）。
                case EvtKind.Heal:
                    BattleSfx.Play(BattleSfx.MinionHeal);
                    break;
                case EvtKind.Hit:
                    // 挨打的 cue 不在这一处（见下面那段），正数 `Hit` 这里不出声；
                    // 负数 = 幸存者广播 ⇒ 也不出声（原版 Survivor 没有 `MinionHeal`）。
                    break;
                    // ⚠️ **挨打那一下的 `meleeAttackHit*` 不在这里** —— 它要「紧跟前一条是不是攻击、是近战还是远程」
                    //    那个**批内视野** ⇒ 由 `PlayMeleeHitCues(_signalBuf)` 在 `PlaySignals` 里成批算
                    //    （拆成纯函数 `MeleeHitCueCount` 便于断言），同 `unitDamage` 那条的做法。

                // 🆕 2026-10-16（`T06` B 组）：**单位死亡**那一拍（原版 `CardScript.<UnitDeath>d__446`
                //   → `Play3D`，`…_UnitDeath_d__446__MoveNext.c:359-369`）—— **在单位那一格的位置上播**。
                //   ⚠️ 原版那道闸是 `+0x228 == 5`（卡状态那一格）；**残骸体算不算那一档没查清**
                //   ⇒ 一律照播（`RemnantSfx` 那一族是**另外六条** cue，两者在原版本来就各播各的，⛔ 别互相顶掉）。
                case EvtKind.Death:
                    PlayBattleSfx3D(BattleSfx.MinionDeathCUE, e.Player, e.Slot);
                    break;

                // 🆕 2026-10-16（`T06` B 组）：**场上单位变回手牌卡**那一拍
                //   （原版 `CardScript.<TransformUnitInPlayToCard>d__256__MoveNext.c:52,73,76-79`，**2D**）。
                //   ⚠️ `EvtKind.Return` 的语义含「回牌库」（原版**同一条动画**、`PlayBackToHandAnimation`）
                //   ⇒ 两条路都照播（判据在 `BattleEvent.Return` 的 doc 里）。
                case EvtKind.Return:
                    BattleSfx.Play(BattleSfx.BackToHand);
                    break;

                // 主动技能：**只有这张卡没有专用演出时**才响「默认技能音」。
                //   原版 `BattleManager._ResolveActiveAbilityAnim_d__478__MoveNext.c:19` —— 那支协程
                //   本身就是**默认**那一档（它播完接的就是 `FinishResolvingAction`），它的兄弟
                //   `PlayActiveAbilityAnim` 才是「按卡挑专用演出 / 退回默认」的那个岔口。
                //   我们这边的对应判据 = **这张卡有没有逐卡覆盖**
                //   （`VfxMap.ResolvePerCard` 的 doc 原话：「调用方真正要问的是『这张卡自己有没有逐卡覆盖』」）。
                case EvtKind.Ability:
                    if (string.IsNullOrEmpty(VfxMap.ResolvePerCard(
                            VfxMap.Ability,
                            e.Player == _me ? _myFaction : _foeFaction, e.CardId)))
                        BattleSfx.Play(BattleSfx.DefaultActiveAbility);
                    // 🆕 2026-10-16（`T06` B 组）：技能那一档同样要报「换打法」（`4 Active`）。
                    NoteAttackTypeSound(e.Player, e.Slot, UnitState.AttackTypeActive);
                    break;

                // ✅ **2026-10-16 收口**：原来挂在这儿的两条「本批没接的」都已落地 ——
                //   · `unitDamage` → `PlayUnitDamageCue`（批内算，见那一段）；
                //   · `sneakAttack` → 判为「**我们卡池里没有触发物**」（原版 1195 张卡 SO 与我们 1127 张，
                //     两边都 0 张带 `DefinedTrait.sneakAttack`）⇒ 铁律 11 例外① **不接**，判据在 `任务/T06`。
                // ⏳ **B 组仍未接的一条**：`changeToActiveAbilityCUE` —— **原版这一格是空 PPtr**
                //   （调用点存在、`CardScript__ChangeAttackType.c:53`）⇒ 铁律 11 例外①，我们照原版不响。
            }
        }

        /// <summary>🆕 2026-10-19（战斗线 B2 · 偏差 9）：**起飞那一对 cue** —— 原版在「牌离开手牌、
        /// 飞向战场」那一拍响的两条（`CardScript__StartMovingFromHand.c:43` /
        /// `_ResolvePlayCardFromHand…:397`）。玩家那一路由 `OnPlayerDeployFlightStart` 调；
        /// AI 那一路由 <see cref="StartAiDeployFlight"/> 调；🆕 **B3**：程序化出牌（不走拖拽/飞行那条路）
        /// 由 `DoPlay` 补调。⚠️ `private` 但三处同源，⛔ 别各抄一份。</summary>
        void PlayDeployTakeoffCues()
        {
            BattleSfx.Play(BattleSfx.MoveCardIntoBattle);
            BattleSfx.Play(BattleSfx.PlayMinionFromHand);
        }

        /// <summary>🆕 2026-10-19（战斗线 B2 · 偏差 9）：**落地那一对 cue** —— 原版在
        /// `CardScript.LandOnGround` 那一拍（`CardScript__LandOnGround.c:26-41` +
        /// `CardScript__CardToMinionAnim.c:13,20-30`）。</summary>
        void PlayDeployLandingCues(BattleEvent e)
        {
            if (e == null) return;
            BattleSfx.Play(InvokeCueFieldFor(e));
            PlayBattleSfx3D(BattleSfx.LandOnGround, e.Player, e.Slot);
        }

        /// <summary>🆕 2026-10-16（`T06` B 组）：**`invokeCUE` 还是 `invokeCUELegendary`**。
        /// 判据 = 原版 `CardScript.GetInvokeCue(cardRarity)`（`BattleCardSounds.cs` 的签名桩 + `T06c` 报告）：
        /// **传说（rarity == 4）走 legendary**；🔴 另外**带 `ambush` 的单位也走 legendary** ——
        /// 原版 `CardToMinionAnim` 里把 rarity **强制成** 4（同一条判据还被 `LandOnGround` 用来选落地位移）。
        /// ⚠️ 我们卡池当前**没有一张带 `ambush`**（`cards_engine.json` 现读 0 张）⇒ 那半支今天不可达，
        /// 但**机制照写**（铁律 11：不是「没有触发物」就不写代码，是「写好了等数据」）。
        /// 取不到卡 ⇒ 出声 + 退回普通那条（⛔ 不静默）。</summary>
        string InvokeCueFieldFor(BattleEvent e)
        {
            var unit = (Ctx != null && e.Player >= 0 && e.Player < 2 && BoardSpec.IsValid(e.Slot))
                     ? Ctx.Players[e.Player].Board[e.Slot] : null;
            var card = unit != null ? unit.Card : null;
            if (card == null)
            {
                Debug.LogWarning($"[Battle] `invoke` 那条音效取不到卡（`Deploy` 事件：p{e.Player} 格 {e.Slot}）"
                               + " ⇒ 退回**普通**那条 `invokeCUE`（原版按稀有度挑，挑不了就出声、不猜）。");
                return BattleSfx.InvokeCUE;
            }
            return (card.Rarity == "legendary" || card.Has(KeywordTable.Ambush))
                 ? BattleSfx.InvokeCUELegendary : BattleSfx.InvokeCUE;
        }

        // ==================================================================
        //  🆕 2026-10-16 落地**扬尘**（原版 `CardScript.LandOnGround` 的第二件东西）
        // ==================================================================
        //  判据（`CardScript__LandOnGround.c` 亲读）：
        //    · `:42-51` —— 选哪一件：`!HasCurrentTrait(0x4b0 /*ambush*/)` **且** `cardRarity == 4`
        //      ⇒ 取 `+0x160` = `landOnGroundParticlesLegendary`；否则取 `+0x158` = `landOnGroundParticles`。
        //    · `:52-76` —— 在**卡的世界位置 + `landOnGroundParticlesLocalOffset`**（**竞技场世界单位**）、
        //      按 **prefab 自己的旋转** `Instantiate`（⚠️ 2026-10-16 订正：原写「按卡的旋转」——
        //      现读 `CardScript__LandOnGround.c` 给 `Instantiate` 的第 3 个实参是
        //      `get_rotation(prefab.transform)`，**不是卡的**；我们的播放器本来就不动旋转 ⇒ 天然一致）。
        //    · `:87-106` —— `SetParent(MinionManager)` 之后 `localScale = Vector3.one × desiredScale`。
        //  两件 prefab **本地都有**、而且已经进过效果库：`Invoke Minion Hits Ground` / `… Legendary`
        //  （`Assets/WarpforgeVFX/Prefabs/`；`数据/游戏数据/effect_index.json` 两件都是「对得上 / 高置信」）。
        //  ⚠️ **名字是照语义对上的、不是从 PPtr 解出来的**：卡预制体里那两枚引用是 PPtr
        //  （`m_PathID 2197305140038358634` / `3011442562301428173`），这份解包的 PathID 是重编号过的、
        //  按它反查不到对象；而「同名族 + Legendary 尾缀」与 `Invoke Minion Card Fade Default`（登场淡入那件）
        //  同形，且两件的语义（"hits ground"）与 `landOnGroundParticles` 逐字对得上 —— 如实标在这里。

        /// <summary>普通档的落地扬尘（原版卡预制体 `landOnGroundParticles`）。</summary>
        public const string LandDustMinion = "Invoke Minion Hits Ground";
        /// <summary>传说档的落地扬尘（原版卡预制体 `landOnGroundParticlesLegendary`；
        /// 判据 = `cardRarity == 4` **且不带 ambush**）。</summary>
        public const string LandDustLegendary = "Invoke Minion Hits Ground Legendary";
        /// <summary>扬尘相对卡位的偏移 Y —— 原版卡预制体 `landOnGroundParticlesLocalOffset = (0, 0.015, 0)`，
        /// **量纲 = 竞技场世界单位**。
        /// <para>🔴 **2026-10-16：这一条的量纲已经处理掉了** —— 扬尘现在**挂到那张卡的视图上**（见调用处），
        /// 所以 `localPosition` 活在**父节点（卡）的空间**里 ⇒ 传进去的是 `0.015 / 卡的缩放`，
        /// 落地的**世界**偏移才**逐值等于原版那 0.015**（原来直接当 HUD 单位加，≈1.6 px、且整件活在错的空间里）。</para></summary>
        public const float LandDustOffsetY = 0.015f;

        /// <summary>🆕 2026-10-16 这一拍该撒哪件扬尘（判据见上面那一段）。
        /// <para>⚠️ **与上面 `InvokeCueFieldFor` 的规则【故意不同】**：原版那两处自己就不一样 ——
        /// `CardToMinionAnim` 把带 ambush 的卡的 rarity **强制成 4**（所以那条 CUE 走 legendary），
        /// 而 `LandOnGround` 是**先看 ambush trait、带了就直接用普通档**。
        /// ⇒ **别把两条规则合并成一处**（那样必然改错一边）。我们卡池当前 0 张带 ambush
        /// （`cards_engine.json` 现读），两套规则今天**结论相同**，但机制照写。</para>
        /// <para>取不到卡 ⇒ 出声 + 退回**普通档**（不猜传说档：普通档是原版 `rarity != 4` 的默认那一支）。</para></summary>
        string LandDustFieldFor(BattleEvent e)
        {
            var unit = (Ctx != null && e.Player >= 0 && e.Player < 2 && BoardSpec.IsValid(e.Slot))
                     ? Ctx.Players[e.Player].Board[e.Slot] : null;
            var card = unit != null ? unit.Card : null;
            if (card == null)
            {
                Debug.LogWarning($"[Battle] 落地扬尘取不到卡（`Deploy` 事件：p{e.Player} 格 {e.Slot}）"
                               + " ⇒ 退回**普通**那件（原版按稀有度挑，挑不了就出声、不猜传说档）。");
                return LandDustMinion;
            }
            return (card.Rarity == "legendary" && !card.Has(KeywordTable.Ambush))
                 ? LandDustLegendary : LandDustMinion;
        }

        /// <summary>🆕 2026-10-16（`T06` B 组）：**3D 那一档**的战斗音效（原版 `SoundManager.Play3D`）。
        /// 取不到落点 ⇒ **退成 2D**（同 `RemnantSfx` 那条口径），⛔ **别拿 `Vector3.zero` 当落点**
        /// （那会把声音钉在屏幕正中，是原版没有的位置）。</summary>
        void PlayBattleSfx3D(string field, int side, int slot)
        {
            var w = BoardWorld(side, slot);
            if (w.HasValue) BattleSfx.Play(field, w.Value);
            else BattleSfx.Play(field);
        }

        /// <summary>🆕 2026-10-16（`T06` B 组）：**「换打法」那一下的声音** —— 原版 `CardScript.ChangeAttackType` 里那三条 cue。
        ///
        /// <para>原版**五个** `playSound = 1` 的调用点：玩家点钮（`UnitOnBoardAttackTypeSelector__AttackButtonClick.c:104`）·
        /// `AI__ExecuteAction.c:222,233` · `AiScripted__ExecuteAction.c:1251` · `BattleManager__ParseEnemyAction.c:115` ·
        /// `_ResolveForceAttack_d__504__MoveNext.c:61` —— **只有一个在表现层**，另四个在引擎侧。
        /// 我们这边**没有**「打法变了」这条引擎事件 ⇒ 退一档：**在「攻击 / 技能」事件上按 `(座位,格号)` 比上一次报过的档**，
        /// 不同才响 —— 这正是原版那道闸（`ChangeAttackType` 开头 `if (*(int *)(param_1 + 0x120) != iVar5)`）。</para>
        ///
        /// <para>🔴 **等价物、不是原件**（如实记）：原版是「**写类型那一刻**响」（AI 在动作里先 `ChangeAttackType` 再打），
        /// 我们是「**那个单位下一次动作时**响」—— 对 AI 来说两者相差一个动作内的极短间隔，听感同拍。
        /// ⚠️ 玩家那一下走 `CommitCommand`（点钮即响，与原版同形）⇒ 这里**不会重复响**（调用时就把记忆更新了）。
        /// ⚠️ 记忆键带座位与格号，**换代要清**（`Deploy` / `Death` / `Return` 那三支），否则新单位会被旧值压住。</para></summary>
        public void NoteAttackTypeSound(int side, int slot, int type)
        {
            if (side < 0 || side > 1 || !BoardSpec.IsValid(slot)) return;
            if (type == 0) return;                                  // 0 None 原版不播；3 Spell 原版直接 return（映射回 null）
            int key = side * 16 + slot;
            int was;
            bool known = _attackTypeSoundAt.TryGetValue(key, out was);
            _attackTypeSoundAt[key] = type;
            if (known && was == type) return;                       // **没变就不响**（原版那道闸）
            var f = BattleSfx.ChangeAttackTypeField(type);
            if (f != null) BattleSfx.Play(f);
        }

        /// <summary>「上一次报过的打法档」，键 = `座位 * 16 + 格号`（见 <see cref="NoteAttackTypeSound"/>）。</summary>
        readonly Dictionary<int, int> _attackTypeSoundAt = new Dictionary<int, int>();

        /// <summary>🆕 2026-10-16（`T06` B 组）：**近战攻击命中**那一条（原版 `BattleCardSounds.meleeAttackHit*`）。
        /// 要**批内视野** ⇒ 在 `PlaySignals` 里 drain 之后成批算（同 `unitDamage` 那条的做法）。
        /// 判据与边界 → <see cref="MeleeHitCueCount"/> 的 doc。
        /// 🔴 **2026-10-19（偏差 4）起：这条只留给自检/诊断** —— 生产路径改成「逐条事件到点才响」
        /// （`PlaySignals` 排期时打 `cueMeleeHit` 标记，`PlaySignal` 播）⇒ 这里再调一次会**多响一遍**。</summary>
        public void PlayMeleeHitCues(List<BattleEvent> buf)
        {
            int n = MeleeHitCueCount(buf);
            for (int i = 0; i < n; i++) BattleSfx.Play(BattleSfx.MeleeAttackHitSmall);
        }

        /// <summary>🆕 2026-10-16（`T06` B 组）：**纯函数** —— 这一批里有**几次**该由
        /// `meleeAttackHit*` 负责的近战命中（`0` = 这一批不播）。拆成纯函数是为了**能断言**。
        ///
        /// <para>判据（`资料/普查产出_1016战斗/T06c_B组九条触发点.md`）：原版在**近战攻击动画的命中回调**里播
        /// （`CardScript__ResolveAttackAnimationEffects.c:30-50,64` ← `<AttackMeleeAnim>b__1.c:16`），
        /// 而那一整块**裹在 `meleeHitCameraShakePreset != 0` 里**（我们那一份该字段有值）。</para>
        ///
        /// <list type="bullet">
        /// <item>**只有近战** —— 原版远程那一路不走它（走 `rangedAttackParticlesSO` 那一族）
        ///   ⇒ 判据 = 紧邻的那条 `Attack` 的 `Ranged == false`。</item>
        /// <item>**档位不区分** —— `small/medium/big` 在原版**指向同一个 pathID**（`-3640304923993188049`），
        ///   档位（`SupportMethods.GetUnitSize`）只影响**震动与粒子** ⇒ 一律喊 `MeleeAttackHitSmall`（听感逐位等价）。</item>
        /// <item>**`Amount == 0` 也算**（护盾挡下）—— 原版播的是**动画命中回调**，与掉不掉血无关；
        ///   `Amount &lt; 0` ⇒ 排除 —— 🔴 **2026-10-23 就地订正（铁律 5）**：原来这里写的是
        ///   「`Amount &lt; 0` **是治疗**（`BattleEvent.Hit`）」—— **不成立**：自 2026-10-20（`W58`）起
        ///   治疗走 **`EvtKind.Heal`**，负数 `Hit` 只剩一个含义 = **幸存者广播的标记**
        ///   （判据 → `PlayHitFeel` 开头那一段 / `VfxMap` 里 `W58` 的订正）。
        ///   错因 = 这句写于「负数 Hit 当治疗」那一版口径，换了口径之后**没回来改这里**。
        ///   ⚠️ **行为没变**（排除负数仍然对：广播标记不该算一次近战命中），错的只是理由。</item>
        /// <item>⚠️ **等价物、不是原件**：「哪一条 `Hit` 算攻击命中」我们判的是「**紧跟在一条 `Attack` 后面**」
        ///   —— 与 `UnitDamageCueIndex` **同一条判据**（原版那一位在 `_ResolveAttack` 里、事件里没有）。</item>
        /// </list></summary>
        public static int MeleeHitCueCount(List<BattleEvent> buf)
        {
            if (buf == null) return 0;
            int n = 0;
            for (int i = 0; i < buf.Count; i++) if (IsMeleeHitCueAt(buf, i)) n++;
            return n;
        }

        /// <summary>🆕 2026-10-19（偏差 4）：**第 <paramref name="i"/> 条事件**是不是「近战攻击命中」
        /// （= 该由 `meleeAttackHit*` 响的那一条）。判据见 <see cref="MeleeHitCueCount"/> 的 doc ——
        /// **判据只此一处**（`MeleeHitCueCount` 与 `PlaySignals` 的排期都问它，⛔ 别各写一份）。</summary>
        public static bool IsMeleeHitCueAt(List<BattleEvent> buf, int i)
        {
            if (buf == null || i < 0 || i >= buf.Count) return false;
            var e = buf[i];
            if (e == null || e.Kind != EvtKind.Hit || e.Amount < 0) return false;
            if (i == 0 || buf[i - 1] == null || buf[i - 1].Kind != EvtKind.Attack) return false;
            return !buf[i - 1].Ranged;              // 远程：原版不走这一族
        }

        /// <summary>🆕 2026-10-22（P6 · M1/M2）：**这一批里第 <paramref name="i"/> 条 `Death` 是不是
        /// 「收集灵魂石那一下带出来的残骸消失」**（= 该只播收集粒子、**不播** Destroy 件的那一条）。
        ///
        /// <para>判据（第一权威）= `RemnantAeldari__DoDestroy.c`：`deathType == 50(collectWaystone)`
        /// ⇒ 走 `CollectWaystoneEffect`（收集粒子 + 销毁残骸体），**不**走 `DoDestroyByAttack`；
        /// `RemnantNecrons__DoDestroy` 恒走 `DoDestroyByAttack`（死灵没有收集这一手）。
        /// 我们的引擎在 `RuleCore.CollectWaystoneCore` 里**先发** `EvtKind.CollectWaystone`、
        /// **紧接着** `CleanupDeaths` 发 `EvtKind.Death`（同一个方法、同一格）⇒ **两条必在同一个 drain 批里**。</para>
        /// <para>⚠️ 判据用「**同一批**里有同格 `CollectWaystone`」而不是时间窗 / 棋盘状态 ——
        /// 那个先后关系是引擎代码写死的，比任何时间窗都稳；而棋盘到播的时候已经被补位改过了。
        /// ⛔ 死灵那一族不会有 `CollectWaystone` ⇒ 对它恒假（正是 `DoDestroy` 的分支）。</para>
        /// <para>🔴 **判据只此一处**：`PlaySignals` 用它给 `PendingSignal.collectDeath` 打标，
        /// 之后一路传到 `CardFeel.PickDeathFx` 的 `collectedWaystone`。自检可直接拿合成批调它。</para></summary>
        public static bool IsCollectDeathAt(List<BattleEvent> buf, int i)
        {
            if (buf == null || i < 0 || i >= buf.Count) return false;
            var e = buf[i];
            if (e == null || e.Kind != EvtKind.Death) return false;
            // 同格里有没有那条收集事件（不要求先后 —— 引擎今天就是同一个方法里连着发的）
            for (int k = 0; k < buf.Count; k++)
            {
                var c = buf[k];
                if (c != null && c.Kind == EvtKind.CollectWaystone
                    && c.Player == e.Player && c.Slot == e.Slot) return true;
            }
            return false;
        }

        /// 🆕 2026-09-29（Q 批第 6 条）：**残骸体那三条原版音效**（出现 / 收集 / 被打掉 × 两阵营）。
        /// ⚠️ `public` 是**给自检调**的（批处理里没有帧循环，`PlaySignal` 那条路要走事件泵）——
        ///    自检拿合成事件直接调它，把「哪条事件 → 哪条音效」这层钉住。
        ///
        /// 判据 → `RemnantSfx` 的文件头（六条 cue ↔ 五条 clip 的完整表）。
        /// 🔴 **这里靠的是【棋盘状态】而不是事件字段** —— `BattleEvent` 上**没有**「这是不是残骸」这一项，
        ///    而残骸的 `CardId` 与原卡**是同一个**（引擎里「翻面成残骸」沿用同一个实例）⇒ 光看 CardId 分不出。
        ///    好在状态本身可分：
        ///      · `Death` 且**这一格现在立着残骸** ⇒ 刚**翻面成残骸** ⇒ **出现**
        ///        （引擎 `RuleCore` 那段：`ps.Board[slot] = rem`，事件发出来时棋盘已经换好了）
        ///      · `Death` 且这一格**空了**、而死的那张卡带 `Waystone` / `Remnant` ⇒ 它本来就是残骸、这回真没了 ⇒ **被打掉**
        ///        （同上一段：`IsRemnant` 为真时走 `else` 分支，格子清空、进弃牌堆）
        ///      · `CollectWaystone` ⇒ **收集**（`Slot` = 石头原来那一格）
        /// ⚠️ 阵营判据与 `RemnantPrefabOf` 的关系：🔴 **2026-10-22（B16）起两者不再同一套** ——
        ///    残骸**体**（画哪件 prefab）走逐卡表 `RemnantBodyTable`；这里判「是不是残骸那一族」
        ///    仍按**关键词**（`Waystone` / `Remnant`），因为音效是按族分的，而原版没有逐卡音效表。
        ///    🔴 **2026-10-22（P6）：那条关键词判据已抽成 `CardFeel.IsRemnantFamily`（公开静态，**
        ///    **`out waystone` 表示灵族/死灵两支）—— 这里与 `CardFeel.PickDeathFx` 都调它，⛔ 别再各写一份。**
        /// ⚠️ **两处都缺一行就是静默少一件**（红线） ⇒ 取不到 clip 时 `RemnantSfx.Play` 会出声。
        /// <para>🆕 2026-10-22（P6）：`collectDeath` = 这条 `Death` 是**收集灵魂石**带出来的
        /// （判据 → <see cref="IsCollectDeathAt"/>）⇒ **不播「被打掉」那条 cue** —— 原版
        /// `RemnantAeldari__DoDestroy.c` 在 `deathType == 50(collectWaystone)` 走收集链
        /// （收集 cue 由 `EvtKind.CollectWaystone` 那条事件播），不进 `DoDestroyByAttack`。
        /// 与粒子那一支**共用同一份判据**（⛔ 别一个响一个不响）。</para>
        /// </summary>
        public void PlayRemnantSfx(BattleEvent e, bool collectDeath = false)
        {
            if (e == null || Ctx == null) return;
            if (e.Player < 0 || e.Player > 1) return;

            if (e.Kind == EvtKind.CollectWaystone)
            {
                // 收集：只有灵族有「点石头」这一手（死灵的「收集」是 `reanimate` 效果，不走这个事件）
                RemnantSfx.Play(RemnantSfx.Moment.Collect, true, BoardWorld(e.Player, e.Slot));
                return;
            }
            if (e.Kind != EvtKind.Death) return;

            // 🆕 2026-10-22（P6 · M1/M2）：**收集那一下带出的残骸消失不播「被打掉」那条 cue** ——
            //   原版 `RemnantAeldari__DoDestroy.c` 在 `deathType == 50(collectWaystone)` 时走
            //   `CollectWaystoneEffect`（自己播收集 cue），**不**进 `DoDestroyByAttack`（那里开头才是 `deathSound`）。
            //   判据与粒子同一处（`IsCollectDeathAt`）⇒ 两条表现不会一个响、一个不响。
            if (collectDeath) return;

            var board = Ctx.Players[e.Player].Board;
            var now = BoardSpec.IsValid(e.Slot) ? board[e.Slot] : null;

            if (now != null && now.IsRemnant)
            {
                RemnantSfx.Play(RemnantSfx.Moment.ToRemnant, now.Has(KeywordTable.Waystone),
                                BoardWorld(e.Player, e.Slot));
                return;
            }
            if (now == null && !string.IsNullOrEmpty(e.CardId))
            {
                var card = CardDatabase.Find(_pool, e.CardId,
                                             e.Player == _me ? _myFaction : _foeFaction);
                // 🔴 2026-10-22（P6 · M2/M3）：判「这张是不是残骸那一族」**只此一处** =
                //   `CardFeel.IsRemnantFamily`（关键词 `Waystone` / `Remnant`）。`CardFeel.PickDeathFx`
                //   的「残骸 Destroy 粒子」那一支调的**也是它** —— ⛔ 别在这里再抄一份
                //   `Has(Waystone) || Has(Remnant)`（同一条判据的第二份，迟早不一致）。
                bool waystone;
                if (CardFeel.IsRemnantFamily(card, out waystone))
                    RemnantSfx.Play(RemnantSfx.Moment.Death, waystone,
                                    BoardWorld(e.Player, e.Slot));
            }
        }

        /// <summary>某一格的世界坐标（取那块卡体）—— 取不到就返回 null（`RemnantSfx` 会退成 2D）。</summary>
        Vector3? BoardWorld(int side, int slot)
        {
            if (!BoardSpec.IsValid(slot)) return null;
            var v = BoardViewAt(slot, side == _me);
            return v != null ? (Vector3?)v.transform.position : null;
        }

        /// <summary>🆕 2026-10-22（P6 · M1）：**收集灵魂石那一拍的落点** = 残骸体上的
        /// `Idle / Spirit Stone Idle` 那颗节点的**世界坐标**。
        ///
        /// <para>判据（第一权威）= `RemnantAeldari__CollectWaystoneEffect.c`：`Instantiate(collectParticles +0xf,
        /// GetDeathParticlePosition(), prefab.rotation)`；而 `RemnantAeldari__GetDeathParticlePosition.c`
        /// 取的是 `this + 0x68` 那颗 Transform 的 `position` —— P5 实读那个字段 = **`wayStoneIdle`**，
        /// 落到 prefab 节点 `RemnantBody3D Aeldari / Idle / Spirit Stone Idle`
        /// （localPosition `(0, 1.203, 0)`）。判据 → `资料/普查产出_1022/P5_四未查清.md:139`。</para>
        /// <para>返回 `false` = 视图 / 残骸体 / 那颗节点取不到 ⇒ 调用方（`PlaySignal` 的
        /// `RemnantCollectWorld`）**出声**并退回 `DropTargetWorld`（格心）。</para>
        /// <para>🔴 路径常量只有一处 = <see cref="CardView.RemnantIdleNodePath"/>；本函数是这条**落点判据**
        /// 的唯一实现（`PlaySignal` 与自检都调它 —— ⛔ 别在别处再写一份 `Find("Idle/…")`）。</para></summary>
        public static bool TryRemnantIdleWorld(CardView v, out Vector3 pos)
        {
            pos = default(Vector3);
            Transform node;
            if (v == null || !v.TryGetRemnantNode(CardView.RemnantIdleNodePath, out node) || node == null)
                return false;
            pos = node.position;
            return true;
        }

        /// <summary>`CollectWaystone` 那一拍真正喂给 `FireEventAll` 的落点：
        /// `TryRemnantIdleWorld` 命中就用它，否则**出声**并退回格心（`layout.DropTargetWorld`）。
        /// <para>🔴 **先去 `_fading` 找、再找 `_myUnits/_foeUnits`**（与 `PlayDeathFeel` / `PlayReturnFeel`
        /// 同一个顺序）：连续棋盘里残骸一被收走，**外侧的人当场补位**到同一格号 ⇒ `views[slot]`
        /// 此刻很可能是**邻居那张活卡**，而正在离场的残骸被 `DetachStaleView` 挪进了 `_fading[slot]`
        /// （`PendingExitFor` 认得那条排着队的 `Death`）。⛔ 顺序反了会量到邻居的残骸体。</para></summary>
        Vector3 RemnantCollectWorld(BattleEvent e, BoardLayout layout)
        {
            CardView v;
            if (!FadingMap(e.Player).TryGetValue(e.Slot, out v) || v == null)
                v = BoardViewAt(e.Slot, e.Player == _me);
            Vector3 pos;
            if (TryRemnantIdleWorld(v, out pos)) return pos;
            Debug.LogWarning($"[Battle] 收集灵魂石（{e.Player} 方 · 格 {e.Slot}）：残骸体上取不到 "
                           + $"`{CardView.RemnantIdleNodePath}`（视图 {(v == null ? "没有" : "有")}）"
                           + " ⇒ 落点退回**格心**（`DropTargetWorld`）。原版取 `wayStoneIdle` 的 position"
                           + "（`RemnantAeldari__GetDeathParticlePosition.c`）—— 这不是原版落点，只是不静默");
            return layout.DropTargetWorld(e.Slot);
        }

        /// <summary>🆕 2026-10-19（战斗线 B2 · 偏差 7）：**这条事件该播哪一件【通用】特效**
        /// （`null` = 这条事件没有通用特效，只有手感补间 / 音效 / 词条粒子）。
        /// <para>纯函数（不碰实例状态）—— 拆出来是**为了能断言**（合成一条事件就能验，
        /// 不用跑一局）；`PlaySignal` 是它唯一的生产消费点，⛔ 别在别处再写一份这张映射。</para>
        /// <para>🔴 **`Trigger` 现在回 `null`（偏差 7 的落地）**：原版 `ActivateTriggerTraitAnim`
        /// 只做 `BattleCardUI.HighlightTraitIcon`（徽标脉冲）+ `DisplayTriggerAnim`（状态框），
        /// **没有**任何通用特效；我们原来挂的 `Faith_trigger_unit` 是**原版没有的第二下**。
        /// 判据 → `资料/普查产出_1018/R_战斗表现链路对拍.md` §4 偏差 7。</para></summary>
        public static string GenericVfxFor(BattleEvent e)
        {
            if (e == null) return null;
            switch (e.Kind)
            {
                case EvtKind.Play:    return VfxMap.PlayCard;
                case EvtKind.Deploy:  return VfxMap.Deploy;
                case EvtKind.Attack:  return e.Ranged ? VfxMap.AttackRanged : VfxMap.AttackMelee;
                // 🆕 2026-09-29：**治疗**走另一件（原版 `BattleAnims.heal` → `Healing_Circles`）。
                // 🔴 **2026-10-20（`W58`）就地订正（铁律 5）**：这是一条**独立的治疗事件**
                // （`EvtKind.Heal`）；原来那句「它就是 `Hit` 且 `Amount < 0`」**已过期**。
                // ⚠️ **Syphon（`HealSyphon`）不出治疗圈**：原版 `CardScript._Heal…:201-225` 只在
                //    `HealType.Normal(0)` 实例化 `BattleAnims.heal`，Syphon(1) 只有飘字/音效。
                case EvtKind.Heal:    return e.HealSyphon ? null : VfxMap.Heal;
                // 负数 `Hit` = **幸存者广播**（`BroadcastUnitHealed` 的标记）—— 原版 Survivor
                // 既没有通用命中特效、也没有治疗圈 ⇒ 回 `null`（真正落地的伤害都是正数）。
                case EvtKind.Hit:     return e.Amount < 0 ? null : VfxMap.Hit;
                // 🔴 **阵亡没有「通用事件特效」**（2026-10-01 改）—— 原版阵亡那一下**只有**卡位生成的
                //    `Card 3D Death Explosion`（走 `PlayFeel` → `PlayDeathFeel` → `CardFeel.DeathExplosion`）；
                //    这里原来挂的 `VfxMap.Death`（`Explosion Fenrisian Monstrosities`）是**它的替代品**
                //    （那时那件 prefab 不是 addressable、取不到）。两件同时播 = **原版没有的第二下**。
                //    ⇒ 替代品现在只在**退回分支**里播（效果库里真没有那件时，见 `CardFeel.DeathExplosion`）。
                case EvtKind.Death:   return null;
                case EvtKind.Ability: return VfxMap.Ability;
                // 🔴 偏差 7：原版只有徽标/状态框，**没有通用特效**（见本方法的 doc）。
                case EvtKind.Trigger: return null;
                // 🆕 2026-09-15：这四个原来**结构上就播不出来** —— switch 里没有它们的 case，
                //    落到 `default: return`。见 `VfxMap.ByEvent` 里那四行的出处。
                case EvtKind.Return:     return VfxMap.Return;
                case EvtKind.GainFaith:  return VfxMap.GainFaith;
                case EvtKind.GainSpirit: return VfxMap.GainSpirit;
                case EvtKind.GainQuest:  return VfxMap.GainQuest;
                // 🆕 2026-09-25 收集灵魂石（灵族）：**格位上**那一条（`Slot` = 石头原来那一格）——
                //    ⚠️ 它**不在** `IsResourceUiEvent` 里，走下面普通那条路（按格位取世界坐标）。
                case EvtKind.CollectWaystone: return VfxMap.CollectWaystone;
                // 🆕 2026-10-14（`A1816`）**伏击翻面**（面朝下的 `Ambush` 单位翻开）。
                //    原版那一下接的就是 `AmbushEffect` 一件（判据 → `VfxMap.AmbushExit` 的 doc），
                //    它自己带齐三层（音效 cue `Trait Ambush` / 换卡材质那层动画 / 内部 ps）。
                //    `Slot` = **那个单位还在场上那一格**（`RuleCore.EmitUnit`）⇒ 走下面普通那条路。
                //    ⚠️ 今天两档（`Effect` = `"damage"` / `"attack"`）**播的是同一件** ——
                //      本事件的语义是「这个单位不再面朝下」这个状态迁移，两档都是它。
                //      🔴 **2026-10-20（`W58-LOGFIX`）就地订正（铁律 5）**：原文写 `"damage"` / `"window"` ——
                //      `"window"`（`RuleCore.RevealAmbush`）已删除、是**历史值、今天不可达**
                //      （判据 → `EvtKind.AmbushExit` 的 doc）。
                case EvtKind.AmbushExit: return VfxMap.AmbushExit;
                // 🆕 2026-10-14（`A1816`）**抽卡**。🔴 它的 `Slot` **恒为 -1**（`BattleEvent.Draw` 的 doc）
                //    ⇒ **绝不能走下面那道 `slot < 0 → return`** —— 落点归到「HUD 锚点」那一族
                //      （见 `IsHudAnchoredEvent`，那里也记着为什么它不在 `IsResourceUiEvent` 里）。
                case EvtKind.Draw:       return VfxMap.Draw;
                default: return null;    // 其余（`SecretOrder` 等）没有通用特效
            }
        }

        /// <summary>🆕 2026-10-19（B3 · `T13`）：**把 (卡, 事件) 下的全部权威候选按序播**。
        ///
        /// <para>判据（第一权威）＝原版 `CardAbility.cs:27-29`：「`randomAbilityChoice` 为假
        /// ⇒ **all are triggered in order**」；现读 **1,495/1,496** 为假 ⇒ 同一张卡的同一事件
        /// 本来就可能有好几条 `abilityLogic`，**每一件都要播**。原来这里走
        /// `CardEffects.FireEvent` → `VfxMap.Resolve`（只回**一个**名字）⇒ 现读丢了 **508 个权威
        /// prefab / 375 张卡**（统计 → `资料/普查产出_1019/V2_报告.md` §3·2）。</para>
        ///
        /// <para>⚠️ **`CardEffects` 不在本批白名单**（`Core/` 归别人）⇒ 多名字这一档收在这里：
        /// 名字表由 `VfxMap.ResolveAll` 给（判据只在它那里一份），这里只负责「按顺序各 `Fire` 一次」。
        /// ⛔ **别改回单名字**（那就是本件修的缺陷）。</para>
        /// <para>⚠️ 顺序 = 原版 `abilityLogic` 的数组顺序（`ResolveAll` 的 doc）；**逐候选的错开**
        /// 走 `VfxMap.ResolveAllTimed` 的 `t`（原版串行时长）—— 第 i 件的播放时刻 = `_clock + t[i]`，
        /// 由本方法排进**同一个** `_timeline` 泵（🆕 2026-10-19 · B6；⛔ 不另造调度器、⛔ 不猜固定间隔）。</para></summary>
        void FireEventAll(string evt, Vector3 pos, string faction, string cardId,
                          Transform parent = null, bool perCardOnly = false, string keyword = null)
        {
            var items = VfxMap.ResolveAllTimed(evt, faction, cardId, AnimTimesOf(cardId, faction),
                                               _vfxOffsetRng, perCardOnly, keyword);
            for (int i = 0; i < items.Length; i++)
            {
                if (items[i].T <= VfxTimeEpsilon) CardEffects.Fire(items[i].Name, pos, parent);
                else
                {
                    // 🆕 2026-10-19（T05 · 卡上特效改走挂载）：`parent != null` 时 `pos` 是**局部**点
                    //   （`CardEffects.Fire` → `WarpforgeEffectPlayer.Play(..., parent, localPosition, ...)`）。
                    //   延迟件**不能**带着 parent 排期 —— 到点时那个父件（卡/锚点）可能已经被销毁 ⇒
                    //   `Instantiate(prefab, 销毁的 parent)` 是不可预期行为。⇒ 排期时当场换算成世界点、不挂父件。
                    Vector3 world = parent != null ? parent.TransformPoint(pos) : pos;
                    ScheduleVfxCue(items[i].Name, world, null, null, items[i].T, items[i].Duration);
                }
            }
        }

        /// <summary>🆕 2026-10-19（B3 · `T13`）：多落点版（语义同上 + `CardEffects.Fire` 的数组重载）。
        /// 🆕 B6：同样按 `t` 错开（多落点那一族 = 同批抽卡，候选一般只有一件 ⇒ 行为不变）。
        /// 🆕 2026-10-19（W）：`rng` / `perCardOnly` 与上一重载同口径（见 `VfxMap.ResolveAllTimed` 的 doc）。</summary>
        void FireEventAll(string evt, Vector3[] points, string faction, string cardId,
                          Transform parent = null, bool perCardOnly = false, string keyword = null)
        {
            var items = VfxMap.ResolveAllTimed(evt, faction, cardId, AnimTimesOf(cardId, faction),
                                               _vfxOffsetRng, perCardOnly, keyword);
            for (int i = 0; i < items.Length; i++)
            {
                if (items[i].T <= VfxTimeEpsilon) CardEffects.Fire(items[i].Name, points, parent);
                else ScheduleVfxCue(items[i].Name, Vector3.zero, points, parent, items[i].T, items[i].Duration);
            }
        }

        /// <summary>🆕 2026-10-19（T05 · 「卡上特效改走挂载」的**根实例化**那一档）：把一件**根特效**
        /// 播在**竞技场空间**里。
        ///
        /// <para>为什么需要：原版的登场淡入（`normalSummon`）是**根实例化**
        /// （`CardScript._MinionPlayedIntoField_d__314__MoveNext.c` state 3：`Instantiate(prefab, 卡.transform.position,
        /// prefab.rotation)` —— **不挂父节点、不吃卡的缩放**），原版只有一台相机所以「根」就等于「竞技场画」；
        /// 我们有**两台**（HUD 正交 + 战场透视）⇒ 根特效落在**层 0** 会被 HUD 画，
        /// 一个 prefab 的 1 世界单位在 HUD 上 = 108 px、在战场透视下 ≈ 182 px（我方行）/ 86 px（敌方行）
        /// ⇒ **尺寸与透视全错**（`A367` 那条注记的「位置对、尺度是 HUD 的」就是它）。</para>
        ///
        /// <para>做法 = **临时载体**（层 = `ArenaLayer`、缩放 1、世界位置 = 卡根）当父节点播一次，
        /// 播完立刻把特效摘到世界（<see cref="ReleaseAbilityCarrier"/>）—— 特效保持层 8 与 prefab
        /// 自己的缩放/旋转，与「根实例化」逐项等价。⚠️ 载体只活一帧（同步建/播/摘），
        /// 延迟候选由 <see cref="FireEventAll"/> 换算成世界点、不挂载体。</para></summary>
        void FireDeployVfxInArenaSpace(string evt, BattleEvent e, string faction, bool perCardOnly)
        {
            var layout = e.Player == _me ? playerBoard : enemyBoard;
            Vector3 arena;
            if (!TryArenaCardWorld(e.Player, e.Slot, out arena))
            {
                FireEventAll(evt, layout.DropTargetWorld(e.Slot), faction, e.CardId,
                             parent: null, perCardOnly: perCardOnly);
                return;
            }
            var go = new GameObject("DeployVfxCarrier");
            go.layer = ArenaSlots.ArenaLayer;
            go.transform.position = arena;
            FireEventAll(evt, Vector3.zero, faction, e.CardId, go.transform, perCardOnly);
            ReleaseAbilityCarrier(go.transform);
        }

        /// <summary>🆕 2026-10-19（T05）：**这一格那张卡根的竞技场世界位置** —— 有视图就用视图的
        /// `transform.position`（含飞行/浮动偏移）；视图还没建出来（`Deploy` 那一拍 `SyncBoard` 尚未来得及建）
        /// 就用 `PoseFor` 预测的落位换算到世界。
        /// <para>返回 false = 非 3D 档 / 取不到单位 ⇒ 调用方走老口径（HUD 投影点）。</para></summary>
        bool TryArenaCardWorld(int owner, int slot, out Vector3 world)
        {
            world = Vector3.zero;
            if (!use3DBoard || Ctx == null || owner < 0 || owner >= Ctx.Players.Length || !BoardSpec.IsValid(slot))
                return false;
            var v = BoardViewAt(slot, owner == _me);
            if (v != null) { world = v.transform.position; return true; }
            var u = Ctx.Players[owner].Board[slot];
            if (u == null) return false;
            Vector3 local; float sc;
            PoseFor(owner == _me, slot, u, out local, out sc);
            world = boardRoot != null ? boardRoot.TransformPoint(local) : local;
            return true;
        }

        /// <summary>🆕 **2026-10-24（执行代理 `W15` · `C6` §1·3）**：这一格那张卡的 **`desiredScale`**。
        /// 判据 = `ArenaSlots.CardScale` / `HeroScale`（督军位 = <see cref="ArenaSlots.WarlordSlot"/>，
        /// 或那一格上的单位自称督军）—— 与 <see cref="PoseFor"/> 的 3D 支**同一个口径**。
        /// 用途 = 退路那条根特效的尺度（原版扬尘 `localScale = one × desiredScale` · 攻击件继承卡的 `lossyScale`）。</summary>
        float ArenaCardScale(int owner, int slot)
        {
            bool foe = owner != _me;
            bool warlord = slot == ArenaSlots.WarlordSlot;
            if (!warlord && Ctx != null && owner >= 0 && owner < Ctx.Players.Length && BoardSpec.IsValid(slot))
            {
                var u = Ctx.Players[owner].Board[slot];
                warlord = u != null && u.IsWarlord;
            }
            return warlord ? ArenaSlots.HeroScale(foe) : ArenaSlots.CardScale(foe);
        }

        /// <summary>🆕 **2026-10-24（`W15`）**：这一格的**地面**世界点（`y` = 地面 —— 卡站在地面上）。
        /// <para>判据 = `ArenaSlots.Position`（`y` 恒 0 · 督军位多一个 `heroExtraOffset`）+ `boardRoot` 的位姿；
        /// 与 <see cref="PoseFor"/> 的 3D 支逐项同式（它在本函数结果上 **+ 半个卡高** = 卡根）。
        /// 返回 false = 非 3D 档 / 取不到这一格。</para></summary>
        bool TryArenaGroundWorld(int owner, int slot, out Vector3 world)
        {
            world = Vector3.zero;
            if (!use3DBoard || Ctx == null || owner < 0 || owner >= Ctx.Players.Length || !BoardSpec.IsValid(slot))
                return false;
            Vector3 local = ArenaSlots.Position(slot, owner != _me);
            world = boardRoot != null ? boardRoot.TransformPoint(local) : local;
            return true;
        }

        /// <summary>🆕 **2026-10-24（`W15`）**：这一格的**理想卡根**世界点 —— **不依赖视图/单位**
        /// （卡已经不在盘上了也算得出，退路正是那一档）。
        /// <para>判据 = `ArenaSlots.RootPosition`（= 地面 + `CardUnitH × 0.5 × desiredScale`）+ `boardRoot` 的位姿 ——
        /// 与 <see cref="PoseFor"/> 的 3D 支同式。<paramref name="owner"/>/<paramref name="slot"/> 不合法
        /// 或非 3D 档 ⇒ false（调用方退回 HUD 老口径）。</para></summary>
        bool TryArenaIdealCardWorld(int owner, int slot, out Vector3 world)
        {
            world = Vector3.zero;
            if (!use3DBoard || Ctx == null || owner < 0 || owner >= Ctx.Players.Length || !BoardSpec.IsValid(slot))
                return false;
            Vector3 local = ArenaSlots.RootPosition(slot, owner != _me, ArenaCardScale(owner, slot));
            world = boardRoot != null ? boardRoot.TransformPoint(local) : local;
            return true;
        }

        /// <summary>🔴 **2026-10-24（执行代理 `W15` · 判据 `资料/普查产出_1024c/C6_表现界面轮抽剩余判据.md` §1·3）**：
        /// **「宿主取不到」那两处退路的唯一播放口** ——
        /// <see cref="FireAtAttackAnchor"/> 取不到锚点 / <see cref="PlayDeployLandDust"/> 取不到卡视图。
        ///
        /// <para>**改前**：两处都当 **HUD 平面事件**播（`CardEffects.Fire(name, HUD点)`）⇒ 根特效停在
        /// prefab 自带层（多数攻击件 / 扬尘件是层 **0**）⇒ 由 **HUD 正交相机**画。可它们都是**竞技场事件**
        /// —— 原版 13 个战场逐场实读 `m_CullingMask`：战场透视相机 **1137**、UI 相机 **32**，即
        /// **只有战场相机画层 0**。⇒ 位置与尺度两样全错（HUD 是 108 px/单位，战场透视 ≈182 px/单位）。</para>
        ///
        /// <para>**现在**：3D 档 ⇒ **竞技场世界点 + `ArenaSlots.ArenaLayer`**；
        /// 2D 兜底档（`use3DBoard == false`）或这一格取不到 ⇒ **逐位走老口径**（HUD 投影点 + prefab 自带层）。
        /// 那一档卡本来就活在 HUD 正交平面上，改过去才是错。</para>
        ///
        /// <para>**落点来源**：<paramref name="ground"/> = `true` 用 <see cref="TryArenaGroundWorld"/>
        /// （**地面**，落地扬尘用 —— 原版那句 `landOnGroundParticles` 在卡的世界位置 + `up × 0.015`）；
        /// `false` 用 <see cref="TryArenaCardWorld"/>（**卡根**，攻击件用 —— 与调用方「视图在时喂的
        /// `transform.position`」是同一个点），再退 <see cref="TryArenaIdealCardWorld"/>。
        /// <paramref name="upOffset"/> 只加在竞技场那一档（竞技场世界单位）。
        /// <paramref name="assignScale"/> 见 `WarpforgeEffectPlayer.Play` 的 `assignScale`（扬尘是**赋值**）。</para>
        ///
        /// <para>⚠️ 账记在 <see cref="LastHostFallbackPos"/> / <see cref="LastHostFallbackLayer"/> /
        /// <see cref="LastHostFallbackArena"/> 上（**生产也写**，只有自检读）——
        /// 🧨 把调用方改回 `CardEffects.Fire(name, HUD点)` ⇒ `Editor/CardRootAssert.cs` 那两条红。</para>
        /// <returns>真播出来的实例（竞技场那一档才拿得到句柄；HUD 那一档 `CardEffects.Fire` 不返回）。</returns></summary>
        WarpforgeVFX.WarpforgeEffectPlayer FireHostFallbackVfx(string name, int owner, int slot, Vector3 hudPos,
                                                                bool ground, float upOffset, bool assignScale)
        {
            if (string.IsNullOrEmpty(name)) return null;
            Vector3 arena;
            bool arenaKnown = ground ? TryArenaGroundWorld(owner, slot, out arena)
                                     : TryArenaCardWorld(owner, slot, out arena);
            // 3D 档这一格既没单位也没视图（卡已经不在了）⇒ 用 `ArenaSlots` 那套几何**预测**落点。
            // ⛔ 绝不因为「取不到」就退回 HUD 点 —— 那正是本条要修的那一半。
            if (!arenaKnown && !ground) arenaKnown = TryArenaIdealCardWorld(owner, slot, out arena);

            bool useArena = use3DBoard && arenaKnown;
            int layer = useArena ? ArenaSlots.ArenaLayer : -1;
            Vector3 pos = useArena ? arena + Vector3.up * upOffset : hudPos;

            LastHostFallbackPos = pos;
            LastHostFallbackLayer = layer;
            LastHostFallbackArena = useArena;

            if (!useArena)
            {
                // 老口径**逐位不变**（钩子 / 批处理里的假钩子 / `assignScale` 那条判据全照旧）。
                LastHostFallbackFx = null;
                CardEffects.Fire(name, hudPos);
                return null;
            }
            LastHostFallbackFx = WarpforgeVFX.WarpforgeEffectPlayer.Play(
                name, null, pos, ArenaCardScale(owner, slot), -1f, assignScale, layer);
            return LastHostFallbackFx;
        }

        /// <summary>🆕 2026-10-19（T05 · 同上）：**单件根特效**的竞技场空间版。
        /// <paramref name="hudPos"/> = 老口径（`DropTargetWorld`，非 3D/取不到视图时用）；
        /// <paramref name="arenaPos"/> = 卡根的世界位置（3D 档）。
        /// <para>🔴 **2026-10-21（W61 第 2 批 · 第 2 条）现读：当前【没有调用点】** ——
        /// 它唯一的消费者是「按阵营的召唤法阵」，而那一层已整层删掉（原版没有，见
        /// `Core/VfxMap.cs` 那段注释）。**保留**（不是死代码清理时的漏网）：它是「根特效要进竞技场空间」
        /// 这条通用形状的唯一现成实现，`FireDeployVfxInArenaSpace` 之外再有根特效要进 3D 空间时直接用它，
        /// ⛔ 别另抄一份。要删就**连这条说明一起删**。</para>
        /// <para>🆕 **2026-10-24（`W15`）不是第二份**：<see cref="FireHostFallbackVfx"/> 是「宿主取不到」那两处的
        /// 退路，它要三样这里给不了的东西 —— **显式 `layer`**（`WarpforgeEffectPlayer.Play` 的 `int layer`）、
        /// **根缩放 = `desiredScale`**（扬尘 `assignScale` / 攻击件乘卡的 `lossyScale`）、以及给自检读的**记账格**；
        /// 而本函数是「载体 + `CardEffects` 钩子」那条老形状（层靠父节点继承、没有缩放口）。
        /// ⇒ 两者**用途不同**（本函数留给「已经算得出竞技场点、且不需要缩放/记账」的根特效）。</para></summary>
        void FireRootInArenaSpace(string name, Vector3 hudPos, Vector3 arenaPos)
        {
            if (string.IsNullOrEmpty(name)) return;
            if (!use3DBoard)
            {
                CardEffects.Fire(name, hudPos);
                return;
            }
            var go = new GameObject("ArenaRootFxCarrier");
            go.layer = ArenaSlots.ArenaLayer;
            go.transform.position = arenaPos;
            CardEffects.Fire(name, Vector3.zero, go.transform);
            ReleaseAbilityCarrier(go.transform);
        }


        /// <summary>🆕 2026-10-19（B6）：把一件**延迟特效**排进 `_timeline`（唯一的那个时间线泵）。
        /// <para>判据：原版 `cardAnimations[]` 的每条候选各占一条 `playAnim` 动作、队列**一次弹一条**、
        /// 每条等完 `AnimInfo.GetAnimDuration()` 才结束 ⇒ 候选 i 的起点 = 前面各条的时长之和
        /// （= `CardDef.CardAnimTime.Offset`，由 E12 在数据侧算好）。⛔ 这里**不加**任何固定间隔。</para>
        /// <para>`duration` = 这条候选自己的时长（`CardAnimTime.Duration`）：**队尾与演出闸按
        /// 「起点 + 时长」推** —— 原版队列要等这一拍演完才放行下一条动作，只看起点会让下一批
        /// 事件压在它身上开场（同 `EventTiming.DurationOf` 那条口径）。`0` = 数据里没有时长 ⇒ 只按起点算。</para>
        /// <para>⚠️ 它**不是事件**：`AdvanceTimeline` 弹到它只 `CardEffects.Fire`（见 `PendingSignal.cueVfx`）。</para></summary>
        void ScheduleVfxCue(string name, Vector3 pos, Vector3[] points, Transform parent,
                            float delay, float duration)
        {
            if (string.IsNullOrEmpty(name)) return;
            float at = _clock + Mathf.Max(0f, delay);
            float end = at + Mathf.Max(0f, duration);
            _timeline.Add(new PendingSignal
            {
                at = at, cueVfx = name, cuePos = pos, cuePoints = points, cueParent = parent,
                // 🆕 2026-10-23（`新账-82④`）：把**排期那一刻**的卡上下文一起带下去（见字段 doc）
                cueCtx = _animfxCtx, cueEvt = _animfxLastEvent,
            });
            // 队尾 / 演出闸都要知道「后面还有一拍没演完」—— 否则下一批事件可能插到它前面、闸也可能提前放行。
            _timelineTailAt = Mathf.Max(_timelineTailAt, end);
            if (_blocking) _blockingQuietAt = Mathf.Max(_blockingQuietAt, end);
        }

        /// <summary>🆕 2026-10-23（`新账-82④`）：**播一条延迟 cue 特效**，并在播放期间把
        /// **排期那一刻**的 AnimFX 卡上下文换回去。
        ///
        /// <para>为什么需要：`WFEffectCards.Resolver` / `WFModuleScaleByTarget.CardResolver` /
        /// `WFModuleTween.CardResolver` / `WFModuleCollisions.ContextResolver` 都是**全局静态**、
        /// 读的是「特效**创建那一刻**」的 `_animfxCtx`（见 `HookAnimFxCards` 的 doc）。
        /// 延迟件到点时那个值早就被清成 `default` ⇒ `WFModuleScaleByTarget.Initialize` 拿不到
        /// `actingCard/targetCard`、每条打一行
        /// `[ERROR] Can't find target or acting card in an AnimFXModule of prefab …`
        /// （2026-10-23 真机日志抓到 `BulletImpact_Gordrang`）。</para>
        ///
        /// <para>⚠️ **两个入口共用这一个口**（`AdvanceTimeline` 与单步 `StepOne`）——
        /// 铁律 10 第 5 条：一个对象有多个入口时，状态要在每个入口都带上。</para></summary>
        void FireCueVfx(PendingSignal p)
        {
            var sCtx = _animfxCtx;
            var sEvt = _animfxLastEvent;
            if (p.cueCtx.HasValue) { _animfxCtx = p.cueCtx.Value; _animfxLastEvent = p.cueEvt; }
            try
            {
                if (p.cuePoints != null) CardEffects.Fire(p.cueVfx, p.cuePoints, p.cueParent);
                else                     CardEffects.Fire(p.cueVfx, p.cuePos, p.cueParent);
            }
            finally { _animfxCtx = sCtx; _animfxLastEvent = sEvt; }
        }

        /// <summary>🆕 2026-10-21（W61 第 1 批）：把一记**回调**排进 `_timeline`（与 <see cref="ScheduleVfxCue"/>
        /// 同一条泵、同一个口径 —— 批处理没有帧循环，挂在 `Update` 里就成了「只在一种环境下活」的实现）。
        /// <para>`duration` = 这一拍**演多久**（推进队尾 / 演出闸用；`0` = 只按起点算）。</para>
        /// <para>⚠️ 它**不是事件** —— `AdvanceTimeline` 弹到它只跑这个回调，不重演任何事件级副作用。</para></summary>
        void ScheduleAction(float delay, System.Action act, float duration = 0f)
        {
            if (act == null) return;
            float at = _clock + Mathf.Max(0f, delay);
            _timeline.Add(new PendingSignal { at = at, cueAction = act });
            ExtendTimelineTail(at + Mathf.Max(0f, duration));
        }

        /// <summary>把「队尾 / 演出闸」推到 <paramref name="end"/>（`_clock` 口径）。
        /// 理由同 <see cref="ScheduleVfxCue"/> 末段：只排了起点、不推队尾的话，下一批事件可能插到它前面开场。</summary>
        void ExtendTimelineTail(float end)
        {
            _timelineTailAt = Mathf.Max(_timelineTailAt, end);
            if (_blocking) _blockingQuietAt = Mathf.Max(_blockingQuietAt, end);
        }

        // ==================================================================
        //  🆕 2026-10-21（W61 战斗线「新账-65」第 1 批 · 第 2/3/4 条）
        //  **攻击那一拍的演出**：命中帧 / VFX 发出 / 伤害结算，三件事各在各的时刻、各在各的锚点
        // ==================================================================
        //  原版逐条（`d:/2/tools/decomp_full/`）：
        //   · **近战**：整条动画 0.4 s（位移 0.1 + 转向 0.1 + 停 0.1 + 归位 0.2，
        //     `CardScript._AttackMeleeAnim_d__357__MoveNext.c:130-268`）。
        //     命中帧 = 段1 位移的 OnComplete（`__c__DisplayClass357_0___AttackMeleeAnim_b__1.c:16-27`）：
        //     **同帧** `ResolveAttackAnimationEffects`（震屏 → `SoundManager.Play2D(meleeAttackHit*)` →
        //     `Instantiate(attackHitSmallParticles, **攻方 effectsAnchor.position**, LookRotation(方向))`
        //     + `set_localScale(**攻方卡 localScale**)`，`CardScript__ResolveAttackAnimationEffects.c:26-107`）
        //     + `ReceiveAttackAnim`（后坐）。整条跑完之后 `BroadcastUnitAttacked` → 逐卡 `UnitAttack` 动画
        //     → `ReceiveDamage`（伤害计数器）。
        //   · **远程**：回正 0.1 + 等 0.1（`_ResolveAttackRangedAnim…:80-104`）→ `DelayedVFXPlay`
        //     （先等 `vfxDelayTime`，`_DelayedVFXPlay_d__469:17-27`）→ `CreateAnim`：
        //     位置/父节点 = `GetAnimTransform(startPosOption)`（= 攻方 `effectsAnchor`）、
        //     `CardAnimController.RotateAnim` 把 `transform.forward = end − self`、
        //     缩放继承卡的 `lossyScale`（`CreateAnim.c:55-100` + `RotateAnim.c:130-152`）→
        //     再等 `AnimInfo.GetAnimDuration()` → `ReceiveDamage`。
        //  ⇒ 本方法按这三段排：**命中帧手感**（近战）/ **VFX**（远近各自的时刻）/ 伤害结算交给 `Hit` 事件。
        // ------------------------------------------------------------------

        /// <summary>上一记攻击是不是**远程**（给 `PlayHitFeel` 判「后坐要不要在这一拍再做一次」）。</summary>
        bool _lastAttackRanged;

        /// <summary>🆕 2026-10-23（`新账-78①`）：最近一条 `EvtKind.Attack` **在时间线上落到的时刻**
        /// （= 那条信号被 `PlaySignal` 弹出来时的 `_clock`）。自检拿它当「`Attack + 0.2` 是几点」的锚。
        /// `-1` = 本局还没播过攻击。</summary>
        public float LastAttackEventAtForTest { get { return _lastAttackEventAt; } }
        /// <summary>🆕 2026-10-23（`新账-78①`）：受方 `UnitDamaged` 排期回调被调用的次数
        /// （自检用 —— 只数**排期时刻**，不受 `CardAnimClips` 是否解析出件影响）。</summary>
        public int DefenderDamagedScheduledForTest { get; private set; }
        public void ResetDefenderDamagedScheduledForTest() { DefenderDamagedScheduledForTest = 0; }
        /// <summary>自检用：把上面那个锚清回 `-1`（每段用例前调）。</summary>
        public void ResetLastAttackEventAtForTest() { _lastAttackEventAt = -1f; }
        float _lastAttackEventAt = -1f;

        /// <summary>🆕 2026-10-23（`新账-84`）：**一件攻击特效的起/终锚点**（自检口 + 生产唯一算法）。</summary>
        public struct AttackAnchorPair
        {
            /// <summary>这一件自己的档号（`AnimInfo.startPosOption` / `endPosOption`）。</summary>
            public int StartOpt, EndOpt;
            /// <summary>解析出来的锚点（**载体父节点 = <see cref="Start"/>**）。</summary>
            public Transform Start, End;
            public Vector3 StartPos, EndPos;
            /// <summary>`true` = 这一件的锚点**按它自己那一行**取的；`false` = 缺行 ⇒ 改前的
            /// `self → abilityTarget` 兜底（`Hit` 桶那件通用粒子走这一档）。</summary>
            public bool FromTable;
        }

        /// <summary>🆕 2026-10-23（`新账-84`）：**一件攻击特效的起/终锚点** —— 按【这一件自己】的
        /// `AnimInfo.startPosOption` / `endPosOption` 解析。
        ///
        /// <para>**判据（第一权威）** = `BattleManager._DelayedVFXPlay_d__469__MoveNext.c:46-77`：
        /// 远程攻击那一条对 `startPos` / `endPos` 各调一次
        /// `BattleManager.GetAnimTransform(mgr, animInfo+0x18 / animInfo+0x1c, 攻方卡, 目标卡)` ——
        /// **逐件取**，不是「整条攻击一个锚点」。`CreateAnim.c:62-72` 再把
        /// `Instantiate(prefab, startPos.position, …, **startPos** parent)` 挂上去
        /// ⇒ **载体父节点 = 这一件的 start 锚点**。</para>
        ///
        /// <para>**档号语义**（`BattleManager__GetAnimTransform.c` 现读，只 10 档、其余档 `CustomDebug.LogError`
        /// 后退回行动方督军锚）：`0` = 攻方卡 → `1` / `2` = 目标卡 · `3`/`4` = 双方督军 · `5` = `boardCenter` ·
        /// `14` 空位 · `18` · `19` · `50` / `55` 牌堆。锚点解析统一走 `AnimAnchors.Resolve`
        /// （本仓「判据只此一处」那条口径；`0/1/2` 三档与 `GetAnimTransform` 同义 = self / 目标卡）。</para>
        ///
        /// <para>🔴 **`pointTowardsOption` 在这一条路上【不用】**：`_DelayedVFXPlay:60-65` 把
        /// pointTowards 实参（`+0x50`）直接赋成 **`endPos`** ⇒ 攻击特效的朝向永远是
        /// `LookRotation(endPos − startPos)`（= 我们原来的写法，本条**不动**）。
        /// ⚠️ 技能拍那条路（`PlayAbilityBeat`）走的是 `GetPos(pointTowardsOption)`，**两条路不同**，别互相照搬。</para>
        ///
        /// <para>**缺行怎么办**：`cardAnim` 为空（`Hit` 桶那件通用命中粒子 / 共享兜底件）或表里没这一行
        /// ⇒ **退回改前的 `self → abilityTarget`**（`FromTable = false`；⛔ 不拿别的件的档号顶）。</para>
        ///
        /// <para>现读：`attack_ranged` 的 518 个（卡,件）里 **9 个**不是 `(0,2)`；`attack_melee` 的 12 个里
        /// **8 个**不是（近战这一档原来也被写死成 `self → abilityTarget`）。</para></summary>
        AttackAnchorPair ResolveAttackPieceAnchors(string cardAnim, AnimAnchors.Ctx actx,
                                                   Transform defStart, Vector3 defStartPos,
                                                   Transform defEnd, Vector3 defEndPos)
        {
            var r = new AttackAnchorPair
            {
                StartOpt = (int)PositionOption.self, EndOpt = (int)PositionOption.abilityTarget,
                Start = defStart, StartPos = defStartPos, End = defEnd, EndPos = defEndPos,
                FromTable = false,
            };
            var place = CardAnimClips.PlacementOf(cardAnim);   // null / 空名 ⇒ 回 null 且**不出声**
            if (!place.HasValue) return r;

            r.FromTable = true;
            r.StartOpt = place.Value.StartPos;
            r.EndOpt = place.Value.EndPos;
            var s = AnimAnchors.Resolve((PositionOption)r.StartOpt, actx);
            var t = AnimAnchors.Resolve((PositionOption)r.EndOpt, actx);
            // 取不到那一档（`AnimAnchors` 已经出过声）⇒ 保留调用方给的兜底锚点/坐标
            if (s != null) { r.Start = s; r.StartPos = s.position; }
            if (t != null) { r.End = t; r.EndPos = t.position; }
            return r;
        }

        /// <summary>🆕 2026-10-23（`新账-84`）：**本局每一件攻击特效排期时用的锚点**（自检读它；
        /// 与 `_retaliationPlans` 同一个记账口径 —— 生产也记，只有自检会读）。上限 64 条，
        /// 超过就丢（一局里攻击件不会上百；⛔ 不是行为开关、只是防无界增长）。</summary>
        readonly List<AttackAnchorPair> _attackAnchorPlans = new List<AttackAnchorPair>();
        public int AttackAnchorPlanCount { get { return _attackAnchorPlans.Count; } }
        public AttackAnchorPair AttackAnchorPlanAt(int i) { return _attackAnchorPlans[i]; }
        public void ClearAttackAnchorPlansForTest() { _attackAnchorPlans.Clear(); }
        void RecordAttackAnchorPlan(AttackAnchorPair ap)
        {
            if (_attackAnchorPlans.Count >= 64) return;
            _attackAnchorPlans.Add(ap);
        }

        /// <summary>排一条攻击的演出（近战：命中帧 + 收尾的逐卡特效；远程：VFX 发出那一刻）。
        /// 调用点 = `PlaySignal` 的 `EvtKind.Attack` 那一段（唯一入口）。</summary>
        void ScheduleAttackPresentation(BattleEvent e, string evt, string faction,
                                        bool perCardOnly, string keyword, bool meleeHitCue, int hitAmount)
        {
            var atkView = ViewAt(e.Player, e.Slot);
            var tgtView = ViewAt(e.TargetPlayer, e.TargetSlot);

            // **锚点**（🔴 2026-10-23 · `新账-84` 就地订正：原来这里写「逐卡 `Atk_*` 的 `AnimInfo` 现读
            //   `sp = 0 / ep = 2`」并把两个档号**写死** —— 那句话只对 518 个远程件里的 509 个成立，
            //   另有 **9 个**不是 `(0,2)`、`attack_melee` 的 12 个里也有 **8 个**不是。
            //   现在：**下面这两个只当兜底**（缺行 / 没有 CardAnim 的件用），逐件真值由
            //   `ResolveAttackPieceAnchors` 按该件自己的 `sp/ep` 解析（判据见它的 doc）。
            // ⛔ 判据只此一处 = `AnimAnchors.Resolve`（别在这里自己 switch / 自己取 transform）。
            var actx = new AnimAnchors.Ctx { self = atkView, target = tgtView, actorSeat = e.Player, mySeat = _me };
            Transform start = AnimAnchors.Resolve(PositionOption.self, actx);
            Transform end = AnimAnchors.Resolve(PositionOption.abilityTarget, actx);

            Vector3 startPos = start != null ? start.position
                             : (atkView != null ? atkView.transform.position : Vector3.zero);
            Vector3 endPos = end != null ? end.position
                           : (tgtView != null ? tgtView.transform.position : startPos);
            if (start == null)
                Debug.LogWarning($"[BattleDriver] 攻击特效取不到攻方锚点（槽 {e.Slot} / 座位 {e.Player}）"
                               + " ⇒ 退回卡根、只保留朝向；这一件的**缩放不再继承卡**（原版继承 `lossyScale`）");

            // ① **攻击 VFX**：近战在整条动画收尾（+0.4），远程在 VFX 发出那一刻（+0.2）。
            //    ⚠️ 候选可能有多件、且有各自的组偏移 `T`（`ResolveAllTimed` 的判据）。
            var times = AnimTimesOf(e.CardId, faction);
            var items = VfxMap.ResolveAllTimed(evt, faction, e.CardId, times,
                                               _vfxOffsetRng, perCardOnly, keyword);
            float vfxAt = e.Ranged ? EventTiming.AttackStepRanged : EventTiming.MeleeDamageLag;
            // `WFEffectCards.Resolver` 是**全局静态**、读的是特效**创建那一刻**的 `_animfxCtx`
            // ⇒ 延迟 cue 到点时那个值早就被 `default` 掉了 ⇒ 这里把**排期时**那份上下文带下去。
            // 🔴 **2026-10-23（`新账-82④`）就地修复（铁律 5）**：原来这里抓的是 `_animfxCtx` 字段
            //   —— **抓到的是 `default`**：`_animfxCtx` 只在「播那一刻」被填、播完立刻清成 `default`
            //   （见 `PlayAbilityBeat` / `FireEventAll` 那几处），而**排期这一刻**根本没人填它。
            //   后果 = 所有**延迟到点**的攻击件都拿着一张空上下文去建 AnimFX 模块 ⇒
            //   `WFModuleScaleByTarget.Initialize` 拿不到 `actingCard/targetCard` ⇒ 每次一条
            //   `[ERROR] Can't find target or acting card in an AnimFXModule of prefab …`
            //   （真机日志 2026-10-23 抓到 `BulletImpact_Gordrang`，`Warboss Gordrang` 的远程那一件）。
            //   ⇒ 现在按**这条事件**现建（`BuildCardContext` —— 与 `PlayAbilityBeat` 同一个口；
            //     `Attack` 那一支 = acting 攻方 / target 受方）。
            var capCtx = BuildCardContext(e);
            var capEvt = e;
            for (int i = 0; i < items.Length; i++)
            {
                string nm = items[i].Name;
                // 🆕 2026-10-23（P1 · 演出时序 ⑤）：`CardAnim` 名一起带下去（弹道位移的查表键）。
                // ⚠️ 必须**先拷到局部**再进 lambda —— `for` 的 `i` 不是每轮一份（`foreach` 才是）。
                string an = items[i].Anim;
                // 🆕 2026-10-23（`新账-84`）：**这一件自己的** sp/ep（原版逐件 `GetAnimTransform`）。
                //   缺行 / 没有 CardAnim ⇒ 兜底那对（`self → abilityTarget`，与改前一致）。
                var ap = ResolveAttackPieceAnchors(an, actx, start, startPos, end, endPos);
                RecordAttackAnchorPlan(ap);
                Transform st = ap.Start;
                Vector3 stPos = ap.StartPos;
                Vector3 enPos = ap.EndPos;
                ScheduleAction(vfxAt + Mathf.Max(0f, items[i].T),
                               () => FireAttackVfxWithCtx(nm, an, st, stPos, enPos, capCtx, capEvt));
            }
            // 队尾：整条链按原版**演完**才算完（`CardAnimClips.RangedChainDuration` 用逐件
            // `AnimInfo.GetAnimDuration()` 真值 —— 逐卡 `AnimTimes` → 共享件表 → **按 CardAnim 名查表**；
            // ⚠️ `items[i].Duration` 在「单候选回归口径」下恒 0 ⇒ 不能拿它当队尾）。
            // 🔴 **2026-10-23（P1 · 演出时序 ③）就地修复（铁律 5）：这里原来少了 `_clock +`** ——
            //   同文件另三处（`ScheduleAction` / `ScheduleVfxCue` / `PlayUnitSkillAnim`）都带。
            //   少了它 ⇒ `_clock > 3` 之后算出来的数**恒小于已排的队尾** ⇒ `ExtendTimelineTail` 空操作
            //   （**静默没排队尾**：下一批事件能插到这一件还没演完时开场）。现在走 `AttackVfxTailAt`
            //   那个口（`_clock` 项只此一处，⛔ 别再手写）。
            ExtendTimelineTail(EventTiming.AttackVfxTailAt(_clock, vfxAt,
                                CardAnimClips.RangedChainDuration(evt, faction, e.CardId, times)));

            // ② **命中帧那一拍**（只有近战 —— 原版 `ResolveAttackAnimationEffects` **只**被
            //    `_AttackMeleeAnim` 的 OnComplete 调，`decomp_full` 里没有第二个调用点；
            //    远程那一族没有震屏/命中音/`AttackHitSmall`）。
            if (!e.Ranged)
            {
                bool feel = animateFeel;
                bool cue = meleeHitCue;
                ScheduleAction(EventTiming.HitFrameLag(e), () =>
                {
                    // 🔴 **2026-10-25（`AU1` · `新账 N5`）同帧次序照原版** ——
                    //   原版那一下是 `CardScript.<AttackMeleeAnim>b__1`（
                    //   `CardScript.__c__DisplayClass357_0___AttackMeleeAnim_b__1.c:16-27`）：
                    //   先 `ResolveAttackAnimationEffects(攻方, 目标, pos)`、**之后**才 `ReceiveAttackAnim(受方)`；
                    //   而 `ResolveAttackAnimationEffects` 内部（`CardScript__ResolveAttackAnimationEffects.c:51-107`）是
                    //   **`OverwriteCameraShakePreset.Play()`（震屏）→ `SoundManager.Play2D(命中音)` →
                    //   `Instantiate(命中粒子)` + `set_localScale`**。
                    //   ⇒ **震屏 → 命中音 → 命中粒子 → 后坐**。改前我们的次序是「粒子 → 音 → 后坐 → 震屏」（反的）。
                    //   ⚠️ **震屏不挂在「受击视图还在不在」上**（原版那条由**攻方**的 `CardScript` 触发，
                    //      见上面 `PlayHitFeel` 里同一条判据的注释）—— 改前它跟后坐一起被 `target == null` 挡掉了。
                    if (feel) PlayHitFrameShake();
                    if (cue) BattleSfx.Play(BattleSfx.MeleeAttackHitSmall);
                    // `AttackHitSmall`：位置 = **攻方 effectsAnchor**、朝向 = 目标−攻方、缩放 = 攻方卡
                    // （`ResolveAttackAnimationEffects.c:82-106`：`Instantiate(…, effectsAnchor.position, LookRotation(dir))`
                    //   + `set_localScale(攻方 localScale)`）。
                    // ⚠️ `cardAnim` 传 `null`：`Hit` 桶那件是**通用命中粒子**，没有 `CardAnim`
                    //   ⇒ `ArmAttackVfxMove` 不查表、不位移（`PlacementOf(null)` 也不出声）。
                    FireAttackVfxWithCtx(VfxMap.Resolve(VfxMap.Hit), null, start, startPos, endPos, capCtx, capEvt);
                    if (feel) PlayHitFrameRecoil(e, tgtView, hitAmount);
                });
            }

            // ③ 🆕 2026-10-23（`W63` 收口）→ 🔴 **2026-10-24（执行代理 `B1` · `C2` §1·5 步 E · `D3`）
            //   这一整段【已删】。** 攻方自己的 `UnitAttack(50)` 技能动画不再在这里播，改由
            //   `PlaySignal` 的 `EvtKind.Trigger` 支按 canonical 分流到 `PlayUnitSkillAnim`
            //   （判据与整段说明 → 那一支；时刻基准 → `_batchAttackSkillAnimAt` / `SkillAnimLagOf`）。
            //   【为什么必须搬】原版那一下是 **ability 的一步**（`OnTrigger(50)` → `TriggerAbilities` →
            //   `CardAbility__CanTriggerAbility.c:126-140` → `PlayAbility` → `PlayAnim`）——
            //   写的这一版**不判 ability 是否结算** ⇒ `DA22 Techmarine` 自己攻击时也会播（原版不播），
            //   而 7 张「监听别人的攻击」的卡一条都不播（`TryResolveTriggerPicks` 只看 `trigger`/`ability`
            //   两桶，`unit_attack_anim` 不在合并范围）。
            //   【为什么不能只「再补一条 Trigger 支」】那会和这一条**重复播**（同一击两下）⇒ 只能删。
            //   ⚠️ 时刻公式（近战 `EventTiming.MeleeDamageLag` 0.4 / 远程 `RangedDamageLag`）**一字未变**，
            //     只是搬到 `SkillAnimLagOf`（判据只此一处）。
            //   【改前这段的原始记录（保留痕迹）】原注释：这 13 条**原来被当成近战攻击粒子**播在**受击方**
            //     （`attack_melee` 桶）—— 播的时刻、锚点、属于谁全错
            //     （判据 → `资料/普查产出_1022/W63_飞行与卡ID演出_调查.md` §B）。
            //     ⛔ 也别把它挪回 ①（那是「攻击 VFX」，另一档）。

            // ④ 🆕 2026-10-23（P2 · 演出时序 · `新账-78①`）：**受方的 `UnitDamaged(60)`** 排在
            //    `Attack + AttackWindUp`（0.2）—— 原版 `BattleManager._ResolveAttack_d__438:866`
            //    的 `ResolveAttackDamage` → `BroadcastUnitDamaged` → `CardScript.ResolveDamageDealt:161`
            //    的 `0x3c`，**早于**同 state 里 `:899` 的 `AttackMeleeAnim` / `ResolveAttackRangedAnim`。
            //    我们原来排在 `Hit` 那一拍（= Attack+0.4）⇒ **晚 0.2 s**。
            if (e.TargetPlayer >= 0 && e.TargetSlot >= 0 && !string.IsNullOrEmpty(e.TargetCardId))
            {
                int dSeat = e.TargetPlayer, dSlot = e.TargetSlot;
                string dCard = e.TargetCardId;
                ScheduleAction(EventTiming.AttackWindUp, () => PlayDefenderDamagedAnim(dSeat, dSlot, dCard));
            }
        }

        /// <summary>🆕 2026-10-23（P2 · 演出时序 · `新账-78①`）：**受方的 `UnitDamaged(60)` 技能动画**。
        ///
        /// <para>**判据** = 原版 `BattleManager._ResolveAttack_d__438__MoveNext.c:866`（`ResolveAttackDamage`
        /// 排在 `AttackMeleeAnim` / `ResolveAttackRangedAnim` 起播 `:899` **之前**）→
        /// `BattleManager__ResolveAttackDamage.c:24-31`（`BroadcastUnitDamaged`）→
        /// `CardScript__ResolveDamageDealt.c:161`（`0x3c` = `UnitDamaged`）。⇒ 时刻 = **`Attack + 0.2`**。</para>
        ///
        /// <para>**为什么造一条合成事件**：`PlayUnitSkillAnim` 的入参是「谁挨打」的那条事件
        /// （`Player/Slot/CardId`）。原版这一刻伤害还没结算、`EvtKind.Hit` 还没发 ⇒ 只有攻击事件可用
        /// （它的 `Target*` 正是受方）。`Target*` 留 `-1`：与原来那条 `Hit` 的字段形状**逐位一致**
        /// （`Hit` 不带目标 ⇒ `PlayOneUnitAnim` 走 `MapSelf` 的「这 4 条 `UnitDamaged` 都是自己的效果」那一档），
        /// ⛔ 别把攻击方塞进去（那会改这几条件的锚点）。</para>
        ///
        /// <para>⚠️ **`Amount &lt; 0`（幸存者广播）那一档判不到这里**：攻击事件在伤害之前就发了
        /// （`RuleCore.cs:6042`）、拿不到 amount；而负数 `Hit` 是**另一条**事件（`__UseSurvivor` 直接写血、
        /// 不进 `ReceiveDamage`）⇒ 与攻击不同源。如实记：这一位判据在「攻击」这条路上是空的。</para>
        ///
        /// <para>⚠️ 受方那一刻**没有视图**（已被移走 / 还没建）⇒ `PlayUnitSkillAnim` 直接跳过（不是错）。</para></summary>
        void PlayDefenderDamagedAnim(int seat, int slot, string cardId)
        {
            DefenderDamagedScheduledForTest++;      // 🆕 2026-10-23：自检观察口（排期时刻，不依赖件解析）
            var de = new BattleEvent
            {
                Kind = EvtKind.Hit, Player = seat, Slot = slot, CardId = cardId, Amount = 0,
                // TargetPlayer / TargetSlot 保持默认 -1（见 doc：与原来那条 Hit 同形）
            };
            PlayUnitSkillAnim(de, VfxMap.UnitDamaged, 0f);
        }

        // ==================================================================
        //  🆕 2026-10-22（`W64` · 反击演出）：**守方自己那一发**
        // ==================================================================
        //  判据（第一权威）= `BattleManager._ResolveAttack_d__438__MoveNext.c:1114-1152`：
        //   · 只在**本次打法 = 远程**（`+0x58 == 2`）时守方才 `ResolveAttackRangedAnim(守方, 攻方, 0, 0)`
        //     （`:1119-1131`）；近战打法直接跳到伤害（`:1132-1150`，守方**没有**攻击动画）；
        //   · 那个协程与攻方那一发**完全同一个**（`CardScript._ResolveAttackRangedAnim_d__360__MoveNext.c`）：
        //     回正三条 tween（0.1）+ 等 0.1 + 从**施法者自己的** `effectsAnchor`（`sp = 0 self`）发出、
        //     朝 `abilityTarget`（`ep = 2`）、件 = **施法者自己的** `customRangedAttackParticles`
        //     （`:142-163`；守方就是施法者 ⇒ 用的是守方的卡）。
        //   · 🔴 那一段里**没有** `Play2D` / `AttackHitSmall`（对比同文件哨戒 `:1054`、践踏 `:1112`
        //     都有 `Play2D(ActivateBlast)`）⇒ 反击这一拍**不补**命中音、不补通用命中粒子。
        //   · 🔴 **2026-10-23（P1 · 演出时序 §文档错）就地订正（铁律 5）**：这里原来写
        //     「**「飞行体动画层」今天不存在**（我们没有 `Card3DAnimationController`）…… **缺层**」——
        //     **那句话已过期**：`Battle/Card3DAnimationController.cs` **存在**（`W63` 收口时落的），
        //     自检里 `AnimOfForTest(...).PlayedCount` 已经在证明它跑起来了
        //     （见 `PlayUnitSkillAnim` / `PlayOneUnitAnim` 那一节的文件头）。
        //     **仍然成立的那半句**：**反击这一拍**在原版里也**只**走「回正三条 tween」，
        //     没有额外的一层 3D 体攻击 clip（判据同上 `_ResolveAttackRangedAnim…:80-104`）——
        //     所以这里**不用**补 `DoAnim`，不是「缺层」而是「原版就没有这一层」。
        //     （错因：写这句的时候 `Card3DAnimationController` 还没落地，之后没回来改。）
        // ------------------------------------------------------------------

        /// <summary>反击那一发的**排期计划**（自检口；字段语义见 <see cref="ScheduleRetaliationPresentation"/>）。</summary>
        public struct RetaliationPlan
        {
            /// <summary>守方（播件的那一方）= 事件里的 `Player` / `Slot`。</summary>
            public int Owner, Slot;
            /// <summary>守方卡名 / 阵营（解析逐卡件的键）。</summary>
            public string CardId, Faction;
            /// <summary>攻方（件的朝向目标）= 事件里的 `Target*`。</summary>
            public int TargetOwner, TargetSlot;
            /// <summary>是否远程档（= **本次打法**，判据见 `EvtKind.Retaliation` 的 doc）。</summary>
            public bool Ranged;
            /// <summary>排期时**真正取到的**锚点属于谁（`-1` = 没取到 / 不是守方的 ⇒ 那就是错的）。</summary>
            public int AnchorOwner, AnchorSlot;
            /// <summary>解出来的件名（= `VfxMap.ResolveRangedAttackPieces` 那**三层链**的结果：
            /// 逐卡 → `RangedAttackParticlesByClan`（守方 clan）→ SO 第一条）。**空**理论上不会出现
            /// （最后一层恒有件）；真为空只可能是表被改坏了 —— 那时这一发不播、并已在别处如实登记。</summary>
            public string[] Vfx;
            /// <summary>相对事件起播的时刻（秒）。</summary>
            public float At;
            /// <summary>这一发占多久（秒，含 `AttackStepRanged` 前摇）。</summary>
            public float Duration;
        }

        readonly List<RetaliationPlan> _retaliationPlans = new List<RetaliationPlan>();
        /// <summary>「守方那一刻没有视图」的出声去重（按 (座位,格号)；⛔ 不刷屏，也⛔ 不静默）。</summary>
        readonly HashSet<int> _retaliationNoViewWarned = new HashSet<int>();
        /// <summary>自检用：本局排过几次「反击演出」（生产路径 = 每条 <see cref="EvtKind.Retaliation"/> 一次）。</summary>
        public int RetaliationPlanCount { get { return _retaliationPlans.Count; } }
        /// <summary>自检用：第 <paramref name="i"/> 条反击计划（见 <see cref="RetaliationPlan"/>）。</summary>
        public RetaliationPlan RetaliationPlanAt(int i) { return _retaliationPlans[i]; }
        /// <summary>自检用：清空记录（每段用例前调，避免跨用例串账）。</summary>
        public void ClearRetaliationPlansForTest() { _retaliationPlans.Clear(); }

        /// <summary>算一条反击计划（**纯函数**：不排 cue、不动时间线）—— 唯一入口 = 排期那一段，
        /// ⛔ 别在别处再算一份（那会变成两张表）。</summary>
        /// <param name="e">那条 `EvtKind.Retaliation`（守方 = `Player/Slot`、攻方 = `Target*`）。</param>
        /// <param name="items">解出来的候选（`T` = 组内起点偏移）—— 走 `VfxMap.ResolveRangedAttackPieces`
        /// 那条**三层链**（逐卡 → clan → SO 第一条）；近战档恒空。</param>
        RetaliationPlan PlanRetaliation(BattleEvent e, out VfxMap.ResolvedVfx[] items)
        {
            var plan = new RetaliationPlan
            {
                Owner = e.Player, Slot = e.Slot, CardId = e.CardId,
                TargetOwner = e.TargetPlayer, TargetSlot = e.TargetSlot,
                Ranged = e.Ranged, AnchorOwner = -1, AnchorSlot = -1,
                Vfx = new string[0],
            };
            items = new VfxMap.ResolvedVfx[0];
            if (e.Player == _me) plan.Faction = _myFaction; else plan.Faction = _foeFaction;

            // 近战档：原版守方**没有**攻击动画、也没有粒子（`:1132-1150`）⇒ 计划是空的、
            // 但**照记一条**（自检要能区分「近战档本来就没有」与「漏接了」）。
            if (!e.Ranged) return plan;

            // 件 = **原版那条三层链**（`_ResolveAttackRangedAnim…:142-163`）：
            //   ①**守方自己的** `customRangedAttackParticles` → ②`RangedAttackParticlesByClan`（守方 clan）
            //   → ③**SO 第一条**（= `BulletImpact_2shot_trail`，我们 `ByEvent[AttackRanged]` 就是它）。
            // 🔴 **2026-10-22（`W64` 补做，铁律 11）：上一版这里是 `perCardOnly: true`（只用逐卡件）** ——
            //   **错**：原版 `:151-163` 明写 `HasCustomRangedAttackParticles == 0` 就退到 clan 件
            //   （`RangedAttackParticlesByClanSO__GetRangedClanParticles`，查不到再回 SO 第一条）——
            //   「没有就空着」**不是原版**。判据全文与三层对照 → `VfxMap.ResolveRangedAttackPieces` 的 doc。
            //   ⚠️ 普通攻击那条路走的是 `ResolveAllTimed(..., perCardOnly:false)`（`ScheduleAttackPresentation`），
            //   **早就是同一条链** ⇒ 反击与攻击这一档从此同源；⛔ 别把任何一边改成 `perCardOnly:true`。
            var times = AnimTimesOf(e.CardId, plan.Faction);
            items = VfxMap.ResolveRangedAttackPieces(plan.Faction, e.CardId, times, _vfxOffsetRng);
            var names = new string[items.Length];
            for (int i = 0; i < items.Length; i++) names[i] = items[i].Name;
            plan.Vfx = names;

            // 锚点归属（结构判据，自检用）：`self` 档解析出来的 transform 必须挂在**守方那张卡**下面。
            // ⚠️ 守方视图不在时**不去探**（`AnimAnchors` 那条 `Missing` 会出声 —— 那个案子的声音
            //    已经由 `ScheduleRetaliationPresentation` 发一次，别在这儿再刷一遍）。
            var defView = ViewAt(e.Player, e.Slot);
            if (items.Length > 0 && defView != null)
            {
                var atkView = ViewAt(e.TargetPlayer, e.TargetSlot);
                var actx = new AnimAnchors.Ctx { self = defView, target = atkView, actorSeat = e.Player, mySeat = _me };
                var anchor = AnimAnchors.Resolve(PositionOption.self, actx);
                if (anchor != null
                    && (anchor == defView.transform || anchor.IsChildOf(defView.transform)))
                {
                    plan.AnchorOwner = e.Player;
                    plan.AnchorSlot = e.Slot;
                }
            }

            plan.At = EventTiming.AttackStepRanged;
            // 时长**只此一处** = `EventTiming.DurationOf(BattleEvent)` → `RetaliationHoldOf`
            // （它用挂钩的「座位→阵营 / 卡名→AnimTimes」现算；⛔ 别在这里再算一份）。
            if (items.Length > 0) plan.Duration = EventTiming.DurationOf(e);
            return plan;
        }

        /// <summary>排一条反击的演出：**守方锚点 + 守方那件件**（唯一入口 = `PlaySignal` 的
        /// `EvtKind.Retaliation` 那一段）。判据见本节头注。
        /// <para>"那件件" = 原版那条三层链（逐卡 → clan → SO 第一条），见 `VfxMap.ResolveRangedAttackPieces`。</para>
        /// <para>⚠️ 近战档**什么都不排**（原版守方不播；攻方挨那一下的反应用它自己的 `Hit`）。
        /// 但两种档都记一条 <see cref="RetaliationPlan"/>，自检才能证明「近战档是有意不播」。</para></summary>
        void ScheduleRetaliationPresentation(BattleEvent e)
        {
            VfxMap.ResolvedVfx[] items;
            var plan = PlanRetaliation(e, out items);
            _retaliationPlans.Add(plan);
            if (!e.Ranged || items.Length == 0) return;

            var defView = ViewAt(e.Player, e.Slot);
            var atkView = ViewAt(e.TargetPlayer, e.TargetSlot);
            // 🔴 **守方那张卡已经没有视图 ⇒ 这一发不排**（不许喂 `Vector3.zero` 把特效打在原点）。
            //   什么时候会发生：守方在同一批里先被别的伤害打死、且它那条 `Death` 排得更早
            //   （原版那一刻卡对象还在、只是要消散；我们这边视图已被摘走）。**出声、⛔ 不静默**。
            //   ⚠️ 常见局面**不会**走到这里：主伤害 `Hit` 只掉血，死亡演出排在时间线更晚（见 `DetachStaleView`）。
            if (defView == null)
            {
                if (_retaliationNoViewWarned.Add(e.Slot + 16 * e.Player))
                    Debug.Log($"[BattleDriver] 反击：守方 P{e.Player + 1}@槽{e.Slot} 这一刻**没有视图**"
                            + "（多半是它已被打死、阵亡演出排在更早）⇒ 这一发不播（原版是从那张卡发出的）");
                return;
            }
            var actx = new AnimAnchors.Ctx { self = defView, target = atkView, actorSeat = e.Player, mySeat = _me };
            Transform start = AnimAnchors.Resolve(PositionOption.self, actx);
            Transform end = AnimAnchors.Resolve(PositionOption.abilityTarget, actx);
            Vector3 startPos = start != null ? start.position
                             : (defView != null ? defView.transform.position : Vector3.zero);
            Vector3 endPos = end != null ? end.position
                           : (atkView != null ? atkView.transform.position : startPos);

            // ① **守方卡自己的远程攻击动画**：原版那个协程的 state 0 是「回正三条 tween」
            //    （`DOLocalMove(handHomePos)` + `DORotateQuaternion(identity)` + `DOScale(DefaultScale)`，
            //    时长 `attackStepTime` = 0.1）⇒ 与攻方远程那一支**复用同一个口**
            //    （`PlayAttackFeel` 的 `e.Ranged` 分支调的就是它）。
            //    ⚠️ 只做这一档：3D 体自己的攻击 clip（原版 `Card3DAnimationController.DoAnim`）见下一节的 doc
            //      （**已实现**，2026-10-23 订正了这句过期注释）。
            // 🆕 2026-10-23（`新账-82①`）：`isPlayer` 显式传 —— 守方 = 这条事件的 `Player`
            //   （`RetaliationPlan.Owner` 的 doc 写的就是「守方 = 事件里的 `Player`」）。
            if (animateFeel && defView != null)
                CardFeel.AttackRecover(defView.transform, defView.transform.localPosition,
                                       defView.transform.localScale.x, isPlayer: e.Player == _me);

            // ② 件：**从守方 `effectsAnchor` 发出、朝攻方**（`FireAtAttackAnchor` = `CreateAnim` 的
            //    最小等价物：挂载点 + 世界朝向 + 继承卡尺度）。⚠️ 复用攻方那条实现，⛔ 别另写一份。
            // 🔴 2026-10-23（`新账-82④`）：与攻方那一处**同一个缺陷**（原来抓的是 `default` 上下文）⇒
            //   现在按这条 `Retaliation` 事件现建（`BuildCardContext` 对 `Retaliation` 走 Attack 同一支：
            //   acting = 守方、target = 攻方）。
            var capCtx = BuildCardContext(e);
            var capEvt = e;
            for (int i = 0; i < items.Length; i++)
            {
                string nm = items[i].Name;
                // 🆕 2026-10-23（P1 · 演出时序 ⑤）：守方那一发与攻方**同一个协程** ⇒ 同样带 `CardAnim`
                // （弹道位移的查表键；`for` 的 `i` 不是每轮一份 ⇒ 先拷局部）。
                string an = items[i].Anim;
                // 🆕 2026-10-23（`新账-84`）：逐件 sp/ep —— 与攻方那一发**同一个口**
                // （原版守方走的就是 `_ResolveAttackRangedAnim` → 同一条 `DelayedVFXPlay`）。
                var ap = ResolveAttackPieceAnchors(an, actx, start, startPos, end, endPos);
                Transform st = ap.Start;
                Vector3 stPos = ap.StartPos;
                Vector3 enPos = ap.EndPos;
                float at = plan.At + Mathf.Max(0f, items[i].T);
                ScheduleAction(at, () => FireAttackVfxWithCtx(nm, an, st, stPos, enPos, capCtx, capEvt));
            }
            // 队尾 = **绝对时刻**（`_clock` 口径）：这一发演完之前别让下一批事件插到它前面开场。
            ExtendTimelineTail(_clock + plan.Duration);
        }

        /// <summary>🆕 2026-10-21（W61 第 1 批）：**带卡上下文**播一件攻击特效。
        /// <para>为什么需要：`WarpforgeVFX.WFEffectCards.Resolver` 是**全局静态**、读的是特效
        /// **创建那一刻**的 `_animfxCtx`（见 `Begin` 里 `HookAnimAnchors` 那一带的挂钩），
        /// 而本批把这些件改成了**延迟 cue** ⇒ 到点时上下文早被 `default` 掉了。
        /// ⇒ 这里把**排期时**那一份临时换回去、播完还原。</para>
        /// <para>🆕 **2026-10-23（P1 · 演出时序 ⑤）**：多了 <paramref name="cardAnim"/> —— 这一件的
        /// `CardAnim` 名（`ResolvedVfx.Anim`）。`FireAtAttackAnchor` 要拿它查 `AnimInfo` 的弹道参数
        /// （`shouldMoveVFX` / `timeAtStartPos` / `timeMoving`）。传 `null` / 空 = 这一件没有 `CardAnim`
        /// （例如 `Hit` 桶那件通用命中粒子）⇒ 不位移。</para></summary>
        void FireAttackVfxWithCtx(string name, string cardAnim, Transform anchor, Vector3 anchorPos, Vector3 targetPos,
                                  WarpforgeVFX.WFEffectCardContext ctx, BattleEvent evt)
        {
            var sCtx = _animfxCtx;
            var sEvt = _animfxLastEvent;
            _animfxCtx = ctx;
            _animfxLastEvent = evt;
            try
            {
                // `evt` = 这一发所属的那条事件（攻方 / 守方各一条）—— 退路要靠它的 `Player/Slot` 算竞技场点。
                FireAtAttackAnchor(name, cardAnim, anchor, anchorPos, targetPos,
                                   evt != null ? evt.Player : -1, evt != null ? evt.Slot : -1);
            }
            finally { _animfxCtx = sCtx; _animfxLastEvent = sEvt; }
        }

        /// <summary>把一件特效播在**攻方锚点**上、朝目标（原版 `CreateAnim` 那条路的最小等价物）。
        /// <para>做法 = **载体**：挂在攻方 `effectsAnchor` 下（⇒ 位置 = 锚点、世界缩放继承卡的 `lossyScale`，
        /// 与原版 `Instantiate(prefab, startPos, rot, startParent)` 等价），把载体的**世界朝向**设成
        /// `LookRotation(目标 − 锚点)`，播完立刻把特效摘到世界（`ReleaseAbilityCarrier`）。</para>
        /// <para>⚠️ 取不到锚点（没有视图）时退回「根特效 + 世界点」，并已由调用方出过声。</para>
        /// <para>🔴 **2026-10-24（执行代理 `W15` · `C6` §1·3）就地修正**：这条退路原来是
        /// `CardEffects.Fire(name, anchorPos, null)` —— **根特效 + prefab 自带层**（那批攻击件多是层 0）
        /// ⇒ 由 **HUD 正交相机**画，而它是**竞技场事件**（原版那台透视相机才画层 0，13 场逐场实读
        /// `m_CullingMask` = 1137 / 32）。现在 3D 档改成 **竞技场世界点 + `ArenaLayer`**（见
        /// <see cref="FireHostFallbackVfx"/>）；2D 兜底档仍逐位走老口径。</para>
        /// <para>🆕 **2026-10-23（P1 · 演出时序 ⑤ · `新账-77④`）**：这一件若带 `shouldMoveVFX`
        /// （`AnimInfo` 的 `mv=1` 且 `timeMoving &gt; 0`）⇒ **不再当场释放载体**，改由
        /// <see cref="ArmAttackVfxMove"/> 排进 <see cref="TickAbilityVfxMoves"/> 那条**现成的位移泵**
        /// （与技能拍 `PlayAbilityBeat` 用的是同一个泵）。判据见 `ArmAttackVfxMove` 的 doc。</para></summary>
        /// <param name="owner">这一发属于哪一方（`-1` = 不知道 ⇒ 退路只能走老口径）。</param>
        /// <param name="slot">这一发从哪一格发出（同上）。</param>
        void FireAtAttackAnchor(string name, string cardAnim, Transform anchor, Vector3 anchorPos, Vector3 targetPos,
                                int owner = -1, int slot = -1)
        {
            if (string.IsNullOrEmpty(name)) return;
            if (anchor == null)
            {
                // ⚠️ `anchorPos` 是**调用方的兜底点**（视图在时 = 卡根世界位、视图不在时 = `Vector3.zero`）；
                //   3D 档由 `FireHostFallbackVfx` 换成**按格现算的竞技场卡根**，2D 档逐位沿用 `anchorPos`。
                FireHostFallbackVfx(name, owner, slot, anchorPos, ground: false, upOffset: 0f, assignScale: false);
                return;
            }
            // 锚点层校准（`EffectAnchorBoard` 是**懒建**的 ⇒ 可能停在层 0，而特效的层是**跟直接父节点**
            // 继承的 —— 见 `EnsureAnchorSpace` 的 doc）。判据只此一处。
            EnsureAnchorSpace(anchor);
            var go = new GameObject("AttackVfxCarrier");
            go.layer = anchor.gameObject.layer;             // 卡在竞技场层 ⇒ 特效也归那台相机画
            var carrier = go.transform;
            carrier.SetParent(anchor, false);
            carrier.localPosition = Vector3.zero;
            carrier.localRotation = Quaternion.identity;
            carrier.rotation = AttackVfxRotation(anchor.position, targetPos);   // 世界朝向（原版 `set_forward`）
            CardEffects.Fire(name, Vector3.zero, carrier);  // `parent != null` ⇒ `pos` 是**局部**点
            if (!ArmAttackVfxMove(carrier, cardAnim, anchor.position, targetPos))
                ReleaseAbilityCarrier(carrier);
        }

        /// <summary>🆕 **2026-10-23（P1 · 演出时序 ⑤ · `新账-77④`）：给攻击 / 反击那一件挂上【弹道位移】。**
        ///
        /// <para>**判据（第一权威）** = `CardAnimController__Initialize.c` + `CardAnimController__Update.c:36-97`：</para>
        /// <list type="bullet">
        /// <item>`Initialize`：`if (!shouldMoveVFX) { enabled = 0; }` —— **不飞时整条控制器关掉**，
        ///   特效就停在起锚点（我们这边 = 当场 `ReleaseAbilityCarrier`，与改前逐字一致）；</item>
        /// <item>飞的时候 `if (start == end) enabled = 0`（同一个位置 ⇒ 也不飞）；</item>
        /// <item>`Update`：`t01 = (elapsed − ts) / tm`，只在 `[0,1)` 里写位置
        ///   `lerp(startPos, endPos, easeCurve(t01))`；`t01 ≥ 1` 之后**不再写**（停在终点）。
        ///   ⇒ 我们的 <see cref="TickAbilityVfxMoves"/> 就是这个形状（`t01 ≥ 1` 时写 `end` 再释放载体）。</item>
        /// </list>
        ///
        /// <para>**参数从哪来**：`CardAnimClips.PlacementOf(cardAnim)`（= `Resources/cardanim_clips.json`，
        /// 键 = **`CardAnim` 名**，⛔ 不是 prefab 名 —— 215 组同名不同参）。现读全池
        /// `attack_ranged` 的 **518** 个（卡,件）组合里 **32 个**带 `mv=1 &amp;&amp; tm &gt; 0`
        /// （`Manticore` / `Night Spinner` / Grot 家族 / `Rokkit Boy` / `Whirlwind` / `Exorcist` /
        /// `Sun Shark Bomber` …），另加 `attack_melee` 的 **1 个**（`Techmarine` 的
        /// `Healing_Volley_Effect`，`sp 0 → ep 2`）。</para>
        ///
        /// <para>🆕 **2026-10-23（`新账-83`）已补齐 `AnimInfo` 的三列**（原来这里写着「本批没做」）：
        /// ① `easeCurve` —— 32/33 线性，唯一例外 `Jain Zar / Atk_JainasMor_Throw_Return`
        ///   （`0→1`@0.4 · 持到 0.6 · `→0`@1.0 = **飞出去再飞回来**）；
        /// ② `applyMovementOffsets` + `offsetMovementAxis` —— 33 件里 **26 件为 1**、其中 **22 件带非零弧线**
        ///   （21 件 y 轴抛物线 + `Jain Zar` 的 x 轴；例 `Atk_GrotGrenade` y 弧 **2.5**、
        ///   `Atk_BulletImpact_Ork Missile Big` **3.0** = **手雷/导弹的抛物线**）；
        /// ③ `orientToVelocity` —— **22/33 为 1**，原版移动期间每帧转向速度方向。
        ///   三者现读都已在 `cardanim_clips.json`（生成器 `工具/gen_cardanim_clips.py` 2026-10-23 起烘）。</para>
        ///
        /// <returns>`true` = 已排进位移泵（载体由泵在终点释放）；`false` = 这一件不飞（调用方当场释放载体）。</returns>
        bool ArmAttackVfxMove(Transform carrier, string cardAnim, Vector3 start, Vector3 end)
        {
            if (carrier == null) return false;
            // `PlacementOf(null/空)` 直接回 null（**不出声** —— 那一档是「这一件本来就没有 `CardAnim`」，
            // 例如 `Hit` 桶那件通用命中粒子；真缺行的那种会在 Resolve 那一侧就已经报过 warning）。
            var place = CardAnimClips.PlacementOf(cardAnim);
            if (!place.HasValue) return false;
            var p = place.Value;
            if (!p.Move || p.Tm <= 0f) return false;                       // `Initialize`：不飞 ⇒ 控制器关掉
            if ((end - start).sqrMagnitude <= 1e-8f) return false;         // `Initialize`：`start == end` ⇒ 也不飞
            _abilityVfxMoves.Add(new AbilityVfxMove
            {
                carrier = carrier, start = start, end = end, ts = p.Ts, tm = p.Tm,
                ease = p.Ease, t = 0f,
                // `applyMovementOffsets` 的三轴弧线（`CardAnimPlacement` → 摊平进载体，与技能拍同一个泵）
                ao = p.OffsetAo ? 1 : 0, ont = p.OffsetOnt ? 1 : 0,
                ofx = p.Ofx, ofy = p.Ofy, ofz = p.Ofz,
                randomAmp = RandomOffsetAmp(p.OffsetAo ? 1 : 0, p.Mnx, p.Mxx, p.Mny, p.Mxy, p.Mnz, p.Mxz),
                otv = p.OrientToVelocity,
                lastPos = start,
            });
            return true;
        }

        /// <summary>🆕 2026-10-21（W61 第 1 批 · 第 3 条）：攻击特效朝目标的方向 ——
        /// 原版 `CardAnimController.RotateAnim` 的非督军那一支：`transform.set_forward(end − self)`
        /// （`CardAnimController__RotateAnim.c:130-152`）⇒ 等价于 `Quaternion.LookRotation(方向)`。
        /// 两点重合时退 `identity`（`LookRotation(0)` 在 Unity 会**报错**，原版 `set_forward(0)` 保持原朝向）。</summary>
        public static Quaternion AttackVfxRotation(Vector3 from, Vector3 to)
        {
            Vector3 d = to - from;
            if (d.sqrMagnitude < 1e-8f) return Quaternion.identity;
            return Quaternion.LookRotation(d.normalized, Vector3.up);
        }

        /// <summary>命中帧那一拍的**震屏**（只有近战）。
        /// <para>🔴 **2026-10-25（`AU1` · `新账 N5`）：命中帧拆成「震屏」+「后坐」两个口** —— 原版它们之间
        /// 还夹着命中音与命中粒子，而且**震屏不依赖受击方视图是否存在**。判据 =
        /// `CardScript.__c__DisplayClass357_0___AttackMeleeAnim_b__1.c:16-27`（先
        /// `ResolveAttackAnimationEffects`、再 `ReceiveAttackAnim`）＋
        /// `CardScript__ResolveAttackAnimationEffects.c:51-107`（`SetDirection` → `SetAmplitude` →
        /// **`Play()` 震屏** → `Play2D(命中音)` → `Instantiate(命中粒子)`）。</para>
        /// <para>🔴 改前它与**后坐**共用一个 `if (target == null) return;` ⇒ 受击方视图不在
        /// （那一格已经空了 / 还没建）时**连震屏也一起没播**；而原版这条是**攻方**的 `CardScript` 触发的、
        /// 与「被打的视图还在不在」无关（同一条判据 → `PlayHitFeel` 里「震镜头放在 `v != null` 外面」那段）。</para>
        /// <para>⚠️ 只在 `animateFeel` 开着时排（批处理自检要**当场**精确坐标 —— 与 `PlayFeel` 同一条口径）。</para></summary>
        void PlayHitFrameShake()
        {
            CardFeel.ShakeCameraForHit(cam, hudRoot, _lastAttackerMelee, 0f, boardCam);
        }

        /// <summary>命中帧那一拍的**后坐**（只有近战）—— 原版 `ReceiveAttackAnim`，
        /// 排在震屏 / 命中音 / 命中粒子**之后**（`<AttackMeleeAnim>b__1.c:27`）。
        /// 方向 = `normalize(受击方 − 攻击方)`（见 `CardFeel.PushBackDir` 的 doc）；
        /// `away` 只剩「这条事件里取不到攻击方视图」时的退路（`CardFeel` 会出声）。</summary>
        void PlayHitFrameRecoil(BattleEvent e, CardView target, int hitAmount)
        {
            if (target == null) return;
            Vector3 away = e.Player == _me ? Vector3.down : Vector3.up;
            var attacker = ViewAt(e.Player, e.Slot);
            CardFeel.HitReactFrom(target.transform, attacker != null ? attacker.transform : null, away,
                                  Mathf.Abs(hitAmount) >= CardFeel.HeavyHitDamage, 0f, _lastAttackerMelee);
        }

        /// <summary>`t` 小到什么程度就当成「与事件同一拍」（浮点防御）。
        /// 依据：数据侧的 `t` 是**若干已给定时长之和**，合法取值要么是 0，要么 ≥ 0.05 s
        /// （现读最小非零 `t` 是 0.1 s）⇒ 1e-3 不会把真实的错开吞掉。</summary>
        const float VfxTimeEpsilon = 1e-3f;

        /// <summary>🆕 2026-10-19（B6）：这张卡的**逐候选动画时间**（`CardDef.AnimTimes`）。
        /// null = 没有这张卡 / 这张卡没有 `animTimes` ⇒ 消费端全部 `T = 0`（= 改前的行为）。</summary>
        IReadOnlyList<CardDef.CardAnimTime> AnimTimesOf(string cardId, string faction)
        {
            if (_pool == null || string.IsNullOrEmpty(cardId)) return null;
            var card = CardDatabase.Find(_pool, cardId, faction);
            return card != null ? card.AnimTimes : null;
        }

        /// <summary>🆕 2026-10-21（W61 第 1 批 · 第 2 条）：`e` 是 `Hit`、`prev` 是它前面那条**远程** `Attack`
        /// ⇒ 返回这一击 VFX 自己演多久（`EventTiming.DelayBetween` 的第三参）；其余组合 ⇒ **-1**（= 没传）。
        /// <para>🔴 **2026-10-23（P1 · 演出时序 ④）**：改走 `CardAnimClips.RangedChainDuration` ——
        /// 三档：逐卡 `CardAnimTime.Duration` → 共享件表 → **按 `ResolvedVfx.Anim`（CardAnim 名）查
        /// `cardanim_clips.json`**（原版 = 逐件 `AnimInfo.GetAnimDuration()`，四字段直加）。
        /// 这第三档是**伤害时刻**这条链的修复点：原来 441 个（卡,件）组合都落回 0.75 兜底
        /// （265 个真值 ≠ 0.75，极端 −2.85 s）。</para>
        /// <para>判据 = `VfxMap.ChainDuration`（前两档）＋ <see cref="CardAnimClips.RangedChainDuration"/>
        /// （补齐第三档）。返回 **≥ 0 = 真值**（0 也是真值）、**-1 = 判据为空**。
        /// ⚠️ 阵营取**攻方**（`prev.Player`）—— 原版这条链读的是攻方卡自己的
        /// `customRangedAttackParticles` / 攻方 clan 的 `RangedAttackParticlesByClanSO`。</para></summary>
        float RangedVfxDurationBefore(BattleEvent e, BattleEvent prev)
        {
            if (e == null || prev == null || e.Kind != EvtKind.Hit
                || prev.Kind != EvtKind.Attack || !prev.Ranged) return -1f;
            // 🔴 C5（2026-10-25）：原版这条链读的是**攻方卡自己**的 `customRangedAttackParticles` /
            //   攻方卡的 clan（`cardArmy`）⇒ 取那张卡的阵营，⛔ 不是攻方座位的阵营（跨阵营会取错变体）。
            string f = VfxFactionOf(prev.Player, prev.CardId, prev.InstanceId, prev.Slot);
            float d = CardAnimClips.RangedChainDuration(VfxMap.AttackRanged, f, prev.CardId,
                                                        AnimTimesOf(prev.CardId, f));
            // 🔴 **2026-10-21（W61 第 1 批 · 第 2 条）：查不到逐卡/共享时长 ⇒ 回 -1，交给
            //   `EventTiming.RangedVfxFallback`（0.75）兜底，⛔ 不在这里写死、也不静默当 0。**
            //   ⚠️ 现读**确实有半数是这一档**：逐卡 `customRangedAttackParticles` 是卡 SO 的**顶层字段**，
            //     而 `CardDef.AnimTimes` 只收 `cardAbilities[].abilityLogic[].cardAnimations[]`
            //     ⇒ 226 条攻击 CardAnim 里有 241 条**没有** `AnimTimes` 行（ASH77 就是一条）。
            //     判据 → `资料/普查产出_1021/W61_战斗线_演出链第1批.md` §4。
            // 🔴 **2026-10-23（P1 · 演出时序 ④）**：`RangedChainDuration` 的返回值**已经**是
            //   「≥ 0 = 真值 / -1 = 判据为空」⇒ **原样转出去**，⛔ 别再写 `d > 0f ? d : -1f`
            //   （那会把「真值 0」—— 4 张 Tau 无人机那份 `AnimInfo` 四字段全 0 —— 当成查不到）。
            return d;
        }

        /// <summary>一条引擎事件 → 一个特效。（事件种类和特效名的对应在 `VfxMap` 里）
        /// <paramref name="drawFromEnd"/> 🆕（`A1865`）= 抽卡那一件专用：**这一段里它是倒数第几张**
        /// （1 起；别的种类恒 -1）。由 `PlaySignals` 排时间线时算好、随 `PendingSignal` 一路带下来。
        /// <paramref name="points"/> / <paramref name="pointIndex"/> 🆕（`A1884`）= **同一批抽卡的全部落点**
        /// 与「本事件占第几个」—— 由 `PlaySignals` **一次算齐**（见那儿那段注释），这里是唯一的消费点。</summary>
        void PlaySignal(BattleEvent e, int drawFromEnd = -1, Vector3[] points = null, int pointIndex = -1,
                        bool beat = false, string beatVfx = null, int beatSp = 0, int beatEp = 0,
                        int beatPt = 0, bool beatTail = false,
                        bool beatMove = false, bool beatOtv = false, float beatTs = 0f, float beatTm = 0f,
                        float[] beatEase = null,
                        bool cueUnitDamage = false, bool cueMeleeHit = false,
                        CardAnimBeat beatData = null,
                        bool hitOfAttack = false, int hitAmount = 0,
                        bool collectDeath = false, bool hitOfCounter = false,
                        float skillAnimAt = -1f, BattleEvent attackEvent = null)
        {
            // 🆕 2026-10-24（引擎线 `G1b` · 战斗线 `C2` §6）：**同一个关键词再次施加 ⇒ 重播 `Start(0)`**。
            //   判据 = 原版 `BattleCardUI__DisplayStatusAnim.c`：`Start(0)` 那一档**每次都演**
            //   （`:78-119`，不进表、不查重）；`OnPlay(2)` 那一档只首次演（`:121-198`，已有 ⇒ 只归位）。
            //   我们原来的唯一入口 = `SyncBoard` → `TraitFrames.SyncKeywords` 的**集合对差**
            //   ⇒ 同一个关键词第二次以后**一次都不调** `DisplayStatus`（`C2` §6·3 的缺口）。
            //   🔴 `Amount` 的约定（见 `EvtKind.StatusApplied` 的 doc）：`0` = **首次** ⇒ **不由这里演**
            //   （`SyncKeywords` 的「新出现」那条路负责 —— 两条路**结构上互斥**，一次施加恰好演一次）；
            //   `> 0` = **重施加** ⇒ 这里演一次。
            //   ⚠️ 取视图**不新建** `TraitFrames`：`TraitFrames.Attach` 会挂一个 `_prev` 为空的新实例
            //   ⇒ 下一次 `SyncKeywords` 会把**所有**关键词的 OnPlay 重演一遍（静默多播）。
            //   视图还没建出来（`ViewAt` 回 null）⇒ 什么都不做：那时它是「首次」，
            //   `SyncBoard` 建视图之后 `SyncKeywords` 本来就会演。
            if (e.Kind == EvtKind.StatusApplied)
            {
                if (e.Amount > 0)
                {
                    var statusView = ViewAt(e.Player, e.Slot);
                    var statusTf = statusView != null ? statusView.GetComponent<TraitFrames>() : null;
                    if (statusTf != null) statusTf.DisplayStatus(e.CardId);
                }
                return;
            }

            // 🆕 2026-10-17（`T05` 第 3 步）：**「按表展开的一拍」那条出口**（展开点 = `ExpandAbilityBeats`）。
            //   它**整条在这里处理**（含第一拍的事件级副作用），走完就 return ⇒ 下面原来那整段
            //   （`case EvtKind.Ability: evt = VfxMap.Ability;` 那一格）**只留给「表里没有这张卡」的卡**
            //   （= 原样一拍，行为与改前**逐字一致**）。
            if (beat)
            {
                if (!beatTail)
                {
                    // 事件级副作用**只在这一串的第一拍上跑一次** —— 一条 `EvtKind.Ability` 展开成 N 拍后
                    // 本方法会被调 N 次；不设这道门，一次技能会响 N 遍单位语音与战斗音效
                    // （原版这两样是**事件**级的，不是拍级的）。
                    SpeakFor(e);
                    PlayRemnantSfx(e);
                    PlayBattleSfx(e);
                    if (animateFeel) PlayFeel(e);
                    PlayTraitParticles(e);
                }
                PlayAbilityBeat(e, beatVfx, beatSp, beatEp, beatPt,
                                beatMove, beatOtv, beatTs, beatTm, beatEase, beatData);
                return;
            }

            // 🔴 **2026-10-24（`W64·B-30`）**：**原版那一个入口** —— 摊开一批卡
            //   （效果 470 → 动作 86 → `ResolveAction` case 86 → `BattleHud.DisplayMultiCardView`；
            //    引擎侧判据 → `EvtKind.ShowCardsWindow` 的 doc）。
            //   · ⛔ **不门在 `animateFeel` 上**：这是**一扇窗的开关**、不是补间/手感
            //     （同族 `PlayFeel` / `MaybeDisplayPlayedCardInCenter` 要门，是因为批处理自检要「当场精确」的坐标）。
            //   · 「`IsPlayerTurn` 才开窗」那道闸 + 「卡名 → `CardData`」全在 `OpenShowCardsWindow` 里。
            //   · 🔴 **非阻塞**：这一拍**不加时长**（`EventTiming.DurationOf` 的 `default` = 0f 恰好与原版一致，
            //     原版 `FinishResolvingAction` 紧跟其后、无 `yield`）—— ⛔ 别往 `EventTiming` 补。
            if (e.Kind == EvtKind.ShowCardsWindow) OpenShowCardsWindow(e);

            // 🆕 2026-10-19（`W57` · `T04` #1）：**非单位卡打出 → 中央展示 + 卡背翻面**
            //   （原版 `CardScript._PlayEnemyCard/_PlayPlayerCard` 的 `cardType != 0` 那支 →
            //   `DisplayEnemyCardInCenter`）。只在真机演出档跑（`animateFeel`；批处理自检要「当场精确」）。
            //   ⚠️ 与后续事件**并行**（原版是 await，我们这里没有等待层）—— 见那个方法的头注释。
            if (e.Kind == EvtKind.Play && animateFeel) MaybeDisplayPlayedCardInCenter(e);

            // 🆕 2026-10-19（偏差 4）：**这两条 cue 在「事件到点」这一拍才响**（原来在 `PlaySignals` 的
            //   drain 里当场响 ⇒ 命中音比受击帧早到）。判据见 `UnitDamageCueIndex` / `IsMeleeHitCueAt`。
            // 🔴 **2026-10-21（W61 第 1 批 · 第 2 条）**：`meleeAttackHit*` **搬去命中帧**了 ——
            //   原版它在 `ResolveAttackAnimationEffects` 里（近战动画的命中回调，
            //   `CardScript__ResolveAttackAnimationEffects.c:30-64` ← `<AttackMeleeAnim>b__1.c:16`），
            //   不在伤害结算那一拍 ⇒ 现在由 `ScheduleAttackPresentation` 排到 `HitFrameLag` 那一刻。
            if (cueUnitDamage) BattleSfx.Play(BattleSfx.UnitDamage);

            // 🆕 2026-10-19（偏差 1 的残余④）：**这一格等到 `Deploy` 这一拍才把视图建出来**
            //   （`SyncBoard` 在 `PlaySignals` 之后跑 ⇒ 这一笔会在本帧同步完成，见 `_syncAfterDeploy`）。
            if (e.Kind == EvtKind.Deploy) CompletePendingDeploy(e);

            // 🆕 2026-10-19（战斗线 W 第 1 条）：**轮到这一刻才让血掉下来**（受击帧）。
            //   在 `PlayFeel` / 飘字**之前** —— 卡面先到新值，挨打反馈与飘字同一拍（原版
            //   `ReceiveDamage` 协程里也是先改 HP 再播受击动效）。
            CompletePendingHpBeat(e);

            SpeakFor(e);          // 单位语音条（原版 `Unit Chat`）—— 和特效同一个事件流，不另开一条路
            PlayRemnantSfx(e, collectDeath);    // 🆕 2026-09-29：残骸体那三条原版音效（出现 / 收集 / 被打掉）
            PlayBattleSfx(e);     // 🆕 2026-10-15（`T06`）：战斗「时机 → cue」那一族（原版 `SoundAssetCollection`）

            // 🆕 2026-10-23（`W63` 收口；🔴 **2026-10-23（P2 · `新账-78①`）就地搬到 `Attack + 0.2`**）：
            //   **受击方自己的 `UnitDamaged(60)` 技能动画** —— 原来排在 `Hit` 这一拍（= Attack+0.4），
            //   **晚 0.2 s**。现在由 `ScheduleAttackPresentation` 的 ④ 排到 `Attack + AttackWindUp`，
            //   调用口 = `PlayDefenderDamagedAnim`（判据与整段说明在那儿）。⛔ 别在这里再加回来
            //   （那会变成**同一发播两次**）。
            //   ⚠️ 这 4 条原来躺在 `hit` 桶里、被当成「受击粒子」那一档；而受击那一拍原版
            //   **一件粒子都不播**（见下面 `e.Kind != EvtKind.Hit` 那一段）⇒ 它们只走技能动画那个口。

            string evt = GenericVfxFor(e);
            // 🆕 2026-10-19（W · 触发逐卡）：`Trigger` **没有通用特效**（B2 · 偏差 7：`GenericVfxFor`
            //   对它返回 null），但**逐卡**的 `cardAnimations[]` 是原版真有的 ——
            //   `RawCardScript__OnTrigger.c:15` 把任意 trigger 原样转给 `TriggerAbilities` →
            //   `RawCardScript__TriggerAbility` → `AbilityLogic.PlayAbility` → `PlayAnim` 进动作队列
            //   （即：Strike/Slay 这些 trigger 的卡自己的动画**会播**）。
            //   ⇒ 给它一个**只查逐卡表**的出口（`perCardOnly`）：⛔ 不许掉进 `ByEvent` 的兜底
            //   （那条 `Trigger → Faith_trigger_unit` 是死条目，播出来就是原版没有的第二下）。
            bool perCardOnly = false;
            if (evt == null && e.Kind == EvtKind.Trigger)
            {
                evt = VfxMap.Trigger;
                perCardOnly = true;
            }
            // 🆕 2026-10-19（战斗线 `T21` · 引擎事件缺口）：**把 `BattleEvent.Keyword` 交给 VfxMap** ——
            //   它就是原版 `AbilityTrigger` 枚举名（`FollowUpResolution` / `OtherCardPlayed` /
            //   `TurnStart` …）。`VfxMap.TryResolveTriggerPicks` 拿到它才能按 `CardAnimTime.TriggerName`
            //   精确归口；没有它就只能靠「整张卡只标出一种 trigger 名」的保守推断（混 trigger 的卡
            //   如 `GSC16` 会多播 —— 报告 §五·6）。
            //   ⚠️ 只对 `Trigger` 那一档有意义（别的 `evt` 走 `TryResolvePerCardPicks`，`keyword` 不影响）。
            string triggerKeyword = e.Kind == EvtKind.Trigger ? e.Keyword : null;
            // 没有通用特效的档：阵亡（爆散体在 `PlayFeel` 里、这里不能再叠一件）、
            // 触发（🔴 2026-10-19 B2 · 偏差 7：原版只有徽标/状态框/词条粒子，没有通用特效）、
            // 🆕 2026-10-20（`W58`）**Syphon 治疗**（`GenericVfxFor` 回 null —— 原版只有 Normal 档有
            //   治疗圈；可是那一拍的**飘字/音效必须照播** ⇒ 这一档要继续走到 `PlayFeel`）、
            // 🔴🆕 2026-10-22（`W64` · 自检 7 条红查实）**反击**（`GenericVfxFor` 也回 null ——
            //   原版那一发**只按「施法者自己的件」解**，没有「通用事件特效」这一档）；
            // 以及**未知/不归这一族**的事件（原本 `default: return;` 那一档）——
            // 前四档要继续走到下面的 `PlayFeel` / `PlayTraitParticles`（反击自己那一支在**再下面**，
            // ⚠️ 见紧跟着这条 return 的那句注释：**这一道闸漏了它，反击整条永远到不了**
            // —— 2026-10-22 一次自检就是这么红的：`RetaliationPlanCount == 0`、件一次没播），
            // 第三档直接收工。
            if (evt == null && e.Kind != EvtKind.Death && e.Kind != EvtKind.Trigger
                && e.Kind != EvtKind.Heal && e.Kind != EvtKind.Retaliation) return;

            // **手感补间**（和特效同一时刻起，参数在 `CardFeel` 里、逐条有出处）。
            // ⚠️ 必须赶在 `SyncBoard` 之前 —— 阵亡那一格马上就要空了，视图还在的只有现在。
            // 🆕 2026-10-21（W61 第 1 批 · 第 2 条）：把「这条 `Hit` 是某一击攻击的伤害结算」传下去 ——
            //   近战那一击的后坐/震屏已经在**命中帧**做过，这一拍不再做（判据见 `PlayHitFeel`）。
            if (animateFeel) PlayFeel(e, hitOfAttack, collectDeath, hitOfCounter);

            // 🆕 2026-10-01：**trait 的 FromCode 粒子**（见 `PlayTraitParticles` 的头注释）。
            // ⚠️ 必须放在下面 `evt == null` 那道 early-return **之前** —— 阵亡那一条也会走这里。
            PlayTraitParticles(e);

            // 🔴🆕 **2026-10-24（执行代理 `W1` · AN1 `R6`）：阵亡触发的能力动画**（`ThisUnitDeath(80)` /
            //   `UnitDeathByAbility(180)` 那一族，现读 7 行 / 6 卡）。同样必须赶在下面 `evt == null`
            //   的 early-return **之前** —— `GenericVfxFor(Death)` 恒 `null`。判据与「为什么与 D13 不冲突」
            //   → `PlayDeathAbilityAnims` 的方法头。
            if (e.Kind == EvtKind.Death) PlayDeathAbilityAnims(e);

            // 🔴🔴 **2026-10-22（`W64` · 反击演出）：`EvtKind.Retaliation` 走自己的那一发，
            //    而且**必须赶在下面 `evt == null` 的 early-return 之前** ——
            //    `GenericVfxFor` 对它回 null（原版的守方那一发**只查逐卡表**，没有通用件），
            //    放在 early-return 之后 = 这一支**永远到不了**（静默不播）。
            //  判据（第一权威）= `BattleManager._ResolveAttack_d__438__MoveNext.c:1114-1152`：
            //    远程打法那一支是 `CardScript__ResolveAttackRangedAnim(守方, 攻方, 0, 0)`（`:1121`），
            //    与攻方那一发**同一个协程** —— 从**施法者自己的** `effectsAnchor` 发出、朝 `abilityTarget`、
            //    件 = **施法者自己的** `customRangedAttackParticles`。施法者 = **守方**
            //    ⇒ ⛔ 不用攻方的件、⛔ 不在目标格播。近战打法那一支（`:1132-1150`）守方**什么都不播**。
            if (e.Kind == EvtKind.Retaliation)
            {
                // 后面紧跟的那条 `Hit`（**攻方**挨反击）要按「攻方 = 守方」算后坐幅度/震屏档 ——
                // 见 `PlayHitFeel` 的 `melee` 判据（不更新的话两边同侧 ⇒ 判成「没有攻击方」）。
                if (animateFeel && Ctx != null && e.Player >= 0 && e.Player < Ctx.Players.Length
                    && e.Slot >= 0 && e.Slot < Ctx.Players[e.Player].Board.Length)
                {
                    var def = Ctx.Players[e.Player].Board[e.Slot];
                    _lastAttackerMelee = def != null ? def.Attack : -1;
                    _lastAttackerSide = e.Player;
                    _lastAttackerSlot = e.Slot;
                }
                _animfxLastEvent = e;
                _animfxCtx = BuildCardContext(e);      // AnimFX 模块要用「为哪两张卡播的」
                ScheduleRetaliationPresentation(e);
                _animfxCtx = default;
                return;
            }

            // 这一条事件**只有手感补间、没有通用特效**（目前只有阵亡，见上面那个 case）。
            // ⚠️ 必须在 `PlayFeel` **之后**返回 —— 阵亡的消散/爆散体就是 `PlayFeel` 里起的。
            if (evt == null) return;

            // 🔴🔴 **2026-10-24（执行代理 `B1` · `C2` §1·4 / §1·5 步 C · 战斗线 `D3`）：
            //   `UnitAttack(50)` 那一族 ⇒ 走【技能动画】那个口，⛔ 不走 `FireEventAll` 的通用件。**
            //
            //   【判据（第一权威，逐句）】
            //     · `BattleManagerSupport__BroadcastUnitAttacked.c:22 / :29 / :48-58` —— 攻击动画跑完后
            //       **对在场每张卡**（外加被打者与攻方）各调一次 `ResolveUnitAttacked`；
            //     · `CardScript__ResolveUnitAttacked.c:28-30` —— 收端无条件 `OnTrigger(0x32 = 50, …)`；
            //     · `CardAbility__CanTriggerAbility.c:126-140` —— 但**动画是 ability 的一步**：
            //       `OnTrigger` 无条件 ≠ 动画无条件（要过 `IsRightContext` + 三条 criteria）⇒
            //       **animation 的唯一来源 = 引擎真的把这条 ability 跑了一次**。
            //   ⇒ 所以「该不该播」由**这条 trigger 事件本身**回答（它是 `EmitCardTrigger` 在闸内发的），
            //     而不是像改前的 ③ 那样「只要有人攻击就给攻方播一发」。
            //
            //   【为什么不能用 `FireEventAll` 的通用通道】（C2 §1·4，2026-10-24 的新发现）：
            //     那条路的 `pos` 是**这张卡在屏幕上的格位点**（`layout.DropTargetWorld`），
            //     **没有** `startPos/endPos` 锚点解析、**没有**卡体动画层（`DoAnim`）、
            //     **没有**每拍时长 `SkillBeatDuration` ⇒ 名字虽对，位置/朝向/体动画/时长全错。
            //     `PlayUnitSkillAnim` 才是这一桶的正确播放入口（`CardAnimClips.Resolve` 取件 → `PlayOneUnitAnim`）。
            //
            //   【时刻】`t0` = **这一击整条攻击动画跑完**的那一刻（`skillAnimAt` = 这条信号所属那一批的
            //     `_batchAttackSkillAnimAt`，在 `PlaySignals` 排时间线时先算好、再回填到信号上；
            //     见 `PendingSignal.skillAnimAt` 的 doc —— ⛔ 别读字段本体，下一批会覆盖它）。
            //     `attacked` 族排在攻击宣言**之前**、监听者族排在**之后** ⇒ 两条路都只能靠这个绝对值。
            //     `Mathf.Max(0f, …)`：播放这一刻已经过了那个时刻（远程件很短时会出现）⇒ 当场起播，
            //     ⛔ 不要倒着排（`ScheduleAction` 会把负延迟夹成 0，行为相同，但这里显式写出来）。
            if (e.Kind == EvtKind.Trigger)
            {
                // ⚠️ 先拆 `#i` 后缀（`EmitCardTrigger` 把能力序号拼在 `Keyword` 里）——
                //    ⛔ 别拿带后缀的原文去比 canonical（会漏掉多能力卡那几条）。
                string kw = BattleEvent.SplitKeywordAbility(e.Keyword, out _);
                string canonical = VfxMap.CanonicalTriggerName(kw);
                if (string.Equals(canonical, VfxMap.UnitAttackTriggerName, System.StringComparison.OrdinalIgnoreCase))
                {
                    // `skillAnimAt` / `attackEvent` = **这条信号自己那一批**的（见 `PendingSignal.skillAnimAt`）。
                    float t0 = skillAnimAt >= 0f ? skillAnimAt - _clock : 0f;
                    // 载体选谁（见 `_batchAttackEvent` / `PendingSignal.attackEvent` 的 doc）：
                    //   · **反应者就是攻方**（`attacked` 族 / `SW16` 那种自己攻击的监听者）⇒ 用这一批的
                    //     **攻击事件**（`Kind = Attack` + `Target*` = 被打者）—— 与改前 ③ 逐字段相同；
                    //   · **别的卡在监听**（`DA22` / `UM70` / `UM83` …）⇒ 用**它自己**那条 trigger 事件
                    //     （`Player/Slot/CardId` = 它自己，锚点 = 它自己那张卡）。
                    //     ⚠️ **如实记（未闭合）**：这一档**没有目标** ⇒ `endPos/pointTowards = abilityTarget`
                    //     会退回 `self` 并出声（`MapSelf`）。原版那几条能力的**目标列表**我们的事件不带
                    //     （`CardAbility.abilityTargets` 不进 `EvtKind.Trigger`）⇒ 这一位判据未定，
                    //     ⛔ 别自己拿「被打者」去顶（那是 `attacked` 族的语义，对监听者族没有依据）。
                    BattleEvent carrier = attackEvent != null
                                          && e.Player == attackEvent.Player
                                          && e.Slot == attackEvent.Slot
                                          && string.Equals(e.CardId, attackEvent.CardId,
                                                           System.StringComparison.OrdinalIgnoreCase)
                                        ? attackEvent : e;
                    LastUnitSkillUsedAttackEventForTest = ReferenceEquals(carrier, attackEvent) && attackEvent != null;
                    PlayUnitSkillAnim(carrier, VfxMap.UnitAttack, Mathf.Max(0f, t0));
                    _animfxCtx = default;       // 与改前 Trigger 那条路收尾同形（见 `PlaySignal` 末尾）
                    return;
                }
            }

            // 🔴 **「挂在 HUD 上、不是挂在格位上」的那一族** —— 它们的 `Slot` **本来就是 -1**
            //    （阵营资源那三件：`BattleEvent.GainFaith` 的注释写着是「给玩家」的；
            //     抽卡：`BattleEvent.Draw` 的注释写着「不在场上」）
            //    ⇒ **绝不能走下面那道 `slot < 0 → return`** —— 只加 case 不加这一段的化，
            //      它们还是永远不播（2026-09-15 查实的「结构上播不出来」就是这个）。
            //    2026-10-14（`A1816`）把判据收成 `IsHudAnchoredEvent` 一处 —— 原来这里是
            //    `IsResourceUiEvent(e.Kind)` 内联，加 `Draw` 时要是再写一句 `if`，就成了两份判据。
            Vector2 hud01;
            if (TryHudAnchor(e, out hud01, drawFromEnd))
            {
                _animfxLastEvent = e;
            _animfxCtx = BuildCardContext(e);          // AnimFX 模块要用「为哪两张卡播的」
                // 🔴 C5（2026-10-25）：`cardArmy` 口径 —— 见 `VfxFactionOf` 的 doc
                string hudFaction = VfxFactionOf(e.Player, e.CardId, e.InstanceId, e.Slot);
                // 🆕 2026-10-14（`A1884`）：落点可能来自**批数组**（同批抽 N 张 ⇒ N 个点，
                //   由 `PlaySignals` 一次算齐）。本事件占第 `pointIndex` 个 ⇒ 交给**多落点重载**。
                //   批里没有它（资源图标那三件等）⇒ 退回原来的单点。
                if (points != null && pointIndex >= 0 && pointIndex < points.Length)
                    FireEventAll(evt, new[] { points[pointIndex] }, hudFaction, e.CardId,
                                 parent: null, perCardOnly: perCardOnly, keyword: triggerKeyword);
                else
                    FireEventAll(evt, LayoutSpace.ToWorld(hud01.x, hud01.y), hudFaction, e.CardId,
                                 parent: null, perCardOnly: perCardOnly, keyword: triggerKeyword);
                _animfxCtx = default;
                return;
            }

            // Attack 打在**目标**那一格（原版也是弹着点，不是抬手那一下）；
            // 其余事件都发生在自己那一格
            int owner = e.Kind == EvtKind.Attack ? e.TargetPlayer : e.Player;
            int slot  = e.Kind == EvtKind.Attack ? e.TargetSlot   : e.Slot;

            // 🔴🔴 **2026-10-24（执行代理 `W1` · AN1 `R1` · **S0**）：未指定目标的战术 / 防御卡 —— `play` 桶整条**
            //   【病灶】`EffectResolver.PlayTactic` 发 `EvtKind.Play` 时 `Slot = targetSlot`，**没指定目标就保持 `-1`**
            //     ——那是**照原版记录字段**的正确结果；错的是下面那句「`slot < 0` 就 return」，
            //     它把这类卡当成「从牌库直接进弃牌堆」⇒ 全池 **405 行 / 269 卡**（Sautekh 试点 37 行 / 22 卡）
            //     的 `play` 桶件**一次都不播**。
            //   【判据（第一权威）】`CardScript__PlayEnemyCard_d__258__MoveNext.c:22` —— 出牌先把卡状态置 `10`
            //     （`inHandPlaying`），再 `DisplayEnemyCardInCenter`；`AbilityLogic__PlayAnim.c` 接着按这张卡自己的
            //     `cardAnimations[]` 演，锚点走 `AbilityLogic__GetPos`；而 `CardScript__GetEffectAnchor.c:11-19`
            //     对状态 `10` / `0` / `1` / `4` / `8` / `9` / `12` / `16` 取的是 **`cardUI + 0x30`（2D 卡那一级）**、
            //     **不是**场上的 `+0x1a0` ⇒ 这类卡的 `thisCard` 锚点 = **中央展示那张临时卡**。
            //   【我们的等价物】`_playedCenterView`（`MaybeDisplayPlayedCardInCenter` 建的那一张）。
            //     ⚠️ 它只在 `animateFeel` 档存在 ⇒ 批处理 / 我方那一侧没有它时由 `PlayPlacedOne` 降级到
            //        `createCardPos(140)`（原版 `GetUIAnchor(140)` = 中央展示位那颗 UI 锚；**我们挑的降级**，如实标）。
            //   ⚠️ **只放行「`EvtKind.Play` + 非单位卡」** —— `Slot = -1` 还有别的来路（从牌库直接进弃牌堆那类），
            //      一律放行 = 多播原版没有的件。
            if (slot < 0 && e.Kind == EvtKind.Play)
            {
                // 🔴 C5（2026-10-25）：`cardArmy` 口径 —— 见 `VfxFactionOf` 的 doc
                string pFaction = VfxFactionOf(e.Player, e.CardId, e.InstanceId, e.Slot);
                var pDef = CardDatabase.Find(_pool, e.CardId, pFaction);
                if (pDef != null && !pDef.IsUnit)
                {
                    var hudPos = ResolveAnimAnchor(PositionOption.createCardPos, e.Player, _playedCenterView, null);
                    Vector3 fbPos = hudPos != null ? hudPos.position : LayoutSpace.ToWorld(0.5f, 0.5f);
                    int nPlaced = PlayPlacedPieces(e, evt, pFaction, perCardOnly, triggerKeyword,
                                                   _playedCenterView, null, fbPos);
                    if (nPlaced == 0)
                        Debug.LogWarning($"[Battle] `{e.CardId}`（非单位卡 · `Slot = -1`）在 `play` 桶里"
                                       + "**没有任何候选件** ⇒ 这条事件什么都不会播（如实报，⛔ 不静默）");
                    _animfxCtx = default;
                    return;
                }
            }
            if (slot < 0) return;                       // 不在场上（比如从牌库直接进弃牌堆）

            var layout = owner == _me ? playerBoard : enemyBoard;
            // 🔴 C5（2026-10-25）：`owner` 是「这一拍发生在谁的格子上」（攻击时 = 受方），
            //   但特效表要按**那张卡自己的阵营**查 ⇒ 传 `e` 自己那两格（`e.Player/e.Slot`），
            //   ⛔ 别拿受方的座位阵营当攻方卡的 `cardArmy`。
            string faction = VfxFactionOf(e.Player, e.CardId, e.InstanceId, e.Slot);

            // 濒死的单位已经不在 `_myUnits/_foeUnits` 里了（视图也要等 SyncBoard 才清），
            // 但格位坐标只跟棋盘几何有关 —— 直接问 layout，不依赖视图
            _animfxLastEvent = e;
            _animfxCtx = BuildCardContext(e);              // AnimFX 模块要用「为哪两张卡播的」

            // 🔴 2026-10-21（W61 战斗线「新账-65」第 1 批 · 第 3/4 条）：**攻击那一拍的特效不走下面那条路**。
            //   原版的攻击特效是「从**攻方**的 `effectsAnchor` 发出、朝目标」，时刻也不是事件那一拍：
            //   · 近战逐卡 `UnitAttack` 在**整条近战动画跑完之后**（`BroadcastUnitAttacked`）；
            //   · 远程在回正 0.2 s 之后 `DelayedVFXPlay`。
            //   ⇒ 交给 `ScheduleAttackPresentation` 排（用同一个时间线泵）。
            if (e.Kind == EvtKind.Attack)
            {
                // ⚠️ 归属方 = **攻方**（`e.Player`）：原版的逐卡件挂攻方卡的脚本
                //  （`RawCardScript.customRangedAttackParticles`）、阵营兜底件也是攻方的 clan
                //  （`RangedAttackParticlesByClanSO.GetRangedClanParticles(rawCard +0x2c)`，
                //    `CardScript._ResolveAttackRangedAnim_d__360__MoveNext.c:146-176`）。
                //  🔴 原来这里套的是**目标**那一方（`owner`）—— 后果：跨阵营攻击时
                //  `AnimTimesOf(cardId, faction)` 用错阵营查不到**攻方**那张卡 ⇒ 逐卡时长整块丢掉
                //  （名字仍能解出来，因为重名只是 3 组）。这一条在本批修掉。
                // 🔴 C5（2026-10-25）：攻方卡自己的阵营（`cardArmy`）—— 见 `VfxFactionOf` 的 doc
                string atkFaction = VfxFactionOf(e.Player, e.CardId, e.InstanceId, e.Slot);
                _lastAttackEventAt = _clock;         // 🆕 2026-10-23（`新账-78①`）：自检锚点
                ScheduleAttackPresentation(e, evt, atkFaction, perCardOnly, triggerKeyword, cueMeleeHit, hitAmount);
                _animfxCtx = default;
                return;
            }

            // 🔴 **2026-10-16（`A367` 的改法落地 · 与 `A337`/`A359` 同一族、同一口）**：
            //   原来喂 `layout.SlotPosition(slot)` —— 那是**2D 兜底布局的行线点**（屏上 708 px），
            //   而 3D 下卡真正画在 **631~657 px（逐格不同）** ⇒ 根特效比卡偏 **51~72 px**。
            //   **为什么根特效要看「卡画在哪」**：`parent = null` 的根特效**拿不到第 8 层**
            //   （`WarpforgeVFX/Runtime/*.cs` 里 `.layer` 零命中；`CardView.SetLayerRec` 只递归卡自己）
            //   ⇒ 它由 **HUD 正交相机**画（战场相机 `cullingMask = 1<<8`、HUD 相机摘掉第 8 层）
            //   ⇒ 喂**竞技场世界坐标**会偏 ≈267 px、喂 **2D 行线**偏 51~72 px、
            //   **只有 `DropTargetWorld`（这一格卡心的投影）落在卡上**。
            //   ⛔ 判据只此一处（`BoardLayout.DropTargetWorld:506-516`）：非 3D 时它**逐位等于** `SlotPosition`。
            //   普查（含「消费方归哪台相机」的判别式）→ `资料/普查产出_1016战斗/W_卡牌飞行族普查.md` §二/§三。
            // 🆕 2026-10-19（B2 · 偏差 8）：**AI 飞行**时这一拍是「起飞」⇒ 登场那几件（卡淡入 + 召唤法阵 +
            //   扬尘）全部押到飞行终点（`PlayAiDeployLandingVfx`）。
            bool aiDeployFlight = e.Kind == EvtKind.Deploy && _aiDeployFlights.ContainsKey(HpKey(e.Player, e.Slot));
            if (!aiDeployFlight)
            {
                // 🆕 2026-10-19（T05 · 卡上特效改走挂载 · 登场那一档）：原版 `normalSummon` 是**根实例化**
                //   在卡的世界位置上（判据见 `FireDeployVfxInArenaSpace` 的 doc）⇒ 它要活在**竞技场空间**；
                //   其余事件保持原样（各自的判据还没查全 —— 见报告）。
                if (e.Kind == EvtKind.Deploy)
                    FireDeployVfxInArenaSpace(evt, e, faction, perCardOnly);
                // 🔴 **2026-10-22（W63 · `新账-65` 第②条）：`Hit` 这一拍【一件粒子都不播】。**
                //   判据（第一权威）= 原版 `CardScript._ReceiveDamage…MoveNext.c` —— 扣血之后**只**调
                //   `BattleCardUI.DamageReceived`（伤害计数器 = 血痕 + 飘字），**不生成任何粒子**。
                //   改前这里对**非攻击来源**的 `Hit`（技能伤害 / 疲劳 / 反噬 / 反击）多播一件
                //   `AttackHitSmall`（`VfxMap.Hit`）= 原版没有的第二下 ⇒ 删。
                //   报告 → `资料/普查产出_1022/W63_飞行与卡ID演出_调查.md` §B（`hit` 那一行）。
                //   ✔ **原版仍有的表现一件没少**（它们本来就不在这一支）：伤害计数器/飘字
                //     = `PlayHitFeel` → `PopNumber.PopDamage`（血痕是它的子件）· 受击音效 = `BattleSfx.UnitDamage`
                //     （`cueUnitDamage` 那一拍，判据 = `UnitDamageCueIndex` 的 doc；`PlayBattleSfx` 的 `Hit` 支本来就是空转）
                //     · 后坐 + 转一下 = `CardFeel.HitReact` · 震镜头 = `CardFeel.ShakeCameraForHit`。
                //   ✔ **攻击来源的 `Hit` 不受影响**：它的命中粒子在**命中帧**由 `ScheduleAttackPresentation`
                //     播（上面 `EvtKind.Attack` 那一段的 `HitFrameLag`），**从来不经过这一支**
                //     ⇒ 2026-10-21 那条 `!hitOfAttack` 守卫到此被本条**吸收**（`Hit` 一律不播，不必再判来路）。
                //   ⚠️ **技能伤害自己的技能动画**是另一条路（`ExpandAbilityBeats` → `PlayAbilityBeat`；
                //     逐卡 `hit` 桶里那 4 条其实也是 `UnitDamaged(60)` 技能动画）—— 另账，⛔ 不在这一笔。
                // 🆕 2026-10-22（P6 · M1）：**收集灵魂石那一拍的落点不是格心** —— 原版
                //   `RemnantAeldari__CollectWaystoneEffect.c` 用 `GetDeathParticlePosition()`，
                //   那一位取的是残骸 prefab 的 `wayStoneIdle`（= 节点 `Idle/Spirit Stone Idle`）的 position
                //   （判据 → `TryRemnantIdleWorld`）。取不到才退回格心**并出声**（`RemnantCollectWorld` 里那一句）。
                //   ⚠️ 只加这一支，其余事件仍然走下面原来的 `DropTargetWorld(slot)`。
                else if (e.Kind == EvtKind.CollectWaystone)
                    FireEventAll(evt, RemnantCollectWorld(e, layout), faction, e.CardId,
                                 parent: null, perCardOnly: perCardOnly, keyword: triggerKeyword);
                else if (e.Kind != EvtKind.Hit)
                {
                    // 🔴🆕 **2026-10-24（执行代理 `W1` · AN1 `R2` · S1）：`play` / `trigger` 两桶改走
                    //   「按 `AnimInfo` 逐拍参数播」**（`PlayPlacedPieces`，判据见它的头注释）。
                    //   改前：`FireEventAll(evt, 一个格位点)` —— 那是**根特效 + 一个点**：
                    //   `startPosOption` / `endPosOption` / `pointTowardsOption` / `shouldMoveVFX` /
                    //   `timeAtStartPos` / `timeMoving` / `easeCurve` / `applyMovementOffsets` **一个都不消费**。
                    //   全池影响面：`play` **270 行带参数** · `trigger` 9 行 · `attack_melee` 6 行
                    //   （`attack_melee` 不在这儿 —— 它走 `ScheduleAttackPresentation`）。
                    //   ⚠️ 查不到 `AnimInfo` 的候选由 `PlayPlacedOne` **退回今天的单点路**（逐字不变）。
                    //   ⚠️ 其余事件类型（`Deploy`/`Draw`/`Heal`/资源三件/…）**一个字没动**，仍然走下面这条。
                    if (e.Kind == EvtKind.Play || e.Kind == EvtKind.Trigger)
                    {
                        CardView pSelf = ViewAt(e.Player, e.Slot);
                        CardView pTarget = (e.TargetPlayer >= 0 && e.TargetSlot >= 0)
                                         ? ViewAt(e.TargetPlayer, e.TargetSlot) : null;
                        // 🔴🆕 **2026-10-25（`AU1` · `J1` §1）：`play` 桶相对 `Deploy` 的偏移** ——
                        //   原版 `BroadcastCardPlayed` 在 `_ResolvePlayCardFromHand:1426`（state 0xb），
                        //   **前面整条登场链全 yield 完了** ⇒ 手牌打出的普通单位 = **1.30 s**（判据 → `PlayBucketOffsetOf`）。
                        PlayPlacedPieces(e, evt, faction, perCardOnly, triggerKeyword,
                                         pSelf, pTarget, layout.DropTargetWorld(slot),
                                         baseAt: PlayBucketOffsetOf(e));
                    }
                    else
                        FireEventAll(evt, layout.DropTargetWorld(slot), faction, e.CardId,
                                     parent: null, perCardOnly: perCardOnly, keyword: triggerKeyword);
                }
            }

            // 🔴 **2026-10-21（W61 第 2 批 · 第 2 条）：这里原来还有一发「按阵营的召唤法阵」—— 【已整层删掉】。**
            //   原版**没有**「阵营登场法阵」这一层（`decomp_full` 按 `SummonCircle` / `summonParticles` /
            //   `SummonAnim` 搜 **0 命中**；`assets_full` 的 `*ByArmy*` 只有 `RangedAttackParticlesByArmy` /
            //   `CardFramesByArmy` 两条；本地那 4 个候选其实是**某些卡的技能动画**）。
            //   ⇒ 删除记录 → `Core/VfxMap.cs` 那段注释；判据 → `资料/普查产出_1021/W61_战斗线_演出链对账.md` §2·1 #10。
            //   ⛔ 别再补第二件「看起来像登场特效」的东西（那是原版没有的额外段）。
            if (e.Kind == EvtKind.Deploy)
            {
                // 登场这一拍**有判据的**只剩两件：卡的淡入（上面 `FireDeployVfxInArenaSpace` = `normalSummon`）
                // + 落定那一拍的扬尘（`CardScript.LandOnGround` 的 `landOnGroundParticles`）。
                //   ⚠️ 下面这两行（「落点仍走 `DropTargetWorld` … 根特效拿不到第 8 层」）是 **2026-10-16 之前**的状态，
                //   已被再下面那条 🔴 就地推翻；🔴 **2026-10-24（W15）起连「卡视图取不到」那条退路也不再喂 HUD 点**
                //   （3D 档 → 竞技场地面点 + `ArenaLayer`，见 `FireHostFallbackVfx`）。⛔ 别再照这两行改回去。
                //   🔥 判据与「我们没做到的那一档（原版把它缩到 desiredScale 0.36）」→ `LandDustFieldFor`。
                // 🔴 **2026-10-16（余账 (a)(b)）：扬尘照原版【挂到那张卡上】，不再喂 HUD 投影点。**
                //   原版（`CardScript__LandOnGround.c:52-106` 现读）= 在**卡的世界位置 + offset**、按 prefab 自己的
                //   旋转 `Instantiate` → 挂到 `MinionManager` → **`localScale = one × desiredScale`（0.36 / 0.69）**
                //   ⇒ 它活在**竞技场空间、由透视相机画**，尺度就是**卡自己的尺度**。
                //   我们原来喂 `DropTargetWorld(slot)`（HUD 平面的投影点）+ 不动 scale ⇒ **位置与大小都偏离原版**。
                //   **现在的做法 = 挂到那张卡的视图上**：视图本来就在竞技场层、尺度就是 `desiredScale`、
                //   旋转是 identity ⇒ **空间 / 层 / 旋转 / 尺度四样一次对上，一处换算都不用写**。
                //   ⚠️ 层：钩子现在会让特效实例**继承父节点的层**（Unity 的层不继承，见 `WarpforgeEffectHook`）——
                //     没有那一条，挂上去的扬尘会停在层 0 被 HUD 正交相机画成乱飘。
                //   ⚠️ `LandDustOffsetY` 是**竞技场世界单位**，而 `localPosition` 活在**卡的空间**里
                //     ⇒ 除以卡的缩放，落地的世界偏移才逐值等于原版那 0.015。
                //   ✅ **2026-10-22（W64 · `B17`）这一档已经补齐**：播放器新增 `assignScale` 口，
                //     钩子对这两件扬尘按**赋值**设根缩放（`WarpforgeEffectPlayer.Play(... assignScale: true)`），
                //     判据 = 原版 `CardScript__LandOnGround.c:87-106` 那句 `localScale = Vector3.one × desiredScale`。
                //     ⚠️ 原来这里记的「我们乘、自带 0.9913 的那件大 0.9%」**已不再成立**（铁律 5：就地订正）。
                // 🆕 2026-10-19（B2 · 偏差 8）：**AI 飞行**时这一拍是「起飞」、不是落地 ——
                //   扬尘/震镜头押到飞行终点（见 `StartAiDeployFlight` 的完成回调）。
                if (!_aiDeployFlights.ContainsKey(HpKey(e.Player, e.Slot)))
                    PlayDeployLandDust(BoardViewAt(slot, owner == _me), slot, layout, e);
            }
            _animfxCtx = default;
        }

        /// <summary>🆕 2026-10-19（B2）：**落定那一拍的扬尘**（原版 `CardScript.LandOnGround` 的
        /// `landOnGroundParticles`；判据见调用点那一大段注释）。拆出来是为了让 **AI 飞行**能在
        /// 飞行终点再撒（那时 `PlaySignal` 早已跑过）。</summary>
        void PlayDeployLandDust(CardView dustHost, int slot, BoardLayout layout, BattleEvent e)
        {
            if (dustHost != null)
            {
                float hostScale = Mathf.Max(1e-4f, dustHost.transform.localScale.y);
                CardEffects.Fire(LandDustFieldFor(e),
                                 Vector3.up * (LandDustOffsetY / hostScale),
                                 dustHost.transform);
            }
            else
            {
                // 取不到视图（正常不该发生）⇒ **出声**，退回那条「宿主取不到」的退路，⛔ 不静默什么都不撒。
                // 🔴 **2026-10-24（执行代理 `W15` · `C6` §1·3）**：这条退路原来是
                //   `CardEffects.Fire(name, layout.DropTargetWorld(slot) + up*LandDustOffsetY)` ——
                //   **HUD 投影点 + prefab 自带层**，可扬尘是**竞技场事件**（原版挂在 `MinionManager` 下、
                //   由战场透视相机画）⇒ 画面会跑到 UI 层。3D 档现在改成
                //   **竞技场地面点（+`LandDustOffsetY`）+ `ArenaLayer`**（见 `FireHostFallbackVfx`）；
                //   2D 兜底档逐位走老口径。
                Debug.LogWarning($"[BattleDriver] 落地扬尘取不到卡视图（slot {slot}）"
                               + (use3DBoard ? "⇒ 退回竞技场地面点（层 ArenaLayer）播放"
                                             : "⇒ 退回 HUD 投影点播放"));
                FireHostFallbackVfx(LandDustFieldFor(e), e.Player, slot,
                                    layout.DropTargetWorld(slot) + Vector3.up * LandDustOffsetY,
                                    ground: true, upOffset: LandDustOffsetY, assignScale: true);
            }
        }

        /// <summary>🆕 2026-10-17（`T05` 第 3 步）：播**按表展开的一拍**（`PlaySignal` 那条 `beat` 出口）。
        ///
        /// <para>**起锚点** = 这一拍的 `startPosOption` 经 <see cref="ResolveAnimAnchor"/> 解析
        /// （原版 `AbilityLogic.GetPos`，36 档；判据 → `Battle/AnimAnchors.cs` 文件头）。
        /// 解析不出来（那一档取不到 —— `AnimAnchors` 自己已经出声）⇒ **退回这一格**（`DropTargetWorld`）
        /// 并**出声**，⛔ 不静默、也⛔ 不猜一个点（本仓红线）。</para>
        ///
        /// <para>🆕 **2026-10-19（战斗线 B1 · 偏差 6「主动技只演一半」）：`endPosOption` / `pointTowardsOption`
        /// 已消费。** 判据（逐句读 `d:/2/tools/decomp_full/`）：
        /// · `AbilityLogic__PlayAnim.c:...` 对 `start != end` 时**再解析一次终锚点**，`pointTowards != 0`
        ///   时**再解析一次朝向锚点**，三个一起交给 `BattleManager.AddCardAnim`；
        /// · `BattleManager__CreateAnim.c` 把 prefab `Instantiate` 在**起锚点**上、挂到它底下；
        /// · `CardAnimController__Update.c` —— `timeAtStartPos ≤ t < timeAtStartPos + timeMoving` 那一段里
        ///   `t01 = (t − ts) / tm`、`e = clamp01(easeCurve.Evaluate(t01))`、`pos = lerp(start, end, e)`
        ///   （`+0x38` = `shouldMoveVFX`，关着时控制器整个 `enabled = false`）；
        /// · `CardAnimController__Initialize.c` → `RotateAnim` —— 朝向 = `transform.forward = 锚点 − 自己`
        ///   （**当且仅当** `pointTowards != 0` 且 `(orientToVelocity == false || shouldMoveVFX == true)`）。
        /// </para>
        ///
        /// <para>⚠️ **实现口径（如实记）**：`CardEffects.Play` 只给「名字 + 一个点 + 父节点」，**拿不到特效句柄**
        /// ⇒ 位移/朝向靠**一个空载体（carrier）**做父节点：把位移写进 carrier，特效跟着走。
        /// · 代价：`localPosition` 传的是 `Vector3.zero`（自检那个记录钩子因此记不到世界点 —— 本条已核，
        ///   现有断言里**没有一条**断技能拍的落点）；层跟着 carrier（层 0 = 与原来那条根特效同一条渲染路）。
        /// · ⚠️ 原版是直接写特效实例的 `forward`（**覆盖** prefab 自带旋转）；我们是让 carrier 转、
        ///   prefab 的 `localRotation` 叠在上面 ⇒ 二者差 prefab 作者那一段旋转（渲染上通常看不见，如实记）。
        /// · ⚠️ **锚点空间那条大账没动**（`T05` §2·4：场上锚 = 竞技场空间、HUD 锚 = HUD 空间，
        ///   而根特效由 HUD 正交相机画）—— 本条按 `anchor.position` 原样用，与改前**同一个口径**。
        /// </para>
        /// </summary>
        /// <summary>🆕 **2026-10-23（R26）**：把「刚生成的那几层特效实例」的**局部旋转归零**。
        ///
        /// <para>**为什么要**：原版 `CardAnimController.Initialize/Update` 直接写**实例自己**的
        /// `transform.forward`（`CardAnimController__Initialize.c` 的 `RotateAnim`：
        /// `transform.forward = 锚点 − 自己`）⇒ 它**覆盖** prefab 上作者摆的旋转。
        /// 我们把朝向落在**载体**上，prefab 那层 `localRotation` 会**乘上去**（= 多叠一个作者朝向）。
        /// ⇒ 只有**这一拍真的要朝向**（<paramref name="orient"/>）才归零；
        /// `move` 但 `!orient` 时原版**不碰旋转**（作者朝向要留着），⛔ 别一起归零。</para>
        ///
        /// <para>⚠️ `CardEffects.Fire` 是同步的（`WarpforgeEffectPlayer.Play` 里 `Instantiate` 完立刻返回）
        /// ⇒ 调用前后 `parent.childCount` 的差就是这一拍新生出来的实例（同 `CardEffects` 自己的口径）。
        /// 抽成静态是为了自检能直接验它（批处理里 `CardEffects.Play` 被换成假钩子、不建子节点）。</para></summary>
        public static void FlattenNewEffectRotation(Transform parent, int from, bool orient)
        {
            if (!orient || parent == null) return;
            for (int i = from; i < parent.childCount; i++)
            {
                var c = parent.GetChild(i);
                if (c != null) c.localRotation = Quaternion.identity;
            }
        }

        void PlayAbilityBeat(BattleEvent e, string vfx, int sp, int ep, int pt,
                             bool moveOn, bool otv, float ts, float tm, float[] ease,
                             CardAnimBeat beatData = null,
                             // 🔴🆕 **2026-10-24（执行代理 `W1` · AN1 `R2`）：这一口现在**不止 `ability` 用** ——
                             //   `play` / `trigger` 两个桶的逐拍也走它（`PlayPlacedPieces`）。
                             //   · `place` = 那一拍的 `AnimInfo` 参数（`CardAnimClips.PlacementOf(CardAnim 名)`）。
                             //     只有**没有 `CardAnimBeat`**（= 非 ability 桶）时才用它取位移偏移那几位；
                             //     ⛔ 别再为它写第二份 `AbilityVfxMove`（同一个泵、同一个求值口）。
                             //   · `selfOverride` / `targetOverride` = **视图从哪来**。`ability` 桶的视图就是
                             //     「那一格上的卡」（默认）；而**未指定目标的战术/防御卡**（`Slot = -1`，
                             //     原版 `CardScript._PlayEnemyCard` 把卡状态置成 `10 inHandPlaying` 再走中央展示，
                             //     `CardScript__PlayEnemyCard_d__258__MoveNext.c:22`）**不在任何格位上** ——
                             //     它的 `thisCard` = **中央展示那张临时卡**（判据 → `MaybeDisplayPlayedCardInCenter`）。
                             CardAnimPlacement? place = null,
                             CardView selfOverride = null, CardView targetOverride = null)
        {
            if (string.IsNullOrEmpty(vfx)) return;   // 纯延时拍：没有特效（时长已由 `ExpandAbilityBeats` 算进调度）

            CardView self = selfOverride != null ? selfOverride : ViewAt(e.Player, e.Slot);
            CardView target = targetOverride != null ? targetOverride
                            : ((e.TargetPlayer >= 0 && e.TargetSlot >= 0) ? ViewAt(e.TargetPlayer, e.TargetSlot) : null);

            Vector3 pos = Vector3.zero;
            Transform anchor = ResolveAnimAnchor((PositionOption)sp, e.Player, self, target);
            if (anchor == null)
            {
                // 那一档取不到（`AnimAnchors` 已经出过声）。两条退路：
                // ① `Slot >= 0`（`ability` 桶的常档）⇒ 退回**这一格**（与改前逐字一致）；
                // ② `Slot < 0`（未指定目标的战术/防御，`R1`）⇒ **格位根本不存在**。判据：原版那张卡此刻
                //    的 `GetEffectAnchor()` 取的是「2D 卡控制器」那一级（`CardScript__GetEffectAnchor.c:11-19`：
                //    状态 ∈ {0,1,4,8,9,10,12,16} 走 `cardUI + 0x30`，**不是**场上的 `+0x1a0`）——
                //    我们的等价物 = 中央展示位那颗 HUD 锚（`createCardPos(140)`）。
                //    （正常路径上 `PlayPlacedOne` 已经把 `0/1/2` 三档换成 140 了，这里是第二道兜底。）
                //    **这是「我们挑的降级」**（原版那张 2D 卡的位置我们没复刻），如实标。
                Transform hudAnchor = e.Slot < 0
                    ? ResolveAnimAnchor(PositionOption.createCardPos, e.Player, self, target) : null;
                if (hudAnchor != null)
                {
                    anchor = hudAnchor;
                }
                else if (e.Slot >= 0)
                {
                    var layout = e.Player == _me ? playerBoard : enemyBoard;
                    pos = layout.DropTargetWorld(e.Slot);
                }
                else
                {
                    Debug.LogWarning($"[Battle] 逐卡演出：`{e.CardId}` 的一拍既解不出起锚点（`startPosOption={sp}`）"
                                   + "、又不在场上（`Slot={e.Slot}`）、中央展示锚也取不到 ⇒ 这一拍不播");
                    return;
                }
            }
            if (anchor != null) pos = anchor.position;

            // ---- 🆕 偏差 6：终锚点 / 朝向锚点（判据见方法头）----
            //   原版：`start == end` 时**终锚点 = 起锚点**（`PlayAnim.c` 那句 `if (start != end) GetPos(end)`）。
            Vector3 end = pos;
            if (ep != sp)
            {
                Transform endAnchor = ResolveAnimAnchor((PositionOption)ep, e.Player, self, target);
                if (endAnchor != null) end = endAnchor.position;
            }
            // 原版 `Initialize` 的那道组合门：`pointTowards != 0 && (!orientToVelocity || shouldMoveVFX)`
            // 🆕 W：`pointTowardsOption == 5`（boardCenter）在原版走的是**另一条支**（`RotateAnim.c:31-127`），
            //   它不解析「boardCenter 锚点」，而是按**对面那侧 MinionManager 的左右端点**算一个 Z 角
            //   —— 见下面 `orient` 那一段。所以这一档**不**走锚点解析。
            bool ptIsBoardCenter = pt == (int)PositionOption.boardCenter;
            Transform ptAnchor = (pt != 0 && !ptIsBoardCenter)
                ? ResolveAnimAnchor((PositionOption)pt, e.Player, self, target) : null;
            bool orient = (ptIsBoardCenter || ptAnchor != null) && (!otv || moveOn);
            bool move = moveOn && tm > 0f && (end - pos).sqrMagnitude > 1e-8f;

            // 🔴 C5（2026-10-25）：原版按 **`cardArmy`**（卡自己的阵营）查特效/动画表 —— 见 `VfxFactionOf` 的 doc
            string faction = VfxFactionOf(e.Player, e.CardId, e.InstanceId, e.Slot);
            _animfxLastEvent = e;
            _animfxCtx = BuildCardContext(e);         // AnimFX 模块要用「为哪两张卡播的」

            if (!orient && !move)
            {
                // 🔴 **2026-10-19（T05 · 「卡上特效改走挂载」+「锚点空间」）**：
                //   原版 `BattleManager.CreateAnim` 是 **`Instantiate(prefab, anchor.position, prefab.localRotation,
                //   **anchor** parent)`**（`BattleManager__CreateAnim.c:62-72` 逐句读，第 4 个实参就是锚点自己；
                //   ⇒ 特效**挂在锚点下面**：层 / 缩放 / 旋转全由锚点说话。
                //   我们原来 `CardEffects.Fire(vfx, pos)`（`parent = null`）⇒ 根特效被 **HUD 正交相机**画，
                //   而锚点可能在**竞技场空间**（卡的 `EffectAnchor` / `Board Center` / 空位锚）⇒
                //   **位置对、尺度和旋转是 HUD 的**（`A367` 那条路的同族问题）。
                //   ⇒ 这里改成挂在锚点上（`localPosition = zero` = 原版那个 `Instantiate` 的位置）。
                //   ⚠️ 取不到锚点时（`AnimAnchors` 已出声）保持老路：根特效播在退回点上。
                if (anchor != null)
                {
                    EnsureAnchorSpace(anchor);
                    CardEffects.Fire(vfx, Vector3.zero, anchor);
                }
                else CardEffects.Fire(vfx, pos);
                _animfxCtx = default;
                return;
            }

            // 载体：位置 = 起锚点；朝向 = 指向 `pointTowards` 锚点（原版 `RotateAnim` 的非 5 档那一支）。
            // ⚠️ `pointTowardsOption == 5` 在原版走的是「按两边 MinionManager 的左右端点算上向量」那个特殊支
            //   （`RotateAnim.c` 前半段）—— **我们卡池这 99 拍里 0 条用 5**（现读 `card_anim_order.json`），
            //   所以那条支**没写**；真碰上时按下界走通用支并出声（⛔ 不静默猜）。
            var carrierGo = new GameObject("AbilityBeatCarrier");
            var carrier = carrierGo.transform;
            // 🔴 **2026-10-19（T05 · 锚点空间）**：载体**挂到锚点上**（原版那一件就挂在锚点下），
            //   并把载体的层也设成锚点的层 —— `WarpforgeEffectHook` 是按**直接父节点**的层给特效定层的
            //   （`WarpforgeEffectHook.cs:36`），载体若留在层 0，特效就还是 HUD 画的。
            if (anchor != null)
            {
                EnsureAnchorSpace(anchor);
                carrier.SetParent(anchor, false);
                carrier.localPosition = Vector3.zero;
                carrierGo.layer = anchor.gameObject.layer;
                pos = anchor.position;               // 与下面 `carrier.position` 同值（位移起点 / pt 角度用）
            }
            else carrier.position = pos;
            if (orient)
            {
                if (ptIsBoardCenter)
                {
                    // 🆕 W（偏差 6 的第 2 条）—— 原版 `CardAnimController__RotateAnim.c:31-127` 的 **pt==5 支**，逐句：
                    //   · `GetMinionManager(param_4 ^ 1)`：**对面那一侧**的 MinionManager（`param_4` = 施法卡是不是玩家）；
                    //   · `leftMost = GetLeftMostPos()` / `rightMost = GetRightMostPos()`（= 该管理器位置表的**两端**）；
                    //   · `transform.up = leftMost − self.position`；
                    //   · `angle = atan2(rightMost.y − self.y, rightMost.x − self.x)`（`FUN_180486da0` = `Mathf.Atan2`）；
                    //   · `DORotate(ToEulerRad(AngleAxis(angle × 57.2958 − 90, Vector3.forward)) × 57.2958,`
                    //     `tm = +0x30, delay = ts = +0x2C)`，`MakePositive`（= 负角折回 0..360）· `SetEase(1)` = Linear。
                    //   ⇒ 最终 = **绕 Z 转 `atan2(dy,dx) × Rad2Deg − 90` 度**。我们当场设到 carrier 上
                    //     （原版是 `tm` 长的补间；载体旋转补间还没做，与「通用支」同一个近似口径，如实记）。
                    //   ⚠️ 现读瘦身表 99 拍里 **0 条** `pt==5`（数据侧 → `资料/普查产出_1019/B1_报告.md` §二），
                    //     这一支今天**不可达**；写出来是为了「真碰上时不静默走歪」。
                    //   ⚠️ 端点用的是**对面**棋盘的 `DropTargetWorld(0 / SlotCount-1)`（与本方法其它落点同一个口）。
                    var foeBoard = e.Player == _me ? enemyBoard : playerBoard;
                    if (foeBoard != null)
                    {
                        Vector3 leftMost = foeBoard.DropTargetWorld(0);
                        Vector3 rightMost = foeBoard.DropTargetWorld(BoardLayout.SlotCount - 1);
                        float angleDeg = Mathf.Atan2(rightMost.y - pos.y, rightMost.x - pos.x) * Mathf.Rad2Deg;
                        carrier.rotation = Quaternion.Euler(0f, 0f, Mathf.Repeat(angleDeg - 90f, 360f));
                    }
                    else
                    {
                        BeatSoundOff($"pt5:{e.CardId}",
                            $"`{e.CardId}` 的一拍 `pointTowardsOption = boardCenter`（5）—— 取不到对面那侧棋盘，"
                          + "这一拍朝向按零度播（原版按左右端点算角）。");
                    }
                }
                else
                {
                    Vector3 dir = ptAnchor.position - pos;
                    if (dir.sqrMagnitude > 1e-8f) carrier.forward = dir;
                }
            }
            // 🔴 **2026-10-23（R26）**：原版 `CardAnimController.Initialize/Update` 是直接写**实例自己**的
            //   `transform.forward`（`CardAnimController__Initialize.c` 那句 `transform.forward = 锚点 − 自己`）
            //   ⇒ **覆盖** prefab 上作者摆的旋转。我们把这个朝向落在**载体**上，
            //   而 prefab 自己那层 `localRotation` 会**乘上去**（= 叠一个作者朝向，与原版不同）。
            //   ⇒ 只有**这一拍真的要朝向**（`orient`）时，把刚生成的那一层实例的局部旋转归零
            //   （原版那一句写的正是 root 的 forward；`move` 但 `!orient` 时原版不碰旋转，⛔ 别一起归零）。
            //   ⚠️ `CardEffects.Fire` 是**同步**的（`WarpforgeEffectPlayer.Play` 里 `Instantiate` 完立刻返回），
            //      所以调用前后 `carrier.childCount` 的差就是这一拍新生出来的实例（同 `CardEffects` 自己的口径）。
            int beforeFire = carrier.childCount;
            CardEffects.Fire(vfx, Vector3.zero, carrier);
            FlattenNewEffectRotation(carrier, beforeFire, orient);
            _animfxCtx = default;

            if (move)
            {
                // 🆕 W（偏差 6 第 1 条）：`applyMovementOffsets` 的三轴曲线 + **每拍随机一次**的幅度。
                //   原版 `CardAnimController__Initialize.c` 在控制器初始化时调一次
                //   `OffsetMovementCurvesByAxis.GetRandomOffsetValues()`（`Random.Range(min,max)` × 3 轴），
                //   之后 `Update` 每帧把 `curve(t) × 幅度` 加到 lerp 后的坐标上。
                //   我们的随机源 = `_vfxOffsetRng`（开局种子派生，⛔ 不动引擎的 `Ctx.Rng`）。
                // 🆕 2026-10-23（`新账-83`）：载体上存的是**摊平的曲线 + 幅度**（不再存 `CardAnimBeat` 对象），
                //   这样攻击弹道那条路（数据在 `CardAnimPlacement` 上、没有 Beat）与技能拍共用同一个泵。
                // 🔴🆕 **2026-10-24（`W1` · `R2`）**：非 `ability` 桶（`play` / `trigger`）**没有 `CardAnimBeat`**
                //   ⇒ 那几列从 `place`（`AnimInfo`）取 —— 同一个泵、同一个求值口，⛔ 不写第二份。
                int mvAo   = beatData != null ? beatData.ao  : (place.HasValue && place.Value.OffsetAo ? 1 : 0);
                int mvOnt  = beatData != null ? beatData.ont : (place.HasValue && place.Value.OffsetOnt ? 1 : 0);
                float[] mvOfx = beatData != null ? beatData.ofx : (place.HasValue ? place.Value.Ofx : null);
                float[] mvOfy = beatData != null ? beatData.ofy : (place.HasValue ? place.Value.Ofy : null);
                float[] mvOfz = beatData != null ? beatData.ofz : (place.HasValue ? place.Value.Ofz : null);
                Vector3 amp = beatData != null
                    ? RandomOffsetAmp(beatData)
                    : (place.HasValue
                        ? RandomOffsetAmp(place.Value.OffsetAo ? 1 : 0,
                                          place.Value.Mnx, place.Value.Mxx, place.Value.Mny, place.Value.Mxy,
                                          place.Value.Mnz, place.Value.Mxz)
                        : Vector3.zero);
                _abilityVfxMoves.Add(new AbilityVfxMove
                {
                    carrier = carrier, start = pos, end = end, ts = ts, tm = tm, ease = ease, t = 0f,
                    ao = mvAo, ont = mvOnt,
                    ofx = mvOfx, ofy = mvOfy, ofz = mvOfz,
                    randomAmp = amp,
                    // `orientToVelocity` —— 初始朝向由上面那个 `orient` 门管；**逐帧**转向由泵管。
                    otv = otv,
                    lastPos = pos,
                });
            }
            else
            {
                // 只有朝向、没有位移 ⇒ 载体当场就可以退场（特效已按世界位姿挂上去，见 `ReleaseAbilityCarrier`）。
                ReleaseAbilityCarrier(carrier);
            }
        }

        // ==================================================================
        //  🆕🔴 2026-10-24（执行代理 `W1` · AN1 **`R1` + `R2`**）：
        //  **`play` / `trigger` 两个桶的「按逐拍参数播」出口**
        // ==================================================================
        //  判据（第一权威，逐句读过 `d:/2/tools/decomp_full/`）：
        //   · `AbilityLogic__PlayAnim.c` 对**任何** trigger 的动画都走同一条路 ——
        //     按卡自己的 `cardAnimations[]` 逐条排队、每拍调三次 `AbilityLogic__GetPos`
        //     （起锚 / 终锚 / 朝向，见 `:194 / :203 / :215 / :254 / :261 / :271`），
        //     再 `BattleManager.AddCardAnim` → `CreateAnim`（`Instantiate` 在锚点下）→
        //     `CardAnimController.Update` 做位移/转向。**没有「只有 activeAbility 才用锚点」的分支。**
        //     ⇒ `play` / `trigger` 桶原来只喂「一个格位点」（`FireEventAll(evt, 一个点)`）是**我们缺的一层**，
        //       不是原版行为（AN1 §二 R2；本仓 `CardAnimClips` 里那些 `sp/ep/pt/mv/ts/tm/ease` 早已有数据，
        //       只有 `ability`（`ExpandAbilityBeats`）与 `attack_ranged`（`ResolveAttackPieceAnchors`）在消费）。
        //   · `R1`（未指定目标的战术/防御卡）：`CardScript__PlayEnemyCard_d__258__MoveNext.c:22` 先把
        //     卡状态置 `10`（`inHandPlaying`）再走中央展示；`CardScript__GetEffectAnchor.c:11-19` 对状态 10
        //     取的是 **`cardUI + 0x30`（2D 卡控制器那一级）**，不是场上的 `+0x1a0`
        //     ⇒ 这类卡的 `thisCard` 锚点 = **中央展示那张临时卡**（我们的 `_playedCenterView`）。
        //     ⚠️ 那张卡只在 `animateFeel` 档建得出来（`MaybeDisplayPlayedCardInCenter`），
        //        批处理 / 我方那一侧没有它 ⇒ `0/1/2` 三档降级到 `createCardPos(140)`（**我们挑的降级**，如实标）。
        // ==================================================================

        /// <summary>🆕 **2026-10-25（`AU1` · `J1` §1）：`play` 桶起播相对**这一拍 `Deploy`**的偏移（秒）**。
        ///
        /// <para>**判据** = 原版 `BattleManagerSupport.BroadcastCardPlayed` 的**唯一**调用点
        /// `BattleManager._ResolvePlayCardFromHand_d__447__MoveNext.c:1426`（state 0xb）—— 它排在**整条登场链之后**：
        /// `PlayMinionFromHand` 飞行 0.3 → `WaitForSeconds(GetMinionConversionTime)` = `GetHandToBoardAnimEventTime(0.55)`
        /// + `minionToConversionPointTime(0.3)` = 0.85 → `yield MinionPlayedIntoField` = `delay 0.1` +
        /// `timeBeforeLand 0.05` + `timeToLand 0.2` + `attackStepTime 0.1` = 0.45 ⇒ **1.30 s**
        /// （常量与逐段出处 → `EventTiming.PlayBucketHandPlayedHold`）。</para>
        ///
        /// <para>⚠️ **只对手牌打出的单位成立**（`J1` §1 那张表）：
        /// · **战术 / 法术 = 0**（`_d__447:641 goto LAB_1809bdcfc` 直落广播块；`Slot < 0` 的无目标战术卡同理）；
        ///   🔴 **例外（2026-10-25 `AU1` · `J3` §4 已接）**：**敌方**从手牌打出 `targeted` 的战术/低语 ⇒
        ///   **+0.5**（准星定位 `EnemyTargetingAnim` 的 `WaitForSeconds(GetTargettingTime())`，`_d__447:477-491`；
        ///   回放局 ÷3 = 0.1667）—— 判据与门见实现里那段注释、常量 = `EventTiming.EnemyTargetingHold`；
        /// · **自动打出 / 效果召唤**：原版**根本不广播 `CardPlayed`**（`_d__447` 是唯一调用点）⇒ 这两个来源
        ///   本来就不该播 `play` 桶；我们的引擎也只在 `RuleCore.PlayCard` / `PlayTactic` 发 `EvtKind.Play` ⇒ 天然一致；
        /// · `teleport` 的卡 ≈ 1.25（`J1` 标「待核」）⇒ 今天按 1.30 排（差 0.05，如实记）。</para>
        /// <para>⛔ 别把它并进 `DeployHoldOf` —— 一个是「`Deploy` 这拍占多久」、一个是「`play` 桶晚多久起播」，
        /// 两件事（`J1` §1 末句也这么说）。</para></summary>
        float PlayBucketOffsetOf(BattleEvent e)
        {
            if (e == null || e.Kind != EvtKind.Play) return 0f;     // 只有 `Play` 才有这一支（Trigger 是别的时机）
            if (e.Slot < 0) return 0f;                             // 无目标战术卡（`Slot = -1` 那一档）
            if (_pool == null) return 0f;
            var def = CardDatabase.Find(_pool, e.CardId,
                        VfxFactionOf(e.Player, e.CardId, e.InstanceId, e.Slot));
            if (def == null) return 0f;
            if (def.IsUnit) return EventTiming.PlayBucketHandPlayedHold;   // 1.30
            // 🔴🆕 **2026-10-25（`AU1` · `J3` §4）：战术 / 低语 · `targeted` · `fromEnemyHand` ⇒ 准星定位 0.5 前置。**
            //   判据（`_d__447:470-491`）：取牌 + `PayCardCost` 之后先 `EnemyTargetingAnim` 再
            //   `WaitForSeconds(GetTargettingTime()=0.5)`，**法术在 `TargetedSpellPlayed` 才生效**。
            //   · `fromEnemyHand` 的等价物 = **打出方不是本机**（`e.Player != _me`；联机客机时 `_me` 可能是 1）；
            //   · `cardType ∈ {Tactic 20, Whispers 40}` —— 我们卡表的 `Type` 只有 `tactic`（低语并入这一档，池内没有单独的 `whisper`）；
            //   · `targeted` = `CardDef.Targeted == 1`（原版 `rawCardData.targeted` `+0x268`，同一列）。
            //   ⚠️ 回放局（`ReplaySkipAnims()` 的等价物 = `_replaySession`）⇒ **÷3 = 0.1667**。
            if (def.Type == "tactic" && def.Targeted == 1 && e.Player != _me)
                return _replaySession
                     ? EventTiming.EnemyTargetingHold / EventTiming.ReplaySkipAnimDivisor
                     : EventTiming.EnemyTargetingHold;
            return 0f;
        }

        /// <summary>🆕 2026-10-25（`AU1` · `J1` §9/§10）：**这一拍的 `screenShake`**（原版 `_ResolveAnim:79-105`,
        /// 与拍子起播**同帧**；门 = preset 非空）。走现成的 `WFModuleScreenShake.Resolve` + `OnShake`
        /// （下游 = `HookAnimFxShake` 里那条相机+HUD 平移，⛔ 别在这里另写一套震屏）。
        /// ✅ **2026-10-25（`TL` §3）**：数据已进运行期表（`shk` 57 行 / 10 个 preset）⇒ **已真的会播**。</summary>
        static void PlayBeatShake(CardAnimPlacement p)
        {
            if (string.IsNullOrEmpty(p.ShakePreset)) return;
            var entry = new WarpforgeVFX.WFModuleScreenShake.ShakeEntry
            {
                preset = p.ShakePreset,
                delay = Mathf.Max(0f, p.ShakeDelay),
                overwriteAmplitude = p.ShakeOverAmplitude, amplitude = p.ShakeAmplitude,
                overwriteFrequency = p.ShakeOverFrequency, frequency = p.ShakeFrequency,
            };
            var req = WarpforgeVFX.WFModuleScreenShake.Resolve(entry);
            var hook = WarpforgeVFX.WFModuleScreenShake.OnShake;
            if (hook != null) hook(req);
            else WarpforgeVFX.WFModuleScreenShake.DroppedRequests++;
        }

        /// <summary>🆕 **2026-10-25（`AU1` · `TL` §1·4 判据读全）：卡本体沿曲线位移那一档** ——
        /// `AnimInfo.minionMovementInfo` + `shouldActivateMinionMovement != 0`。
        /// 原版 = `CardScript.MoveAndDisappearAnim`（`_d__358` 388 行 + `ApplyMovementDisappearAnimRotations`），
        /// 调用点 `BattleManager._ResolveAnim_d__466:214-231`（**与「等 `GetAnimDuration()`」是 if/else** ⇒
        /// 这一拍时长 = <see cref="CardAnimPlacement.MoveBodyDelay"/> + <see cref="CardAnimPlacement.MoveBodyTime"/>，
        /// 那半在 `SkillBeatDuration` / `PlayPlacedPieces` 里已按此算）。
        ///
        /// <para>**逐句算式**（`TL` §1·4，`:` 后是 `_d__358` 的行号）：</para>
        /// <list type="number">
        /// <item>`delay > 0 ⇒ WaitForSeconds(delay)`（`:71-79`）⇒ 这里用 `SetDelay`。</item>
        /// <item>`start = transform.TransformPoint(originalLocalPosInPlay)`（`:81-87`）——
        ///   我们**没有** `originalLocalPosInPlay`（那是原版在场静止位的一份缓存）⇒ 等价物 = **这一拍起播时卡的当前位置**
        ///   （让位/瞄准补间与它同帧结束，正常就是格位）。⚠️ 如实记。</item>
        /// <item>`n = normalize(boardPos − start)`（`:101-112`），`boardPos` = **目标卡**的位置
        ///   （`BattleManager.GetBoardPosOfCard(targetCard)`）。</item>
        /// <item>`margin = isPlayer ? playerAttackMargin(1.7) : enemyAttackMargin(1.0)`（`:95-100`）。</item>
        /// <item>**`end = boardPos − n × margin`**（`:113-117`）。</item>
        /// <item>`end += v × (targetCard.effectsAnchor.y − targetCard.y) × attackPositionYOffset(0.5)`（`:126-137`）——
        ///   🔴 **2026-10-25（`AU1` · `J3` §2·②）判据闭合：`v` = `Vector3.up`**（同一个静态格 `+0x18`，
        ///   `il2cpp.h:5149-5160` 的声明序 + 四条独立互证）⇒ 等价算式
        ///   `end.y += CardFeel.EffectsAnchorHeight(target) × CardFeel.AttackPositionYOffset`
        ///   （`EffectsAnchorHeight` 就是「锚点到卡底边」= 原版的 `effectsAnchor.y − card.transform.y`）。</item>
        /// <item>`end.x += xOffset; end.z += zOffset`（**yOffset 不在这里加**，`:140-142`）。
        ///   ⚠️ 这两个偏移**与目标无关**（数据自带）⇒ 我们的「没有目标卡」那条退路里也照加（⛔ 不是猜方向）。</item>
        /// <item>补间（时长**全 = `animTime`**，`:156-225`）：`useXZCurve == false` ⇒ 一条 `DOMove(end)`
        ///   （**不 `SetEase`** ⇒ 吃 DOTween 默认）；`true` ⇒ `DOMoveX(end.x).SetEase(curveX)` +
        ///   `DOMoveZ(end.z).SetEase(curveZ)`；`useYCurve` ⇒ 另加 `DOMoveY(yOffset + end.y).SetEase(curveY)`。</item>
        /// <item>收尾（state 3，`:247-267`）：`transform.position = end`；`visibilityStateAfterFinish == 0`
        ///   ⇒ `CardUI.ToggleBody3D(false, true)`（= 卡体隐藏 + `effectsAnchor` 显示；**`effectsAnchor` 那半我们不用做**
        ///   —— 我们的 `EffectAnchorBoard` 从不 SetActive(false)）；`!= 0` ⇒ **什么都不做**
        ///   （⚠️ 现读 2 行都是 0，其它值**没有样本** ⇒ 出声一次，但按原版「什么都不做」执行，⛔ 不猜「显示」）。</item>
        /// <item>🔴 **三轴旋转**（`:284-378` + `CardScript__ApplyMovementDisappearAnimRotations.c`，**2026-10-25（`AU1` · `J3` §2）
        /// 判据全解**）：轴 = **世界 right(X) / up(Y) / forward(Z)**；单轴
        /// `enable == 0 ⇒ identity`，否则 `Quaternion.SlerpUnclamped(startRot, AngleAxis(maxValue 度, axis), curve.Evaluate(elapsed/animTime))`
        /// —— 🔴 **必须 Unclamped**（中键 −0.952，钳到 0 会抹掉「先反拧约 −43° 再甩到 +45°」）；
        /// 连乘 = `transform.rotation = qX * qY * qZ * startRot`，**三次的 `cur` 都是 `startRot`**
        /// （`startRotation` 在**起播那一刻**取，原版 `:229-236`）；`elapsed` 由 tween 自己推（`Elapsed(false)` 排掉 `SetDelay`）。</item>
        /// </list>
        /// <para>⛔ 全部走 `CardTween.Use`（批处理 = `Manual`，由 `CardTween.Advance` 推）+ `SetLink` ——
        /// **不能靠 `Update`**（批处理没有帧循环）。</para></summary>
        void PlayMinionMovement(CardView self, CardView target, CardAnimPlacement p, bool isPlayer)
        {
            if (self == null || !p.MoveBody) return;
            float delay = Mathf.Max(0f, p.MoveBodyDelay);
            float dur = Mathf.Max(0f, p.MoveBodyTime);
            // ⑩ 起播那一刻的朝向（原版 `:229-236`）—— 三轴 Slerp 的**起点**，三次 Apply 都用它（不是上一次的结果）
            Quaternion startRot = self.transform.rotation;

            // ② 起点：原版 `TransformPoint(originalLocalPosInPlay)`；我们的等价物 = 起播这一刻的世界位置。
            Vector3 start = self.transform.position;
            Vector3 end = start;
            if (target == null)
            {
                // 原版这一支 `targetCard` 必非空（`_d__358` 一进去就解引用）；我们没有目标就**不位移**、只占时长，并出声。
                WarnMinionMove("这一拍**没有目标卡** ⇒ 终点算不出来（原版 `boardPos = GetBoardPosOfCard(targetCard)`）"
                             + " ⇒ 只按 `delay + animTime` 占时长、不位移");
            }
            else
            {
                Vector3 boardPos = target.transform.position;
                Vector3 n = boardPos - start;
                if (n.sqrMagnitude <= 1e-8f)
                {
                    WarnMinionMove("起点与目标重合 ⇒ `normalize(0)` 无方向（原版那一下会给 0 向量）⇒ 本拍不位移");
                }
                else
                {
                    // ③④⑤ end = boardPos − normalize(boardPos − start) × margin
                    float margin = isPlayer ? CardFeel.PlayerAttackMargin : CardFeel.EnemyAttackMargin;
                    end = boardPos - n.normalized * margin;
                    // ⑥ 🔴 `v` = **Vector3.up**（`J3` §2·② 已闭合）⇒ `end.y += Δy × attackPositionYOffset`
                    //   （Δy = 目标卡「锚点 − 卡底边」的高，`CardFeel.EffectsAnchorHeight` 就是它）
                    end.y += CardFeel.EffectsAnchorHeight(target) * CardFeel.AttackPositionYOffset;
                }
            }
            // ⑦ x/z 偏移（`yOffset` 不在这里加）—— 与目标无关（数据自带），**两条支都加**
            end.x += p.MoveOffX;
            end.z += p.MoveOffZ;

            // ⑧ 补间（时长全 = animTime）
            var move = DG.Tweening.DOTween.Sequence();
            if (p.MoveUseXZ)
            {
                var tx = self.transform.DOMoveX(end.x, dur);
                var cx = MinionCurve(p.MoveCurveX); if (cx != null) tx.SetEase(cx);
                move.Append(tx);
                var tz = self.transform.DOMoveZ(end.z, dur);
                var cz = MinionCurve(p.MoveCurveZ); if (cz != null) tz.SetEase(cz);
                move.Join(tz);
            }
            else
            {
                // 原版**不 SetEase** ⇒ 吃 DOTween 默认缓动（本工程 = 6 `OutQuad`）
                move.Append(self.transform.DOMove(end, dur));
            }
            if (p.MoveUseY)
            {
                var ty = self.transform.DOMoveY(p.MoveOffY + end.y, dur);
                var cy = MinionCurve(p.MoveCurveY); if (cy != null) ty.SetEase(cy);
                move.Join(ty);
            }

            // ⑨ 收尾：钉回 end + 按 `visibilityStateAfterFinish` 收卡本体
            move.OnComplete(() =>
            {
                if (self == null) return;
                self.transform.position = end;
                if (p.MoveBodyEndVis == 0) self.SetBody3DVisible(false);   // 0（现读两行的值）= 隐藏卡本体
                else
                    WarnMinionMove($"`visibilityStateAfterFinish = {p.MoveBodyEndVis}`（**没有样本**）⇒ 按原版那一支"
                                 + "「**什么都不做**」执行（⛔ 不猜成「显示」）");
            });
            var tw = CardTween.Use(move, DG.Tweening.Ease.Linear, self.transform);
            if (delay > 0f) tw.SetDelay(delay);

            // ⑩ 三轴旋转（判据 → 本方法的 doc 第 ⑩ 条）：逐帧 `rotation = qX * qY * qZ * startRot`。
            //   ⚠️ 曲线**先建一次**（`AnimationCurve` 每帧 new 太浪费）；`Elapsed(false)` 排掉 `SetDelay`（同 `CardFeel.HookDepthScale` 的读法）。
            //   ⚠️ 如实记一处原版形状：单轴 `SlerpUnclamped(startRot, …, k)` 在 `k == 0` 时**返回 `startRot`（不是 identity）**
            //      ⇒ `startRot` 完全不是单位四元数时，t=0 那一帧的 `qX*qY*qZ*startRot` 会是 `startRot⁴`。
            //      原版算的是同一式（`J3` §2·③/④ 逐项还原），而双方场上卡都是 billboard（`rotation ≈ identity`）
            //      ⇒ 今天无可见差；⛔ 别为了「看起来更对」自己把 k=0 换成 identity（那是改原版口径）。
            var rotX = MinionCurve(p.RotXCurve);
            var rotY = MinionCurve(p.RotYCurve);
            var rotZ = MinionCurve(p.RotZCurve);
            if (p.RotXOn || p.RotYOn || p.RotZOn)
            {
                move.OnUpdate(() =>
                {
                    if (self == null) return;
                    float t01 = dur > 1e-6f ? move.Elapsed(false) / dur : 1f;   // 不 Clamp：原版曲线的 pre/post 本身就是 Clamp
                    Quaternion qx = MinionAxisRot(p.RotXOn, p.RotXDeg, Vector3.right, rotX, startRot, t01);
                    Quaternion qy = MinionAxisRot(p.RotYOn, p.RotYDeg, Vector3.up, rotY, startRot, t01);
                    Quaternion qz = MinionAxisRot(p.RotZOn, p.RotZDeg, Vector3.forward, rotZ, startRot, t01);
                    self.transform.rotation = qx * qy * qz * startRot;
                });
            }
        }

        /// <summary>单轴旋转（`CardScript__ApplyMovementDisappearAnimRotations` 逐句）：
        /// `enable==0` / 没有曲线 ⇒ `identity`；否则 `Quaternion.SlerpUnclamped(startRot, AngleAxis(maxValue 度, axis),
        /// curve.Evaluate(t01))`。🔴 **必须 `SlerpUnclamped`** —— 现读曲线中键 **−0.952**，钳到 0 会把
        /// 「先反向拧约 −43°、再甩到 +45°」整段抹掉（判据 `J3` §2·④）。</summary>
        static Quaternion MinionAxisRot(bool on, float deg, Vector3 axis, AnimationCurve curve,
                                        Quaternion startRot, float t01)
        {
            if (!on || curve == null) return Quaternion.identity;
            return Quaternion.SlerpUnclamped(startRot, Quaternion.AngleAxis(deg, axis), curve.Evaluate(t01));
        }

        /// <summary>扁平 `[t,v,…]` → `AnimationCurve`（`null` / 不足 2 键 ⇒ `null` = 不 `SetEase`，
        /// 与原版「那一轴没有曲线就不设缓动」同义）。`t` 已在 [0,1]（原版 `curve.Evaluate(elapsed/animTime)`）。</summary>
        static AnimationCurve MinionCurve(float[] flat)
        {
            if (flat == null || flat.Length < 4) return null;
            int n = flat.Length / 2;
            var keys = new Keyframe[n];
            for (int i = 0; i < n; i++) keys[i] = new Keyframe(flat[i * 2], flat[i * 2 + 1]);
            return new AnimationCurve(keys);
        }

        static bool _warnedMinionMoveNoTarget, _warnedMinionMoveDegenerate, _warnedMinionMoveVis;
        /// <summary>这一档的**每一类**「算不出/无样本」各出声一次（⛔ 不静默；也不刷屏）。
        /// （2026-10-25 起「`v` 读不到」与「三轴旋转未建」两类**已消失** —— 判据由 `J3` 闭合、两处都已实现。）</summary>
        static void WarnMinionMove(string why)
        {
            // 用「类别」去重：同一类只喊一次（文案里带具体原因，方便定位是哪一条）。
            if (why.Contains("没有目标卡")) { if (_warnedMinionMoveNoTarget) return; _warnedMinionMoveNoTarget = true; }
            else if (why.Contains("重合")) { if (_warnedMinionMoveDegenerate) return; _warnedMinionMoveDegenerate = true; }
            else { if (_warnedMinionMoveVis) return; _warnedMinionMoveVis = true; }
            Debug.LogWarning("[Battle] `minionMovementInfo`（`CardScript.MoveAndDisappearAnim` 等价物）：" + why);
        }

        /// <summary>一条事件的全部候选**按 `AnimInfo` 的逐拍参数**播出去（`play` / `trigger` 桶共用这一口）。
        /// 返回真正排出去的件数（0 = 这条事件本来就没有件）。
        /// <para>⛔ **不写第二份展开逻辑**：名字/时长/错开仍由 `VfxMap.ResolveAllTimed` 给，
        /// 播放仍由 `PlayAbilityBeat` 做 —— 本方法只负责「把 `AnimInfo` 的逐拍参数接上去」。</para>
        /// <para>⚠️ 某一个候选**在 `cardanim_clips` 里查不到**（`PlacementOf` 回 null）⇒ 那一件**退回今天的
        /// 单点路**（`FireEventAll(evt, 一个点)` 同款：`CardEffects.Fire(name, fallbackPos)`）——
        /// 与改前逐字一致，⛔ 不拿默认参数硬套锚点。</para></summary>
        int PlayPlacedPieces(BattleEvent e, string evt, string faction, bool perCardOnly, string keyword,
                             CardView self, CardView target, Vector3 fallbackPos,
                             bool cardAnimRowsOnly = false, float baseAt = 0f)
        {
            if (e == null || string.IsNullOrEmpty(evt)) return 0;
            var items = VfxMap.ResolveAllTimed(evt, faction, e.CardId, AnimTimesOf(e.CardId, faction),
                                               _vfxOffsetRng, perCardOnly, keyword);
            int fired = 0;
            for (int i = 0; i < items.Length; i++)
            {
                var it = items[i];
                if (string.IsNullOrEmpty(it.Name)) continue;
                // `R6`：只取「来自 `cardAnimations[]` 的那一族」（`ResolvedVfx.Anim` 非空）——
                // 这正是 D13 用的判别式（`customDeathParticles` 解出来**没有** `CardAnim`，
                // 见 `VfxMap.ResolveDeathParticle` 的 doc），⛔ 不另立第二条判据。
                if (cardAnimRowsOnly && string.IsNullOrEmpty(it.Anim)) continue;
                var place = CardAnimClips.PlacementOf(it.Anim);
                // 🆕 2026-10-25（`AU1` · `新账 N4`）：**`startDelay` 折进起播偏移**（判据 →
                //   `BattleManager._ResolveAnim_d__466__MoveNext.c:67-75`：state 0 先
                //   `WaitForSeconds(AnimInfo+0x28)` 才 `DelayedVFXPlay`；`it.T` 里已经含 `vfxDelayTime`）。
                //   现读全池只有 1 件非 0（`Cuts Brutal Warp Spider` 0.5 s，`Empyric Ambush SaimHann` 的 `play` 桶）。
                float at = Mathf.Max(0f, baseAt) + it.T
                         + (place.HasValue ? Mathf.Max(0f, place.Value.StartDelay) : 0f);
                // 🆕 2026-10-25（`AU1` · `J1` §9）：**卡本体位移那一档** ⇒ 这一拍时长换成 `delay + animTime`
                //   （原版 `_ResolveAnim` 是 if/else：走 `MoveAndDisappearAnim` 就**不再**等 `GetAnimDuration`）。
                //   ✅ 2026-10-25（`TL` §1）数据已进表（`mvt==1` 2 行、`mva=0.6`）⇒ 这一档**现在真的会生效**。
                float beatDur = it.Duration;
                if (place.HasValue && place.Value.MoveBody)
                    beatDur = Mathf.Max(0f, place.Value.MoveBodyDelay) + Mathf.Max(0f, place.Value.MoveBodyTime);
                if (at <= VfxTimeEpsilon)
                    PlayPlacedOne(e, it.Name, place, self, target, fallbackPos);
                else
                {
                    // 与 `FireEventAll` 同一个错开口径（`ResolvedVfx.T` = 组内顺序时长之和 + 自身 `vfxDelayTime`）。
                    string nm = it.Name; var pl = place;
                    ScheduleAction(at,
                        () => PlayPlacedOne(e, nm, pl, self, target, fallbackPos), beatDur);
                }
                fired++;
            }
            return fired;
        }

        /// <summary><see cref="PlayPlacedPieces"/> 的单件（见那一大段的判据）。</summary>
        void PlayPlacedOne(BattleEvent e, string vfx, CardAnimPlacement? place,
                           CardView self, CardView target, Vector3 fallbackPos)
        {
            if (string.IsNullOrEmpty(vfx)) return;
            if (!place.HasValue)
            {
                // 判据为空（这条候选没有 `CardAnim` 名 / 表里没有它）⇒ **退回今天那条单点路**。
                CardEffects.Fire(vfx, fallbackPos);
                return;
            }
            var p = place.Value;
            int sp = p.StartPos, pt = p.PointTowards;
            if (self == null && sp >= (int)PositionOption.self && sp <= (int)PositionOption.abilityTarget)
            {
                // 原版 `0/1/2` 三档都指向 `thisCard` / `targetCard` —— 我们手里**没有那张 2D 卡**时解不出来。
                if (e.Slot < 0)
                {
                    // `R1`（未指定目标的战术/防御）：降级到 `createCardPos(140)`（原版 `GetUIAnchor(140)`，
                    // 中央展示位那颗锚）。**我们挑的降级**，如实标。
                    sp = (int)PositionOption.createCardPos;
                }
                else
                {
                    // 有格位、却没有卡视图 ⇒ **与改前逐字一致**：根特效播在这一格（= 改前 `FireEventAll` 那条）。
                    // ⛔ 不拿 140 硬套（那会把本该在棋盘上的件挪到 HUD 中央）；也⛔ 不去调
                    // `AnimAnchors`（它对空卡视图会逐条 `LogError`，几百行会把日志冲掉 —— 判据本来就空）。
                    CardEffects.Fire(vfx, fallbackPos);
                    return;
                }
            }
            // 没有目标时：`1 cardTarget / 2 abilityTarget` 两档的「朝向」没有意义
            // （原版 `PlayAnim.c:191-219` 对 `2` 会退到 `thisCard` ⇒ 朝自己 = 不转）⇒ 按「不朝向」播。
            if (target == null && pt >= (int)PositionOption.cardTarget && pt <= (int)PositionOption.abilityTarget)
                pt = 0;
            // 🆕 2026-10-25（`AU1` · `J1` §9/§10）：起播同帧的屏震 + 卡本体位移那一档
            //   （两条都缺数据时零调用；判据见各自的方法 doc）。
            PlayBeatShake(p);
            PlayMinionMovement(self != null ? self : ViewAt(e.Player, e.Slot), target, p, e.Player == _me);
            PlayAbilityBeat(e, vfx, sp, p.EndPos, pt,
                            p.Move, p.OrientToVelocity, p.Ts, p.Tm, p.Ease,
                            null, place, self, target);
        }

        /// <summary>🔴🆕 **2026-10-24（执行代理 `W1` · AN1 `R6` · **S0**）：单位死亡时**它自己的死亡触发能力动画**
        /// （`ThisUnitDeath(80)` / `UnitDeathByAbility(180)` → `TriggerAbilities` → `AbilityLogic.PlayAnim`）。
        ///
        /// <para>**病灶**：生成器把这两族的 `cardAnimations[]` 归到 `death` 桶
        /// （`工具/gen_card_vfx_by_card.py` 的 `TRIGGER_EVENT`），而 `death` 桶在表现层只有两个消费者：
        /// ① `CardFeel.PickDeathFx` —— `D13` 之后**只认 `customDeathParticles`**（那一族解出来没有 `CardAnim`）；
        /// ② `PlaySignal` —— `GenericVfxFor(Death)` 回 `null` ⇒ 走到 `evt == null` 那条 early-return。
        /// ⇒ 这两族的动画**一条都不播**（现读 **7 行 / 6 卡**：`AM34`(180) · `BL62` · `BL66` ·
        /// `GOF3`×2 · `GOF83` · `SAU72`）。`D13` 只修掉了「被当成阵亡爆散体播」，**播放拍本身没建**。</para>
        ///
        /// <para>**判据**：`RawCardScript__OnMinionDeath.c:19/22/23` —— 死者自己那一支先 `0x50`（80）、
        /// 再 `0x51`（81）、再按死因发 175/180/170；`TriggerAbilities` → `AbilityLogic.PlayAbility` →
        /// `PlayAnim`（= `PlayAbilityBeat` 那条逐拍路）。⇒ **这一拍就是「这个单位死了」那一拍**，
        /// 我们的等价物 = `EvtKind.Death`（引擎在死亡那一刻发的表现层信号）。</para>
        ///
        /// <para>🔴 **与 `D13` 不冲突**：`PickDeathFx` 管的是「哪一件**阵亡爆散体**」（`customDeathParticles` /
        /// 默认件）；本方法管的是「**能力动画**那一族」，两者按 `ResolvedVfx.Anim` 是否为空**互斥**划分
        /// （判据只此一处 = `VfxMap.ResolveDeathParticle` 的 doc），同一行不会被两边各播一次。</para>
        ///
        /// <para>⚠️ **如实记（没有编造）**：原版的 80/180 排在**反噬结算之后**（`ResolveBacklash:88` → `:144`），
        /// 而我们的 `EvtKind.Death` 是**先发**的表现信号（"趁格位还有意义"）⇒ 我们这一拍**比原版早**。
        /// 差多少没量过；先按「同一个死亡拍」落，⛔ 别为此把它挂到引擎的反噬之后（那是引擎线的口）。</para></summary>
        int PlayDeathAbilityAnims(BattleEvent e)
        {
            if (e == null || e.Kind != EvtKind.Death || Ctx == null) return 0;
            // 🔴 C5（2026-10-25）：原版按 **`cardArmy`**（卡自己的阵营）查特效/动画表 —— 见 `VfxFactionOf` 的 doc
            string faction = VfxFactionOf(e.Player, e.CardId, e.InstanceId, e.Slot);
            var self = ViewAt(e.Player, e.Slot);
            var layout = e.Player == _me ? playerBoard : enemyBoard;
            Vector3 fb = (layout != null && e.Slot >= 0)
                       ? layout.DropTargetWorld(e.Slot)
                       : LayoutSpace.ToWorld(0.5f, 0.5f);
            int n = PlayPlacedPieces(e, VfxMap.Death, faction, perCardOnly: true, keyword: null,
                                     self, target: null, fallbackPos: fb, cardAnimRowsOnly: true);
            if (n > 0)
                Debug.Log($"[Battle] 阵亡触发的能力动画：`{e.CardId}`（座位 {e.Player} 格 {e.Slot}）"
                        + $"播了 {n} 件（原版 `TriggerAbilities(80/180)` → `AbilityLogic.PlayAnim`；"
                        + "判据 → `PlayDeathAbilityAnims` 的 doc）");
            return n;
        }

        // ==================================================================
        //  🆕 2026-10-19（战斗线 B1 · 偏差 6）：**技能拍的「起→终位移」泵**
        // ==================================================================
        //  判据 = `CardAnimController__Update.c`（逐句读，见 `PlayAbilityBeat` 的 doc 那一串）。
        //  ⚠️ 挂在 `AdvanceTimeline` 上（批处理没有帧循环 —— 挂 `Update` 就成了「只在一种环境下活」的实现）。
        //  🔴 **2026-10-23 就地订正（铁律 5 · `新账-83`）**：这里原来写「**没做的那一半**：`applyMovementOffsets`
        //     没进 `CardAnimBeat` ⇒ 我们走的是**直线**」—— **两句都不成立**：
        //     ① `CardAnimBeat` 早就有 `ao/ont/ofx/ofy/ofz/mn*/mx*` 且生成器已烘（99 拍里 `ao=1` 3 拍）；
        //     ② 今天连**攻击弹道**那条路（数据在 `CardAnimClips`）也补齐了 ⇒ 两条路同一个泵、同一个求值口。
        //     现读 `Resources/card_anim_order.json`：`mv=1` 的 7 拍里 **7 拍都带 `applyMovementOffsets=1`**，
        //     但其中 4 拍 `sp == ep`（`ArmourEffect` / `FlankEffect` / `BlindEffect`）—— 原版
        //     `CardAnimController__Initialize.c` 对 `start == end` **整个 `enabled = 0`**（不飞）⇒
        //     **这 4 拍我们原地播是对的**。真正有弧线的是另外 3 拍（`BulletImpact_MissileToTarget` 3→2）。
        // ------------------------------------------------------------------

        /// <summary>一个「还在飞的」技能拍特效。</summary>
        class AbilityVfxMove
        {
            public Transform carrier;
            public Vector3 start, end;
            public float ts, tm, t;
            /// <summary>位移进度曲线（`easeCurve`，扁平关键帧）。null = 线性（原版默认曲线）。</summary>
            public float[] ease;
            // ── 🆕 2026-10-23（`新账-83`）：`applyMovementOffsets` 的逐轴曲线 ──
            //   原来这里存的是 **`CardAnimBeat` 对象**（只有技能拍那条路有），攻击路径没有 `Beat` ⇒ 拿不到。
            //   现在摊平成「三个曲线 + 一位开关 + 一位时间基准 + 随机幅度」——
            //   **两条路（技能拍 / 攻击弹道）共用同一组字段、同一个求值口**（`CardAnimOrder.OffsetAt`）。
            public int ao, ont;
            public float[] ofx, ofy, ofz;
            /// <summary>三轴的随机幅度（原版每拍初始化时抽一次；见 `RandomOffsetAmp`）。</summary>
            public Vector3 randomAmp;
            /// <summary>🆕 `orientToVelocity`(0x48) —— 移动期间**每帧**转向速度方向（判据见 `TickAbilityVfxMoves`）。</summary>
            public bool otv;
            /// <summary>上一帧写下去的位置（速度 = 本帧 − 它）。初始 = `start`（原版 `Initialize` 存的就是实例初始位）。</summary>
            public Vector3 lastPos;
        }
        readonly List<AbilityVfxMove> _abilityVfxMoves = new List<AbilityVfxMove>();

        /// <summary>🆕 W（偏差 6 第 1 条）：`applyMovementOffsets` 逐轴幅度的随机源。
        /// **独立于引擎的 `Ctx.Rng`**（那一条是规则随机流，表现层碰它会改变对局结果 ⇒ 铁律）；
        /// 在 `Begin` 里用开局种子重建 ⇒ **同一局重放两次得到同一条轨迹**。
        /// 判据：原版 `OffsetMovementCurvesByAxis.GetRandomOffsetValues()` 用的是 `UnityEngine.Random`，
        /// 但铁律要求「确定性只用 `System.Random(seed)`」⇒ 换源、数值口径不变（`min + r × (max − min)`）。</summary>
        System.Random _vfxOffsetRng = new System.Random(20260911);

        /// <summary>三轴幅度：`Random.Range(min, max)` 逐轴（`OffsetMovementCurvesByAxis__GetRandomOffsetValues.c:20-30`）。
        /// ⚠️ **只在 `ao != 0` 时抽** —— 抽一次的副作用是推随机流，不偏移的件不许碰它（否则轨迹会串）。
        /// 两条路（`CardAnimBeat` 技能拍 / `CardAnimPlacement` 攻击弹道）都走这一个口。</summary>
        Vector3 RandomOffsetAmp(CardAnimBeat beatData)
        {
            if (beatData == null) return Vector3.zero;
            return RandomOffsetAmp(beatData.ao, beatData.mnx, beatData.mxx,
                                   beatData.mny, beatData.mxy, beatData.mnz, beatData.mxz);
        }

        Vector3 RandomOffsetAmp(int ao, float mnx, float mxx, float mny, float mxy, float mnz, float mxz)
        {
            if (ao == 0) return Vector3.zero;
            return new Vector3(VfxRange(mnx, mxx), VfxRange(mny, mxy), VfxRange(mnz, mxz));
        }

        float VfxRange(float lo, float hi)
        {
            if (hi <= lo) return lo;
            return lo + (float)_vfxOffsetRng.NextDouble() * (hi - lo);
        }

        /// <summary>每一帧（`AdvanceTimeline` 末尾附近）推一次位移。
        ///
        /// <para>🔴 **2026-10-23（`新账-83`）补齐 `AnimInfo` 那三列**（判据 = `CardAnimController__Update.c:36-97`
        /// 逐句读）：</para>
        /// <list type="bullet">
        /// <item>位置 = `lerp(start, end, easeCurve(t01))`（`ease` 空 = 线性，原版默认曲线）；</item>
        /// <item>`applyMovementOffsets` 开着 ⇒ lerp **之后**逐轴叠 `curve(ont ? t01 : e) × randomAmp`
        ///   （`ont` 真用原始进度、假用缓动后进度）；</item>
        /// <item>`orientToVelocity` 且 `shouldMoveVFX` 开着 ⇒ 每帧 `rotation = LookRotation(速度)`，
        ///   速度 = 本帧位置 − **上一帧写下去的位置**；`|v|² &lt; 1e-10` 时**不转**（保持上一帧朝向）。
        ///   ⚠️ 原版这一句在比较前还减了一个**静态 `Vector3`**（`DAT_1842da2a8 + 0xb8` 那块静态区、
        ///   类名未定）—— 按「每个值都要有判据」的口径如实记：**这一项没解出来**；
        ///   最可能是 `Vector3.zero`（那就与本实现逐值相同），但我**没证实**，所以这里不减。</item>
        /// <item>`t01 ≥ 1` ⇒ 按 **`ease(1)`** 把最终位姿写一次再释放载体（原版是「停止写」，
        ///   最后一帧的值就是 `ease(1⁻)` 的极限）⇒ **`Jain Zar` 那种「飞出去再飞回来」的件会回到起点**，
        ///   ⛔ 别写死 `carrier.position = end`（那会让它停在目标格）。线性档 `ease(1) = 1` ⇒ 仍等于 `end`。</item>
        /// </list></summary>
        void TickAbilityVfxMoves(float dt)
        {
            for (int i = _abilityVfxMoves.Count - 1; i >= 0; i--)
            {
                var m = _abilityVfxMoves[i];
                if (m == null || m.carrier == null) { _abilityVfxMoves.RemoveAt(i); continue; }
                m.t += dt;
                float t01 = m.tm <= 0f ? 1f : (m.t - m.ts) / m.tm;
                if (t01 >= 1f)
                {
                    // `ease(1)` 的极限位置（线性 = `end`；Jain Zar = 起点）
                    float e1 = CardAnimOrder.EaseAt(m.ease, 1f);
                    Vector3 pend = Vector3.Lerp(m.start, m.end, e1);
                    if (m.ao != 0)
                        pend += CardAnimOrder.OffsetAt(m.ao, m.ont, m.ofx, m.ofy, m.ofz, 1f, e1, m.randomAmp);
                    m.carrier.position = pend;
                    ApplyVelocityOrientation(m, pend);
                    ReleaseAbilityCarrier(m.carrier);
                    _abilityVfxMoves.RemoveAt(i);
                    continue;
                }
                if (t01 > 0f)
                {
                    float e01 = CardAnimOrder.EaseAt(m.ease, t01);
                    Vector3 p = Vector3.Lerp(m.start, m.end, e01);
                    // 🆕 W（偏差 6 第 1 条）：`applyMovementOffsets` —— `Update` 在 lerp **之后**叠
                    //   `curve(ont ? t01 : e01) × randomAmp`（逐轴；判据 `CardAnimController__Update.c:60-97`）。
                    //   🆕 2026-10-23（`新账-83`）：求值口收口到 `CardAnimOrder.OffsetAt`（技能拍 / 攻击弹道共用）。
                    if (m.ao != 0) p += CardAnimOrder.OffsetAt(m.ao, m.ont, m.ofx, m.ofy, m.ofz, t01, e01, m.randomAmp);
                    m.carrier.position = p;
                    ApplyVelocityOrientation(m, p);
                }
            }
        }

        /// <summary>🆕 2026-10-23（`新账-83`）：`orientToVelocity` —— 把载体转向**本帧速度方向**。
        /// 判据 = `CardAnimController__Update.c:80-120`：`if (orientToVelocity &amp;&amp; shouldMoveVFX)`
        /// → `v = pos(本帧) − pos(上一帧)`；`if (v.sqrMagnitude &gt;= 1e-10) transform.rotation = LookRotation(v)`。
        /// <para>⚠️ 复杂度如实记：原版比较的是 `v − 静态Vector3`（来源类名未定，见 `TickAbilityVfxMoves` 的 doc），
        /// 这里不减那个静态量；阈值 `DAT_1834b2ba8` 现读 `.rdata` 4 字节 float = **1e-10**（读值工具）。</para>
        /// <para>⚠️ 我们转的是**载体**（特效实例的父节点），原版转的是实例自己 —— 与
        /// `PlayAbilityBeat` 的初始朝向同一个近似口径（prefab 作者朝向会叠上去；`FlattenNewEffectRotation`
        /// 只在技能拍那条路的初始朝向上归零过）。</para></summary>
        static void ApplyVelocityOrientation(AbilityVfxMove m, Vector3 pos)
        {
            if (m.otv)
            {
                Vector3 v = pos - m.lastPos;
                if (v.sqrMagnitude >= 1e-10f)
                    m.carrier.rotation = Quaternion.LookRotation(v.normalized, Vector3.up);
            }
            m.lastPos = pos;
        }

        /// <summary>把载体上的特效**原样留在世界里**，再销毁载体（特效自己的生命周期照旧由播放器管）。
        /// ⚠️ 必须先 `SetParent(null, worldPositionStays: true)` —— 直接销毁载体会把特效一起带走。</summary>
        void ReleaseAbilityCarrier(Transform carrier)
        {
            if (carrier == null) return;
            for (int i = carrier.childCount - 1; i >= 0; i--)
                carrier.GetChild(i).SetParent(null, true);
            Kill(carrier.gameObject);
        }

        /// <summary>🆕 2026-10-19（T05 · 「锚点空间换算（HUD vs 竞技场）」）：把锚点的**层**校正到
        /// 「它现在住在哪个空间」该有的那一层 —— 特效实例的层是 `WarpforgeEffectHook` 按**直接父节点**
        /// 继承的（`WarpforgeEffectHook.cs:36`），锚点层错了特效就由错的相机画。
        ///
        /// <para>三类锚点：</para>
        /// <list type="bullet">
        /// <item>**卡的锚点**（`CardView.EffectAnchor*`）—— 跟着卡：卡在场上 = `ArenaLayer`，在手牌 = 层 0。
        ///   🔴 这一条是**必须**的：`EffectAnchorBoard` 是**懒建**的（第一次要它才 `new`），而
        ///   `CardView.SetLayer` 只在 `SyncBoard` 那一刻递归**已存在**的子件 ⇒ 之后才建的锚点会停在层 0。</item>
        /// <item>**运行时补的两颗锚点**（`Board Center` / `Next Minion Spot`）—— 位置在竞技场空间 ⇒ 3D 档 = `ArenaLayer`。</item>
        /// <item>**HUD 锚点**（`Anim Anchors` 那 4 颗 / 手牌 / 牌堆 / 能量板）—— 它们自己的层就是对的（层 0 = HUD 相机画），**不动**。</item>
        /// </list>
        /// <para>⚠️ 取不到归属 ⇒ 不动它（并**不**出声：这是层校准、不是「判据缺失」）。</para></summary>
        void EnsureAnchorSpace(Transform anchor)
        {
            if (anchor == null) return;
            int want;
            var owner = anchor.GetComponentInParent<CardView>();
            if (owner != null) want = owner.gameObject.layer;
            else if (anchor == _animBoardCenter || anchor == _animMinionSpot)
                want = use3DBoard ? ArenaSlots.ArenaLayer : 0;
            else return;

            if (anchor.gameObject.layer != want) SetLayerDeep(anchor, want);
        }

        /// <summary>把一个节点连同子树设到某一层（Unity 的层**不继承**，必须自己走一遍）。</summary>
        static void SetLayerDeep(Transform t, int layer)
        {
            if (t == null) return;
            t.gameObject.layer = layer;
            for (int i = 0; i < t.childCount; i++) SetLayerDeep(t.GetChild(i), layer);
        }

        /// <summary>清掉所有在飞的特效载体（跨局 / 丢事件时用）。</summary>
        void ClearAbilityVfxMoves()
        {
            for (int i = 0; i < _abilityVfxMoves.Count; i++)
                if (_abilityVfxMoves[i] != null) ReleaseAbilityCarrier(_abilityVfxMoves[i].carrier);
            _abilityVfxMoves.Clear();
        }

        // ==================================================================
        //  🆕 2026-10-19（T05 · `A2081`）：**飞行单位抬到空中 + 上下浮动**
        // ==================================================================
        //  判据（逐句，`d:/2/tools/decomp_full/FlyingCardController__*.c`，2026-10-19 全篇读完）与
        //  全部参数 → `Battle/FlyingCardController.cs` 的文件头；⛔ 别在这儿再抄一份。
        //  「什么时候飞」= **`Has(Flying) && !Has(Vanguard)`** —— 判据 = `BattleCardUI__DisplayStatusAnim.c:297-310`
        //  与 `__RemoveStatusAnim.c:166-172`（flying = 0x186 = 390 · vanguard = 0x3d4 = 980，逐行读过）：
        //  显示 flying 徽标且**没有** vanguard ⇒ 飞；显示 vanguard 徽标且**有** flying ⇒ 落；摘 status ⇒ 按 flying 判。
        //  ⚠️ **只在 `animateFeel` 开时走**（与这一节别的动作同一条规矩）：批处理里卡必须精确停在
        //     `PoseFor` 的坐标上（十几条断言靠它）⇒ 批处理**结构上不抬**。浮动数学由
        //     `FlyingCardController.HeightOffsetAt` 这条**纯函数**给自检单测（不依赖视图）。

        /// <summary>每张在飞的卡 → 它的控制器（键 = 视图；视图销毁后在 tick 里剪掉）。</summary>
        readonly Dictionary<CardView, FlyingCardController> _flyingViews =
            new Dictionary<CardView, FlyingCardController>();
        readonly List<CardView> _flyDead = new List<CardView>();

        /// <summary>`SyncBoard` / 落地那一拍调：按这张卡**现在**有没有 Flying 开/关浮动，
        /// 并把「原地位置」跟到最新摆位（换格 / 让位之后浮动要跟过去）。
        /// <para><paramref name="inFlight"/> = 这张视图正被一段**飞行补间**搬着（AI 出牌那 0.65 s）
        /// ⇒ 这期间不许开浮动（两套位移会抢同一个 `localPosition`）。</para></summary>
        void SyncUnitFlying(CardView v, UnitState u, Vector3 home, bool inFlight)
        {
            if (v == null) return;
            FlyingCardController f;
            _flyingViews.TryGetValue(v, out f);

            // 判据只此一处（见上面那一段）：Flying **且不** Vanguard。
            bool want = !inFlight && animateFeel && u != null
                        && u.Has(KeywordTable.Flying) && !u.Has(KeywordTable.Vanguard);

            if (want)
            {
                if (f == null)
                {
                    f = new FlyingCardController(v.transform);
                    _flyingViews[v] = f;
                }
                f.SetHome(home);
                // 🆕 2026-10-23（`W63` 收口）：**卡体动画层正在「先落地、演完再飞回」那一段时，
                //   这里不许把它拉起来**。`DoAnim(disableFlying: true)` 会把飞行控制器按进
                //   `InTransitionToLand`（0.15 s），而本方法是**每批事件都会跑**的（`SyncBoard`）
                //   —— 不加这道闸，下一帧就 `Toggle(true)` 把落地取消掉 ⇒ 动画永远等不到
                //   `OnFlyingToggleFinish(false)`、**一拍都起不来**（静默）。
                //   判据 = 动画层那两个状态位（0x48 与 0x49 **同时**为真才算「正在为动画落地」）。
                //   ⛔ 别改成「只要 0x49 就跳过」：单 0x49 在动画演出期间一直是真，
                //   那样会让「演完之后又该飞起来」的那次同步也被跳过（单位永久留在地面）。
                var ac = AnimOfForTest(v);
                if (ac != null && ac.UnitWasFlying && ac.HasAlreadyToggledOffFlying) return;
                f.Toggle(true);                       // 幂等：已在过渡/已飞起 ⇒ `ChangeState` 早退
                return;
            }

            if (f == null) return;
            f.SetHome(home);
            f.Toggle(false);                          // 0.4 s 落回（`DefaultTransitionTime`）
            if (f.State == FlyingCardController.States.Landed) _flyingViews.Remove(v);
        }

        /// <summary>每帧推一次（`AdvanceTimeline` 里调）。视图销毁 ⇒ 账作废（Unity 的 `== null` 判得出来）。</summary>
        void TickFlyingUnits(float dt)
        {
            if (_flyingViews.Count == 0) return;
            _flyDead.Clear();
            foreach (var kv in _flyingViews)
            {
                if (kv.Key == null) { _flyDead.Add(kv.Key); continue; }
                kv.Value.Update(dt);
            }
            for (int i = 0; i < _flyDead.Count; i++) _flyingViews.Remove(_flyDead[i]);
            _flyDead.Clear();
        }

        /// <summary>跨局 / 丢事件：清账（视图本来就要销毁/复位）。</summary>
        void ClearFlyingUnits()
        {
            _flyingViews.Clear();
        }

        /// <summary>自检：现在有几个视图挂着飞行控制器。</summary>
        public int FlyingUnitCountForTest { get { return _flyingViews.Count; } }

        /// <summary>自检：某个视图的飞行状态（没有控制器 ⇒ `null`）。</summary>
        public FlyingCardController FlyingOfForTest(CardView v)
        {
            FlyingCardController f;
            return (v != null && _flyingViews.TryGetValue(v, out f)) ? f : null;
        }

        // ==================================================================
        //  🆕 2026-10-23（`W63` 收口）：**卡体动画层**（`Card3DAnimationController`）
        // ==================================================================
        //  判据（逐方法亲读）→ `Battle/Card3DAnimationController.cs` 文件头（状态机 / 常数 / 我们改的三处）。
        //  这一节只做三件事：**谁持有它** · **谁推它** · **谁调它**。
        //   · 持有 = 每个场上的 `CardView` 一份（`_animViews`，懒建；视图销毁就剪掉）。
        //   · 推   = `AdvanceTimeline` → `TickCardAnims`（批处理没有帧循环，同 `TickFlyingUnits` 的理由）。
        //   · 调   = `PlayUnitSkillAnim`（下面）：把 `VfxMap.UnitAttack` / `UnitDamaged` 那两桶的每一拍
        //            **既播技能动画 prefab**（`PlayAbilityBeat`，与原版 `AbilityLogic.PlayAnim` 同一个口）
        //            **也喂给 `DoAnim`**（卡体动画 + 飞行闸）。
        //
        //  ⚠️ **`DoAnim` 喂什么**（如实记，铁律 3 + 11）：
        //    原版喂的是 `MinionAnimClipInfoDefinition.animationClip`（真 `AnimationClip`），
        //    而本 build 的**卡体 clip 表是空的** —— 判据：`assets_full` 全库 **1,152** 个 `CardAnim`
        //    里 `minionAnimationClipInfo.enable`（序列化注释 "Use animation clips or not"）为 1 的
        //    **0 个**、`minionClips` 非空的 **0 个** ⇒ 原版这条链在这份数据上**一次都不会走到**
        //    （`BattleManager._ResolveAnim_d__466__MoveNext.c:166-171` 那道 `enable == 0` 的分支）。
        //    ⇒ 我们喂的是**同一张卡同一拍的技能动画 prefab + 它的 `AnimInfo.GetAnimDuration()`**
        //      （`CardAnimPlayback.Prefab` 那一路）—— 这样「落地闸住 → 演完 → 飞回去」那套状态机
        //      在**有数据的那一层**上真的在跑，而不是一条只存在于纸面上的代码。
        //      ⛔ **绝不伪造 `AnimationClip`**：`Clip` 那一路完整可用（`BattleScene` 用探针 clip 证明）。
        //    ⚠️ `toggleFlyOff`（原版 = `MinionAnimClipInfoDefinition` 的 +0x25，**逐 clip 序列化**）
        //      今天**没有判据可读**（没有 clip ⇒ 没有那一位）⇒ 取 `true`（= 本件要求的那条行为）。
        readonly Dictionary<CardView, Card3DAnimationController> _animViews =
            new Dictionary<CardView, Card3DAnimationController>();
        readonly List<CardView> _animDead = new List<CardView>();

        /// <summary>自检：本局一共排过几拍「逐卡技能动画」（= 真的解出了候选的那些拍）。</summary>
        public int UnitSkillAnimsScheduled { get; private set; }

        /// <summary>🆕 2026-10-24（执行代理 `B1` · 战斗线 `D3`）自检口：最近一拍技能动画**真的起播**
        /// 那一刻的 `_clock`（在 `PlayOneUnitAnim` 第一行记）。用来验「Trigger 那条路与改前 ③ 的时刻等价」：
        /// 期望 ≈ <see cref="BatchAttackSkillAnimAtForTest"/>（差 ≤ 一个 `Step` 的 dt）。</summary>
        public float LastUnitSkillBeatAtForTest { get; private set; } = -1f;

        /// <summary>🆕 2026-10-24（`B1` · `D3`）自检口：最近那次 `UnitAttack` 分流**用的是不是攻击事件当载体**
        /// （`true` = 反应者就是攻方：`attacked` 族 / `SW16` 那种自己攻击的监听者 ⇒ 带 `Target*`；
        /// `false` = 别的卡在监听 ⇒ 用它自己的 trigger 事件，**没有目标**）。</summary>
        public bool LastUnitSkillUsedAttackEventForTest { get; private set; }
        /// <summary>自检：其中真的有内容（prefab 非空）的拍数 —— 纯计时拍（`Wait_1s`）不算。</summary>
        public int UnitSkillAnimBeats { get; private set; }

        /// <summary>取这个视图的卡体动画控制器（懒建；`Flying` 那一档**按需**去 `_flyingViews` 拿）。</summary>
        Card3DAnimationController CardAnimOf(CardView v)
        {
            if (v == null) return null;
            Card3DAnimationController c;
            if (_animViews.TryGetValue(v, out c) && c != null) return c;
            var view = v;      // 闭包按视图取（同一个视图可能一会儿在飞、一会儿落地）
            c = new Card3DAnimationController(view.transform,
                                              () => FlyingOfForTest(view));
            _animViews[v] = c;
            return c;
        }

        /// <summary>每帧推一次（`AdvanceTimeline` 里调，紧跟 `TickFlyingUnits`）。</summary>
        void TickCardAnims(float dt)
        {
            if (_animViews.Count == 0) return;
            _animDead.Clear();
            foreach (var kv in _animViews)
            {
                if (kv.Key == null) { _animDead.Add(kv.Key); continue; }
                if (kv.Value != null) kv.Value.Update(dt);
            }
            for (int i = 0; i < _animDead.Count; i++) _animViews.Remove(_animDead[i]);
            _animDead.Clear();
        }

        /// <summary>跨局 / 丢事件：清账（视图本来就要销毁）。</summary>
        void ClearCardAnims()
        {
            foreach (var kv in _animViews) if (kv.Value != null) kv.Value.Detach();
            _animViews.Clear();
        }

        /// <summary>自检：某个视图的卡体动画控制器（没建 ⇒ `null`）。</summary>
        public Card3DAnimationController AnimOfForTest(CardView v)
        {
            Card3DAnimationController c;
            return (v != null && _animViews.TryGetValue(v, out c)) ? c : null;
        }

        /// <summary>自检：现在有几个视图挂着卡体动画控制器。</summary>
        public int CardAnimControllerCountForTest { get { return _animViews.Count; } }

        /// <summary>一条「逐卡技能动画」事件：把该卡这个桶里的每一拍排出去。
        /// <para><paramref name="evt"/> = <see cref="VfxMap.UnitAttack"/>（攻方，攻击收尾时）/
        /// <see cref="VfxMap.UnitDamaged"/>（受击方，`Hit` 那一拍）。</para>
        /// <para><paramref name="t0"/> = 相对**现在**的起点偏移（秒）。</para>
        /// <para>⚠️ 表里没有这张卡 ⇒ **什么都不做**（原版这两档只有逐卡，没配 = 没有；
        /// `VfxMap.IsOriginalNoGenericEvent` 已经把「静默回 null」写死了）。</para></summary>
        void PlayUnitSkillAnim(BattleEvent e, string evt, float t0)
        {
            if (e == null || string.IsNullOrEmpty(evt)) return;
            var v = ViewAt(e.Player, e.Slot);
            if (v == null) return;                       // 视图不在（刚被移走 / 还没建）⇒ 不表演，不是错
            // 🔴 C5（2026-10-25）：原版按 **`cardArmy`**（卡自己的阵营）查特效/动画表 —— 见 `VfxFactionOf` 的 doc
            string faction = VfxFactionOf(e.Player, e.CardId, e.InstanceId, e.Slot);
            var clips = CardAnimClips.Resolve(evt, faction, e.CardId, AnimTimesOf(e.CardId, faction));
            if (clips.Length == 0) return;

            UnitSkillAnimsScheduled += clips.Length;
            for (int i = 0; i < clips.Length; i++)
            {
                var clip = clips[i];
                // 🆕 2026-10-23（P1 · 演出时序 ④ · `新账-75①`）：**这一拍演多久**走
                // `SkillBeatDuration`（单候选时 `clip.Duration` 被 `VfxMap` 的回归口径压成 0，
                // 那里会去 `AnimInfo` 补真值 —— 判据见那个方法的 doc）。
                float dur = SkillBeatDuration(clip);
                // 🔴 **2026-10-23（P2 · 演出时序 · `新账-75④` / `新账-78③`）就地修复（铁律 5）**：
                //   这里原来还有 `+ Mathf.Max(0f, clip.Place.VfxDelay)` —— **`vfxDelayTime` 被加了两次**：
                //   `clip.T` 里**已经含**同一次延迟（`VfxMap.cs:1197-1228`：`T = t + delay`，
                //   `delay = times[idx].Delay`，即 `CardAnimTime.Delay` = 原版 `vfxDelayTime`）。
                //   判据 = `BattleManager._DelayedVFXPlay_d__469:17-27`：原版**只等一次** `vfxDelayTime`。
                //   ⇒ 现在只信 `clip.T`（**唯一一处**折算延迟）。⛔ 别在 `CardAnimClips.VfxDelay` 那一侧再加回来。
                //   ⚠️ 今天零可见差（现读 `UnitAttack`/`UnitDamaged` 两桶 `vd` 全 0），但它是**结构**上的双计：
                //   将来某张卡 `d>0` 且 `vd>0` ⇒ 会等 `2×` 才起播。
                float at = Mathf.Max(0f, t0) + Mathf.Max(0f, clip.T);
                ScheduleAction(at, () => PlayOneUnitAnim(e, clip, dur));
                ExtendTimelineTail(_clock + at + Mathf.Max(0.05f, dur));
            }
        }

        /// <summary>🆕 **2026-10-23（P1 · 演出时序 ④ · `新账-75①`）：这一拍技能动画**演多久**（秒）。
        ///
        /// <para>**判据（第一权威）** = `d:/2/tools/decomp_full/AnimInfo__GetAnimDuration.c` ——
        /// `vfxDelayTime + timeAtStartPos + timeMoving + timeAtEndPos` 四字段**无条件直加**；
        /// 原版动作队列**等完它**才弹下一条（`BattleManager__ResolveActionFromQueue.c:44-76` +
        /// `_ResolveAnim_d__466__MoveNext.c:200-210`）。</para>
        ///
        /// <para>**为什么要有这一层**：`VfxMap.ResolveAllTimed` 对**单候选**故意把 `Duration` 压成 **0**
        /// （「回归口径」，`VfxMap.cs:1302,1350` —— 那一档的队尾由事件自己负责）。而逐卡技能动画
        /// **几乎都是单候选** ⇒ 直接读 `clip.Duration` 会得到 **0**，下游
        /// `Mathf.Max(0.05f, 0)` = **0.05 s**：既喂给 `CardAnimPlayback.Duration`（动画提前结束），
        /// 又喂给队尾（动作队列提前放行）。现读实测 **16 桶 / 16 卡**受害
        /// （12 张 `attack_melee` + 4 张 `hit`；真值 **0.3 – 2.2 s**，`Arjac Rockfist` 2.2 s 最狠；
        /// 逐卡表 → `资料/普查产出_1023c/审查_每卡VFX与音效.md` §三·4）。</para>
        ///
        /// <para>**返回值契约**：与 `VfxMap.ChainDuration` 不同 —— <see cref="CardAnimClips.DurationOf"/>
        /// **≥ 0 = 真值（`0` 也是真值）**、**-1 = 判据为空**。这里只在 `clip.Duration &lt;= 0` 时才去补，
        /// 且补到 **0** 时仍然返回 0（下游那个 0.05 下限是「一拍至少占一帧」的实现细节，不是原版值）。
        /// 判据为空 ⇒ 返回 **0**（= 改前的行为，且 `CardAnimClips.PlacementOf` 那一侧已经出过声 ——
        /// ⛔ 不在这里再补一个静默常数）。</para>
        ///
        /// <para>⛔ **别改 `VfxMap` 的 `regression`**：那一位同时管着别的桶的队尾口径（见 `VfxMap.cs:1302`
        /// 的注释）；本件只在**消费端**补真值。</para></summary>
        public static float SkillBeatDuration(CardAnimClip clip)
        {
            // 🆕 2026-10-25（`AU1` · `J1` §9）：**卡本体位移那一档** ⇒ 这一拍时长 = `delay + animTime`
            //   （原版 `_ResolveAnim` 对 `minionMovementInfo != null && shouldActivateMinionMovement != 0`
            //    走 `MoveAndDisappearAnim` 并 `yield`，**不再**等 `GetAnimDuration` —— 是 if/else，不是相加）。
            //   ✅ 2026-10-25（`TL` §1）数据已进表（`mvt==1` 2 行、`mva=0.6`）⇒ 这一档**现在真的会生效**。
            if (clip.Place.MoveBody)
                return Mathf.Max(0f, clip.Place.MoveBodyDelay) + Mathf.Max(0f, clip.Place.MoveBodyTime);
            if (clip.Duration > 0f) return clip.Duration;
            float truth = CardAnimClips.DurationOf(clip.Anim);   // -1 = 表里没有这条 CardAnim
            return truth >= 0f ? truth : 0f;
        }

        /// <summary>播一拍（技能动画 prefab + 卡体动画层）。
        /// <para><paramref name="duration"/> = 这一拍**演多久**（= <see cref="SkillBeatDuration"/>；
        /// ⛔ 别再读 `clip.Duration` —— 单候选时它被回归口径压成 0）。</para></summary>
        void PlayOneUnitAnim(BattleEvent e, CardAnimClip clip, float duration)
        {
            // 🆕 2026-10-24（执行代理 `B1` · D3）：**自检口** —— 这一拍**真的起播**那一刻的 `_clock`。
            //   主对话用它验「Trigger 那条路的 t0 与改前 ③ 逐帧等价」：期望 ≈ `BatchAttackSkillAnimAtForTest`
            //   （差 ≤ 一个 `Step` 的 dt；`PlaySignals` 里 `_clock` 会略过信号自身的 `at`）。
            LastUnitSkillBeatAtForTest = _clock;
            var v = ViewAt(e.Player, e.Slot);
            if (v == null) return;

            // 🆕 2026-10-25（`AU1` · `J1` §9/§10）：起播**同帧**的屏震 + 卡本体位移那一档
            //   （原版 `_ResolveAnim:79-105` 的 `screenShake` 在 `DelayedVFXPlay` 起播那一帧；
            //    两条都缺数据时零调用 —— 判据见 `PlayBeatShake` / `PlayMinionMovement`）。
            PlayBeatShake(clip.Place);
            PlayMinionMovement(v,
                (e.TargetPlayer >= 0 && e.TargetSlot >= 0) ? ViewAt(e.TargetPlayer, e.TargetSlot) : null,
                clip.Place, e.Player == _me);

            // ---- ① 技能动画 prefab（原版 `BattleManager.CreateAnim` 那一层）----
            if (!clip.IsTimingOnly)
            {
                UnitSkillAnimBeats++;
                int sp = clip.Place.StartPos, ep = clip.Place.EndPos, pt = clip.Place.PointTowards;
                // ⚠️ 这条事件**没带目标**（`Hit` 那一路）而这一拍要 `abilityTarget` 时：
                //    原版的 `abilityTarget` 来自那条 `CardAbility` 的目标列表，我们的事件不带
                //    ⇒ 退回 `self`（池内这 4 条 `UnitDamaged` 全是**自己的**效果：BL20 是自 buff）
                //    **并出声一次**（⛔ 不静默换锚点）。
                bool noTarget = e.TargetPlayer < 0 && e.TargetSlot < 0;
                if (noTarget)
                {
                    sp = MapSelf(sp, e, "startPos");
                    ep = MapSelf(ep, e, "endPos");
                    pt = MapSelf(pt, e, "pointTowards");
                }
                PlayAbilityBeat(e, clip.Prefab, sp, ep, pt,
                                clip.Place.Move, false, clip.Place.Ts, clip.Place.Tm, null);
            }

            // ---- ② 卡体动画层（原版 `CardScript.DoBodyAnimation` → `DoAnim`）----
            //   ⚠️ 纯计时拍（`Wait_1s`）**不进**卡体层：原版那一拍 `animAdressable` 为空、
            //   `minionAnimationClipInfo` 也不归它管（它有自己的 1.0 s 等待）⇒ 见上面 `PlayUnitSkillAnim` 的时长。
            if (clip.IsTimingOnly) return;
            var ctl = CardAnimOf(v);
            if (ctl == null) return;
            var pb = new CardAnimPlayback
            {
                // 本 build 没有卡体 clip（判据见本节头注）⇒ 走 prefab 那一路
                Clip = CardAnimClips.BodyClipOf(e.CardId),
                Prefab = clip.Prefab,
                Duration = Mathf.Max(0.05f, duration),
                Label = e.CardId + "/" + clip.Prefab,
                // 🆕 2026-10-23（`新账-76②`）：原版 `MoveAndDisappearAnim` 的**逐帧深度缩放**只挂在
                //   「这一拍真的会移动」上（`b__1`/`b__4` 仅由 `BattleManager._ResolveAnim` /
                //   `_ResolveTraitAnim` 起，即 `AnimInfo` 的 `move` 那一位）⇒ 按 `clip.Place.Move` 开。
                //   `isPlayer` 显式传**真值**（原版 `CardScript+0x40`），⛔ 别让它退回按 z 推断。
                DepthScaleByBoardPosition = clip.Place.Move,
                DepthScaleIsPlayer = e.Player == _me,
            };
            // `toggleFlyOff` 取 true（判据为空，见本节头注）⇒ **在飞的单位先落地、演完再飞回去**。
            // 🔴 `safeResetOnEnd` 取 **false**（原版这一位 = `MinionAnimClipInfoDefinition.safeResetOnEnd`，+0x26，
            //    同样**没有 clip 定义可读**）。**必须 false**：`AnimFinished` 的复位是「回到 `Start()`
            //    那一刻的位置/旋转/缩放」，而我们的卡一直在被补间搬（让位 / 瞄准抬手 / 换格）
            //    ⇒ 复位到建控制器那一刻会把卡**弹回旧格**（静默错位）。取 false ⇒ 这一层只动它自己该动的。
            if (!ctl.DoAnim(pb, disableFlying: true, onAnimationEnd: null, safeResetOnEnd: false))
                UnitSkillAnimEmpty++;
        }

        /// <summary>自检：`DoAnim` 因为「空动画」被挡下过几次。</summary>
        public int UnitSkillAnimEmpty { get; private set; }

        static readonly HashSet<string> _warnedSelfAnchor = new HashSet<string>();
        /// <summary>`abilityTarget` 而事件没目标 ⇒ 映射成 `self`（见 <see cref="PlayOneUnitAnim"/> 的注释）。</summary>
        int MapSelf(int opt, BattleEvent e, string which)
        {
            if (opt != (int)PositionOption.abilityTarget) return opt;
            string key = e.CardId + "|" + which;
            if (_warnedSelfAnchor.Count < 8 && _warnedSelfAnchor.Add(key))
                Debug.LogWarning($"[Battle] `{e.CardId}` 的技能动画 `${which} = abilityTarget`，"
                               + "但这条事件**没带目标**（`Hit` 那一路）⇒ 锚点退回 **self**"
                               + "（原版的 `abilityTarget` 来自那条 `CardAbility` 的目标列表，我们的事件不带）");
            return (int)PositionOption.self;
        }

        /// <summary>自检用：`CardAnimClips` 表里登记了几条位置参数（= 池内「有件的」那 16 条）。</summary>
        public static int CardAnimPlacementCountForTest { get { return CardAnimClips.TableCount; } }

        /// <summary>自检用：直接走生产那条 `PlayUnitSkillAnim`（`evt` = `VfxMap.UnitAttack` / `UnitDamaged`）。
        /// 用来证明「数据 → 排期 → 真的播了一拍」这条链在**指定卡**上也通（不必等它真的出手）。</summary>
        public void PlayUnitSkillAnimForTest(BattleEvent e, string evt) { PlayUnitSkillAnim(e, evt, 0f); }

        static bool IsResourceUiEvent(EvtKind k)
        {
            return k == EvtKind.GainFaith || k == EvtKind.GainSpirit || k == EvtKind.GainQuest;
        }

        // ==================================================================
        //  「HUD 锚点」那一族（`Slot` 是 -1、**不能**走格位那条路的事件）
        //
        //  🔴 **为什么单收成一个判据（2026-10-14 · `A1816`）**：`PlaySignal` 里原来是
        //     `if (IsResourceUiEvent(e.Kind))` 内联的一句，而 `Draw` 也要走这一族 ——
        //     在调用点再写一句 `if` 就成了**两份判据**（本仓红线：两处写同一条规则迟早不一致）。
        //     ⇒ 现在**只有一处**说「谁是 HUD 锚点」，`PlaySignal` 和自检都问它。
        //
        //  ⚠️ **判据是「这个事件的落点在哪」，不是「它是不是资源事件」**：
        //     `Draw` 加进来**不是**因为它也是资源事件（它不是），而是因为它的 `Slot` 恒 -1、
        //     落点是**手牌区**。所以 `IsResourceUiEvent` 保持原样（它是**落点**在资源图标上那三件的
        //     判据），`IsHudAnchoredEvent` 才是「要不要绕开格位那条路」的判据。
        // ==================================================================

        /// <summary>这条事件的落点是不是**挂在 HUD 上**（而不是棋盘某一格）。
        /// `true` ⇒ `PlaySignal` 走 HUD 锚点那条路（**必须**，否则会被 `slot &lt; 0 → return` 静默吃掉）。
        /// **自检也断言它** —— 这是「只加了 case、没加这一段」那个形状上唯一的锁。</summary>
        public static bool IsHudAnchoredEvent(EvtKind k)
        {
            return IsResourceUiEvent(k) || k == EvtKind.Draw;
        }

        /// <summary>HUD 锚点事件 → 归一化落点（(0,0) = 左下角）。**自检用**（生产走 <see cref="TryHudAnchor"/>）。
        /// ⚠️ `mine` = 「**哪一方**的这个事件」（抽卡：抽牌那一方；资源：拿到资源那一方）。</summary>
        public Vector2 HudAnchor01(EvtKind k, bool mine, int drawFromEnd = -1)
        {
            return IsResourceUiEvent(k)
                 ? ResourceIcon01(k, mine)
                 : HandRow01(mine, drawFromEnd);
        }

        /// <summary>HUD 锚点事件 → 归一化落点；不是那一族就返回 `false`（调用方走格位那条路）。</summary>
        bool TryHudAnchor(BattleEvent e, out Vector2 at01, int drawFromEnd = -1)
        {
            at01 = default(Vector2);
            if (!IsHudAnchoredEvent(e.Kind)) return false;
            at01 = HudAnchor01(e.Kind, e.Player == _me, drawFromEnd);
            return true;
        }

        /// <summary>**手牌区那一点**（归一化）—— 抽卡那一件特效的落点。
        ///
        /// **判据 = 原版**：台账 `vfx_wiring_j4.tsv:65` 把 `UM_CardDraw` 判成 `UI`，触发写着
        /// 「抽卡特效(**卡飞入手牌区闪光**)」、挂点是「手牌接收动画」⇒ 落点 = **手牌区**，
        /// ⛔ 不是棋盘、也不是牌堆。
        ///
        /// **取哪一点**：取**刚抽到那张牌**会在的位置 —— 手牌是**追加到末尾**的
        /// （判据 → `RuleCore.MoveDeckTopToHand` 的 `ps.Hand.Add(inst)`，全仓唯一入队口），
        /// 所以 `SlotPosition(count-1, count)` 就是它（**问的是 `HandLayout` 自己那份排布**，
        /// ⛔ 不另算一份坐标 —— 「两处写同一条规则」）。
        /// ⚠️ 一张牌都拿不到时（`count == 0` / 排布件没接上）**退成那一行的正中**
        /// （`HandLayout` 自己的基线 y）—— 两级都落在**手牌区**，不会落到棋盘上。
        /// ⚠️ 同一帧里抽两张（「抽 2 张」）时 —— 🔴 **2026-10-14（`A1865`/`A1884`）已修**：
        /// ① 排时间线时算好 `drawFromEnd`（这一段里它是**倒数第几张**，1 起）；
        /// ② 🆕 这一批的**落点坐标**也在 `PlaySignals` 里**一次算齐**
        ///    （`Vector3[] points`，`points[k] = HandRow01(mine, n - k)`），随 `PendingSignal`
        ///    交给 `PlaySignal` ⇒ 两张**各落各的那一格**，且同批用的是同一个 `count`。
        /// （修前：两条都按**当时**的张数各算一遍 ⇒ 都落在最后那一格。）
        /// ⚠️ **仍然没做的那一半（如实记着）**：原版那件特效自己会**移动**
        /// （`card_anim_map.json` 实读 `shouldMoveVFX = 1` · `timeMoving = 2.5`），而**效果 prefab 那一层**
        /// 还没有「沿路径飞」的实现 ⇒ 我们这边是「两张各在各自那一格闪一下」，
        /// ⛔ 不是「一件特效从牌堆飞到手上」。**API 那一半 2026-10-14（`A1884`）已开**
        /// （`Core/CardEffects.cs` 的 `Vector3[] points` 重载：给 N 个点就在 N 个点各播一份）。
        /// ⚠️ 张数对不上时（手牌满被弃掉 / 这一段里只补了一部分）下标会被**夹回** `[0, count-1]`，
        /// 不会算出越界格 —— 但那时落点只是近似，**如实记着**。</summary>
        Vector2 HandRow01(bool mine, int drawFromEnd = -1)
        {
            var hl = HandOf(mine ? _me : 1 - _me);
            int side = mine ? _me : 1 - _me;
            int count = 0;
            if (Ctx != null && Ctx.Players != null && side >= 0 && side < Ctx.Players.Length
                && Ctx.Players[side].Hand != null)
                count = Ctx.Players[side].Hand.Count;
            if (hl != null && count >= 1)
            {
                int idx = count - 1;                                  // 默认：末尾那张（= 只抽一张时那一张）
                if (drawFromEnd >= 1) idx = count - drawFromEnd;      // 这一段里倒数第几张
                if (idx < 0) idx = 0; else if (idx > count - 1) idx = count - 1;   // 夹回合法范围
                return LayoutSpace.ToNormalized(hl.SlotPosition(idx, count));
            }
            return new Vector2(0.5f, mine ? HandLayout.DefaultBaselineY : HandLayout.EnemyBaselineY);
        }

        /// <summary>HUD 上那个**资源计数图标**的归一化位置（我方 / 敌方各一套）。
        /// 🔴 坐标**复用 HUD 画图标时用的同一组常量**（`MyFaithX01` 等）—— 别另抄一份，
        ///    否则图标挪了、特效还留在原地（「两处写同一条规则」）。</summary>
        static Vector2 ResourceIcon01(EvtKind k, bool mine)
        {
            if (k == EvtKind.GainFaith)
                return new Vector2(mine ? MyFaithX01 : FoeFaithX01, mine ? MyFaithY01 : FoeFaithY01);
            if (k == EvtKind.GainSpirit)
                return new Vector2(mine ? MyStoneX01 : FoeStoneX01, mine ? MyStoneY01 : FoeStoneY01);
            return new Vector2(mine ? MyQuestX01 : FoeQuestX01, mine ? MyQuestY01 : FoeQuestY01);
        }

        // ==================================================================
        //  手感补间：引擎事件 → 卡自己的动作
        //
        //  和特效是**两回事**：特效是「在哪一格播哪个 prefab」，这里是「那张卡自己怎么动」。
        //  参数全在 `CardFeel` 里，逐条标了出处（原版 clip / UnitTweenSO / 卡预制体字段 /
        //  反编译常量），**3D→2D 的迁移那几处也标了是「我们改的」**。
        //
        //  ⚠️ `animateFeel` 默认关：批处理自检要**当场精确**的坐标（和 `HandLayout.animateRelayout`
        //     同一条规矩），存场景那一路上打开（`BattleScene.BuildAndSaveScene`）。
        // ==================================================================

        /// <summary>打开手感补间。批处理自检里由用例显式打开，见 `BattleScene` 第 13 节</summary>
        public bool animateFeel = false;

        void PlayFeel(BattleEvent e, bool hitOfAttack = false, bool collectDeath = false,
                      bool hitOfCounter = false)
        {
            switch (e.Kind)
            {
                case EvtKind.Attack: PlayAttackFeel(e); break;
                case EvtKind.Hit:    PlayHitFeel(e, hitOfAttack, hitOfCounter);    break;
                // 🆕 2026-10-20（`W58`）：**治疗**有自己的一拍（卡上 `HealText`），
                // ⛔ 不走 `PlayHitFeel`（原版治疗没有后仰 / 震镜头 / 伤害计数器）。
                case EvtKind.Heal:   PlayHealFeel(e);   break;
                // 🆕 2026-10-22（P6 · M1/M2）：`collectDeath` = 这一条 `Death` 是「收集灵魂石」那一下
                //   带出来的（判据 → `IsCollectDeathAt`）⇒ 那一拍**不播**残骸 Destroy 件 / 普通阵亡件。
                case EvtKind.Death:  PlayDeathFeel(e, collectDeath);  break;
                case EvtKind.Return: PlayReturnFeel(e); break;
                // 🆕 2026-09-29：「这个词条刚触发」⇒ 卡上**那一位徽标脉冲一下**
                // （原版 `CardScript.ActivateTriggerTraitAnim` → `BattleCardUI.HighlightTraitIcon(traitId)`）。
                // 🔴 **2026-10-24（`G1` · `W64·B-11` 表现半边）**：`swarm` 这一档还要走「合并那一拍」
                //    （合并件 + 3D 音 + 存活那张的虫群图标）—— 判据与三条如实偏离见 `PlaySwarmMergeFeel`。
                case EvtKind.Trigger: PlayTraitPulse(e); PlaySwarmMergeFeel(e); break;
                // 🆕 2026-10-16：**落地那一下的震镜头**（原版 `CardScript.LandOnGround`
                //   里和扬尘/落地音同一时刻的那件）。⚠️ 它只在 `animateFeel` 开着时跑 ——
                //   与 `PlayHitFeel` 那条挨打震动**同一个口径**（批处理自检要当场精确坐标）。
                case EvtKind.Deploy:
                    // 🆕 2026-10-19（B2 · 偏差 8）：**AI 飞行**这一拍是起飞、不是落地 ⇒ 震镜头押到飞行终点。
                    if (!_aiDeployFlights.ContainsKey(HpKey(e.Player, e.Slot))) PlayDeployFeel(e);
                    break;
            }
        }

        /// <summary>🆕 2026-10-16 **落定那一拍的手感** —— 原版 `CardScript.LandOnGround`
        /// （`CardScript__LandOnGround.c:26-41`）里**三件同时**：震镜头 + 落地音 + 扬尘。
        /// 我们这边音与扬尘跟着 `EvtKind.Deploy` 走（见 `PlaySignal` 的 Deploy 分支），
        /// 「震镜头」按本文件的既有分工落在这里（**手感补间只有 `PlayFeel` 这一个出口**）。
        /// <para>时序对齐：原版这三点是在 `WaitForSeconds(timeToLand)` **之后**才起
        /// （`CardScript._MinionPlayedIntoField_d__314__MoveNext.c` 的 state 3）——
        /// 我们的 `EvtKind.Deploy` 现在也正好发在**序列末尾**那一拍
        /// （`DeploySequence.Play` 的 `onDone` → `OnCardDeployed` → `DoPlay`），**两者同拍**。</para>
        /// <para>判据与幅度（preset 真件 `Shake Land on ground`）→ `CardFeel.ShakeCameraForLand`。</para>
        /// <para>⚠️ **AI 出的牌也走这里**：那条路没有飞行/落下补间（视图直接出现在格位上），
        /// 所以这一下会跟「卡出现」同拍 —— 事件语义没变，是 AI 那条路本来就没有位移演出。</para></summary>
        void PlayDeployFeel(BattleEvent e)
        {
            CardFeel.ShakeCameraForLand(cam, hudRoot, 0f, boardCam);
        }

        /// <summary>刚触发的那个词条 ⇒ 找到它那一位徽标、脉冲一次。
        /// 配对的键 = `BattleEvent.Keyword`（引擎发 `EvtKind.Trigger` 时写的规范键）。
        /// ⚠️ 认不出（那个词条本来就没有图标）**是正常的**，不是错 —— 所以只**每个词条提示一次**，
        ///    免得 `Talent` 那种刷满日志；绝不猜着去脉冲别的一位。</summary>
        /// <summary>🔴 2026-10-20（W57 · 战斗线 `T09` 步骤 WIRE）：事件 `Keyword` 的**显示形态**。
        /// 双能力卡把能力序号放在 `BattleEvent.Keyword` 的 `#i` 后缀里（`BattleEvent.KeywordWithAbility`，
        /// 例 `UseFaith#1`）—— 那是**传输形态**；玩家看到的只该是 trigger 名（`UseFaith`）。
        /// 判据只此一处：转发 `BattleEvent.SplitKeywordAbility`（⛔ 不在表现层另写一份解析）。
        /// ⛔ **不改事件本体**：`VfxMap` 靠原始 `Keyword` 筛行（它自己也会拆，见 `VfxMap.cs:787`）。</summary>
        static string KeywordForDisplay(string keyword)
        {
            return string.IsNullOrEmpty(keyword) ? keyword : BattleEvent.SplitKeywordAbility(keyword, out _);
        }

        void PlayTraitPulse(BattleEvent e)
        {
            if (e.Player < 0) return;
            var v = ViewAt(e.Player, e.Slot);
            if (v == null) return;                    // 视图不在（刚死的 / 刚被挪走的）⇒ 不表演

            // 🆕 2026-09-29：**这个关键词真的触发了** ⇒ 那张「触发类状态框」也演一下。
            //   原版 = `CardScript.ActivateTriggerTraitAnim` → `BattleCardUI.DisplayTriggerAnim`
            //   （全量反编译里**唯一同时调 `HighlightTraitIcon`** 的地方 —— 而「徽标脉动」我们早就有了，
            //    所以这一处原本只缺框那一半）。判据 → `Core/TraitFrames.cs` 文件头。
            // 🔴 **2026-10-20（W57 · `T09` WIRE）**：`e.Keyword` 可能是 `UseFaith#1`（传输形态）——
            //   `TraitFrames.DisplayTrigger` / `CardView.PulseBadgeByKeyword` 都是**按裸 trigger 名**查表的
            //   ⇒ 先拆掉 `#i` 后缀（`KeywordForDisplay`，判据只此一处）。不拆的话状态框/徽标都会**查不到**
            //   （而 miss 日志还会印一句「这个词条本来就没有图标」= **误导**）。
            string kw = KeywordForDisplay(e.Keyword) ?? "";
            var tf = v.GetComponent<TraitFrames>();
            // 🆕 2026-10-23（新账-70 第 3 条）：**`playIfWarlord` 门**（原版 `DisplayTriggerAnim.c:62-68`）
            //   要问「这张卡是不是督军」—— 判据 = `UnitState.IsWarlord`（引擎侧唯一的督军身份位；
            //   原版那个 `GameStaticData.IsWarlordEquivalent` 看的是卡类型 10 = 我们的 `Type == "hero"`，
            //   两者同一个身份，⛔ 别按「槽位 == 4」判 —— 那是布局，不是卡的属性）。
            bool isWarlord = false;
            if (Ctx != null && e.Player >= 0 && BoardSpec.IsValid(e.Slot))
            {
                var u = Ctx.Players[e.Player].Board[e.Slot];
                isWarlord = u != null && u.IsWarlord;
            }
            if (tf != null && tf.DisplayTrigger(kw, isWarlord))
                Debug.Log($"[Battle] 「{kw}」触发 ⇒ 状态框上场（原版 `DisplayTriggerAnim`）");
            else if (tf != null && isWarlord && TraitFrames.BlocksForWarlord(kw))
                Debug.Log($"[Battle] 「{kw}」触发但卡是督军、该 effect 的 `playIfWarlord = 0` ⇒ 原版不播（`DisplayTriggerAnim.c:62-68`）");

            if (v.PulseBadgeByKeyword(kw)) return;

            if (_pulseMissWarned.Add(kw))
                Debug.Log($"[BattleDriver] 「{kw}」触发时卡上没有对应的徽标位 ⇒ 不脉冲（该词条本来就没有图标，属正常）");
        }
        static readonly HashSet<string> _pulseMissWarned = new HashSet<string>();

        // ==================================================================
        //  🆕 2026-10-01：trait 的「**从代码播**」粒子
        //     （原版 `CardScript.ActivateTraitParticlesFromCode` / `…InTarget`）
        // ==================================================================
        //  判据（8 个调用点与 trait id 都从指令流实读）→ `资料/待办判据_战场与战斗视图.md` 的「trait 粒子」段；
        //  绑定表与「和 `TraitFrames` 那两本字典不是一条链」的说明 → `Core/TraitParticles.cs` 的文件头。
        //  🔴 **触发口 = 「事件 → 该查哪几个 trait」**（原版是在那几个方法里**点名调**的，我们这边用事件流近似）：
        //    · `EvtKind.Ability` ← `UsedActiveAbility`（trait id `0x4f1` = ferocity）
        //    · `EvtKind.Attack`  ← `_ResolveAttack` 里连调的四个（sniper / markerlight / longrange / stomp）
        //    · `EvtKind.Trigger` ← 关键词真的触发（`swarm` / `synapse` 走这一格）
        //  🔴 **2026-10-23（`新账-79`）就地订正（铁律 5）**：原来这里还有第二条缺口
        //    「② `huntMark` 那条是 `…InTarget`，prefab **判据不足**（映射表里没有 `…InTarget` 结尾的
        //      CardAnim）⇒ 整条没接（按铁律 3：宁可留白，不猜）」—— **那句已被数据推翻**：
        //    原版 `HuntMark.asset` **确实有一条 FromCode(5)**：`HuntMark Damage Anim` → `HuntMark_DamageEffect`；
        //    现在由 `TraitParticles` 那张**数据驱动**的表绑上（`Resources/trait_effect_bindings.json`，
        //    判据与「为什么原来错」→ `Core/TraitParticles.cs` 文件头的 2026-10-23 那段）。
        //    **错因**：当年是「按 CardAnim 名字反推绑定」，而这条的名字不叫 `…InTarget` ⇒ 反推不到。
        //  🔴 **2026-10-24（`G1`）就地订正（铁律 5）**：本段下面原来写「① `swarm` 合并那一下**不发
        //    `EvtKind.Trigger`**（走 `BroadcastKeywordEvent`）」—— **已过期**：`RuleCore.SwarmMergeNow`
        //    尾部（`A1356` 收口）走 `FireTriggerAlways`，**有正文走 `FireTriggerAt`、没正文也自己发
        //    `EvtKind.Trigger`** ⇒ 今天 `swarm` **会**发这一格（合并那一拍的消费点见 `PlaySwarmMergeFeel`）。
        void PlayTraitParticles(BattleEvent e)
        {
            string[] want = null;
            switch (e.Kind)
            {
                case EvtKind.Ability: want = new[] { KeywordTable.Ferocity }; break;
                case EvtKind.Attack:  want = AttackTraitParticles; break;
                case EvtKind.Trigger:
                    // 🔴 **2026-10-20（`W57` · 战斗线 · 来源 `W57_战斗线_TraitParticles_#i.md` §4）：`
                    //   `e.Keyword` 可能是**传输形态** `UseFaith#1`（`BattleEvent.KeywordWithAbility`）——
                    //   `UnitState.Has` 查的是**引擎键**（`_keywords.ContainsKey`，**永不带 `#i`**）
                    //   ⇒ 不拆的话 `u.Has("usefaith#1")` 先拦下，`PlayTraitParticles` 这一支**整条不播**。
                    //   解码口只走 `BattleEvent.SplitKeywordAbility`（⛔ 不在表现层另写解析，也⛔ 不改
                    //   `UnitState.Has` —— 那会把传输形态漏进引擎层，违反 `BattleEvent.cs` 的「解码只此一处」）。
                    //   `TraitParticles.Has/PrefabFor` 已同批认得 `#i`（那个文件自己的 `Norm`），这里拆完两边同键。
                    if (!string.IsNullOrEmpty(e.Keyword))
                        want = new[] { BattleEvent.SplitKeywordAbility(e.Keyword, out _).Trim().ToLowerInvariant() };
                    break;
            }
            if (want == null || e.Player < 0 || !BoardSpec.IsValid(e.Slot)) return;

            var u = Ctx != null ? Ctx.Players[e.Player].Board[e.Slot] : null;
            if (u == null) return;                    // 不在场上（已离场 / 已挪走）⇒ 不表演
            var v = ViewAt(e.Player, e.Slot);
            if (v == null) return;

            foreach (var t in want)
                if (u.Has(t)) TraitParticles.Play(t, v.transform, why: e.Kind.ToString());
        }
        // `sniper` / `markerlight` / `stomp` 在 `KeywordTable` 里**没有常量**（只出现在规范化表里），
        // 所以这里写字面量 —— **拼写必须与规范化后的键逐字相同**（`CardDef.cs` 那张表）。
        static readonly string[] AttackTraitParticles =
            { "sniper", "markerlight", KeywordTable.LongRange, "stomp" };

        CardView ViewAt(int owner, int slot)
        {
            var views = owner == _me ? _myUnits : _foeUnits;
            CardView v;
            return views.TryGetValue(slot, out v) ? v : null;
        }

        // ═══════════════════════════════════════════════════════════════════════════════════════════
        //  🔴 2026-10-24（`G1`）：**虫群合并那一拍**（`W64·B-11` 的表现半边）
        //
        //  **判据链（全是现读）**：
        //   · **引擎**：`RuleCore.TrySwarmMerge` → 队列动作 `SwarmMergeNow`，尾部
        //     `FireTriggerAlways(ctx, host, KeywordTable.Swarm, p, hostSlot, just)`
        //     ⇒ 发 **`EvtKind.Trigger`**，`Keyword = "swarm"`，`Player/Slot` = **合并后还活着那一格**
        //     （按身份现查，⛔ 不是写死的 `slot`/`right` —— 连续棋盘会补位）。
        //   · **原版**：`CardScript__ExecuteSwarm.c:39-79` —— 在**被并掉那张**的世界位姿上 `Instantiate`
        //     `Swarm Card Merge VFX`（= `CardTrait "Swarm"`(`definedTrait 650`) 的 `customObject`），
        //     `localScale` 取被并掉那张的；该 prefab 上的 `SwarmVFXController` 靠 clip
        //     `Swarm Triat Merge.anim` 的 **1.2 s 动画事件 `OnAnimationEndEvent`** 收尾
        //     （A31 已补接收口 ⇒ `WarpforgeEffectPlayer` 会在那一拍销毁；⛔ 不传 `autoDestroySeconds`）。
        //   · **音**：原版 `sound` = cue **`Trait Swarm Tyranid`**，走 **`Play3D`** ⇒ `is2d = false`。
        //     ⚠️ **必须在这里单独播**：`Swarm Card Merge VFX` 这个 prefab **没有 `AnimFXController`**
        //     （效果库 控制器数 0 / 模块空），而 `WarpforgeEffectPlayer.BuildSounds()` 只吃
        //     `AnimFXController.sounds[]` ⇒ **cue 在表里也没人播**（G3 2026-10-24 查清，cue 已进
        //     `animfx_sounds.json`，460/460 解析通过）。先例 = `Core/CardView.PlaySwarmOnSound`。
        //   · **图标**：同一跳把**存活那张**的 `CardView.SetSwarm(true)`（原版 `ActivateTraitAnim` 那一族）。
        //     `CardView.SetSwarm` 此前**游戏内 0 调用点**（A31 §七·4 记的断链）—— 就是这里接上。
        //
        //  ⚠️ **如实标的偏离（⛔ 别当成已完成；判据缺口不是猜测能填的）**：
        //   ① **落点 = 存活那格**（`e.Slot`）。原版实例化在**被并掉那张**的世界 pos/rot、并按**它**的
        //      `localScale` 缩放 ⇒ 我们挂在存活那格上是**相邻一格的近似**。要精确得让引擎把
        //      被并掉那张的位姿一起带出来（`RuleEngine/**`，不在本件白名单）。
        //   ② **混音组号**：原版 `MixerType` 实参没逐值解出，`WFSoundPlayer` 没有这个概念（统一 `FxGroup`）。
        //   ③ **3D 空间曲线**：没有和原版对照过（`WFSoundPlayer` 用默认 3D 衰减）。
        //   ④ 原版 `ToggleBody3D(false)`（合并期间藏卡 3D 本体）与材质交接 `ConfigureMaterial`
        //      需要目标卡 UI 引用 ⇒ **没做**（A31 §六·③⑤ 同一条缺口）。
        // ═══════════════════════════════════════════════════════════════════════════════════════════

        /// <summary>虫群合并那一拍播的件名（= 原版 `CardTrait "Swarm"` 的 `customObject`）。</summary>
        public const string SwarmMergeVfxName = "Swarm Card Merge VFX";
        /// <summary>虫群合并那一拍的 **3D 音 cue**（原版 `Trait Swarm Tyranid.asset`；G3 2026-10-24 已入库）。</summary>
        public const string SwarmMergeCue = "Trait Swarm Tyranid";
        /// <summary>自检用：虫群合并那一拍**真的走过**几次（A31 §七·4 那条断链是否接上）。</summary>
        public int SwarmMergeFeelCount { get; private set; }
        /// <summary>自检用：最近一次虫群合并落在哪一格（`-1` = 没走过）。</summary>
        public int SwarmMergeLastSlot { get; private set; } = -1;
        /// <summary>自检用：最近一次虫群合并的音 cue 取到了没有（`false` = `WFSoundBank` 里没有）。</summary>
        public bool SwarmMergeCueFound { get; private set; }
        static bool _swarmMergeCueWarned;

        /// <summary>见上面那一段判据。非 `swarm` 的 `Trigger` 事件**直接返回**（零开销）。</summary>
        void PlaySwarmMergeFeel(BattleEvent e)
        {
            if (e == null || e.Player < 0 || !BoardSpec.IsValid(e.Slot)) return;
            if (string.IsNullOrEmpty(e.Keyword)) return;
            string kw = BattleEvent.SplitKeywordAbility(e.Keyword, out _).Trim().ToLowerInvariant();
            if (kw != KeywordTable.Swarm) return;

            var v = ViewAt(e.Player, e.Slot);
            if (v == null) return;                 // 视图不在（刚被移走）⇒ 不表演，不是错

            SwarmMergeFeelCount++;
            SwarmMergeLastSlot = e.Slot;

            // ① 存活那张的**虫群图标**（原版 `ActivateTraitAnim` 那一族）
            v.SetSwarm(true);

            // ② 合并件（挂在存活那格；⚠️ 偏离 ① —— 原版挂在被并掉那张）
            WarpforgeVFX.WarpforgeEffectPlayer.Play(SwarmMergeVfxName, v.transform, Vector3.zero, 1f, -1f);

            // ③ 3D 音（原版 `Play3D` ⇒ is2d = false）
            WarpforgeVFX.WFSoundCue cue;
            SwarmMergeCueFound = WarpforgeVFX.WFSoundBank.TryGetCue(SwarmMergeCue, out cue);
            if (SwarmMergeCueFound)
            {
                WarpforgeVFX.WFSoundPlayer.Play(cue, v.transform.position, false);
            }
            else if (_swarmMergeCueWarned == false)
            {
                _swarmMergeCueWarned = true;
                Debug.LogWarning($"[Battle] 虫群合并的音 cue `{SwarmMergeCue}` 在 `WFSoundBank` 里取不到 ⇒ 这一拍**不出声**"
                               + "（**不是静默**：原版 = `Trait Swarm Tyranid.asset` 的 sound；补法 = 跑 "
                               + "`工具/import_original_sfx.py` 重新生成 `animfx_sounds.json`）");
            }
        }

        /// <summary>攻击：先蓄力（`timeToChargeAttack` 0.35s），再朝目标冲一下
        /// （`DoPushBack` 的形状 + `Recoil Normal Tween` 的幅度）</summary>
        void PlayAttackFeel(BattleEvent e)
        {
            // 🔴 **记下攻击方的近战攻击** —— 挨打后坐的幅度原版是 `GetPushBackFactor(GetUnitSize(攻击方))`
            //    （判据与出处见 `CardFeel.PushBackMagnitude`），而 `EvtKind.Hit` 是发给**受击方**的、
            //    **不带攻击者**。表现层是先收 `Attack` 再收 `Hit`（`RuleCore.Attack` 里就是这个顺序），
            //    所以在这里存一份给下一条 `Hit` 用 —— 不用为这件事改引擎的伤害链。
            //    ⚠️ 放在 early-return **之前**：视图不在（比如攻击方那一刻刚被移走）也照样要记。
            var attacker = (e.Player >= 0 && e.Player < Ctx.Players.Length && e.Slot >= 0
                            && e.Slot < Ctx.Players[e.Player].Board.Length)
                ? Ctx.Players[e.Player].Board[e.Slot] : null;
            _lastAttackerMelee = attacker != null ? attacker.Attack : -1;
            _lastAttackerSide = e.Player;
            _lastAttackerSlot = e.Slot;
            // 🆕 2026-10-21（W61 第 1 批 · 第 2 条）：记下远近 —— 挨打那两拍要按它分流
            //（近战的后坐/震屏已在**命中帧**做过，伤害结算那一拍不再做；远程仍在结算那一拍做）。
            _lastAttackRanged = e.Ranged;

            var v = ViewAt(e.Player, e.Slot);
            if (v == null) return;

            // 🔴 **2026-09-29 这里有一处真缺陷，顺手修掉**：原来目标位置取的是
            //    `layout.SlotPosition(e.TargetSlot)` —— 那是 **2D 屏幕布局**的坐标
            //    （`BoardLayout.SlotPosition` = `LayoutSpace.ToWorld`，单位是 HUD 的 108 px/单位），
            //    而场上的卡活在 **3D 战场的原版世界单位**里（`ArenaSlots`，见 `BoardLayout` 文件头那句
            //    「真 3D 那条路不吃这一套了」）⇒ 那个 `dir` 是**两个坐标系相减**出来的，
            //    只在 2D 兜底布局下才有意义。改成**两边都取真身的 `transform.position`** ——
            //    原版也是这么取的（出手点 = 攻方 transform、目标点 = 受击方 `transform.position`）。
            var tv = ViewAt(e.TargetPlayer, e.TargetSlot);
            if (tv == null) return;                 // 目标视图不在（刚被移走）⇒ 不表演，不是错

            // 出手前那个**静止位**（瞄准时卡会「抬手」，见 `TickTargetingLean`；段4 回的是它）
            Vector3 home = LeanHomeOf(e.Player, e.Slot, v);

            if (e.Ranged)
            {
                // 🔴 **2026-10-21（W61 第 2 批 · 第 4 条）：补上原版那一整段【回正】。**
                //   判据 = `CardScript._ResolveAttackRangedAnim_d__360__MoveNext.c:80-104`：
                //   一个 Sequence 里三条同时（时长全是 `attackStepTime` = 0.1、无 SetEase ⇒ 默认 OutQuad）：
                //   `DOLocalMove(handHomePos, 0.1)` + `DORotateQuaternion(identity, 0.1)` +
                //   `DOScale(DefaultScale, 0.1)` → `WaitForCompletion` → 再 `WaitForSeconds(0.1)` → 才发 VFX。
                //   ⇒ 我们这 0.2 s 的**前 0.1 s 现在真的在动**（原来只有 `LeanHomeOf` 把瞄准抬手那个字段
                //   关掉，卡可能停在半途 —— 对账 §2·3 #1「缺（潜在残留偏移）」）。
                //   ⚠️ 后 0.1 s 是纯等待，已含在 `EventTiming.AttackStepRanged`（0.2）里。
                // 🆕 2026-10-23（`新账-82①`）：**显式传 `isPlayer`** —— 调用点明明知道（`e.Player == _me`），
                //   别再让 `CardFeel` 按「静止位离哪一行近」去推断（铁律 6：推断只留一处；
                //   `IsPlayerRow` 那条兜底只该给**取不到阵营**的调用点用）。
                CardFeel.AttackRecover(v.transform, home, v.transform.localScale.x,
                                       isPlayer: e.Player == _me);
                return;
            }

            // 近战：原版那条三段式（0.4s 全程、**命中在 t = 0.1**）——
            // 命中时刻由 `EventTiming.HitFrameLag`（= `AttackStepMelee` 0.1）保证，命中帧的**手感**
            // 由 `ScheduleAttackPresentation` 单独排（2026-10-21 · W61 第 1 批：原来这里引的是已删除的
            // `EventTiming.MeleeImpactLag`）。
            // 🆕 2026-10-23（`新账-82①`）：`isPlayer` 显式传（同上面远程那一支 —— `MeleeEndPos` 与
            // 深度缩放都用它；⛔ 别只改一处，两处必须同一个值）。
            // 🔴 **2026-10-24（执行代理 `W15` · `C6` §2·1）**：**第四参必须传 `tv`** ——
            //   `CardFeel.MeleeEndPos(Vector3, Vector3, bool)` 那条三参重载的 `dy` 恒 `0f`
            //   ⇒ 近战段1「受击方原位 + `up × attackPositionYOffset × dy`」那半条**整段不生效**。
            //   带卡视图的重载现算 `dy = EffectsAnchorHeight(tv)`（判据 = `CardScript._AttackMeleeAnim_d__357__MoveNext.c`
            //   的 `fVar15 = anchor.y − targetCard.y`，随后 `× attackPositionYOffset`）。
            //   🧨 改回三参那条 ⇒ `Editor/CardRootAssert.cs` 里「生产近战端点带 dy」那条红
            //   （它读的就是下面这一行**自己记的账** `LastMeleeEndPosForTest`）。
            Vector3 meleeEnd = CardFeel.MeleeEndPos(v.transform.position, tv.transform.position,
                                                    e.Player == _me, tv);
            LastMeleeEndPosForTest = meleeEnd;      // 自检口：生产实际传给 `MeleeAttack` 的端点（只有自检读）
            CardFeel.MeleeAttack(v.transform, meleeEnd, home, isPlayer: e.Player == _me);
        }

        // ================= 🔴 `FinishAfterAttack` 后半段（战斗线 `新账-82⑤`）：**判据为空，⛔ 不补那一层** =================
        //  （2026-10-23 · `A10` 现核；判据链逐条可查，⛔ 别照旧账再开一轮「补 `CardView.bloodThirstFrame`」）
        //
        //  原版 `CardScript__FinishAfterAttack.c` 在位姿三句（sortingLayer → localPosition → rotation → localScale）之后还有两段：
        //    ① `:80-84` —— `if (hp(+0x68) > 0 && state(+0x228) != 5) state(+0x228) = 2`
        //       （`CardStateOptions`：2 = `inPlay`、5 = `waitingToDie`）⇒ **打完还活着就回到 inPlay**。
        //       我们这一侧的「状态」在 `RuleEngine`（`UnitState` / `Evicted` 等）、视图是隐式的 ⇒ **没有等价物，也没有可观测差**。
        //    ② `:85-104` —— 嗜血高亮：`HasCurrentTrait(0xdc /*bloodThirst*/)` && `+0x48 == 1`（本回合计数）
        //       && `isPlayer(+0x40) == BattleManager.IsPlayerTurn` && `state != 5` ⇒ `CardScript.SendHighlightBloodThirstAction()`
        //       → 动作队列（`BattleActionType.bloodThirstAnim = 43`）→ `BattleManager.ResolveAction` →
        //       `CardScript.HighlightBloodThirst`（`CardScript__HighlightBloodThirst.c`）→ 两件：
        //         (a) `BattleCardUI.HighlightBloodThirst` —— 取 `ui+0x268` = **`bloodThirstFrame`** 的
        //             `GetComponentInChildren<SpriteRenderer>()`，`DOFade(0, 0.3).SetLoops(6, Yoyo).SetEase(22)`
        //             （`0.3` = `read_literal.py` 实读 `0x1834b2dc8`，与 `CardScript.DoPushBack` 那个 0.3 同一常量）；
        //         (b) `DisplayTriggerAnim(0xdc, 1, 0)` —— 嗜血触发动画（**已经在**：见本条末）。
        //
        //  🔴 **(a) 那一层在本 build 里是【死字段】**，三条独立判据：
        //    Ⅰ. `d:/2/tools/il2cpp_out/dump.cs:26221`：`private GameObject bloodThirstFrame; // 0x268` —— **没有 `[SerializeField]`**
        //       （同一个类里 `genericBattleAnims // 0x1B8` 有），⇒ 序列化不进来，只能由代码赋值；
        //    Ⅱ. **写点 0 处**：`BattleCardUI` 的全部方法（`BattleCardUI__*.c` 81 个 + 三个嵌套迭代器）在 `decomp_full` 里逐个对过（无缺体），对 `+0x268` 只有
        //       `BattleCardUI__HighlightBloodThirst.c:15/21/26` 三处**读**；同族那些**有**写点的框可作对照
        //       （`0x2A8` oath / `0x2A0` codex / `0x2B8` ephemeral-reflected / `0x280` stealth / `0x288` mulligan 各在
        //       `ShowOath:62` / `ShowCodex:62` / `ShowEphemeral:65` / `ShowStealth:65` / `SetAsMulliganSelected:76` 被赋值）。
        //       其它类写不到私有字段，全量反编译里也没有反射按名字取（grep `bloodThirstFrame` 全库 0 命中）；
        //    Ⅲ. **件本身也不存在**：`CardPrefab.prefab`（AssetRipper 导出，唯一挂 `BattleCardUI` 的那份）里没有任何血渴框子节点
        //       （`m_Name` 只有 `SwarmIcon` / `CardFrame` 等），`BattleAnims` SO 也没有 `bloodThirst*` 字段/资源。
        //    ⇒ `HighlightBloodThirst` 今天恒在 `if (ui+0x268 != null)` 早退 ⇒ **原版这一支不产生任何画面**。
        //
        //  ⇒ 处置 = **铁律 11 例外①（原版本身就没有 / 判据是空的）**：**不补这一层**（贴图 / 尺寸 / 颜色 / 队列一个判据都没有，
        //    补出来就是自造美术，正好撞上本批简报那条「⛔ 别为了『有东西可看』自造一层」）。
        //  ✅ 可观测的那一半**已经在**：`RuleCore.EmitBloodThirst` 在「本回合计数变成 1」时发 `EvtKind.Trigger`
        //    （判据 = 同一个 `+0x48 == 1`）→ `TraitFrames.DisplayTrigger` → `BloodThirstEffect_Gain`（首次连 6 那条也播）。
        //  ⚠️ 若将来把原版跑到实况并**真的看到**血渴框脉冲 ⇒ 说明这份 build 的这个字段被别的路径填过（判据被推翻），届时再翻案。
        // ======================================================================================================================

        /// <summary>出手前那个**静止位**（局部坐标）。瞄准时卡被 <see cref="TickTargetingLean"/> 抬起来了，
        /// 攻击序列的段4 要回到**没抬手之前**那一处，不是出手那一帧的位置。
        /// 顺手把瞄准那条路让开（`_leanActive = false`）—— 两个东西不能同时改同一个 transform。</summary>
        Vector3 LeanHomeOf(int owner, int slot, CardView v)
        {
            Vector3 home = (_leanActive && _leanSlot == slot && owner == _me)
                         ? _leanHome : v.transform.localPosition;
            _leanActive = false;
            return home;
        }

        /// <summary>上一次 `Attack` 的攻击方：近战攻击（-1 = 没有/取不到）+ 在哪一侧。
        /// 给挨打后坐的幅度用，见 `PlayAttackFeel` 里的注释。</summary>
        int _lastAttackerMelee = -1;
        int _lastAttackerSide = -1;
        /// <summary>攻击方的格位（方向算法要找到那张视图；2026-10-23 W63）。</summary>
        int _lastAttackerSlot = -1;

        /// <summary>🆕 2026-10-20（`W58`）：**治疗那一拍** —— 只显示卡上 `HealText`（`"+" + 实际量`）。
        ///
        /// <para>**判据 = 原版 `CardScript.Heal` 协程**（`d:/2/tools/decomp_full/
        /// CardScript._Heal_d__468__MoveNext.c:155-225`）：那一拍**只做**四件事 ——
        /// 开 `healText` 节点 / 写 `"+" + min(请求, 缺失)` / 跑 `DOScale(0.05→1.0, 0.7s, OutQuad, Yoyo ×2)` /
        /// `WaitForSeconds(1.5)` 后关，外加 Normal 档的治疗圈与 `MinionHeal` 音效。
        /// ⛔ **没有** `HitReact`（后仰）、**没有** `ShakeCameraForHit`（震镜头）、
        /// **没有** `PopNumber.PopHeal`（那颗飘字是伤害计数器的时间轴，与卡上 `HealText` 是**两颗不同的 TMP**）。</para>
        ///
        /// <para>⚠️ `amount &lt; 1` 的事件**不该存在**（引擎 `HealUnit` 只在 `healed &gt; 0` 时发），
        /// 这里再挡一次是防御（手工合成事件 / 旧存档回放）。</para></summary>
        void PlayHealFeel(BattleEvent e)
        {
            if (e == null || e.Amount < 1) return;
            // 视图不在（那一格已经空了 / 还没建）⇒ 不显示。原版 `CardScript.CanContinueAnim`
            // 与 `ResolveHeal` 的 `IsInPlay` 守卫是同一件事（不能对不在场的卡飘字）。
            var v = ViewAt(e.Player, e.Slot);
            if (v == null) return;
            v.ShowHeal(e.Amount);
        }

        /// <summary>挨打：位置弹一下 + 转一下（`Impact Light Tween`），
        /// 顺便把伤害数值飘出来（`InBattleDamageCounter Variation 1` 的时间轴）
        /// <para>🆕 2026-10-21（W61 第 1 批 · 第 2 条）：<paramref name="hitOfAttack"/> = 这条 `Hit` **紧跟在
        /// 一条 `Attack` 后面**（= 那一击的伤害结算拍；由 `PlaySignals` 按事件流现判，⛔ 不靠粘性字段）。</para></summary>
        void PlayHitFeel(BattleEvent e, bool hitOfAttack = false, bool hitOfCounter = false)
        {
            // 🔴🆕 2026-10-20（`W58`）：**负数 `Hit` 是「幸存者广播」的标记，不是治疗** ——
            //   原版 `CardScript.__UseSurvivor.c:36-40` 直接写血、`:87` 只 `BroadcastUnitHealed`，
            //   **不进 `CardScript.Heal`** ⇒ **没有治疗字、没有治疗圈、没有后仰/震镜头/伤害计数**。
            //   真正的治疗现在走 `EvtKind.Heal`（见 `PlayHealFeel`）。
            //   🧨 把这个 early-return 删掉 ⇒ Survivor 会重新「后仰 + 震镜头 + 飘 +N」三件一起冒出来
            //   （`BattleScene` 的 W58 那组断言当场红）。
            if (e.Amount < 0) return;
            var v = ViewAt(e.Player, e.Slot);
            var layout = e.Player == _me ? playerBoard : enemyBoard;
            // 🔴🔴 **2026-10-11（A359）这一处是 `PlayAttackFeel` 那个缺陷的【同族漏网】**：
            //    原版这枚飘字是**挂在受击那张卡上的** `CardDamageCounterController`（字段
            //    `damageCounterParent`，见 `Battle/PopNumber.cs` 文件头的注释）⇒ 基准点 = **那张卡自己**。
            //    我们这里原来取 `layout.SlotPosition(e.Slot)` —— 那是 **2D 屏幕布局**的点
            //    （`LayoutSpace.ToWorld`，屏上 708 / 466 px），而场上的卡活在 **3D 战场**里
            //    （`ArenaSlots.RootPosition`，投影到屏上 631~657 px）⇒ 3D 下飘字**偏低 51~72 px**。
            //    改法与同族的 `PlayAttackFeel`（`:5875-5881`：那处 `dir` 是**两个坐标系相减**出来的）
            //    同一个口径：取**这张卡在屏幕上真正画在哪** = `BoardLayout.DropTargetWorld(e.Slot)`
            //    （`BoardLayout.DropTargetWorld`；**非 3D 时它逐位等于 `SlotPosition`** ⇒ 2D 路不动）。
            //    **判据只此一处**（铁律 6）—— 别在这里再算一次投影；`Editor/BattleScene.cs` 那条
            //    「飘在挨打那张卡上」的断言**必须跟着换同一个口**（两处一起改，否则那条先红）。
            //    🧨 **改坏法**：换回 `layout.SlotPosition(e.Slot)` ⇒ 飘字回落到 2D 行线（低 51~72 px）
            //    ⇒ `BattleScene.cs` 那条飘字位置断言当场红；在 2D 兜底布局下两种写法**完全等价**（不报错）。
            Vector3 at = layout.DropTargetWorld(e.Slot);

            // 🔴 **2026-10-14（`A1767` · 写手 `W11`）**：这一档**提到 `if` 之前** —— 因为**震镜头**那一条在
            //   `if (v != null)` **外面**（原版那条是**打人那张卡**的 `CardScript` 触发的，与「被打的视图还在不在」无关），
            //   而它也要用同一个「**攻击方近战档**」（`CardFeel.ShakeCameraForHit`）。
            //   ⚠️ **只在「挨打方跟攻击方不是同一侧」时才用** —— 攻击永远跨半场，而**疲劳**那一次
            //      （`RuleCore` 给玩家自己的督军发的那条 `Hit`）没有攻击方 ⇒ 不加护栏会把**上一刀**的攻击方档位套上去。
            int melee = (e.Player != _lastAttackerSide) ? _lastAttackerMelee : -1;

            // 🔴 **2026-10-21（W61 第 1 批 · 第 2 条）**：**近战攻击**那一击的「后坐 + 震屏」已经挪到
            //   **命中帧**（`ScheduleAttackPresentation` → `PlayHitFrameShake` + `PlayHitFrameRecoil`，判据见那里）——
            //   这一拍是**伤害结算**（攻方动画收尾，近战 Attack+0.4），⛔ 别在同一击上再做一次
            //   （否则挨打反应又回到「晚 0.3 s」，而且一次挨打两下）。
            //   ⚠️ 只挡「紧跟着一记**近战**攻击」的那条 `Hit`：
            //      · **远程**仍留在这一拍（原版那条弹道飞完就是命中，没有更早的挨打反馈）；
            //      · 技能伤害 / 疲劳 / 反伤没有攻击方 ⇒ 照旧在事件那一拍。
            //   🔴 **判据用 `hitOfAttack`（这一批事件流里紧跟在 Attack 后面），⛔ 不用 `_lastAttackerSide`** ——
            //     那是**粘性**字段（整局都在），会把「上一回合那一刀之后的一次技能伤害」误判成近战追击
            //     ⇒ 那次技能伤害会**丢掉后坐/震屏**（静默）。`_lastAttackRanged` 只在 `hitOfAttack` 为真时才读。
            bool meleeAttackFollow = hitOfAttack && !_lastAttackRanged;
            // 🆕 **2026-10-25（`AU1` · 第七批 · `E4` 拆两拍后的接续）**：**易伤第二拍不做后坐/震屏** ——
            //   原版那一拍是**另一条** `_ReceiveDamage`：写血 → `UpdateHealthText` → … → `DamageReceived`（伤害计数器）
            //   → `WaitForSeconds`，**没有** `ReceiveAttackAnim`（后坐只挂在近战攻击动画的命中回调上）；
            //   震屏同理（`ResolveAttackAnimationEffects` 只在近战命中帧调一次）。
            //   ⇒ 第二拍**只留飘字**（下面那段不动），后坐与震屏两者都跳过；⛔ 否则一次挨打会抖两下、震两次。
            bool recoilBeat = !meleeAttackFollow && !e.IsVulnerableSecondHit;

            if (v != null && recoilBeat)
            {
                // 「背离攻击者」= 往**自己那半场的外侧**弹 —— 🆕 2026-10-23（`W63` 收口 ②）：
                // 这只是**取不到攻击方时**的退路（原版方向恒为 `受击方 − 攻击方`）。
                Vector3 away = e.Player == _me ? Vector3.down : Vector3.up;
                // 幅度：**攻击方**的近战档（`CardFeel.PushBackMagnitude`）。
                // ⚠️ **只在「挨打方跟攻击方不是同一侧」时才用** —— 攻击永远跨半场，而**疲劳**伤害
                //    （`RuleCore` 里给玩家自己的督军发的那条 `Hit`）没有攻击方，
                //    不加这个护栏就会把**上一刀**的攻击方档位套上去。
                // （`melee` 在上面、`if` 之前 —— 2026-10-14（`A1767`）挪出去给**震镜头**共用）
                // 🔴 **只有「这条 `Hit` 紧跟在一条 `Attack` 后面」时才把攻击方交给方向计算** ——
                //    `_lastAttackerSide/_lastAttackerSlot` 是**粘性**字段（整局都在），
                //    拿它给「技能伤害 / 疲劳」算方向 = 把方向指向一个八竿子打不着的旧攻击者。
                //    ⚠️ 与 `melee` 那道护栏不同：`melee` 只看**座位不同**（老代码的判据，没动），
                //    方向这一格必须更严（`hitOfAttack`），因为方向错了是**看得见**的错。
                var attacker = ((hitOfAttack || hitOfCounter) && _lastAttackerSide != e.Player)
                    ? ViewAt(_lastAttackerSide, _lastAttackerSlot) : null;
                CardFeel.HitReactFrom(v.transform, attacker != null ? attacker.transform : null, away,
                                      Mathf.Abs(e.Amount) >= CardFeel.HeavyHitDamage, 0f, melee);
            }

            // 震镜头（原版卡预制体 `meleeHitCameraShakePreset` → preset `Shake Hit Small`）。
            // ⚠️ **放在 `v != null` 外面**：原版这条是**打人那张卡**的 `CardScript`
            //    （`ResolveAttackAnimationEffects`）触发的，与「被打的那张视图还在不在」无关。
            // 做法与「为什么是相机 + HUD 根一起动」见 `CardFeel.ShakeCamera` 的注释。
            // 🔴 **2026-10-14（`A1767` · `W11`）**：原来这里传的是**写死的 `ShakeWorldAmplitude`（0.04 = 第 1 档别名）**
            //   ⇒ 原版那三档（`GetUnitSize` 按**单位当前近战攻击** ≤3→0 / ≤7→2 / 其余→3 ⇒ 幅度 2.0/4.0/8.0）
            //   **一档都没接上**。现在改传**攻击方那一档**（`melee`，同一条 `if` 外的语义）。
            //   ⚠️ 判据 = preset 真件 `Shake Hit Small`（amplitude 2.0 · direction (0,0.2,0.2)）＋
            //      `CardScript__ResolveAttackAnimationEffects.c:32-52` 的覆盖点。
            if (recoilBeat) CardFeel.ShakeCameraForHit(cam, hudRoot, melee, 0f, boardCam);

            // 伤害 0 = 被挡下（原版也发事件）—— 那一条不飘字，免得屏幕上冒出「-0」
            // 🔴 **2026-10-17（`A1213②`）**：伤害 / 治疗走**两条独立路径**（原版是两颗不同的 TMP 组件，
            //    四格、自己的 RT 缩放、`m_isOrthographic`（0 / 1）都不同 ⇒ 有效字号比 **1.21 : 1**）。
            //    ⚠️ **2026-10-18（`N54②`）订正**：这里原来写「12.1 : 1」—— 那是漏了 3D TMP 的
            //    `isOrthographic` ×0.1 那一跳（两颗都是 3D `TextMeshPro`，不是 UGUI）。实现在 `Battle/PopNumber.cs`，
            //    判据（两颗 MB 的 pid 与逐字段读数 + 绝对字号的换算链）在它的文件头。
            //    ⛔ 别再并回「一颗函数 + 一个 bool」。
            if (e.Amount != 0)
            {
                // 🆕 2026-10-20（`W58`）：**治疗不再走这里**（负数 `Hit` 已在函数头 return；
                //   真正的治疗走 `EvtKind.Heal` → `PlayHealFeel` → 卡上 `HealText`）。
                //   ⇒ 这里只剩**伤害计数器**这一档 —— ⛔ 别再调 `PopNumber.PopHeal`（那会是第二次显示）。
                // 🆕 2026-10-19（B4）：敌方那一行整组（字号 + 偏移）都按 59.48/65.57 缩一档 ——
                // 原版这枚飘字挂在卡上，卡的 `desiredScale` 与所在行的 px/单位两样都不同。
                // 🔴 **2026-10-20（W58 · BTFIX3）**：偏移缩放收成**只读口** `PopOffsetWorldFor(seat)`
                //   —— 自检那条「飘在挨打那张卡上」也读同一个口（铁律 6：判据只此一处）。
                bool popFoe = e.Player != _me;
                // 🆕 2026-10-24（`A19` · `C1-B02`）：督军那一格的血痕/白字偏移要按**该卡实际卡根缩放**
                //   算桥（原版 `3DBody/DamageCounter` 是卡的子件）—— 见 `PopOffsetWorldFor` 的 doc。
                //   ⚠️ 判据 = 结构（督军位恒为 `BoardSpec.WarlordSlot`），⛔ 不读视图数据（受击那一刻
                //      视图可能已经不在表里）。
                bool popWarlord = layout != null && layout.IsWarlord(e.Slot);
                Vector3 popAt = at + PopOffsetWorldFor(e.Player, popWarlord);
                LastPop = PopNumber.PopDamage(transform, popAt, e.Amount, enemy: popFoe);
            }
        }

        /// <summary>伤害飘字（含它底下那颗**红色血痕** —— 血痕是这颗飘字的子件，见 `PopNumber.cs:304`）
        /// 相对**基准点**（受击那张卡的**卡身中点**）的偏移。
        /// <para>🔴 **2026-10-22 订正（铁律 5 · `W63`）：原文写「原版查不到等价字段 ⇒ 这一项是我们挑的」—— 已过期，判据找到了。**
        /// 真身 = `3DBody/DamageCounter/DamageIcon`（判据 → `资料/普查产出_1022/W63_场上卡牌与底座绿光_调查.md` §4）：</para>
        /// <list type="bullet">
        /// <item>`DamageCounter` 在 `3DBody` 空间 `localPosition = (0, 1.708, 0)`；血痕 `DamageIcon` 再偏
        /// `(0.094, −0.104, −0.05)` —— 那一跳是**子件偏移**，`PopNumber` 已按卡局部单位扣在血痕自己身上
        /// （`PopNumber.cs:304`），**不在本常量里重复扣**。</item>
        /// <item>我们的**卡根**在 `3DBody` 空间 y = `CardView.Height / 2` = **1.66565**
        /// ⇒ `DamageCounter` 在**卡根局部** y = `1.708 − 1.66565` = **+0.04235**。</item>
        /// <item>基准点 `BoardLayout.DropTargetWorld` 投的是 `ArenaSlots.CardCenter`
        /// = 卡根局部 **−0.34335**（`ArenaSlots.BodyMidOffset`）⇒ 差 = **0.3857 卡局部单位**。</item>
        /// <item>卡局部 → 我们世界单位 = `PopNumber.CardLocalToOurs`（`desiredScale 0.36 × 182.14/108` = 0.60713）
        /// ⇒ **0.2342 我们世界单位**（我方那一行；敌方行由 `PopOffsetWorldFor` 再乘 0.9071）。</item>
        /// </list>
        /// <para>⚠️ 旧值 `CardFeel.ToOurs(0.35)` = **0.5903** ⇒ **高 2.52 倍**（落在卡根局部 +0.63 ≈ 卡身上部），
        /// 用户报的「血痕 / 白字跑到卡上部」就是这一条（白字与血痕同挂这个节点，一起修）。</para>
        /// <para>⛔ `z = −0.4` **不是**原版数据（原版血痕的 z −0.05 已含在子件偏移里）—— 那是我们这颗 HUD 飘字
        /// 往相机方向的**绘制选择**，保留；别拿它当判据。</para>
        /// 🔴 **判据只此一处**（铁律 6）：`PlayHitFeel` 用它摆飘字，`Editor/BattleScene.cs` 那条
        /// 「飘在挨打那张卡上」的位置断言**读同一个常量** —— 两处各抄一份的话，偏移一改，
        /// 断言就变成「拿旧靶判新位置」（2026-10-11 A359 顺手收口：原来它内联在下面那句实参里）。</summary>
        public static readonly Vector3 PopOffset = new Vector3(
            0f,
            // = 0.3857 卡局部单位 × 卡局部 → 我们世界单位的桥（我方行那一档；敌方由 `PopOffsetWorldFor` 再缩放）
            (1.708f - CardView.Height * 0.5f - ArenaSlots.BodyMidOffset) * PopNumber.CardLocalToOurs,
            -0.4f);

        /// <summary>🆕 **2026-10-20（W58 · BTFIX3）**：某个座位的飘字相对基准点的**世界偏移**
        /// = `PopOffset` × 该行「卡局部单位 → 我们世界单位」那一档比。
        /// <para>比值的出处 = `PopNumber.EnemyCardLocalToOurs / PopNumber.CardLocalToOurs`
        /// （敌方 0.5507 / 我方 0.6071 = **0.9071** = 原版 59.48/65.57）—— 见
        /// <see cref="PopNumber.CardLocalToOursFor"/> 与它那两格的注释。</para>
        /// <para>🔴 **判据只此一处（铁律 6）**：`PlayHitFeel` 摆飘字与 `Editor/BattleScene.cs` 那条
        /// 「飘字在挨打那张卡上」的位置断言**读同一个口**。2026-10-19（B4）给敌方加这一档缩放时
        /// 断言没跟上 ⇒ 差值 0.0532 = `0.0929 × |PopOffset|` 逐位吻合（日志 51758/51771）。
        /// ⛔ 别在别处再乘一遍 / 写死 0.9071。</para>
        ///
        /// <para>🆕 **2026-10-24（`A19` · `C1-B02`）督军那一档**：血痕/白字节点 `3DBody/DamageCounter`
        /// 是**卡的子件** ⇒ 它的偏移随**卡根缩放**缩放，而督军的卡根是 `heroScale`、部队是 `desiredScale`
        /// （`BattleManager__GetUnitSizeInPlay.c:21-29`：0.36/0.40（我）· 0.69/0.77（敌）；
        /// 我们这一份常量在 `Board/ArenaSlots.cs:59-70`）⇒ 打在督军身上时还要再乘
        /// `HeroScale / CardScale`：我方 `0.40/0.36 = 1.1111`、敌方 `0.77/0.69 = 1.1159`。
        /// 差额 = 我方 **0.02602 世界单位（2.81 px@108）** / 敌方 **0.02462（≈2.12 px@86.2）**
        /// —— 也就是原来打在督军身上时飘字**低了**那两点几个像素。</para></summary>
        /// <param name="warlord">被挨打的那一格**是不是督军**（判据 = `BoardLayout.IsWarlord(slot)`，
        /// 督军位恒为 `BoardSpec.WarlordSlot`；⛔ 别改成「看视图的 `Data`」—— 那要视图还在）。</param>
        public Vector3 PopOffsetWorldFor(int seat, bool warlord = false)
        {
            bool foe = seat != _me;
            float f = PopNumber.CardLocalToOursFor(foe) / PopNumber.CardLocalToOurs;
            // 🆕 2026-10-24（C1-B02）：督军档再乘该卡「根缩放 → 世界单位」那一档的比值（见上面的 doc）。
            if (warlord) f *= ArenaSlots.HeroScale(foe) / ArenaSlots.CardScale(foe);
            return PopOffset * f;
        }

        /// <summary>最近一次飘出来的数值（自检断言用 —— 飘字 1.83 s 后自己销毁，截图上看不出它来过）</summary>
        public Label LastPop { get; private set; }

        /// <summary>阵亡消散。
        /// ⚠️ **必须把视图从 `_myUnits/_foeUnits` 里摘掉** —— 不然 `SyncBoard` 发现引擎里那一格空了，
        ///    当场就把视图 `Kill` 了，消散一帧都看不见（批处理里更是直接 `DestroyImmediate`）。
        /// <para>🆕 2026-10-22（P6 · M1/M2）：`collectDeath` = 这条 `Death` 是**收集灵魂石**带出来的
        /// （判据 → <see cref="IsCollectDeathAt"/>）⇒ 走 `CardFeel.PickDeathFx` 的
        /// `collectedWaystone` 那一支：**不播**残骸 Destroy 件、也不播普通阵亡件
        /// （原版 `RemnantAeldari.DoDestroy` 的 `deathType == 50` 只走收集链），
        /// `DeathExplosion` 回 `null` ⇒ 下面 `tw == null` 那一支**当场就把视图收掉**
        /// （原版 `CollectWaystoneEffect` 末尾就是 `Destroy(残骸体)`，没有 `UnitDeath` 那 0.7 s）。</para></summary>
        void PlayDeathFeel(BattleEvent e, bool collectDeath = false)
        {
            var views = e.Player == _me ? _myUnits : _foeUnits;
            var fade = FadingMap(e.Player);
            CardView v = null;
            bool fromFade = false;
            if (fade.TryGetValue(e.Slot, out v) && v != null) fromFade = true;
            else if (!views.TryGetValue(e.Slot, out v) || v == null) return;

            // 🆕 2026-09-25 **「引擎说它死了、可那一格还站着人」= 它变成残骸了 ⇒ 不播阵亡消散、不摘视图。**
            //
            // 原版那条路根本不是普通阵亡：`BattleManager.ResolveDestroyUnit` 里先问
            // `SupportMethods.HasToTransformIntoRemnant`（`remnant(1050) || waystone(1140)`），
            // 命中就走 `AddTransformIntoRemnant` —— 画面上是**同一张卡**被盖上残骸体
            // （`BattleCardUI.CreateRemnantBody` + `RemnantBody.ToggleBody3D(false)`），**那张卡不消散**。
            //
            // ⚠️ 没有这道守卫的后果（**很难查**）：`SyncBoard` 刚给同一张视图盖上残骸体，
            //    0.85 s 后这条阵亡事件轮到播放，又把它溶解销毁 ⇒ 残骸**闪一下没了、再新建一张视图**，
            //    看上去像「残骸随机消失」。而两条路径各自看都「对」。
            // ⚠️ 判据用**棋盘那一格还有没有东西**，而不是 `IsRemnant` —— 因为这条事件是在
            //    `EventTiming` 排的**延迟队列**里，轮到播的时候棋盘可能又变过了；
            //    「这一格还站着人」才是「别溶解」的充分理由（格子上真有别人也算，不能溶掉一张活的卡）。
            // ⚠️ 判据 = **这一格上站的是不是「同一张卡翻了个面的残骸」**，而不是原来那句
            //    「这一格里有没有人」—— 🔴 **2026-10-01 改模型时这一条必须跟着改**：
            //    棋盘连续无洞之后，普通阵亡**当场就会有人补位进来**（`BoardSlots.RemoveAt`），
            //    按「有没有人」判的话**所有内侧阵亡都不会演消散**（画面上人「啪」地消失，
            //    而自检里那些洞状夹具不会有这个现象 ⇒ 只有真人玩才看得出来）。
            //    现在按**身份**判：只有「那一格站着的确实是它的残骸」才不溶解。
            if (!fromFade && Ctx != null && BoardSpec.IsValid(e.Slot))
            {
                var occ = Ctx.Players[e.Player].Board[e.Slot];
                if (occ != null && occ.IsRemnant && occ.Card != null && occ.Card.Name == e.CardId)
                    return;      // 翻面成了残骸 ⇒ 同一张卡继续站着（原版 `RemnantBody3D` 那一路）
            }

            fade.Remove(e.Slot);
            // ⚠️ 只摘**它自己**那一格 —— 这一格里现在挂的可能是补位上来的新主人（别把它一起摘了）
            CardView occupied;
            if (views.TryGetValue(e.Slot, out occupied) && occupied == v) views.Remove(e.Slot);
            _dying.Add(v);
            // 督军格的**抖动**更长（原版 `deathTimeWarlordDuration 0.5` vs 小兵 0.2，见 `CardFeel.DeathDissolve`）
            // ⚠️ **2026-10-23（`新账-79`）就地订正（铁律 5）**：这一行原来写「督军格的阵亡**慢一倍多**」——
            //   **总寿命两档相同**（都是 `DeathTotal` 0.7，见下面那段），慢的只有**抖动**那一段。
            // 🆕 2026-09-29：表现**照原版重做**了 —— 不是溶解，是「关掉 3D 体 + 在卡位生成死亡爆散体 + 抖一下」
            //   （判据与被卡住的那一环 → `CardFeel.DeathExplosion`）。
            // 🆕 2026-10-16：**那一串的四拍顺序照原版补齐了**（抖 → 站 0.5 s → 这时才爆散 + 关 3D 体 →
            //   再 0.2 s → `GoToCemetery`）⇒ 这个视图从这一刻起要活 **`CardFeel.DeathTotal(warlord)`**
            //   = **0.7 s，小兵/督军同**（抖 0.2/0.5 只决定抖多久，**不影响总寿命**）。
            //   🔴 **2026-10-23（P1 · 演出时序 ②）就地订正（铁律 5）**：这里原来写「小兵 0.9 s /
            //   督军 1.2 s」—— 那是**把抖动串在 0.5 s 前面**算出来的旧值（`W61` 第 1 批已改成并行）。
            //   判据 → `CardFeel.DeathBeats` / `DeathTotal` 的 doc。
            bool warlord = e.Slot == BoardSpec.WarlordSlot;
            // 🆕 2026-10-22（P6 · M2/M3）：**把这一张的 `CardDef` 带下去** ——
            //   `CardFeel.PickDeathFx` 要用 `CardFeel.IsRemnantFamily`（与 `PlayRemnantSfx` **同一份**判据）
            //   判「死的是不是残骸 ⇒ 播 `Remnant <阵营> Destroy particles` 而不是普通阵亡件」。
            //   ⚠️ 判据**不看棋盘那一格**：连续棋盘下它当场就被补位的人占了（与上面那道守卫同一条理由），
            //   所以按键词判「这一族」是唯一稳定的口径（同 `PlayRemnantSfx`）。
            RuleEngine.CardDef deadDef = (string.IsNullOrEmpty(e.CardId) || _pool == null) ? null
                : CardDatabase.Find(_pool, e.CardId, e.Player == _me ? _myFaction : _foeFaction);
            var tw = CardFeel.DeathExplosion(v, 0f, () => { _dying.Remove(v); Kill(v.gameObject); },
                                             warlord, deadDef, collectDeath);
            if (tw == null) { _dying.Remove(v); Kill(v.gameObject); }   // 没补间（例如 DOTween 不可用）就直接销毁
        }

        /// <summary>
        /// **回手 / 回牌库**（`Return a friendly Vehicle to your hand`）—— 把视图从格位上摘掉。
        ///
        /// 和 <see cref="PlayDeathFeel"/> 的区别只有一条，但很要紧：**不播消散**。
        /// 它不是死了，是回手牌了 —— 播阵亡特效是**错的画面**。
        /// （引擎侧也不会把它放进弃牌堆／阵亡登记表，两边对得上。）
        ///
        /// ✅ **「飞回手牌」那条动画原版是什么，2026-09-17 查到了**（原来这里写「没查到」）：
        ///    `BattleCardUI.PlayBackToHandAnimation`（`decomp_out/BattleCardUI__PlayBackToHandAnimation.c`）=
        ///    **把「手牌 → 战场」那条 clip 倒放**：
        ///      `Animation.Rewind()` → 取那条 clip 的 `AnimationState` →
        ///      **`speed = −1`**（字面量 `_DAT_1834b2bc8`，本机用 `工具/read_literal.py` 读出 **−1.0**）→
        ///      **`time = AnimationState.length`**（从末尾起；⚠️ 不是 `AnimationClip.length`，值相同但**措辞**要准）→
        ///      `Play()`；随后 `StartCoroutine(DelayedResetMaterial(0.55))` 复位材质。
        /// ✅ **2026-09-29 做完了**：实现 = `CardFeel.ReturnToHand`（**同一条时间轴用代码喂值** ——
        ///    我们这套 2D 卡没有 `Animation` 组件、更没有那条 clip）。逐帧判据（含反向四个时刻与
        ///    `DOMove(up × localScale.x × 3.0, 0.208 s, 线性)`）都写在那个方法的注释里，本文件不抄第二份。
        /// ⚠️ **回牌库也走这条倒放**（原版两个调用者：`ResolveRecallToHand` / `ResolveRecallToDeck`）。
        /// </summary>
        void PlayReturnFeel(BattleEvent e)
        {
            var views = e.Player == _me ? _myUnits : _foeUnits;
            var fade = FadingMap(e.Player);
            CardView v;
            // 🔴 2026-10-01：回手/回牌库**也会让外侧的人补位** ⇒ 键可能已经被顶掉了，先去 `_fading` 找
            //   （键被顶掉那一刻由 `DetachStaleView` 存下来；没顶掉的仍挂在 `views` 上）
            if (fade.TryGetValue(e.Slot, out v) && v != null) fade.Remove(e.Slot);
            else if (!views.TryGetValue(e.Slot, out v) || v == null) return;
            // ⚠️ 只摘**它自己**那一格（这一格可能已经换了新主人）
            CardView occupied;
            if (views.TryGetValue(e.Slot, out occupied) && occupied == v) views.Remove(e.Slot);

            // 🆕 2026-09-29：**倒放 `Card Hand To Board`**（原版 `BattleCardUI.PlayBackToHandAnimation`）——
            //   原来这里是「当场摘掉」。⚠️ 与阵亡同一条道理：**必须先从字典里摘掉**，否则 `SyncBoard`
            //   发现引擎里那一格空了，当场就把它 `Kill` 了，动画一帧都看不见。
            //   摘掉之后它成了孤儿 ⇒ 挂进 `_returning`，重开一局时由 `Begin` 那一段统一清掉。
            //   ⚠️ **回牌库也走同一条倒放**（原版两个调用者：`ResolveRecallToHand` 与 `ResolveRecallToDeck`）。
            if (animateFeel)
            {
                _returning.Add(v);
                var tw = CardFeel.ReturnToHand(v, 0f, () => { _returning.Remove(v); Kill(v.gameObject); });
                if (tw != null) return;
                _returning.Remove(v);       // 没补间（DOTween 不可用）⇒ 落到下面直接销毁
            }
            Kill(v.gameObject);
        }

        /// <summary>正在回手的视图（已经从 `_myUnits/_foeUnits` 里摘掉了）。自检断言用。</summary>
        readonly List<CardView> _returning = new List<CardView>();
        public int ReturningCount { get { return _returning.Count; } }
        public CardView ReturningView(int i) { return i >= 0 && i < _returning.Count ? _returning[i] : null; }

        /// <summary>正在消散的视图（已经不在 `_myUnits/_foeUnits` 里了）。自检断言用</summary>
        readonly List<CardView> _dying = new List<CardView>();
        public int DyingCount { get { return _dying.Count; } }
        public CardView DyingView(int i) { return i >= 0 && i < _dying.Count ? _dying[i] : null; }

        /// <summary>这一格有没有**排着队还没播**的阵亡事件 —— `SyncBoard` 靠它决定
        /// 「现在能不能把这个视图销毁掉」（见那里面的注释：销毁早了消散就演不出来）</summary>
        bool DeathPendingFor(int owner, int slot)
        {
            for (int i = 0; i < _timeline.Count; i++)
            {
                var e = _timeline[i].evt;
                // 🔴 **2026-10-22（`W64`）**：同一族的空守卫 —— cue（`cueVfx` / `cueAction`）的
                //   `evt` 恒 null（见 `PendingExitFor` 里那条注释与
                //   `资料/普查产出_1022/W64_PendingExitFor空引用诊断.md` §①/§⑤）。
                //   `null` 不可能 `Kind == Death` ⇒ 跳过它判定结果逐位不变。
                if (e == null) continue;
                if (e.Kind == EvtKind.Death && e.Player == owner && e.Slot == slot) return true;
            }
            return false;
        }

        /// <summary>
        /// 销毁视图。
        /// ⚠️ **编辑器模式下 `Object.Destroy` 不生效**（它要等下一帧，而编辑/批处理里没有帧循环），
        ///    必须用 `DestroyImmediate`。踩过：批处理自检里旧的手牌视图全留在画面上，
        ///    看起来像「手牌莫名其妙多出好几张」。
        /// </summary>
        static void Kill(Object o)
        {
            if (o == null) return;
            if (Application.isPlaying) Destroy(o);
            else DestroyImmediate(o);
        }

        /// <summary>某一格上那个单位**该站的位置与缩放**。
        /// 🔴 **判据只此一处** —— `SyncBoard` 落位与「让位」预览（`TickShufflePreview`）都读它，
        /// 免得多处各算一套坐标（那种分叉本工程吃过好几次）。
        /// 两套走法：真 3D 战场用 `ArenaSlots`（逐值来自原版 `MinionManager`，判据 = `ArenaSlots` 唯一出处）；
        /// 没有 3D 战场时退回烘好的背景图那套正交坐标 —— 那一层没有别的相机，
        /// 这时候把卡挂到 `ArenaLayer` 会**两台相机都不画**（静默消失）。</summary>
        void PoseFor(bool mine, int slot, UnitState u, out Vector3 pos, out float scale)
        {
            if (use3DBoard)
            {
                // 站在地面上、y=0、卡根旋转 identity、缩放 = `desiredScale`（玩家 0.36 / 敌 0.69）。
                // ⚠️ **屏幕位置和原来那套正交坐标几乎重合**（两行 65.4%/42.7% vs 原版实测
                //    65.6%/43.1%）⇒ **命中判定仍然按屏幕空间走，不用改**。
                bool foe = !mine;
                float sc = (u != null && u.IsWarlord) ? ArenaSlots.HeroScale(foe) : ArenaSlots.CardScale(foe);
                pos = ArenaSlots.RootPosition(slot, foe, sc);
                scale = sc;
            }
            else
            {
                var layout = mine ? playerBoard : enemyBoard;
                pos = layout.SlotPosition(slot);
                scale = layout.placedScale * LayoutSpace.Scale;
            }
        }

        /// <summary>🆕 2026-10-19（B2 · 偏差 8）：这一格这张视图**正在飞**吗（见 `_aiDeployFlying` 的 doc）。
        /// 带视图身份 —— 同一格换了别人的视图时**不算**（那时候该正常摆位）。</summary>
        bool IsAiDeployFlying(int owner, int slot, CardView v)
        {
            CardView fly;
            return _aiDeployFlying.TryGetValue(HpKey(owner, slot), out fly) && fly == v;
        }

        /// <summary>🆕 2026-10-19（B2 · 偏差 8）：**AI 飞行落地那一拍**的整套登场反馈 ——
        /// 原版这几件都在 `CardScript.LandOnGround` / `MinionPlayedIntoField` 跑完那一刻：
        /// 卡淡入（`VfxMap.Deploy`）· 阵营召唤法阵 · 扬尘 · 震镜头。
        /// ⚠️ 它们在 `PlaySignal` 里被 `_aiDeployFlights` 守卫**跳过**（那一拍是起飞），到这里才补。</summary>
        void PlayAiDeployLandingVfx(BattleEvent e)
        {
            if (e == null || Ctx == null) return;
            var layout = e.Player == _me ? playerBoard : enemyBoard;
            if (layout == null) return;
            // 🔴 C5（2026-10-25）：原版按 **`cardArmy`**（卡自己的阵营）查特效/动画表 —— 见 `VfxFactionOf` 的 doc
            string faction = VfxFactionOf(e.Player, e.CardId, e.InstanceId, e.Slot);

            PlayDeployFeel(e);

            _animfxLastEvent = e;
            _animfxCtx = BuildCardContext(e);
            // 🆕 2026-10-19（T05 · 卡上特效改走挂载）：与 `PlaySignal` 的 Deploy 同一口径 ——
            //   `normalSummon` 是根实例化在卡的世界位置上 ⇒ 进竞技场空间（判据见 `FireDeployVfxInArenaSpace`）。
            FireDeployVfxInArenaSpace(VfxMap.Deploy, e, faction, perCardOnly: false);
            // 🔴 **2026-10-21（W61 第 2 批 · 第 2 条）**：这里原来还补一发**按阵营的召唤法阵** ——
            //   原版没有那一层（判据与删除记录 → `Core/VfxMap.cs` 那段注释）。⛔ 别加回来。
            _animfxCtx = default;

            PlayDeployLandDust(BoardViewAt(e.Slot, e.Player == _me), e.Slot, layout, e);
        }

        /// <summary>🆕 2026-10-19（战斗线 B2 · 偏差 8）：**AI 打出的单位从敌方手牌飞进格位**
        /// （原版 AI 走**同一条** `_ResolvePlayCardFromHand` → `CardScript.MinionPlayedIntoField`，
        /// 也就是玩家那条四段飞行：`DeploySequence` 的 0.3 飞向格位上方 → **0.1 等** →
        /// **0.4 换 3D 体** → 0.05 悬停 → 0.2 竞技场空间落下）。
        ///
        /// <para>起点 = **敌方手牌那张牌**（`foeHand.SlotPosition` + `RotationAt` + `EnemyCardScale`），
        /// 终点 = `PoseFor` 算出的格位位姿；两者都从**生产那一份**取（⛔ 不另算坐标）。</para>
        ///
        /// <para>🔴 **2026-10-19（B3）载体改对了**：原版 `MinionPlayedIntoField` 的整条协程都在**手牌那张
        /// 卡对象本体**上动 `transform`（`CardScript._MinionPlayedIntoField_d__314__MoveNext.c`）；
        /// 敌方手牌露出来的是**卡背节点** ⇒ 现在飞的是 **`_foeHandViews` 里那张卡背 `ImageQuad`**
        /// （`DeploySequence.PlayQuad`，与玩家那条**同一组时长/缓动**），而 `SyncBoard` 建出来的
        /// 场上样式视图**全程隐藏**、落地那一刻才显示并摆到 `PoseFor` 的位姿。
        /// ⚠️ B2 那一版飞的是场上样式视图（外观差一层卡框/背面），这一版才是原版的载体。
        /// ⚠️ **退路**：手牌视图取不到 / 量不到卡背宽度 ⇒ 退回 B2 那种「飞场上视图」，**并出声**。</para>
        ///
        /// <para>落地那两条 cue（`invokeCUE` / `landOnGround`）在飞行**终点**播 —— 这就是偏差 9
        /// 「四条一起响」的另一半（起飞那两条在起点播，见 <see cref="PlayDeployTakeoffCues"/>）。</para>
        ///
        /// <para>⚠️ 只在 `animateFeel` 打开时走到这里（批处理/自检要「当场精确」的坐标，见
        /// `animateFeel` 的 doc）。</para></summary>
        void StartAiDeployFlight(CardView v, int owner, int slot, AiPlayTicket ticket,
                                 Vector3 finalLocal, float finalScale)
        {
            if (v == null) return;
            var layout = owner == _me ? playerBoard : enemyBoard;
            if (layout == null) { v.SetPose(finalLocal, 0f, finalScale); return; }
            AiDeployFlightsStartedForTest++;

            int key = HpKey(owner, slot);
            BattleEvent evt;
            _aiDeployLandingCue.TryGetValue(key, out evt);

            // ---- 终点：与玩家那条**同一组**生产函数（`DropTargetWorld[AtHeight]`）----
            //   🔴 它们返回的是**HUD 平面**上的点（「落位后那个位姿在屏幕上的同一点」，见
            //   `BoardLayout.DropTargetWorld` 的注释）—— 飞行这一段卡由 **HUD 正交相机**画
            //   （和玩家那条完全同形：玩家飞行时卡还没进第 8 层）。落地那一刻再切回 `ArenaLayer`
            //   并把卡摆到 `PoseFor` 的 3D 位姿（`finalLocal/finalScale`）——
            //   两者在屏幕上同点，所以这一跳看不见（同 `DoPlay` 那次交接的判据）。
            Vector3 aboveLocal = layout.DropTargetWorldAtHeight(slot, layout.MinionConversionHeight);
            Vector3 landLocal = layout.DropTargetWorld(slot);
            Vector3 aboveWorld = boardRoot != null ? boardRoot.TransformPoint(aboveLocal) : aboveLocal;
            Vector3 landWorld = boardRoot != null ? boardRoot.TransformPoint(landLocal) : landLocal;
            // 飞行段的缩放 = **玩家那条的同一个值**（`BoardLayout.placedScale × LayoutSpace.Scale`）
            float flyEndScale = layout.placedScale * LayoutSpace.Scale;

            // ---- 载体：优先 **敌方手牌那张卡背本体**（原版的载体）----
            //   ⚠️ 🆕 B5：**只在对手侧**用卡背载体 —— 我方手牌是 `CardView`（不是卡背 quad），
            //     而 `autoPlayFromHand` 那张牌**从来没在画面上落到手里**（同步结算，见 `CompletePendingDeploy`）
            //     ⇒ 我方这一档一律走下面那条「飞场上视图」的路（起点 = 手牌末位，即它若在手里会占的那一格）。
            ImageQuad handQuad = null;
            int handQuadIdx = -1;
            if (owner != _me && foeHand != null && _foeHandViews.Count > 0)
            {
                int n0 = _foeHandViews.Count;
                handQuadIdx = Mathf.Clamp(ticket.handIdx, 0, n0 - 1);
                handQuad = _foeHandViews[handQuadIdx];
            }
            // 卡背要缩放到多大才和「飞行段那张卡」一样宽：两边都换成**世界宽度**再比
            //   （卡背：`_foeBackWorldW × foeHand 的 lossyScale`；目标：`CardView.Width × flyEndScale
            //    × boardRoot 的 lossyScale`）。任何一边量不到 ⇒ 0 ⇒ 走退路。
            float quadEndScale = 0f;
            if (handQuad != null && _foeBackWorldW > 1e-4f)
            {
                float quadWorldW = _foeBackWorldW * Mathf.Max(1e-4f, Mathf.Abs(foeHand.transform.lossyScale.x));
                float targetWorldW = CardView.Width * flyEndScale
                                   * Mathf.Max(1e-4f, Mathf.Abs(boardRoot != null ? boardRoot.lossyScale.x : 1f));
                quadEndScale = targetWorldW / quadWorldW;
            }
            bool useHandCarrier = handQuad != null && quadEndScale > 1e-4f;

            // 偏差 9：**起飞**那两条 cue（原版在牌离开手牌那一拍）
            // 🔴 🆕 2026-10-19（W · 偏差 9：`_ResolveCardAutoSummoned` 逐句读完，判据落定）：
            //   `autoPlayFromHand` **不是**「两条同一拍」—— 原版那条协程
            //   `BattleManager._ResolveCardAutoSummoned_d__511__MoveNext.c` 分 state：
            //     · **state 0**（`:104-106` 玩家 / `:122-124` 敌方）→ `moveCardIntoBattle`（2D）；
            //       紧接着 `CardScript.PlayPlayerCard/PlayEnemyCard(timeToPlayEnemyCard(0.6)/5.0 = 0.12)`
            //       → `ShowCardInCenter(0.12)`：**卡居中展示**
            //       玩家侧 = 0.12(缩放) + 0.1(`timeToScaleIntoMoving` 的位移、delay 0.12) + 0.12(再等) = **0.34 s**
            //       敌方侧 = 0.12(缩放与位移同时) + 0.12(再等) = **0.24 s**（`CardScript__ShowCardInCenter.c` 两个分支逐句）
            //       ⇒ 常量 `VarsGlobal+0x44 = cardInHandMovingScale = 1.1` · `VarsGlobal+0x78 = timeToScaleIntoMoving = 0.1`
            //         · 玩家侧再 × `DAT_1834b3090 = 1.5`（DLL 实读）· 位移方向/距离 = `Vector3.up × 4`（玩家）
            //         / `Vector3.up × −12`（敌方，`DAT_1834b3160 = 12`）—— 见 `PlayAutoPlayCenterDisplay`。
            //     · **state 1/2**（`:187-190`）→ `playMinionFromHand`（2D），**之后**才
            //       `MinionManager.PlayMinionFromHand` 飞向格位 ⇒ 这一条在**居中展示之后**才响。
            //     · **state 3** → `MinionPlayedIntoField(doTransformAnim = 1)`：`LandOnGround` 在**协程收尾那一拍**
            //       （`:37` 判 `doTransformAnim == 0` 时才是「一进来就落」；=1 的那一支在 state 3 才落）
            //       ⇒ 落地两条仍在**飞行终点**（`LandAiDeployFlight`，不变）。
            //   ⇒ autoPlay 的两条起飞 cue **分两拍**（中间隔着居中展示）；其它路照旧两条一起。
            bool autoPlay = ticket.autoPlay;
            if (autoPlay) BattleSfx.Play(BattleSfx.MoveCardIntoBattle);
            else PlayDeployTakeoffCues();
            _aiDeployFlying[key] = v;            // 飞行期间 `SyncBoard` 不许碰这个视图的层与位姿

            if (useHandCarrier)
            {
                AiDeployFlightsViaHandCardForTest++;
                // 它已经离开手牌 ⇒ 从手牌表里摘掉。不摘的话紧接着的 `SyncFoeHand` 会把它
                // **重新排位**（飞行中途被拽回手牌）或在减张那一支把它当**尾巴**杀掉。
                if (handQuadIdx >= 0 && handQuadIdx < _foeHandViews.Count && _foeHandViews[handQuadIdx] == handQuad)
                    _foeHandViews.RemoveAt(handQuadIdx);
                _foeDealt.Remove(handQuad);
                _aiDeployFlyingHand[key] = handQuad;
                // 场上视图**全程看不见**（飞行段画面里只有那张卡背；原版那张卡本体此时也还是手牌形态）。
                // 🔴 **用「关渲染器」而不是 `SetActive(false)`**：飞行这 0.65 s 里 `SyncBoard` 仍会
                //    `SetData` —— 而 TMP 在**未激活**对象上量不出尺寸（本仓踩过，见 `Label` 那条坑）。
                HideBoardViewForFlight(key, v);
                // 🆕 2026-10-19（`W57` · `T05(c)(d)`）：**0.4 s 的交接** —— 原版同一个 `_MinionPlayedIntoField`：
                //   飞行 0.3 + 等待 0.1 之后 `SetUnitInPlayLayer` 换成 3D 体，最后 0.2 s 在竞技场空间落下。
                //   我们这条载体是「敌方手牌那张卡背」⇒ 交接 = 卡背退场、**场上视图**接管落体。
                Vector3 aiAboveLocal = use3DBoard
                    ? finalLocal + Vector3.up * layout.MinionConversionHeight
                    : finalLocal;
                var aiHandoff = new DeploySequence.Handoff
                {
                    FallTarget = v.transform,
                    LandLocal = finalLocal,
                    Apply = () =>
                    {
                        // ⚠️ **不能销毁卡背**：整条序列的 `SetLink` 绑在它身上，提前 `Kill` 会把后半段
                        //    （落体那 0.2 s）一起杀掉 ⇒ 这里只关掉，落地拍（`onDone`）再 `Kill`。
                        // ⚠️ 卡背仍留在 `_aiDeployFlyingHand` 里（丢事件时靠它收账）—— 用一个
                        //    `_aiDeployHandedOff` 标记「从这一拍起在飞的是场上视图」。
                        if (handQuad != null) handQuad.gameObject.SetActive(false);
                        _aiDeployHandedOff.Add(key);       // 从这一拍起「在飞的是场上视图」
                        RestoreBoardViewVisibility(key);   // 飞行期间关掉的渲染器逐件还原
                        if (v == null) return;             // 这一格在这 0.4 s 里被换掉了 ⇒ 不碰（落体会自己报缺）
                        if (use3DBoard) v.SetLayer(ArenaSlots.ArenaLayer);
                        v.SetPose(aiAboveLocal, 0f, finalScale);
                    },
                };
                // 🆕 W（偏差 9 / autoPlay）：起飞那两拍分在两个 state ⇒ 这里把「飞向格位」整段
                //   收进一个 Action：autoPlay 时先跑居中展示（0.24 s），展示结束才响 `playMinionFromHand`
                //   并起飞；其它路原样（cue 已在上面响过）。
                System.Action launch = () =>
                {
                    if (autoPlay) BattleSfx.Play(BattleSfx.PlayMinionFromHand);   // 原版 state 1/2（`:187-190`）
                    var twq = DeploySequence.PlayQuad(handQuad.transform, aboveWorld, landWorld,
                                                      quadEndScale, aiHandoff, () =>
                    {
                        _aiDeployFlyingHand.Remove(key);
                        _aiDeployHandedOff.Remove(key);     // 🆕 W57：交接标记跟着这张票一起结账
                        CardView fly;
                        if (_aiDeployFlying.TryGetValue(key, out fly) && fly == v) _aiDeployFlying.Remove(key);
                        if (handQuad != null) Kill(handQuad.gameObject);   // 落地 = 这张卡背换成场上的卡（可能已被 DropSignals 收掉）
                        LandAiDeployFlight(v, key, evt, finalLocal, finalScale);
                    });
                    if (twq != null) twq.SetUpdate(CardTween.Mode);
                };
                if (autoPlay)
                {
                    float centerMul = owner == _me ? AutoPlayCenterScaleMulPlayer : AutoPlayCenterScaleMulFoe;
                    PlayAutoPlayCenterDisplay(handQuad.transform, owner,
                                              handQuad.transform.localScale * centerMul, launch);
                }
                else launch();
                return;
            }

            if (handQuad != null)
                Debug.LogWarning("[Battle] AI 出牌：量不到敌方手牌卡背的宽度（`_foeBackWorldW`）⇒ "
                               + "飞行退回**场上样式视图**（B2 的做法；外观差一层卡框/背面）");

            // ---- 退路 / 我方：飞场上样式视图（B2 的做法；手牌视图取不到时）----
            // 起点：**那一侧的手牌布局**（局部系 = 手牌节点的 transform）
            //   · 对手 = `foeHand` + 卡背张数（今天的 AI / 远端人类出牌）；
            //   · 我方 = `hand` + 引擎手牌张数（今天只有 `autoPlayFromHand` 走这里，见 `CompletePendingDeploy`）。
            // 🆕 B5：**我方 auto-play 的索引是「当前张数」**（那张牌曾被追加到末尾再拿走）⇒
            //   把张数按 +1 算、索引取末位 —— 那才是它在画面上会占的那一格（⛔ 别 clamp 成现有最后一张，
            //   那会少一格、和原版「追加到末尾」的位置差半张卡）。
            Vector3 startLocal;
            float startRotZ = 0f;
            var handLayout = owner == _me ? hand : foeHand;
            int handN;
            if (owner == _me)
                handN = (Ctx != null && Ctx.Players != null && owner >= 0 && owner < Ctx.Players.Length
                         && Ctx.Players[owner].Hand != null) ? Ctx.Players[owner].Hand.Count : 0;
            else
                handN = foeHand != null ? _foeHandViews.Count : 0;
            float startScale = (owner == _me
                                ? (handLayout != null ? handLayout.cardScale : HandLayout.DefaultCardScale)
                                : HandLayout.EnemyCardScale) * LayoutSpace.Scale;
            if (handLayout != null && (handN > 0 || ticket.handIdx > 0 || owner == _me))
            {
                int n = Mathf.Max(1, handN);
                int idx = Mathf.Clamp(ticket.handIdx, 0, n - 1);
                if (ticket.handIdx >= n)
                {
                    // 索引已经落在现有手牌之外 ⇒ 那张牌曾**追加在末尾**（我方的 auto-play）
                    idx = n;             // 旧张数 = 末位；张数按 n+1 算 ⇒ 归一化位置 = 最右
                    n = n + 1;
                }
                Vector3 handLocal = handLayout.SlotPosition(idx, n);
                Vector3 handWorld = handLayout.transform.TransformPoint(handLocal);
                startLocal = boardRoot != null ? boardRoot.InverseTransformPoint(handWorld) : handWorld;
                startRotZ = handLayout.RotationAt(idx, n);
            }
            else
            {
                Vector3 deckWorld = owner == _me
                    ? LayoutSpace.ToWorld(MyDeckX01, MyDeckY01)
                    : LayoutSpace.ToWorld(FoeDeckX01, FoeDeckY01);
                startLocal = boardRoot != null ? boardRoot.InverseTransformPoint(deckWorld) : deckWorld;
                Debug.Log($"[Battle] 落位飞行：{(owner == _me ? "我方" : "敌方")}手牌视图取不到"
                        + $"（n={handN}）⇒ 飞行起点退回{(owner == _me ? "我方" : "敌方")}牌堆位置");
            }

            v.SetPose(startLocal, startRotZ, startScale);
            v.SetLayer(0);                    // 飞行段归 HUD 正交相机画（同玩家那条：卡还在手牌那一层）
            // 🆕 2026-10-19（`W57` · `T05(c)(d)`）：同手牌卡背那条 —— 0.4 s 换 3D 体、之后在竞技场空间落下。
            //   这一条的载体会就是**场上视图自己的 transform**（退路：手牌视图取不到）。
            Vector3 fbAboveLocal = use3DBoard
                ? finalLocal + Vector3.up * layout.MinionConversionHeight
                : finalLocal;
            var fbHandoff = new DeploySequence.Handoff
            {
                FallTarget = v.transform,
                LandLocal = finalLocal,
                Apply = () =>
                {
                    RestoreBoardViewVisibility(key);   // 退路那条没藏过 ⇒ 空操作，留着与手牌那条同形
                    if (v == null) return;             // 这一格在这 0.4 s 里被换掉了 ⇒ 不碰（落体会自己报缺）
                    if (use3DBoard) v.SetLayer(ArenaSlots.ArenaLayer);
                    v.SetPose(fbAboveLocal, 0f, finalScale);
                },
            };
            // 🆕 W（偏差 9 / autoPlay）：同手牌卡背那条 —— 起飞两条分两拍，中间夹居中展示。
            System.Action fallbackLaunch = () =>
            {
                if (autoPlay) BattleSfx.Play(BattleSfx.PlayMinionFromHand);   // 原版 state 1/2
                var tw = DeploySequence.Play(v, aboveWorld, landWorld, flyEndScale, fbHandoff, () =>
                {
                    CardView fly;
                    if (_aiDeployFlying.TryGetValue(key, out fly) && fly == v) _aiDeployFlying.Remove(key);
                    LandAiDeployFlight(v, key, evt, finalLocal, finalScale);
                });
                tw.SetUpdate(CardTween.Mode);
            };
            if (autoPlay)
            {
                // 居中展示的目标缩放 = 手牌缩放 × `cardInHandMovingScale(1.1)` × [玩家侧再 × `1.5`]
                // （`CardScript__ShowCardInCenter.c` 两个分支；见 `PlayAutoPlayCenterDisplay` 的 doc）。
                float centerMul = owner == _me ? AutoPlayCenterScaleMulPlayer : AutoPlayCenterScaleMulFoe;
                PlayAutoPlayCenterDisplay(v.transform, owner,
                                          Vector3.one * (startScale * centerMul), fallbackLaunch);
            }
            else fallbackLaunch();
        }

        // ==================================================================
        //  🆕 2026-10-19（W · 偏差 9 / autoPlayFromHand）「卡牌居中展示」那半拍
        // ==================================================================
        //  判据（逐句，`d:/2/tools/decomp_full/`）：
        //   · `BattleManager._ResolveCardAutoSummoned_d__511__MoveNext.c:108-133` ——
        //     `PlayPlayerCard/PlayEnemyCard(timeToPlayEnemyCard / DAT_1834b2df4)`
        //     = `0.6 / 5` = **0.12 s**（`DAT_1834b3180=0.6` · `DAT_1834b2df4=5`，DLL 实读）。
        //   · `CardScript._PlayPlayerCard_d__259__MoveNext.c:35-45` —— 单位卡（`cardType==0`）先
        //     `ShowCardInCenter(param)`、`WaitForSeconds(它返回的时长)`，再 `MoveIntoFieldFromHand`、再等 param。
        //   · `CardScript__ShowCardInCenter.c`（两个 `isPlayer` 分支逐句）：
        //       · 缩放目标 = 手牌缩放 × `VarsGlobal.cardInHandMovingScale(0x44) = 1.1`；
        //         玩家侧再 × `DAT_1834b3090 = 1.5`（**DLL 实读**）⇒ 1.65；敌方侧不乘 ⇒ 1.1。
        //       · 位移目标 = **当前位姿 + `Vector3.up` × 距离**
        //         （`DAT_1842da2a8` = `UnityEngine.Vector3` 的 Il2CppClass，`static_fields + 0x18` = `up`；
        //          类身份判据 → `资料/普查产出_1011/审查_W1.md:113`）：
        //         玩家 = **+4**（`DAT_1834b2df0`，DLL 实读）· 敌方 = **−12**（`DAT_1834b3160`，DLL 实读）。
        //       · 时长：玩家侧 `DOScale(0.12)` + `DOMove(延时 0.12、时长 timeToScaleIntoMoving(0x78)=0.1)`
        //         ⇒ 返回 0.22，再等 0.12 ⇒ **0.34 s**；敌方侧 `DOScale(0.12)` 与 `DOMove(0.12)` 同时起
        //         ⇒ 返回 0.12，再等 0.12 ⇒ **0.24 s**。
        //       · 缓动：`DOMove` = `SetEase(6)` = **OutQuad**；`DOScale` = `SetEase(12)` = **OutQuart**；
        //         `TurnCardAround` = `SetEase(1)` = Linear（0.12×0.25 = 0.03 s 转到 Euler(0,90,0)）。
        //   ⚠️ **如实记（两处没照抄）**：
        //     ① 玩家的 `TurnCardAround`（绕 Y 90°、0.03 s）没做 —— 我们的卡是 **2D billboard**
        //        （`CardView` 只有位置 + Z 倾角 + 缩放；绕 Y 转了会整张侧过去不可见）。缓存为「没做的那一半」。
        //     ② 敌方侧原版的 `−12` 落在**它自己的世界坐标**里；我们的手牌世界 y（`HandLayout.EnemyBaselineY=0.9102`
        //        → 世界 +4.1）加上 −12 会掉到屏幕外 ⇒ **敌方侧实际用屏幕中心（世界原点）**；
        //        玩家侧按原版 `+4` 算出来正好落在中心附近（≈ (0,+0.2)）⇒ 两侧视觉一致。
        //        （根因 = 我们对「敌方手牌的世界 y」和原版还有一段没对上的偏差 —— 记在报告里，不在本轮扩面。）
        // 🔴🆕 **2026-10-24（`A19` · `C1-A06`）就地订正（铁律 5）**：下面那两个倍率原来写反了。
        //   现读 `CardScript__ShowCardInCenter.c`（整段方法体）：
        //     · **两个分支都**先 `DOScale(手牌缩放 × cardInHandMovingScale(0x44 = 1.1), param)`；
        //     · **`isPlayer == true`（我方）** 那一支只有：`DORotate(Vector3.up, param × 0.5)` +
        //       `DOMove(当前位 + up × 4, param)` ⇒ **返回 param**（0.12）；
        //     · **`isPlayer == false`（敌方）** 那一支才是：**再 `DOScale(… × 1.5, param)`**
        //       （`DAT_1834b3090` = 1.5）· `TurnCardAround(param, param)` ·
        //       `DOMove(当前位 + up × −12, timeToScaleIntoMoving(0x78 = 0.1))` **且 `SetDelay(param)`**
        //       ⇒ **返回 `param + 0.1`**（0.22）。
        //   ⇒ 原来「玩家 ×1.65 / 敌方 ×1.1」「玩家 0.34 s / 敌方 0.24 s」**两边都反了**。
        //   ⚠️ 判据仍是 `isPlayer`（`dump.cs:21973` `EntityScript.<isPlayer>k__BackingField // 0x40`；
        //      它在 `+0x40` 已由 `CardScript__DrawCard.c:52-59` 那一族交叉印证）。
        const float AutoPlayCenterScaleMulPlayer = 1.1f;          // cardInHandMovingScale（两分支共用的那一档）
        const float AutoPlayCenterScaleMulFoe = 1.1f * 1.5f;      // 敌方支再 × DAT_1834b3090 = 1.5 ⇒ 1.65
        const float AutoPlayCenterScaleTime = 0.12f;              // ShowCardInCenter(param = stepTime)
        /// <summary>敌方支那条 `DOMove` 的**时长** = `VarsGlobal.timeToScaleIntoMoving` = **0.1**
        /// （`ShowCardInCenter` 里读的是 `globalVars + 0x78`，与 `DeploySequence.TimeToScaleIntoMoving` 同源）。
        /// ⚠️ 我方支的 `DOMove` 吃的是 `param`（0.12），**不是**这一个。</summary>
        const float AutoPlayCenterFoeMoveTime = 0.1f;
        const float AutoPlayCenterTailTime = 0.12f;               // `PlayPlayerCard/PlayEnemyCard` 的第二段等待 = param
        /// <summary>我方支那句 `DORotate(Vector3.up, param × 0.5)` 的终点 —— 原版把 `Vector3.up`
        /// 当**欧拉角**传给 `DORotate` ⇒ `Euler(0, 1, 0)` = **绕 Y 1°**。2D billboard 上看不出来，
        /// 但照抄（⛔ 别当成「我们加的观感」删掉，也别当成 90°）。</summary>
        static readonly Vector3 AutoPlayCenterPlayerRotEuler = new Vector3(0f, 1f, 0f);

        /// <summary>autoPlayFromHand 的「卡牌居中展示」半拍：缩放 + 移到中心，**结束后**才响
        /// `playMinionFromHand` 并把卡交给飞向格位那一段（判据见上面那一大段）。返回那条序列
        /// （自检经 <see cref="AutoPlayCenterDisplayDurationForTest"/> 量它的真实总时长）。</summary>
        Tween PlayAutoPlayCenterDisplay(Transform tr, int owner, Vector3 centerScale, System.Action then)
        {
            if (tr == null) { if (then != null) then(); return null; }
            // 中心点：玩家侧 = 原版「当前位姿 + up×4」（我们的世界原点就是屏心，算出来 ≈ 原点）；
            // 敌方侧 = 屏幕中心（原因见上面「如实记②」）。
            Vector3 center = LayoutSpace.ToWorld(0.5f, 0.5f);
            bool mine = owner == _me;
            // 🔴 2026-10-24（C1-A06）：**两条支的时序按 `ShowCardInCenter` 逐句复活**（原来两侧写反了
            //   —— 见上面那一大段常量的注释）。
            float param = AutoPlayCenterScaleTime;                       // 0.12
            float moveDelay = mine ? 0f : param;                         // 只有敌方支才有 `SetDelay(param)`
            float moveTime = mine ? param : AutoPlayCenterFoeMoveTime;   // 我方 0.12 · 敌方 0.1
            var seq = DOTween.Sequence();
            seq.Append(tr.DOScale(centerScale, param).SetEase(Ease.OutQuart));
            if (mine)
                // 我方支那一句 `DORotate`（见 `AutoPlayCenterPlayerRotEuler`）—— 只占 `param × 0.5`。
                seq.Join(tr.DORotate(AutoPlayCenterPlayerRotEuler, param * 0.5f));
            seq.Insert(moveDelay, tr.DOMove(center, moveTime).SetEase(Ease.OutQuad));
            // 收尾：`PlayPlayerCard/PlayEnemyCard` 在 `ShowCardInCenter` 返回之后再等一个 `param`
            // （= 原版 `MoveIntoFieldFromHand()` 之后那一次 `WaitForSeconds(param)`；我们这一步是
            //  `launch` 里的起飞 + `playMinionFromHand`，见调用点）。
            seq.AppendInterval(AutoPlayCenterTailTime);
            var tw = CardTween.Use(seq, Ease.Linear, tr);
            tw.OnComplete(() => { if (then != null) then(); });
            return tw;
        }

        /// <summary>🆕 **2026-10-24（`A19` · `C1-A06`）自检口**：把「居中展示」整套**真演一遍**并返回它的
        /// 总时长（秒）—— 判据是 `ShowCardInCenter` 返回值 + `PlayPlayerCard` 的第二段等待：
        /// 我方 **0.12 + 0.12 = 0.24** · 敌方 **0.22 + 0.12 = 0.34**。
        /// ⚠️ 造出来的那条序列**当场 Kill**（批处理 Manual 档不推它，但别留垃圾）。
        /// </summary>
        public float AutoPlayCenterDisplayDurationForTest(Transform tr, int owner, Vector3 centerScale)
        {
            var tw = PlayAutoPlayCenterDisplay(tr, owner, centerScale, null);
            if (tw == null) return -1f;
            float d = tw.Duration();
            tw.Kill();
            return d;
        }
        /// <summary>自检口：那一支的**居中缩放倍率**（我方 1.1 · 敌方 1.65 —— 判据见
        /// `AutoPlayCenterScaleMulPlayer/Foe` 上面那一大段）。</summary>
        public static float AutoPlayCenterScaleMulForTest(bool mine)
        {
            return mine ? AutoPlayCenterScaleMulPlayer : AutoPlayCenterScaleMulFoe;
        }

        // ==================================================================
        //  🆕 2026-10-19（`W57` · `T04` #1）「打出的卡 → 中央展示」+ **卡背翻面**
        // ==================================================================
        //  判据（`d:/2/tools/decomp_full/` 逐句 + `工具/read_literal.py` 从 DLL 实读常量）：
        //   · `CardScript._DisplayEnemyCardInCenter_d__263__MoveNext.c` —— 四段 state（0..3）；
        //   · `CardScript__DisplayEnemyCardInCenter.c` —— 闭包字段：`+0x20` = `showFront` ·
        //       `+0x30` = **翻面/缩放**时长 · `+0x34` = **停留**系数；
        //   · `CardScript__TurnCardAround.c` + `CardScript__FinishCardDrawRotation.c` —— **翻面**：
        //       第一段 `DORotate(90°, t×0.25, Fast + Ease.Linear)` →
        //       **OnComplete 里 `BattleCardUI.SetObjectVisibility(cardState)`** →
        //       第二段 `DORotate(0°, t×0.25, Fast + Ease.Linear)`；
        //   · 调用点 `CardScript._PlayEnemyCard/_PlayPlayerCard.c:36` —— **非单位卡**（`cardType != 0`）才走，
        //       `showFront = 0`；进之前把 `cardState` 置 **10**（`inHandPlaying`），而
        //       `BattleCardUI__SetObjectVisibility.c` 对 **state 10** 逐分支重放 = `SetCardVisibility(Front)`
        //       ⇒ **卡背 → 正面发生在「第一段 90°」的 OnComplete 那一刻**（侧立时换面、看不见）。
        //       ⚠️ 所以「一开始就露正面」是**错的** —— 前半拍（0.1 s 摆正 + 0.1 s 等 + 第一段 90°）都是**卡背**。
        //   · 常量实读：DOMove **0.15 s**（`DAT_1834b3178`）· 摆正 `DORotate(Vector3.zero)` **0.1 s** 且随后
        //       再等 **0.1 s**（同一个 `DAT_1834b2dc4`）· 停留 `hold × 0.66`（`_DAT_1834b3184`）·
        //       再等 `hold × 2.6`（`_DAT_1834b3190`）；
        //   · 缓动：`DOMove` / `DOScale` = `SetEase(3)` = **OutSine**；`DORotate` 未设（DOTween 默认）；
        //       翻面两段 = `SetEase(1)` = **Linear**；
        //   · `showFront = 1` 的唯一调用点 = `BattleManager._ResolveCreateHandCard_d__512__MoveNext.c:100`
        //       （造到手牌里的卡：开场 `SetCardVisibility(Front)`、**不翻面**、收尾 `SetCardVisibility(Back)`）。
        //
        //  ⚠️ **载体**：原版搬的是那张卡自己的 `BattleCardUI`（它从手牌位置飞出来）；我们这边敌方手牌是
        //     `ImageQuad` 卡背、我方手牌是 `CardView`、且**没有**每卡一份的 `CardStateOptions` 状态机
        //     ⇒ 这里**新建一张临时 `CardView`**（`CardFace.Hand`，与手牌同一套层），起点 = 那一侧手牌末位，
        //     卡背/正面切换直接走 `CardView.SetBackVisible`（= 原版 `Card2DController` 两颗 GameObject 的等价物）。
        //     ⚠️ 与手牌里那张视图**会重叠**（原版是搬本体、不复制）；手牌同步在同一个事件帧里会把原来那张收掉。
        //  ⚠️ state 2 的 `DisplayCreatedByText` —— 🔴 **2026-10-22（`W62/D5①`）订正**：原来这里写
        //     「`EvtKind.Play` 不带创建者 ⇒ 不画」，那是**把「事件里没有」当成了「原版没有」**。
        //     原版那一拍是真画的（state 10 档，只对手那张）；我们现在从 `Ctx.PlayedCards` 回查**那一次打出的
        //     实例**再把创建者传进来（`MaybeDisplayPlayedCardInCenter` 那一处）。`ToggleHighlight(false)` 同拍
        //     —— 临时卡本来就是 Normal。
        //  ⚠️ **不阻塞事件时间线**：原版外层 `PlayEnemyCard` 会 await 这条协程；我们的表现层是
        //     「事件到点各播各的」⇒ 本演出与后续事件**并行**（如实记，见报告 §三）。

        /// <summary>`_PlayEnemyCard/_PlayPlayerCard` 的参：**DOMove** 时长 —— `DAT_1834b3178` 实读 0.15。</summary>
        const float PlayedCardCenterMoveTime = 0.15f;
        /// <summary>state 0 的 `DORotate(Vector3.zero)` 时长 / 随后的 `WaitForSeconds` —— 同源 `DAT_1834b2dc4` = 0.1。</summary>
        const float PlayedCardCenterStraightenTime = 0.1f;
        /// <summary>state 1 之后的等待 = `hold × 0.66`（`_DAT_1834b3184` 实读）。</summary>
        const float PlayedCardCenterHoldMul = 0.66f;
        /// <summary>state 2 之后的等待 = `hold × 2.6`（`_DAT_1834b3190` 实读）。</summary>
        const float PlayedCardCenterWaitMul = 2.6f;
        /// <summary>`BattleManager.timeToPlayEnemyCard` = **0.12 s**（=`0.6 / 5`；判据 → `PlayAutoPlayCenterDisplay` 上面那段）。
        /// ⚠️ `PlayEnemyCard` 传给本方法的两个实参**不是同一个数**：翻面/缩放 = `0.12 × 0.6 = 0.072`、
        /// 停留 = `0.12`（`DAT_1834b3180` = 0.6 实读）。</summary>
        const float TimeToPlayEnemyCard = 0.12f;

        /// <summary>🆕 **2026-10-24（`A19` · `C1-A06`）**：`DisplayEnemyCardInCenter`（**非单位卡**那一支）
        /// 的居中**缩放** —— 它取的是 `CardScript.GetEnemyCardPlayedDisplayScale`
        /// （`globalVars+0x48`，带 `+0x11c` 开关时再 × `+0x4c`），**不是** `ShowCardInCenter` 用的
        /// `cardInHandMovingScale(0x44 = 1.1)` ⇒ **两套字段，别互相顶替**。
        /// <para>🔴 **2026-10-24（执行代理 `B1` · `C2` §7）就地订正（铁律 5）**：原文写「`+0x48/0x4c`
        /// 的原版值本轮没查」—— **不成立**（A19 那句也是错的）：那两个字段就是
        /// `VarsGlobal.enemyCardDisplayScale` / `enemyCardScaleMobileMultiplier`
        /// （`dump.cs:120074-120089` 字段表 · `工具/read_varsglobal.py` 实跑 **1.39999998 / 1.29999995**），
        /// `资料/VarsGlobal_原版数值.md` 第 14/15 行本来就有这两格。
        /// 改前沿用 `ShowCardInCenter` 借来的 1.1×1.5 / 1.1 —— 那是**两个字段被当成一个**。</para>
        /// <para>🔴 **量纲也一起改对了（C2 §7·3）**：原版 `GetEnemyCardPlayedDisplayScale` 的返回值是
        /// **绝对 `Vector3`**（`Vector3.one × globalVars[0x48]`，`Vector3.one` 取自
        /// `UnityEngine.Vector3` 静态块 `+0xc`），`DOScale` 的目标就是它本身；我们改前是
        /// **`手牌缩放 × 倍率`**（`startScale × 1.1` ≈ 0.594）⇒ 比原版小 2.36 倍，**光换常数不会对**。
        /// 现在 `DOScale` 的目标 = **绝对值**（× 窄屏补偿，见调用点）。</para>
        /// <para>⚠️ 这是**可见变化**（敌方打出的非单位卡会明显变大）⇒ 真机要复算一次。</para></summary>
        const float EnemyCardPlayedDisplayScale = 1.4f;
        /// <summary>见上：`globalVars+0x4c` = **1.3**，仅当 `+0x11c`（GraphicsTab 的「小屏」开关）打开时
        /// 再乘一次 ⇒ 小屏档合 **1.82**（判据 `CardScript__GetEnemyCardPlayedDisplayScale.c:53-61` 两支）。
        ///
        /// <para>🔴 **2026-10-24（执行代理 `D6` · 审查 `R1`-P1-2）就地订正（铁律 5）**：原文写
        /// 「**我们没有这个设置项**（`SettingsPanel` 里没有「小屏」那一行）⇒ 生产恒走自造的
        /// `SmallScreenToggle = false`」——**两句都不成立**：
        ///   · 这个设置项**有**：`Shell/SettingsWindow.cs:4411` 的 `Small Screen UI` 那一行 →
        ///     `ToggleSmallScreenUI()`（`:4572-4574` = 原版 `GraphicsTab.SmallScreenToggleClick` 的等价物）；
        ///   · 唯一来源 = **`CardPresentation.SmallScreenUI.Enabled`**（= 原版 `GameStaticData.smallScreenUI`
        ///     `+0x11c`，判据见本文件 `13447-13454` 那段）。自造的 `SmallScreenToggle`（恒 false、
        ///     **零接线**）**已删** —— 留着的后果是「玩家开了小屏 UI，这里仍按 1.4 算」，
        ///     而同文件的 `TutSmallScreenFactor` 那一格（`if (SmallScreenUI.Enabled) v *= …`）**跟着真开关走**
        ///     ⇒ 同一原版字段两条路、自相矛盾。
        /// ⇒ 现在只读 `SmallScreenUI.Enabled` 一条源，⛔ 别在别处再存一份。</para></summary>
        const float EnemyCardPlayedMobileMultiplier = 1.3f;

        /// <summary>自检用：居中展示的**绝对**缩放（原版 `GetEnemyCardPlayedDisplayScale` 的返回值）。
        /// 两档 = 1.4 / 1.4×1.3；开关读 **`SmallScreenUI.Enabled`**（唯一来源）。
        /// ⚠️ `Editor/BattleScene.cs:539-543` 在 `Run` 开头已把它压成「关」并在 `:39962-39969` 放回
        /// ⇒ 自检里默认那一档恒 1.4（要验 1.82 就照 `:31180-31187` 那个两态写法，**用完立刻放回**）。</summary>
        public static float PlayedCardCenterAbsoluteScaleForTest
        {
            get
            {
                return EnemyCardPlayedDisplayScale
                     * (SmallScreenUI.Enabled ? EnemyCardPlayedMobileMultiplier : 1f);
            }
        }

        /// <summary>🆕 **2026-10-25（执行代理 `C` · C1-③）**：自检用 —— 中央展示累计**建了几张**。
        /// <para>为什么要有它：卡片本体的生命周期归 DOTween 序列（演完 `Kill`）⇒ 事后读 `_playedCenterView`
        /// 必然是 `null`（Unity 对象被销毁）。「这一拍到底演没演、演的是哪一侧」只能靠这个计数 +
        /// <see cref="LastPlayedCenterOwnerForTest"/>。</para></summary>
        public int PlayedCenterDisplaysForTest { get; private set; }
        /// <summary>自检用：最近一次中央展示是**哪个座位**的（`-1` = 还没演过）。</summary>
        public int LastPlayedCenterOwnerForTest { get; private set; } = -1;
        /// <summary>自检用：**逐座位**的中央展示计数（按座位断言，别被同一趟里另一侧的一张挤掉）。</summary>
        readonly int[] _playedCenterBySeat = new int[2];
        /// <summary>自检用：某个座位累计建了几张中央展示卡（越界 ⇒ 0）。</summary>
        public int PlayedCenterDisplaysForSeatForTest(int seat)
            => seat >= 0 && seat < _playedCenterBySeat.Length ? _playedCenterBySeat[seat] : 0;
        /// <summary>自检用：当前那张中央展示卡（演完就 `null`，⛔ 别当成长期引用）。</summary>
        public CardView PlayedCenterViewForTest { get { return _playedCenterView; } }


        /// <summary>**「打出的卡 → 中央展示」**（原版 `CardScript._DisplayEnemyCardInCenter`，逐句见上面那一大段）。
        /// 返回载体（自检拿它验翻面时序：`BackVisible` 在**第一段 90° 结束那一刻**由 true 变 false）；
        /// 建不出来 ⇒ null（出声，⛔ 不静默）。
        /// <param name="scaleTime">原版 `param_2` = 翻面两段与 `DOScale` 的时长（`PlayEnemyCard` 传 `0.12 × 0.6`）。</param>
        /// <param name="hold">原版 `param_3` = 停留系数（`PlayEnemyCard` 传 `0.12`）。</param>
        /// <param name="showFront">原版 `param_4`：`true` = 开场强制露正面、**不翻面**、收尾翻回卡背（造牌入手的路）。</param>
        /// <param name="creator">🆕 **2026-10-22（`W62/D5①`）**：这张牌**是谁造出来的**（`null` = 不是造出来的）。
        /// 给了就在 state 2 那一拍点亮 `CreatedByText`（原版 `DisplayCreatedByText` 的 state 10 档；
        /// 那一档**只点亮对手那张** —— 本方法今天也只用于对手），state 3 再收起来。</param></summary>
        public CardView DisplayEnemyCardInCenter(CardData d, CardDef def, int owner,
                                                 bool showFront, float scaleTime, float hold,
                                                 CardDef creator = null)
        {
            if (string.IsNullOrEmpty(d.title) || hudRoot == null)
            {
                Debug.LogWarning("[Battle] 中央展示：缺卡面数据或 `hudRoot` ⇒ **没播**（不静默）");
                return null;
            }
            // ---- 载体：临时卡（手牌那一套层）----
            var v = CardView.Create(hudRoot, d, "CenterCard_" + (def != null ? def.Id : d.title),
                                    CardFace.Hand);
            if (v == null) return null;
            // 🆕 **2026-10-25（执行代理 `C` · C1-③）**：自检读数 —— 中央展示**建了几张**、最近一次**是谁的座位**。
            //   ⚠️ 卡片本体演完就被 DOTween 的 OnComplete `Kill` ⇒「事后读 `_playedCenterView`」读不到，
            //      「建过没有 / 哪一侧」只能靠这两个计数（⛔ 不是自证：计数器的唯一自增点就是这一句建卡）。
            PlayedCenterDisplaysForTest++;
            LastPlayedCenterOwnerForTest = owner;
            if (owner >= 0 && owner < _playedCenterBySeat.Length) _playedCenterBySeat[owner]++;
            // 🔴🆕 **2026-10-24（`W1` · AN1 `R1`）**：这张就是这一拍（`EvtKind.Play`）的 `thisCard`
            //   —— `PlaySignal` 的 `play` 桶要用它当锚点宿主（判据见 `MaybeDisplayPlayedCardInCenter` 开头那段）。
            //   ⚠️ 它会被下面那条 `tw.OnComplete(... Kill)` 收掉；`CardView` 是 Unity 对象 ⇒ 事后读它自然是 `null`。
            _playedCenterView = v;
            v.gameObject.SetActive(true);
            // 🆕 2026-10-23（D · `F6`）：**居中展示那一档 = 原版 `HandMoving` 排序层**
            //   （判据 `CardScript__ShowCardInCenter.c` → `SetSortingLayer(<HandMoving>)`）。
            //   我们的等价物 = `CardView.QHandMoving`（3001，手牌段顶号的上一格）——
            //   不抬这一格的话，「打出的牌在屏幕正中展示」会与手牌最上面那张**同号**
            //   （都是 3000）⇒ 谁压谁退回按距离，画面下方那排手牌可能盖住中间这张。
            v.SetQueue(CardView.QHandMoving);

            // 起点 = 那一侧手牌**末位**（原版从手牌里飞出来）；口径与抽牌落点同一个口（`HandRow01`）
            Vector2 start01 = HandRow01(owner == _me, 1);
            Vector3 startWorld = LayoutSpace.ToWorld(start01.x, start01.y);
            Vector3 centerWorld = LayoutSpace.ToWorld(0.5f, 0.5f);
            Vector3 startLocal = hudRoot.InverseTransformPoint(startWorld);
            Vector3 centerLocal = hudRoot.InverseTransformPoint(centerWorld);

            var hl = HandOf(owner);
            float startScale = (owner == _me
                                ? (hl != null ? hl.cardScale : HandLayout.DefaultCardScale)
                                : HandLayout.EnemyCardScale) * LayoutSpace.Scale;
            bool mine = owner == _me;
            // 🆕 2026-10-24（执行代理 `B1` · C2 §7·3）：**目标缩放 = 原版那个绝对值**（不是「手牌缩放 × 倍率」）。
            //   `× LayoutSpace.Scale` 只补偿「我们的世界 HUD 在窄屏整体缩」这一层（设计宽高比下 = 1，
            //   逐值等于原版的 1.4 / 1.82）；⛔ 别再乘手牌缩放（改前那样算出来敌方只有 0.594，比原版小 2.36 倍）。
            float centerScale = PlayedCardCenterAbsoluteScaleForTest * LayoutSpace.Scale;
            // ⚠️ `mine` 今天只可能来自自检（`MaybeDisplayPlayedCardInCenter` 对 `e.Player == _me` 早退）；
            //   原版我方那张走 `_DisplayOffensiveCardInCenter`，**同一个** `GetEnemyCardPlayedDisplayScale`
            //   （`CardScript._DisplayOffensiveCardInCenter_d__264__MoveNext.c:58`）⇒ 两档同一个数，不分敌我。

            v.SetPose(startLocal, 0f, startScale);
            v.SetHighlight(CardHighlightState.Normal);

            // ---- 卡背：敌方手里那张是背（`SetObjectVisibility(1)` 对 `isPlayer == 0` ⇒ Back）；
            //      我方自己的手牌是正面；`showFront` 那一支开场就正面（原版 `SetCardVisibility(Front)`）----
            var backTex = CardArt.CardBack(mine ? _myFaction : _foeFaction);
            bool startBack = !showFront && !mine;
            if (startBack) v.SetBackVisible(true, backTex);   // 缺图时 `CardView` 自己出声

            // ---- 时间线（逐段见方法头）----
            float flipHalf = scaleTime * CardFeel.TurnCardAroundFrac;   // 0.25 × param_2
            var seq = DOTween.Sequence();
            seq.Insert(0f, v.transform.DOLocalMove(centerLocal, PlayedCardCenterMoveTime).SetEase(Ease.OutSine));
            seq.Insert(0f, v.transform.DOLocalRotate(Vector3.zero, PlayedCardCenterStraightenTime));
            // state 1（t = 0.1）：翻面 + 缩放**同时起**
            if (!showFront)
            {
                var flip = DOTween.Sequence();
                flip.Append(v.transform.DORotate(new Vector3(0f, CardFeel.TurnCardAroundDeg, 0f),
                                                 flipHalf, RotateMode.Fast).SetEase(Ease.Linear));
                // 🔴 换面点 = 第一段 90° 的 OnComplete（原版 `FinishCardDrawRotation` → `SetObjectVisibility(10)`）
                flip.AppendCallback(() =>
                {
                    if (v == null || !startBack) return;
                    v.SetBackVisible(false, null);
                    Debug.Log("[Battle] 中央展示：翻到**正面**（原版第一段 90° 的 OnComplete → "
                            + "`SetObjectVisibility(10)` → `SetCardVisibility(Front)`）");
                });
                flip.Append(v.transform.DORotate(Vector3.zero, flipHalf, RotateMode.Fast).SetEase(Ease.Linear));
                seq.Insert(PlayedCardCenterStraightenTime, flip);
            }
            seq.Insert(PlayedCardCenterStraightenTime,
                       v.transform.DOScale(Vector3.one * centerScale, scaleTime).SetEase(Ease.OutSine));
            // state 2（t = 0.1 + 0.66·hold）：`DisplayCreatedByText` / `ToggleHighlight(false)` —— 见方法头「⚠️」
            // 🔴 **2026-10-22（`W62/D5①`）**：那一拍现在是**真的推**（原来「`Play` 事件不带创建者 ⇒ 不画」）。
            //   判据链：`CardScript._DisplayOffensiveCardInCenter_d__264__MoveNext.c:86-88` 在 state 2 调
            //   `BattleCardUI.DisplayCreatedByText(cardUI, cardState)`；`DisplayCreatedByText` 对 state 10
            //   **只点亮 `isPlayer == 0` 的那张**（`+0x40` 闸）⇒ 这里只有**对手**那张（`isLocalPlayer: false`），
            //   而本方法今天也**只**用于对手（`MaybeDisplayPlayedCardInCenter` 对 `e.Player == _me` 早退）。
            //   ⚠️ 内容 = 创建者那张卡（`Ctx.CreatedByOf`），`creator == null` 时这一段是空操作。
            float stateTwoAt = PlayedCardCenterStraightenTime + PlayedCardCenterHoldMul * hold;
            seq.InsertCallback(stateTwoAt, () =>
            {
                if (v == null || creator == null) return;
                v.SetCreatedBy(creator, CardView.CreatedByState.InHandPlaying, isLocalPlayer: false);
            });
            // state 3（t = 0.1 + 0.66·hold + 2.6·hold）：`showFront` 那一支翻回卡背，然后收摊
            float tailAt = PlayedCardCenterStraightenTime
                         + PlayedCardCenterHoldMul * hold + PlayedCardCenterWaitMul * hold;
            seq.InsertCallback(tailAt, () =>
            {
                if (v == null) return;
                if (showFront) v.SetBackVisible(true, backTex);   // 造牌入手的路：收尾 `SetCardVisibility(Back)`
                // 🔴 `W62/D5①`：原版 state 3 把 `CreatedByText` 节点 `SetActive(false)`
                //   （`_DisplayOffensiveCardInCenter…:79-80`）—— 那一段大图演完就收。
                // 🔴 **2026-10-24（`G9`，读法歧义）**：原来写成 `if (creator != null) v.SetCreatedBy(null);` ——
                //   守卫看的是**外层变量**（「有创建者才走到这一拍」），实参却恒为 `null`，档位又吃默认参
                //   `InHandShowing`（= *展示档*）⇒ 读代码的人会以为「传进去的是创建者」。原版这一拍就是
                //   把那行字收掉（`…MoveNext.c:79-80` 的 `SetActive(false)`）⇒ 显式写 `Hidden`
                //   （与 reveal 那边 state 2/3 同口径，见 `TickOffensiveReveal`）。
                // ⛔ `CreatedByState` 的**默认参**不许动（`CardBaseDemo` 有断言靠它）；改的是这一个调用点。
                if (creator != null)
                    v.SetCreatedBy(null, CardView.CreatedByState.Hidden, isLocalPlayer: false);
            });
            var tw = CardTween.Use(seq, Ease.Linear, v);
            tw.OnComplete(() =>
            {
                if (v == null) return;
                Kill(v.gameObject);
            });
            Debug.Log($"[Battle] 中央展示「{d.title}」：move 0.15s / 摆正 0.1s / 翻面 {flipHalf:F3}×2 / "
                    + $"缩放 {scaleTime:F3}s / 停留 {hold * PlayedCardCenterHoldMul:F3}s + {hold * PlayedCardCenterWaitMul:F3}s"
                    + $"（原版 `CardScript._DisplayEnemyCardInCenter`；showFront={showFront}）");
            return v;
        }

        /// <summary>🆕🔴 **2026-10-24（执行代理 `W1` · AN1 `R1`）：中央展示那张临时卡的引用。**
        /// <para>为什么需要它：**未指定目标的战术 / 防御卡**（`EvtKind.Play` 且 `Slot = -1`）在引擎里
        /// 不在任何格位上，可原版那一拍的 `thisCard` 就是**正在中间展示的这张卡**
        /// （`CardScript__PlayEnemyCard_d__258__MoveNext.c:22` 置状态 `10 inHandPlaying` →
        /// `CardScript__GetEffectAnchor.c:11-19` 对状态 10 取 2D 卡控制器那一级）。
        /// ⇒ 它的 `sp = 0/1/2` 三档要靠这张视图解析锚点（见 `PlaySignal` 的 `R1` 那一支）。</para>
        /// <para>⚠️ 只在 `animateFeel` 档存在（`MaybeDisplayPlayedCardInCenter` 建）；批处理 / 我方那一侧
        /// 恒 `null` ⇒ 由 `PlayPlacedOne` 降级到 `createCardPos(140)`（**我们挑的降级**，如实标）。</para>
        /// <para>⚠️ 生命周期归 `DisplayEnemyCardInCenter` 那条 `DOTween` 序列（演完 `Kill`）——
        /// ⛔ 别在这里 Destroy，也别当它是长期引用。</para></summary>
        CardView _playedCenterView;

        /// <summary>`EvtKind.Play` 那条事件到点时调一次：**非单位卡**才做中央展示（原版 `PlayEnemyCard` 里
        /// `cardType != 0` 才进 `DisplayEnemyCardInCenter`；单位卡走 `ShowCardInCenter`，我们那条在
        /// `PlayAutoPlayCenterDisplay`）。判据 → `DisplayEnemyCardInCenter` 的方法头。</summary>
        void MaybeDisplayPlayedCardInCenter(BattleEvent e)
        {
            // 🔴🆕 **2026-10-24（`W1` · AN1 `R1`）**：**中央展示那张临时卡就是这一拍的 `thisCard`** ——
            //   原版 `CardScript__PlayEnemyCard_d__258__MoveNext.c:22` 把卡状态置 `10 inHandPlaying` 之后，
            //   `AbilityLogic.GetPos` 的 `0/1/2` 三档取的都是 `GetEffectAnchor()`，而状态 10 那一支取的是
            //   **2D 卡控制器那一级**（`CardScript__GetEffectAnchor.c:11-19`）⇒ 就是这张正在中间展示的卡。
            //   ⇒ 记下来给 `PlaySignal` 的 `R1` 那一支当 `self`。⛔ 别另建一张（那就是两张卡了）。
            //   ⚠️ 每次进本方法先清 —— 上一局 / 上一张的那张过一会儿就被 `Kill` 了，留着是脏引用。
            _playedCenterView = null;
            if (e == null || e.Kind != EvtKind.Play || Ctx == null) return;
            // 🔴🆕 **2026-10-25（执行代理 `C` · 账 `RE1` §6 / `AN1` R1 的后续「无目标战术卡中央展示」）**：
            //   **我方那半也走中央展示**。判据 = 原版 `CardScript._PlayPlayerCard.c:36` 与 `_PlayEnemyCard`
            //   **是同一个调用**（`cardType != 0` ⇒ `DisplayEnemyCardInCenter`），两侧都演；
            //   原来这里 `if (e.Player == _me) return;` 把我方整条掐掉了（病灶已记在 `W1` 报告 §三）。
            //   ⚠️ **起点仍是「那一侧手牌末位」**（原版搬的是卡本体、不复制；我们建副本 ⇒ 我方手牌每张不同，
            //     从末位飞出会与那张牌的真实位置不符）—— 这是**我们挑的降级**，如实标；真机并排后再定要不要
            //     改成「拿那张手牌视图的当前位置」。
            //   ⚠️ **创建者文本只对手那侧点亮**（原版 `DisplayCreatedByText` 对 state 10 只点亮 `isPlayer == 0`
            //     那张）⇒ 我方 `creator: null`。
            var def = PlayedDefOf(e);
            if (def == null || def.IsUnit) return;      // 查不到（教程/自设计阵营）⇒ 不播（与 PlayBattleSfx 同一个口径）
            var d = ToCardData(def, def.Faction);
            bool mine = e.Player == _me;
            DisplayEnemyCardInCenter(d, def, e.Player, showFront: mine,
                                     TimeToPlayEnemyCard * 0.6f, TimeToPlayEnemyCard,   // `DAT_1834b3180` = 0.6
                                     creator: mine ? null : PlayedCreatorOf(e));
        }

        /// <summary>🆕 **2026-10-25（执行代理 `C`）**：这一条 `EvtKind.Play` 打出的**那张卡自己**
        /// （`CardDef`）—— 先按 `PlayedCards` 回查（同 <see cref="PlayedCreatorOf"/> 的走法、拿得到真正的
        /// **卡对象**，连跨阵营同名卡都不会认错），查不到才退回卡池按卡名 + **卡自己的阵营**查。
        /// ⛔ 别在调用点各写一份（`C5`：阵营要取拥有者那张卡的 `CardDef.Faction`）。</summary>
        CardDef PlayedDefOf(BattleEvent e)
        {
            if (Ctx == null || e == null) return null;
            for (int i = Ctx.PlayedCards.Count - 1; i >= 0; i--)
            {
                var pc = Ctx.PlayedCards[i];
                if (pc == null || pc.Instance == null || pc.Instance.Card == null) continue;
                if (pc.Owner != e.Player) continue;
                if (!string.Equals(pc.Instance.Card.Name, e.CardId, System.StringComparison.Ordinal)) continue;
                return pc.Instance.Card;
            }
            return _pool != null ? CardDatabase.Find(_pool, e.CardId, VfxFactionOf(e.Player, e.CardId)) : null;
        }


        /// <summary>🆕 2026-10-22（`W62/D5①`）：`EvtKind.Play` 那条事件里**没有实例号** ⇒ 按
        /// 「`Ctx.PlayedCards` 里**最后**一条 同主 / 同卡名 的记录」回查**那一次打出的实例**，再取它的创建者。
        /// <para>⚠️ 如实标着**这是一个回查**，不是原版的直接通道：原版 `CardScript` 自己带着 `createdBy`
        /// （`+0x268`）、协程直接读它。我们的 `BattleEvent` 今天不携带实例号（`Deploy` 带、`Play` 不带）——
        /// 更干净的做法是给 `Play` 事件补 `InstanceId`，那要动 `Emit` 的两个调用点，不在本笔白名单
        /// （`RuleEngine/RuleCore.cs` 只开到「造牌/解析来源」那几处）⇒ **记一笔，留待引擎线**。</para>
        /// <para>⚠️ 尾插序在 `PlayedCards` 上**单调**（`Seq` 只增）⇒ 「最后一条匹配」就是刚打出的那张；
        /// 同名两张连续打出的极端情形会指向后打的（对本层无差别：同名 = 同卡面）。</para></summary>
        CardDef PlayedCreatorOf(BattleEvent e)
        {
            if (Ctx == null || e == null) return null;
            for (int i = Ctx.PlayedCards.Count - 1; i >= 0; i--)
            {
                var pc = Ctx.PlayedCards[i];
                if (pc == null || pc.Instance == null || pc.Instance.Card == null) continue;
                if (pc.Owner != e.Player) continue;
                if (!string.Equals(pc.Instance.Card.Name, e.CardId, System.StringComparison.Ordinal)) continue;
                return Ctx.CreatedByOf(pc.Instance);
            }
            return null;
        }

        /// <summary>🆕 2026-10-19（B3 · 偏差 8）：**AI 飞行落地那一刻**的交接（两条载体共用一份）：
        /// 场上视图恢复显示、切回 3D 层、摆到 `PoseFor` 的位姿，然后播落地 cue 与登场特效。
        /// ⛔ 判据只此一处（手牌卡背 / 场上视图两条路都走这里）。</summary>
        void LandAiDeployFlight(CardView v, int key, BattleEvent evt, Vector3 finalLocal, float finalScale)
        {
            if (v != null)
            {
                RestoreBoardViewVisibility(key);   // 手牌载体那一路飞行期间是关的（关的是渲染器，不是 GameObject）
                if (use3DBoard) v.SetLayer(ArenaSlots.ArenaLayer);
                v.SetPose(finalLocal, 0f, finalScale);
                // 🆕 2026-10-19（T05 · `A2081`）：**飞行这段补间跑完了** ⇒ 现在才允许开「飞行单位」那套浮动
                //   （飞行期间 `SyncBoard` 的 `flyingNow` 分支把它压住了，见 `SyncUnitFlying` 的 doc）。
                int owner = key >> 8, slot = key & 0xFF;
                var unit = (Ctx != null && owner >= 0 && owner < Ctx.Players.Length && BoardSpec.IsValid(slot))
                         ? Ctx.Players[owner].Board[slot] : null;
                SyncUnitFlying(v, unit, finalLocal, false);
                // 🔴 2026-10-24（`A19` · `C1-B01`）：落地 = 登场演出收口（原版 `MinionPlayedIntoField`
                //   state 4 → `ActivateMinion`）⇒ **绿光这一刻才按引擎真值点亮**。
                //   ⚠️ 调用点必须在 `_aiDeployFlying` 已经摘掉之后（`StartAiDeployFlight` 的落地回调先摘账
                //   再调本方法）—— 否则 `SyncBoard` 那道的闸仍会把它压掉。
                RefreshCanActForView(v);
            }
            // 偏差 9：**落地**那两条 cue（原版 `CardScript.LandOnGround` 那一拍）
            PlayDeployLandingCues(evt);
            // 偏差 8：**落地的手感与登场特效**也都在这一拍 —— 它们在 `PlaySignal` 里
            //   因为「这是起飞拍」被跳过了（见那几处的 `_aiDeployFlights` 守卫）。
            PlayAiDeployLandingVfx(evt);
            _aiDeployLandingCue.Remove(key);
        }

        /// <summary>🆕 2026-10-19（B3 · 偏差 8 的载体）：**只开关渲染器**（⛔ 不关 GameObject）。
        /// 理由：飞行那 0.65 s 里 `SyncBoard` 仍会对这张视图 `SetData`，而 TMP 在**未激活**对象上
        /// `ForceMeshUpdate` 量不出尺寸（本仓已知坑，见 `CLAUDE.md`「面板画出来了、字不在」三条）。
        /// 关渲染器 = 画面看不见、GameObject 仍激活 ⇒ 两边都对。
        ///
        /// 🔴 **必须逐件记原值再还原**：`CardView` 里有几处是**故意**把某个渲染器关着的
        /// （rim 在 α=0 时 `CardView.cs:5023/5033/5039`、临时层 `:5769`、若干 `Show()` 的反面），
        /// 一律 `enabled = true` 会把它们**重新点亮**（静默画错）⇒ 快照见
        /// <see cref="_aiDeployHiddenRenderers"/>，落地逐件还原。</summary>
        void HideBoardViewForFlight(int key, CardView v)
        {
            var list = new List<KeyValuePair<Renderer, bool>>();
            var rs = v.gameObject.GetComponentsInChildren<Renderer>(true);
            for (int i = 0; i < rs.Length; i++)
            {
                if (rs[i] == null) continue;
                list.Add(new KeyValuePair<Renderer, bool>(rs[i], rs[i].enabled));
                rs[i].enabled = false;
            }
            _aiDeployHiddenRenderers[key] = list;
        }

        /// <summary>🆕 同 `HideBoardViewForFlight`：飞行期间 `SyncBoard` 可能**懒建**新渲染器
        /// （`TraitFrames.Attach` / `SetData` 那些层），它们默认开着 ⇒ 每帧再压一次。</summary>
        void ReHideNewRenderers(int key, CardView v)
        {
            List<KeyValuePair<Renderer, bool>> list;
            if (!_aiDeployHiddenRenderers.TryGetValue(key, out list) || list == null) return;
            var rs = v.gameObject.GetComponentsInChildren<Renderer>(true);
            for (int i = 0; i < rs.Length; i++)
            {
                var r = rs[i];
                if (r == null) continue;
                bool known = false;
                for (int j = 0; j < list.Count; j++) if (list[j].Key == r) { known = true; break; }
                if (!known) list.Add(new KeyValuePair<Renderer, bool>(r, r.enabled));   // 新层：默认开
                r.enabled = false;
            }
        }

        /// <summary>落地 / 跨局 / 丢事件：把飞行期间关掉的渲染器**逐件还原到它原来的开关状态**。</summary>
        void RestoreBoardViewVisibility(int key)
        {
            List<KeyValuePair<Renderer, bool>> list;
            if (!_aiDeployHiddenRenderers.TryGetValue(key, out list)) return;
            _aiDeployHiddenRenderers.Remove(key);
            if (list == null) return;
            for (int i = 0; i < list.Count; i++)
                if (list[i].Key != null) list[i].Key.enabled = list[i].Value;
        }

        /// <summary>全部还原（跨局 / `DropSignals` 那种「整批不要了」的收尾）。</summary>
        void RestoreAllBoardViewVisibility()
        {
            foreach (var kv in _aiDeployHiddenRenderers)
            {
                var list = kv.Value;
                if (list == null) continue;
                for (int i = 0; i < list.Count; i++)
                    if (list[i].Key != null) list[i].Key.enabled = list[i].Value;
            }
            _aiDeployHiddenRenderers.Clear();
        }

        void SyncBoard(int owner, Dictionary<int, CardView> views, bool mine)
        {
            var board = Ctx.Players[owner].Board;
            var layout = mine ? playerBoard : enemyBoard;
            var byUnit = UnitViewMap(owner);
            // ⚠️ 原来这里是「是不是 Tide，不是就是 Ember」的二选一 —— 一接原版阵营就会
            //    全部掉进 Ember 那个色。改成查表（`FactionColor`）。
            var frame = FactionColor(owner == _me ? _myFaction : _foeFaction);

            for (int s = 0; s < BoardSpec.Size; s++)
            {
                var u = board[s];
                CardView v = null;
                bool hasView = false;
                bool created = false;      // 🆕 B2：这一格这次是**新建**的视图（偏差 8 的 AI 飞行只挂在新建那一档）

                // 🆕 2026-10-19（偏差 1 的残余④）：**这一格刚上场、`Deploy` 还没演到 ⇒ 先不建视图**
                //   （原版是动作队列演到那一步才 `MinionPlayedIntoField` 把卡建出来）。
                //   ⚠️ **只压「没有视图」的那一档** —— 玩家自己打出的单位在 `DoPlay` 里已经搬好视图了，
                //   那一路必须照常同步（否则它会停在半初始化状态）。
                if (u != null && IsPendingDeploy(owner, s, u))
                {
                    CardView existing;
                    if (!(byUnit.TryGetValue(u, out existing) && existing != null))
                    {
                        CardView stale;
                        if (views.TryGetValue(s, out stale) && stale != null
                            && !ViewOwnedByLiveUnit(board, byUnit, stale))
                            DetachStaleView(owner, views, s, stale);
                        continue;
                    }
                }

                if (u != null)
                {
                    // ① **先按身份找它的视图**（换格 / 刚上场都走这一条）。
                    //    ⚠️ Unity 的 `!= null` 判的是「对象还在不在」，销毁过的视图这里会回落成 false。
                    CardView byId;
                    if (byUnit.TryGetValue(u, out byId) && byId != null) { v = byId; hasView = true; }
                    else if (views.TryGetValue(s, out byId) && byId != null
                             && !ViewOwnedByLiveUnit(board, byUnit, byId))
                    {
                        // ② 退路：这一格的键上挂着一张**主人已经不在场上了**的视图 —— 认领它。
                        //    两个常见来源：**首次同步**（还没登记身份），以及 🔴 **变残骸**
                        //    （原版是「同一张卡翻个面」⇒ 引擎那边是个**新的 `UnitState`**，
                        //     身份表里查不到它，但视图必须是原来那张 ⇒ 这里正好接住）。
                        v = byId; hasView = true;
                    }
                }
                else
                {
                    views.TryGetValue(s, out v);      // 可能为 null（已销毁）
                }

                if (u == null)
                {
                    // 🆕 2026-10-19（战斗线 W 第 1 条）：这一格空了 ⇒ 账上那一笔**作废**
                    //   （阵亡单位不打账；这一句防的是「单位挪走/换人」时把旧账留给下一个主人）。
                    // 🔴 B5：账按**实例**记 ⇒ 不能只删格号那条 —— `DropPendingHpForSlot` 会
                    //   ① 人不在场 ⇒ 作废 ② 人挪到别的格 ⇒ 把那一笔挂到新格的 FIFO 上（旧事件格仍销得掉）。
                    DropPendingHpForSlot(owner, s);
                    // 🆕 2026-10-19（B1 · 残余④）：登场账同理 —— 那一位还没露脸就走了 ⇒ 这一笔作废
                    //   （不清的话，以后同一格上场的单位会**一直不建视图**）。
                    _pendingDeploy.Remove(HpKey(owner, s));
                    _pendingDeployByName.Remove(HpKey(owner, s));   // 🆕 B6：名字那条退路同理
                    // 🆕 2026-10-19（B2）：AI 飞行那两笔同理（不清 ⇒ 同一格的下一张牌会**接着上一张的票**飞，
                    //   而且落地 cue 会被误吞）。
                    _aiDeployFlights.Remove(HpKey(owner, s));
                    _aiDeployLandingCue.Remove(HpKey(owner, s));
                    _aiDeployFlying.Remove(HpKey(owner, s));
                    // 🆕 B3：这一格空了 ⇒ 手牌卡背那张载体也作废（它的落地回调会自己 Kill；
                    //   这里只摘账，不动正在飞的补间 —— 半路销毁会让画面「啪」地消失）。
                    _aiDeployFlyingHand.Remove(HpKey(owner, s));
                    _aiDeployHandedOff.Remove(HpKey(owner, s));   // 🆕 W57：同上（交接标记跟着格位作废）
                    RestoreBoardViewVisibility(HpKey(owner, s));
                    if (v == null) { views.Remove(s); continue; }
                    // 🆕 2026-09-26：这一格空了 ⇒ 「未行动」绿光也要灭。
                    //   ⚠️ **必须在这里关**：下面那条 `continue`（阵亡事件还排在时间线上、视图要再站 0.85 s）
                    //      —— 不关的话那张正在消散的卡会**一直亮着绿光**。
                    v.SetCanAct(false);
                    // ⚠️ **这一格刚空、但离场演出还排在时间线上时，先别销毁。**
                    //    `PlaySignals` 只**排期**、不当场播（见 `EventTiming`）—— 引擎里人已经死了，
                    //    而画面上那张卡还要再站 0.85 s 才轮到「阵亡」那一刻。
                    //    第一版就是在这里立刻销毁的：`DyingCount` 恒为 0、消散一帧都没演出来，
                    //    而**截图上看不出**（只看到「人没了」）。
                    if (animateFeel && PendingExitFor(owner, s)) continue;

                    Kill(v.gameObject); views.Remove(s);
                    continue;
                }

                // 🔴 **2026-10-01：这个单位换格号了吗**（棋盘是连续无洞的 —— 它前面插了人 / 补位，
                //    见 `RuleEngine/Core/BoardSlots.cs`）。按**身份**把视图从旧格号搬到新格号，
                //    千万别当「这格空了」销毁重建 —— 重建会瞬移、丢动画、丢关键词框/残骸体那些
                //    挂在视图上的状态。判据 = `byUnit`（单位 → 视图）。
                //
                //    ⚠️ **补位会把「上一任」的键顶掉**：那一格里原来那张卡（已经离场、演出还排在队里）
                //       必须**先摘下来存到 `_fading`**，否则 0.85 s 后演阵亡时 `views[slot]` 已经是
                //       新主人了 —— 会把**一张活着的卡**溶掉（`PlayDeathFeel` 从那一档里找）。
                bool moved = false;
                if (hasView)
                {
                    CardView at;
                    if (views.TryGetValue(s, out at) && at != null && at != v
                        && !ViewOwnedByLiveUnit(board, byUnit, at))
                        DetachStaleView(owner, views, s, at);

                    RemoveSlotKeysExcept(views, v, s);
                    if (!views.ContainsKey(s) || views[s] != v) { views[s] = v; moved = true; }
                    // 掉血/疲劳/关键词要反映到卡面（原来这段挂在「这一格本来就有视图」那一支）
                    // 🆕 2026-10-19（战斗线 W 第 1 条）：走 `ToBoardCardData` —— 它会把这轮
                    //   「引擎已扣、还没演到」的血量加回去（= 显示旧血），事件轮到播时才真跳。
                    v.SetData(ToBoardCardData(u, owner, s));
                }
                else
                {
                    // 这一格的键上要是还挂着**已经不在场上的**视图 ⇒ 先摘掉，别让它变幽灵
                    CardView at;
                    if (views.TryGetValue(s, out at) && at != null
                        && !ViewOwnedByLiveUnit(board, byUnit, at))
                        DetachStaleView(owner, views, s, at);

                    var data = ToBoardCardData(u, owner, s);
                    data.frame = u.IsWarlord ? new Color(0.95f, 0.82f, 0.35f) : frame;   // 督军描金
                    // 🔴 **场上用 `CardFace.Board`**：原版在 inPlay 类状态把**整张 `2DCard` 关掉**
                    //    （`Card2DController.Toggle(false)`），只留 `Board Elements` 那棵子树 ——
                    //    插图/卡框/费用/稀有度宝石/卡名/阵营行/兵种行/效果底板/效果文字**一起没有**，
                    //    只剩攻/血/甲 + 7 槽关键词徽标。见 `CardFace` 的注释与出处。
                    v = CardView.Create(boardRoot, data, $"{(mine ? "My" : "Foe")}Unit_{s}_{u.Name}",
                                        CardFace.Board);
                    views[s] = v;
                    byUnit[u] = v;      // 🆕 2026-10-01：登记身份（上面那段换格靠它认人）
                    created = true;

                    // 🆕 2026-09-29 **督军落场：整组徽标 0 → 1 淡回来**
                    // （原版 `CardScript.<HeroLandIntoField>` 里那句 `FadeAllTraitsIcons(1.0f, 0.3f)`
                    //  —— 那也是全量反编译里 `FadeAllTraitsIcons` 唯一的调用点）。
                    // ⚠️ **只在开了手感补间时演**（和这一节别的动作同一条规矩）：批处理没有帧循环，
                    //    演到一半会停在 α=0 ⇒ 截图里督军的徽标整个不见（而断言看不出来）。
                    if (animateFeel && u.IsWarlord)
                    {
                        v.SetBadgeAlpha(0f);
                        v.FadeBadges(CardFeel.HeroLandBadgeAlpha, CardFeel.HeroLandBadgeFadeTime);
                    }
                }

                Vector3 pose;
                float poseScale;
                PoseFor(mine, s, u, out pose, out poseScale);
                // 🆕 2026-10-19（B2 · 偏差 8）：**这一格正在飞** ⇒ 层与位姿都由那段补间管，
                //   这里**一个都不许碰**（否则外层 `RefreshAll` 紧接着的这次 `SyncBoard` 会把卡
                //   一帧拉回终点 —— 飞行等于白演，而画面「确实动过」，最容易骗过断言）。
                bool flyingNow = IsAiDeployFlying(owner, s, v);
                if (!flyingNow && use3DBoard) v.SetLayer(ArenaSlots.ArenaLayer);   // 换 layer：改由透视相机画

                // 🔴 2026-10-01：**换格 = 补一次位移补间**（原版 `ReassembleMinions` →
                //    `CardScript.UpdateMinionInPlayPosition` 就是一句 `DOLocalMove(新位, 时长)`）。
                //    时长 = `minionReassembleTime (0.15) ÷ 1.5 = 0.1 s`（见 `CardFeel.Reassemble`）。
                //    ⚠️ 批处理里 `animateFeel` 是关的 ⇒ 必须**落位**（断言要的是精确坐标）。
                // 🆕 2026-10-19（B2 · 偏差 8）：**AI 从手牌打出的那一张** ⇒ 走原版那条四段飞行
                //   （起点 = 敌方手牌那张牌的位置/角度/缩放，终点 = `PoseFor` 算出的格位位姿）。
                //   ⚠️ 只挂**新建**那一档（`created`）：换格 / 已有视图不重演。
                // 🆕 2026-10-19（B2 · 偏差 8）：**这一格这次没走「新建」⇒ 飞行演不了**（视图本来就在）
                //   ⇒ 票作废。不删的话它会一直挂着：`PlayBattleSfx(Deploy)` 以后每次都会把那一格的
                //   四条 cue 全跳过（静默丢音）。
                if (!created && _aiDeployFlights.ContainsKey(HpKey(owner, s)))
                {
                    _aiDeployFlights.Remove(HpKey(owner, s));
                    _aiDeployLandingCue.Remove(HpKey(owner, s));
                }
                AiPlayTicket aiTicket = default(AiPlayTicket);
                bool flightTicket = created && _aiDeployFlights.TryGetValue(HpKey(owner, s), out aiTicket);
                if (flyingNow)
                {
                    // 飞行中：什么都不做（补间自己在推）。
                    // 🆕 B3：手牌卡背那一路还要**再关一次渲染器** —— 上面这几句（`TraitFrames.Attach` /
                    //   `SetRemnantBody` / `SetData`）可能**懒建**出新的渲染器，它们默认是开着的。
                    if (_aiDeployFlyingHand.ContainsKey(HpKey(owner, s))
                        && !_aiDeployHandedOff.Contains(HpKey(owner, s)))
                        ReHideNewRenderers(HpKey(owner, s), v);
                }
                else if (flightTicket)
                {
                    _aiDeployFlights.Remove(HpKey(owner, s));
                    StartAiDeployFlight(v, owner, s, aiTicket, pose, poseScale);
                }
                else if (moved && animateFeel) CardFeel.Reassemble(v, pose);
                else v.SetPose(pose, 0f, poseScale);
                v.SetHighlight(CardHighlightState.Normal);

                // 🆕 2026-10-19（T05 · `A2081`）：**飞行单位抬到空中 + 上下浮动** —— 就在摆完位之后
                //   接一句「这张卡现在该不该飞」。判据/参数 → `Battle/FlyingCardController.cs` 文件头。
                //   ⚠️ `flyingNow`（AI 出牌那段飞行补间）期间**不许开** —— 两套位移会抢同一个 `localPosition`。
                SyncUnitFlying(v, u, pose, flyingNow);

                // 🆕 2026-09-29：**状态框**（原版 `BattleCardUI` 的两本字典那一套；
                //   判据全文 → `Core/TraitFrames.cs` 的文件头）。原版挂在 `CardScript.AddEffect`
                //   那几个分支上（trait 被加上那一刻），我们引擎不发那个事件 ⇒ 在这里**按集合对差**
                //   （`RefreshAll` 就在动作结算之后跑，时机与原版一致）。
                var tf = TraitFrames.Attach(v);
                if (tf != null && u != null) tf.SyncKeywords(u.Keywords.Keys);

                // 🆕 2026-09-25：**残骸体**（原版 `RemnantBody3D <阵营>`）——
                //   灵族 = 一枚漂浮的灵魂石（`Spirit Stone Idle`）· 死灵 = 一张碎裂的卡（`Card Remnant`）。
                //   ⚠️ 必须排在 `SetData` **之后**：`SetData`/`SetFace` 会按形态开关各层，
                //      先盖残骸体再 `SetData` 的话，原卡卡身会被它重新打开。
                //   ⚠️ 撤销那一路只在**确实还挂着**时才调（不然每帧对每张卡白跑一遍开关）。
                string remPrefab = RemnantPrefabOf(u);
                if (remPrefab != null) v.SetRemnantBody(true, remPrefab);
                else if (v.RemnantBodyVisible) v.SetRemnantBody(false, null);

                // 🆕 2026-09-26：**「未行动」绿光**（原版 `CardScript.ActivateMinion` → `SetActive(CanAttackNow())`
                //    → `BattleCardUI.canAttackAnim`，偏移 `+0x140`）。
                //   🔴 **判据只写一份** = `RuleCore.CanActNow`（它和 `DeclareAttack` 共用同一段检查）；
                //      这里**只问「画不画」**，别在这儿重写疲劳/眩晕/配额那几条。
                //   ⚠️ 问的是「**至少有一种打法**能打」—— 压制（`pindown`）只禁近战，
                //      所以近战/远程各问一次（`CanActNow` 内部就是这两问）。
                //   ⚠️ 挂在这里（`SyncBoard`）是因为**每一个改动棋盘/回合的地方最后都会走到它**
                //      —— 和光环那 9 个写入点 + `BeginTurn` 是同一条纪律。
                bool canAct = RuleCore.CanActNow(Ctx, owner, s);

                // 🆕 2026-10-22（「出牌后绿光整回合不亮」的**结构兜底**）：**场上视图停在非场上形态**
                //   ⇒ 补一次换体。根因那一半（请求不再丢）在 `CardView.SetCanAct`；正常路径由登场 clip
                //   在 **0.7 s** 的 `SetFace(CardFace.Board)` 收口（`CardFeel.cs:1351-1357`）。
                //   这一条防的是「clip 被杀 / 没起播」⇒ 那张卡**永久**停在 `Hand` 形态
                //   （绿光整局不亮 + 2D 卡面盖在场上，两样都静默）。
                //   ⚠️ 判据**刻意排除 `_handToBoardCard`**（clip 正在演的那一张 —— 形态归 clip 在 0.7 切，
                //      `EnterBoardBody` 对那张只换父节点，见 `:9977-9981`），否则会在 0.3~1.0 s 之间
                //      把登场演出硬切掉（正是对账 §2·1 #2 那条）。
                //   ⚠️ `EnterBoardBody` 幂等（`SetFace` 同形态首句早退、`SetParent` 同父是空操作）⇒ 安全；
                //      出生入口（`:18595` 直接按 `CardFace.Board` 建）与 AI 飞行视图都不会走到这里。
                if (v.Face != CardFace.Board && v != _handToBoardCard)
                {
                    Debug.LogWarning($"[BattleDriver] 场上视图停在 `{v.Face}` 形态（turn {Ctx.Turn} "
                                   + $"seat {owner} slot {s}，`{u.Name}`）⇒ 补一次 `EnterBoardBody`"
                                   + "（登场 clip 没跑到 0.7 s？）");
                    EnterBoardBody(v);
                }

                // 🔴🆕 **2026-10-24（`A19` · `C1-B01`）：舞台上的登场演出期间，绿光一律不亮。**
                //   原版整个「打出 → 落场」链里，可行动高亮**只在最后一句**被决定：
                //   `MinionPlayedIntoField` 的 **state 4**（4 段等待 + 补间全跑完）→
                //   `UpdateSummonSicknessAnims` → `ActivateMinion` → `SetActive(canAttackAnim, CanAttackNow())`
                //   （`CardScript._MinionPlayedIntoField_d__314__MoveNext.c:155-181`；
                //    闸在 `CardScript__ActivateMinion.c:19-25,82-90`）。state 0..3 期间**一次都不点亮**。
                //   ⇒ 我们这两条载体（玩家拖拽 = `_handToBoardCard`；AI/远端 = `_aiDeployFlying`）
                //     在演出期间把请求压成 false；演完各自调 `RefreshCanActForView` 补一次。
                //   ⚠️ 不压的话有两个静默错误：
                //     ① `CardFeel.HandToBoard` 开场借 `SetFace(Board)` 把绿光层建出来、再 `SetFace(Hand)`
                //        退回（`CardFeel.cs:1922-1926`）—— `_canActWanted` 若已是 true，那一瞬就点亮，
                //        而且退回手牌形态时 `ApplyCanAct` **不会把它关掉**（`CardView.cs:1807-1815`）
                //        ⇒ **飞行途中整段亮着**；
                //     ② AI 那条：视图一建出来就是场上形态，不压就**从飞行起点亮到落地**。
                bool inDeployPerf = (v == _handToBoardCard) || IsAiDeployFlying(owner, s, v);
                v.SetCanAct(canAct && !inDeployPerf);

                // 🔧 临时诊断探针（2026-10-22）—— **只在 `WF_CANACT_PROBE=1` 时打印**，零行为变化。
                //   用途 = 判真机「场上单位底座看不到绿光」到底是哪一档：
                //     ① `can=0` ⇒ **单位真的不能行动**（`CanActNow` 的疲劳/眩晕/配额那几条里有一条没过）；
                //     ② `can=1 built=1 vis=1` 但 `playing=0` ⇒ **能行动、粒子没循环**（`CardView.BuildCanAct`
                //        那套 `looping=false` + `ringBufferMode=Loop range(0.1,0.9)` 的问题）；
                //     ③ `can=1 built=1 vis=1 playing=1` ⇒ 视图与粒子都对 ⇒ 往渲染层找（队列/相机/材质）。
                //   🔴 判据 = 原版 `CardScript.ActivateMinion` → `BattleCardUI.canAttackAnim`
                //      （就是上面 `SetCanAct` 那一段注释所复刻的东西；粒子 = 原版 `CanActParticles`
                //      + 子节点 `RotatingRing`，参数注释在 `Core/CardView.cs`）。
                //   ⛔ 只读：不 `Play`/`Stop`/`Emit`/`Clear`，不改粒子参数、不改 `SetCanAct` 语义。
                CanActProbe(owner, s, u, v, canAct);

                // 🆕 2026-10-14（`A1863`）：**伏击「面朝下」**（原版 `CardScript.SetAmbush(card, true)`）。
                //   · 判据 = **引擎那一格上的事实** `UnitState.FaceDown`（⛔ 不在这里另算一遍
                //     「是不是伏击」—— 那是 `RuleCore.PlaysFaceDown` 的事，见 `RuleCore.cs:2443`）。
                //   · 第二个参数 = 原版那道 `isPlayer == 0` 闸（`CardScript__SetAmbush.c:22`，
                //     偏移坐实于 `dump.cs` 的 `EntityScript.<isPlayer>k__BackingField // 0x40`）：
                //     **只有对面那一方**面朝下的单位才藏数值；自己那张，主人看得见自己的数值。
                //   · 🔴 **挂在这里的理由**：这是 `u != null` 那一段的**唯一收口处** ——
                //     视图是**新建的**还是**换格搬过来的**都从这里过，`SetAmbush` 又会把状态存进
                //     `CardView`、在 `SetData`/`SetFace` 末尾各重放一次 ⇒ 三个入口全覆盖
                //     （CLAUDE.md 铁律 10 第 5 条：多入口的场景分层要在每个入口显式设）。
                //   · ⚠️ **排在 `SetCanAct` 之后、`SetQueue` 之前**：`SetQueue` 要落在这一格所有动作
                //     的最后（它扫整棵子树盖章，见它上面那段注释）；本方法**不新建任何子物体**
                //     （只开关已有层 + 换贴图），所以放它前面不破坏那条纪律。
                v.SetAmbush(u.FaceDown, hideStats: u.FaceDown && !mine);

                // 🆕 2026-10-12（`A1672`）：**这一格上的卡占一段渲染队列**。
                //   号源 = `BoardLayout.QueueOf(格号)`（⛔ 别在这儿另算一套号），机制 = `CardView.SetQueue`
                //   （与**手牌那半同一套**：`HandLayout.Refresh` 里 `c.SetQueue(queueTop − top)`）。
                // 🔴 **排在这一格所有动作的【最后】**：上面那几件（`TraitFrames.Attach` / `SetRemnantBody` /
                //   `SetCanAct`）都会往这张卡下面**新挂子物体**，而 `SetQueue` 扫的是**整棵子树**
                //   ⇒ 排在最后才能把它们一起盖章。（再往后懒建的层由 `CardView` 建层当场按 `_queue` 自盖 ——
                //   `AddLayer` / 徽标 / 数值层 / TMP 那几处都有 `StampQueue`，见 `CardView.cs`。）
                // ⚠️ **漏盖章的层会停在默认 3000** —— 那比场上任何一格的号都大 ⇒ 它会**穿过**邻居的卡，
                //   正是 `A1665` 报的「多张卡堆叠时上面的文本互相透出」。所以这一句不能少。
                // ⚠️ **两条路都要盖**（`use3DBoard` 与否）：2D 那条路九格 z 恒 0（全共面、距离排序退化成
                //   不确定），3D 那条路虽然靠距离已经确定性排好，但**演出期卡会离开格位**（出牌飞行 /
                //   让位滑动 / 阵亡），那时也是真重叠 ⇒ 两边都用同一段号把次序写死。
                v.SetQueue(layout.QueueOf(s));

                // 🆕 2026-10-20（W58 · BTFIX4 · `B3·偏差8`）：**手牌卡背在飞**的那一档，在这一格**收口处再压一次渲染器**。
                //   上面那次 `ReHideNewRenderers`（`flyingNow` 支）排在 `SyncUnitFlying` / `SetHighlight` /
                //   `TraitFrames.Attach + SyncKeywords` / `SetRemnantBody` / `SetCanAct` / `SetAmbush` / `SetQueue`
                //   **之前** —— 这几件都可能**懒建**新渲染器（`TraitFrames.SyncKeywords` 还会 `Play` 一段特效），
                //   它们默认 `enabled = true` ⇒ `AiDeployBoardViewHiddenForTest`（判据 = 整棵子树一个 enabled
                //   渲染器都没有）当场红（`battle5.log:95140`）。`RestoreBoardViewVisibility` 逐件还原的是
                //   **登记那一刻**的原值 ⇒ 同一帧压两次是安全的（第二次只新增「没登记过」的那几件）。
                //   ⚠️ 条件与 `flyingNow` 支同一份判据（`_aiDeployFlyingHand` + 未交接），⛔ 别另写一版。
                if (_aiDeployFlyingHand.ContainsKey(HpKey(owner, s))
                    && !_aiDeployHandedOff.Contains(HpKey(owner, s)))
                    ReHideNewRenderers(HpKey(owner, s), v);
            }
        }

        /// <summary>🆕 **2026-10-24（`A19` · `C1-B01`）**：登场演出**结束那一拍**把绿光按引擎真值补推一次。
        ///
        /// <para>为什么必须有它：`SyncBoard` 在演出期间把请求压成 `false`（见那里的注释），
        /// 而 `SyncBoard` **不是逐帧跑**（只在引擎事件上跑）⇒ 演完不会有人再来推第二次
        /// ⇒ 不补就是「这一整回合绿光不亮」（2026-10-22 那条缺陷的翻版，静默）。</para>
        ///
        /// <para>**判据** = 原版 `MinionPlayedIntoField` **state 4** 那一句
        /// `ActivateMinion(canContinueAnim)` → `SetActive(canAttackAnim, CanAttackNow())`
        /// （`CardScript._MinionPlayedIntoField_d__314__MoveNext.c:155-181`）——
        /// 也就是「**整条登场链跑完之后，按当下的引擎真值点亮**」。
        /// ⚠️ 判据仍是 `RuleCore.CanActNow` 一处（⛔ 别在这里重写疲劳/眩晕/配额那几条）。</para></summary>
        void RefreshCanActForView(CardView v)
        {
            if (Ctx == null || v == null) return;
            for (int p = 0; p < 2; p++)
            {
                var board = Ctx.Players[p].Board;
                for (int s = 0; s < BoardSpec.Size; s++)
                {
                    if (board[s] == null) continue;
                    if (ViewAt(p, s) != v) continue;
                    v.SetCanAct(RuleCore.CanActNow(Ctx, p, s));
                    return;
                }
            }
            // 视图已经不在棋盘上（这一拍里被换掉/收掉了）⇒ 不碰它（它自己的销毁路径会收绿光）。
        }

        // ==================================================================
        //  🔧 临时诊断探针：「未行动绿光」到底卡在哪一层（2026-10-22）
        // ==================================================================
        //
        // **只在 `WF_CANACT_PROBE=1` 时生效**（环境变量由 `_canActProbeState` 缓存，只读一次 ——
        // 同 `TouchInputManager.ScrollProbe` 那套；真机上它不会中途变）。
        //
        // **零行为变化**：只读三样东西 —— 已经在 `SyncBoard` 里算好的 `canAct`、`CardView` 的
        // `CanActVisible` / `CanActBuilt`、以及 `ParticleSystem.isPlaying` / `particleCount`。
        // ⛔ 不调 `Play` / `Stop` / `Emit` / `Clear`，不改 `SetCanAct` 语义，不动粒子参数。
        //
        // **判据** = 原版 `CardScript.ActivateMinion` → `BattleCardUI.canAttackAnim`
        // （`SetCanAct` 就是它的复刻，判据全文见 `SyncBoard` 里那一段注释）；
        // 粒子那两层 = 原版 `CanActParticles` + 子节点 `RotatingRing`（参数注释在 `Core/CardView.cs`）。
        //
        // **怎么读这一行**：
        //   · `can=0` ⇒ 单位**真的不能行动** ⇒ 问题在引擎判据那一侧，与粒子无关；
        //   · `can=1 built=1 vis=1 playing=0` ⇒ **能行动、粒子没循环起来** ⇒ 问题在粒子那一侧；
        //   · `can=1 built=1 vis=1 playing=1` ⇒ 视图和粒子都对 ⇒ 往渲染层找（渲染队列 / 相机 / 材质）。
        static int _canActProbeState;                                   // 0 = 还没判过 · 1 = 开 · -1 = 关
        /// <summary>节流用：`(seat, slot)` → 上一次打印时的「组合串」。组合**不含** `particleCount`
        /// （它每帧都在变，含进去就等于每帧刷屏）。</summary>
        static readonly Dictionary<int, string> _canActProbeLast = new Dictionary<int, string>();

        /// <summary>见上面那段注释。**⛔ 临时诊断用，不含任何行为。**</summary>
        void CanActProbe(int owner, int s, UnitState u, CardView v, bool canAct)
        {
            if (_canActProbeState == 0)
                _canActProbeState = System.Environment.GetEnvironmentVariable("WF_CANACT_PROBE") == "1" ? 1 : -1;
            if (_canActProbeState < 0) return;

            bool built = v != null && v.CanActBuilt;
            bool vis = v != null && v.CanActVisible;
            ParticleSystem[] pss;
            if (built) pss = v.CanActRoot.GetComponentsInChildren<ParticleSystem>(true);
            else pss = System.Array.Empty<ParticleSystem>();

            // 节流：`(seat,slot)` 这一格的「组合」没变就**不打**。
            // 组合 = 单位名 + can/vis/built + 每颗粒子的 isPlaying（位置不同也算变化）。
            var combo = new System.Text.StringBuilder();
            combo.Append(u != null ? u.Name : "?").Append('|')
                 .Append(canAct ? 1 : 0).Append(vis ? 1 : 0).Append(built ? 1 : 0);
            for (int i = 0; i < pss.Length; i++) combo.Append(pss[i].isPlaying ? '1' : '0');
            string comboStr = combo.ToString();
            int key = owner * 100 + s;
            string prev;
            if (_canActProbeLast.TryGetValue(key, out prev) && prev == comboStr) return;
            _canActProbeLast[key] = comboStr;

            var sb = new System.Text.StringBuilder();
            sb.Append("[CANACTPROBE] turn=").Append(Ctx.Turn)
              .Append(" active=").Append(Ctx.Active)
              .Append(" seat=").Append(owner)
              .Append(" slot=").Append(s)
              .Append(" unit=").Append(u != null ? u.Name : "?")
              .Append(" can=").Append(canAct ? 1 : 0)
              .Append(" vis=").Append(vis ? 1 : 0)
              .Append(" built=").Append(built ? 1 : 0)
              .Append(" atk=").Append(u != null ? u.Attack : 0)
              .Append(" rng=").Append(u != null ? u.RangedAttack : 0)
              .Append(" hp=").Append(u != null ? u.Health : 0)
              .Append(" faceDown=").Append(u != null && u.FaceDown ? 1 : 0)
              .Append(" ps=");
            if (pss.Length == 0) sb.Append("-");
            for (int i = 0; i < pss.Length; i++)
            {
                if (i > 0) sb.Append("; ");
                sb.Append(pss[i].name)
                  .Append(" playing=").Append(pss[i].isPlaying ? 1 : 0)
                  .Append(" n=").Append(pss[i].particleCount);
            }
            // 🆕 2026-10-22：**视图现在是哪个形态**（`CardFace`）—— 判「绿光整回合不亮」的第四个分档：
            //   绿光那层只有 `Board` 形态才建得出来（`CardView.ApplyCanAct`），而形态要到登场 clip 0.7 s
            //   才切（`CardFeel.cs:1351-1357`）⇒ `face=Hand` 就是那一档的直接证据。
            //   （`CardView.Face` 是 public 只读，`CardView.cs:1476`。）
            sb.Append(" face=").Append(v != null ? v.Face.ToString() : "-");
            Debug.Log(sb.ToString());
        }

        // ==================================================================
        //  「让位」预览（拖拽中，2026-10-01）
        // ==================================================================
        //
        // 原版 `MinionManager__ReassembleMinionsWhilePlayingUnit.c`（由 `BattleManager__Update.c:575` **逐帧**调）：
        //   ① 求出「这张牌会插到该侧的哪个下标」（那函数里是 `GetClosestAvailableSlot`，再被
        //      `InsertMinion` 里的 `AdjustedSlot` 夹紧 —— 我们两处合成 `BoardSlots.Resolve` 一份判据）；
        //   ② **下标 ≥ 插入点的单位整体 +1**（`:43-45` 那句 `iVar8 = iVar9 + 1`）——
        //      ⚠️ 它**不改数据**，只是把它们**补间**到「插进去之后」的位置
        //      （`CardScript.UpdateMinionInPlayPosition`，时长 `minionReassembleTime ÷ 1.5 = 0.1 s`）；
        //   ③ 外加 `SetCardShadow(落点格, active:1, rotate:1)` —— 那半条 = 已经做掉的落点指示 (b)。
        //
        // 🔴 **只在 `animateFeel` 打开时走**：批处理自检要**精确坐标**（拖拽那几条断言盯着
        //    `localPosition`），预览一插进来就会把它们推成浮点数。
        int _previewOwner = -1;        // 哪一方的棋盘在预览（-1 = 没有）
        int _previewRequested = -1;    // 请求的落点格号（-1 = 没有）
        /// <summary>预览期间**被推开过**的那几张视图 —— 收工时要一次性把它们补间送回真格位。</summary>
        readonly List<CardView> _previewMoved = new List<CardView>();

        /// <summary>驱动层接 `CardInteraction.OnDropPreview`：记住「现在拖到哪一格」。
        /// `which == null` / `slot &lt; 0` = 收工（松手、取消、重开一局都走这一条）。</summary>
        void OnDropPreview(BoardLayout which, int requestedSlot)
        {
            if (which == null || requestedSlot < 0)
            {
                EndPreviewReturn();
                _previewOwner = -1;
                _previewRequested = -1;
                return;
            }
            _previewOwner = (which == playerBoard) ? _me : (1 - _me);
            _previewRequested = requestedSlot;
        }

        /// <summary>
        /// 预览收工时把被推开的单位送回**真格位**。两条路分开走，别混：
        ///   · **取消**（拖回手牌 / 拖到空白处）⇒ 真格位还是原来那些 ⇒ **补一次 `DOLocalMove` 送回去**；
        ///   · **放下去**（`interaction.DropAccepted`）⇒ 引擎马上就会把它插进去，
        ///     那时它们**本来就该站在预览位上**。这里**别动**（动了会先弹回原位、再被插出去 = 抖两下）。
        /// </summary>
        void EndPreviewReturn()
        {
            if (_previewMoved.Count == 0) return;
            if (interaction != null && interaction.DropAccepted) { _previewMoved.Clear(); return; }
            for (int i = 0; i < _previewMoved.Count; i++)
            {
                var v = _previewMoved[i];
                if (v == null) continue;
                int owner, slot;
                if (!FindBoardViewSlot(v, out owner, out slot)) continue;
                Vector3 pos; float sc;
                PoseFor(owner == _me, slot, Ctx.Players[owner].Board[slot], out pos, out sc);
                if ((v.transform.localPosition - pos).sqrMagnitude > 1e-6f) CardFeel.Reassemble(v, pos);
            }
            _previewMoved.Clear();
        }

        /// <summary>这张视图现在挂在谁家的第几格上（找不到 = 已经不在场上了）。</summary>
        bool FindBoardViewSlot(CardView v, out int owner, out int slot)
        {
            foreach (var kv in _myUnits) if (kv.Value == v) { owner = _me; slot = kv.Key; return true; }
            foreach (var kv in _foeUnits) if (kv.Value == v) { owner = 1 - _me; slot = kv.Key; return true; }
            owner = -1; slot = -1;
            return false;
        }

        /// <summary>预览时这个单位**暂时**该站哪一格（没有预览 = 它自己那一格）。</summary>
        int PreviewSlotFor(int owner, int slot)
        {
            if (_previewOwner != owner || _previewRequested < 0 || Ctx == null) return slot;
            int side, insertAt;
            if (!BoardSlots.Resolve(Ctx.Players[owner], _previewRequested, out side, out insertAt)) return slot;
            if (BoardSlots.SideOf(slot) != side) return slot;
            if (BoardSlots.IndexOf(slot) < insertAt) return slot;       // 插入点以前的不动
            int moved = BoardSlots.IndexOf(slot) + 1;
            if (moved >= BoardSpec.SlotsPerSide) return slot;           // 已经是最外那一格 ⇒ 无处可让
            return BoardSlots.SlotOf(side, moved);
        }

        /// <summary>拖拽中每帧：把场上单位**推向**预览位（只在拖拽期间跑）。
        /// ⚠️ 这里**只改 `localPosition`**，不碰缩放/旋转 —— 原版那句 `DOLocalMove` 也只动位移。
        ///
        /// 🔴 **只在「预览中」时跑** —— 别让它每帧无条件地把所有卡往格位上拽：
        /// 攻击前冲 / 挨打后坐 / 飘字那些补间**改的也是 `localPosition`**，每帧拽一次会把它们**当场抹平**
        /// （而且只在真人玩的时候看得出来，自检里 `animateFeel` 是关的）。
        /// 收工那一下走 `EndPreviewReturn()`（一次 `DOLocalMove`），不在这儿续着拽。</summary>
        void TickShufflePreview(float dt)
        {
            if (!animateFeel || Ctx == null || _previewRequested < 0) return;

            float k = 1f - Mathf.Exp(-18f * dt);      // 指数趋近：帧率无关
            for (int i = 0; i < 2; i++)
            {
                int owner = i == 0 ? _me : 1 - _me;
                bool mine = owner == _me;
                var views = mine ? _myUnits : _foeUnits;
                foreach (var kv in views)
                {
                    var v = kv.Value;
                    if (v == null) continue;
                    Vector3 pos; float sc;
                    PoseFor(mine, PreviewSlotFor(owner, kv.Key), Ctx.Players[owner].Board[kv.Key], out pos, out sc);
                    var tr = v.transform;
                    if ((tr.localPosition - pos).sqrMagnitude < 1e-6f) continue;   // 已经在位 ⇒ 没被推过
                    if (!_previewMoved.Contains(v)) _previewMoved.Add(v);
                    tr.localPosition = Vector3.Lerp(tr.localPosition, pos, k);
                }
            }
        }

        /// <summary>
        /// 这一格该盖哪一具残骸体（不是残骸 / 原版不建 ⇒ `null`）。
        ///
        /// 🔴 **2026-10-22（`W64` · B16）判据换人了**：现在是**逐卡查原版字段**
        /// （`RemnantBodyTable`，表 = `Resources/remnant_body_by_card.json`），
        /// 不再是「按关键词猜」——
        ///   · 原版 `BattleCardUI__SetRawCardData.c:45`：只有 `SupportMethods.HasToTransformIntoRemnant(rawCard)`
        ///     为真才 `CreateRemnantBody()`（判据 = 两条当前特质 `0x41a Remnant` / `0x474 Waystone`）；
        ///   · `BattleCardUI__CreateRemnantBody.c:36-65`：实例化的是**这张卡自己的**
        ///     `RawCardScript.remnantBodyPrefab`（`rawCard + 0xe0`）。
        /// ⇒ **哪一具是卡自己的 SO 说了算**，不是关键词（两者在本卡池里恰好 0 处分歧，但口径不同）。
        /// 旧关键词链**只保留给「表根本没载进来」那一档**（缺文件 / 解析失败），并在 `RemnantBodySource` 里标出。
        ///
        /// ~~旧口径（保留痕迹）：「判据是卡上的关键词，不是阵营 —— `Waystone` → 灵族那具、`Remnant` → 死灵那具」~~
        ///   —— 值恰好对（52 张能变残骸的卡逐张核过：逐卡字段 vs 关键词规则 **0 处不同**），
        ///   但**判据来源错了**（那是推论，不是原版字段）。现读 `cards_engine.json` 关键词计数 25 / 27 仍然成立。
        /// 出处（原版那两具叫什么、长什么样）→ `资料/查证_useWaystone_语义.md` §五 的资产表。
        /// </summary>
        static string RemnantPrefabOf(UnitState u)
        {
            if (u == null) return null;
            string id = u.Card != null ? u.Card.Id : null;
            return RemnantBodyPrefabFor(id, u.Name, u.IsRemnant,
                                        u.Has(KeywordTable.Waystone), u.Has(KeywordTable.Remnant),
                                        out RemnantBodySource _);
        }

        /// <summary>残骸体该从哪儿来（自检用；`RemnantPrefabOf` 的判定理由）。</summary>
        public enum RemnantBodySource
        {
            /// <summary>这一格不是残骸（`UnitState.IsRemnant == false`）⇒ 不建。</summary>
            NotRemnant = 0,
            /// <summary>表里有这张卡、`canTransform == true` ⇒ 用**表里那件** prefab（原版那条路）。</summary>
            Table = 1,
            /// <summary>表里有这张卡、`canTransform == false` ⇒ 原版 `HasToTransformIntoRemnant` 也是假 ⇒ **不建**。</summary>
            TableCannotTransform = 2,
            /// <summary>表**载进来了**但没有这张卡（= 原版该卡 `remnantBodyPrefab` 字段为空）⇒ **不建 + 出声**。
            /// ⛔ 这一档**不许**退回关键词猜。</summary>
            NoTableEntry = 3,
            /// <summary>表**没载进来**（缺文件 / 解析失败 / schema 不对）⇒ 旧关键词链兜着，**明确标记**。</summary>
            KeywordFallback = 4,
        }

        /// <summary>
        /// 纯函数版（不碰 `UnitState`，自检能直接调）：给定身份 + 两个关键词位，返回该盖哪件 prefab。
        /// 判据与四档含义见 <see cref="RemnantBodySource"/> 的注释 + `RemnantBodyTable` 文件头。
        /// </summary>
        public static string RemnantBodyPrefabFor(string id, string name, bool isRemnant,
                                                  bool hasWaystone, bool hasRemnant,
                                                  out RemnantBodySource why)
        {
            why = RemnantBodySource.NotRemnant;
            if (!isRemnant) return null;

            string prefab;
            bool canTransform;
            if (RemnantBodyTable.TryGet(id, name, out prefab, out canTransform))
            {
                if (!canTransform)
                {
                    why = RemnantBodySource.TableCannotTransform;
                    RemnantBodyTable.NoteCannotTransform(id, name);
                    return null;
                }
                if (string.IsNullOrEmpty(prefab))
                {
                    // 字段在、值却是空 ⇒ 原版也实例化不了任何东西（`CreateRemnantBody` 拿到空 AssetReference）
                    why = RemnantBodySource.NoTableEntry;
                    RemnantBodyTable.NoteMissing(id, name);
                    return null;
                }
                why = RemnantBodySource.Table;
                RemnantBodyTable.TableHits++;
                return prefab;
            }

            if (RemnantBodyTable.Loaded)
            {
                why = RemnantBodySource.NoTableEntry;
                RemnantBodyTable.NoteMissing(id, name);
                return null;
            }

            // 表没载进来 ⇒ 旧关键词链（**只在这一档**，并记标记；⛔ 别把它当常态）
            why = RemnantBodySource.KeywordFallback;
            RemnantBodyTable.KeywordFallbacks++;
            if (hasWaystone) return RemnantBodyAeldari;
            if (hasRemnant) return RemnantBodyNecrons;
            return null;
        }

        /// <summary>残骸体 prefab 名（= `WarpforgeVFX/Prefabs/` 下的文件名 = 效果库的键）。
        /// ⚠️ **2026-10-22 起只在「表没载进来」的退路上用到**（见 `RemnantBodyPrefabFor`）。</summary>
        const string RemnantBodyAeldari = "RemnantBody3D Aeldari";
        /// <summary>见 <see cref="RemnantBodyAeldari"/>。</summary>
        const string RemnantBodyNecrons = "RemnantBody3D Necrons";

        // ==================================================================
        //  逐卡残骸体表（`W64` · B16）
        // ==================================================================
        //
        // 数据：`Assets/CardPresentation/Resources/remnant_body_by_card.json`
        //   （**全量件** = `数据/游戏数据/remnant_body_by_card.json`，生成器 `工具/gen_remnant_body_table.py`，
        //     ⛔ 别手改那个 json；Resources 那份是它的**运行时投影**：`byCard` 字典 → `cards[]` 数组，
        //     因为 `JsonUtility` 不支持字典 —— 与 `Resources/related_cards.json` 同套做法）。
        // 形状：`schema / source / count / cards[{id,name,prefab,canTransform,inPool}]`。
        // 投影规则（**只有这一条**，逐字节可复现）：把全量件的 `byCard` **按 id 排序**，每条的
        //   `id/name/prefab/canTransform/inPool` 五个字段**原样**搬进 `cards[]`，`count = cards.Length`
        //   —— 别加字段、别改值（`--check` 幂等：同一份全量件重跑两遍字节相同）。
        //
        // 判据链（逐跳可复核 → 全量件的 `_judges`）：
        //   ① `BattleCardUI__SetRawCardData.c:45` —— 只有 `HasToTransformIntoRemnant` 才建；
        //   ② `SupportMethods__HasToTransformIntoRemnant.c` —— 判据 = 特质 `0x41a Remnant` / `0x474 Waystone`；
        //   ③ `BattleCardUI__CreateRemnantBody.c:36-65` —— 实例化**这张卡自己的** `remnantBodyPrefab`
        //      （父节点 = 卡、位置 = 卡的位置）。
        // 现读规模（2026-10-22）：池内 **71 张**带该字段 → **2 件** prefab
        //   （`RemnantBody3D Aeldari` ×29 / `RemnantBody3D Necrons` ×42）；其中**能真变残骸**的 **52 张**，
        //   另 **19 张**有字段但拿不到那两条特质 ⇒ 原版也不建（`canTransform=false`）。
        //
        // 🔴 四条纪律：
        //   · **表载不进来要出声**（缺文件 / schema 不对 / 解析失败）—— 不许静默退回关键词；
        //   · **表里没有这张卡 ⇒ 不建 + 出声**（⛔ 不猜）；
        //   · `canTransform == false` ⇒ 不建（原版判据），**出声**只在第一次（19 张卡会正常走到这一档）；
        //   · 自检夹具走 `SetForTest` / `ResetForTest`，键前缀 `Fixture`（不与真卡撞）。
        /// <summary>原版逐卡残骸体字段的运行时查表（判据 / 纪律见上面整段注释）。</summary>
        public static class RemnantBodyTable
        {
            public const string ResourcePath = "remnant_body_by_card";
            /// <summary>schema 前缀（带版本号；`+rt` = 运行时投影）。</summary>
            public const string SchemaPrefix = "remnant_body_by_card/";

            [System.Serializable]
            public class EntryDto
            {
                public string id;
                public string name;
                public string prefab;
                public bool canTransform;
                public bool inPool;
            }

            [System.Serializable]
            public class FileDto
            {
                public string schema;
                public string source;
                public int count;
                public EntryDto[] cards;
            }

            /// <summary>表**载进来了**（false ⇒ 只有旧关键词链可用，`LastError` 有话说）。</summary>
            public static bool Loaded { get { EnsureLoaded(); return _loaded; } }
            /// <summary>表里几条（池内 + 3 张池外 tutorial）。</summary>
            public static int Cards { get { EnsureLoaded(); return _byId != null ? _byId.Count : 0; } }
            public static string LastError { get; private set; }

            /// <summary>查表命中次数（自检：&gt; 0 = 生产路径真的走表）。</summary>
            public static int TableHits;
            /// <summary>命中但 `canTransform == false` 的次数。</summary>
            public static int CannotTransformHits;
            /// <summary>表在、但没有这张卡的次数。</summary>
            public static int MissingEntries;
            /// <summary>表没载进来、退回关键词链的次数（**应恒 0**，非 0 = 缺表）。</summary>
            public static int KeywordFallbacks;

            public static void ResetDiagnostics()
            {
                TableHits = 0; CannotTransformHits = 0; MissingEntries = 0; KeywordFallbacks = 0;
                _warnedMissing.Clear(); _warnedCannot.Clear();
            }

            static readonly HashSet<string> _warnedMissing = new HashSet<string>();
            static readonly HashSet<string> _warnedCannot = new HashSet<string>();

            static bool _tried;
            static bool _loaded;
            static Dictionary<string, EntryDto> _byId;
            static Dictionary<string, EntryDto> _byName;

            /// <summary>按 **卡 id** 查，查不到再按**卡名**（表里 74 条卡名无重名；id 是主键）。
            /// 返回 `false` = 表里没有这张卡（或表没载进来）。</summary>
            public static bool TryGet(string id, string name, out string prefab, out bool canTransform)
            {
                EnsureLoaded();
                prefab = null; canTransform = false;
                if (!_loaded) return false;
                EntryDto e;
                if (!string.IsNullOrEmpty(id) && _byId != null && _byId.TryGetValue(id, out e) && e != null)
                { prefab = e.prefab; canTransform = e.canTransform; return true; }
                if (!string.IsNullOrEmpty(name) && _byName != null && _byName.TryGetValue(name, out e) && e != null)
                { prefab = e.prefab; canTransform = e.canTransform; return true; }
                return false;
            }

            /// <summary>表里有没有这个键（自检用：区分「表里没有」与「表没载进来」）。</summary>
            public static bool Has(string id, string name)
            {
                EnsureLoaded();
                if (!_loaded) return false;
                return (!string.IsNullOrEmpty(id) && _byId.ContainsKey(id))
                    || (!string.IsNullOrEmpty(name) && _byName.ContainsKey(name));
            }

            internal static void NoteMissing(string id, string name)
            {
                MissingEntries++;
                string k = !string.IsNullOrEmpty(id) ? id : name;
                if (MissingEntries <= 8 && _warnedMissing.Add(k ?? ""))
                    Debug.LogWarning($"[残骸体] `{k}`（{name}）**不在** `Resources/{ResourcePath}.json` 里 ⇒ "
                                   + "这一格**不建残骸体**。原版判据是这张卡自己的 `RawCardScript.remnantBodyPrefab`"
                                   + "（`BattleCardUI__CreateRemnantBody.c:36-65`）—— 表里没有 = 原版这个字段是空，"
                                   + "⛔ 我们**不按关键词猜**。要补：重跑 `工具/gen_remnant_body_table.py` 看它是否 `unresolved`。");
            }

            internal static void NoteCannotTransform(string id, string name)
            {
                CannotTransformHits++;
                string k = !string.IsNullOrEmpty(id) ? id : name;
                if (CannotTransformHits <= 4 && _warnedCannot.Add(k ?? ""))
                    Debug.LogWarning($"[残骸体] `{k}`（{name}）的 SO **有** `remnantBodyPrefab` 字段，但它拿不到 "
                                   + "`Remnant`/`Waystone` 特质 ⇒ 原版 `HasToTransformIntoRemnant` 为假、**不会建残骸体**"
                                   + "（`BattleCardUI__SetRawCardData.c:45`）⇒ 这一格不建（照原版）。");
            }

            /// <summary>自检夹具：往表里插/改一条（键请用 `Fixture…` 前缀，别撞真卡）。</summary>
            public static void SetForTest(string id, string name, string prefab, bool canTransform)
            {
                EnsureLoaded();
                if (_byId == null) _byId = new Dictionary<string, EntryDto>(System.StringComparer.Ordinal);
                if (_byName == null) _byName = new Dictionary<string, EntryDto>(System.StringComparer.Ordinal);
                var e = new EntryDto { id = id, name = name, prefab = prefab, canTransform = canTransform, inPool = false };
                if (!string.IsNullOrEmpty(id)) _byId[id] = e;
                if (!string.IsNullOrEmpty(name)) _byName[name] = e;
            }

            /// <summary>清掉夹具并让下一次 `TryGet` 重新从 `Resources` 载（自检收尾用）。</summary>
            public static void ResetForTest()
            {
                _tried = false; _loaded = false;
                _byId = null; _byName = null;
            }

            /// <summary>自检用：**假装表载不进来**（验「旧关键词链只在这一档生效，并且有标记」）。
            /// 传 `false` 收尾（= `ResetForTest`，下一次 `TryGet` 会重新从 `Resources` 载）。</summary>
            public static void SetUnavailableForTest(bool unavailable)
            {
                _unavailableForTest = unavailable;
                ResetForTest();
            }
            static bool _unavailableForTest;

            static void EnsureLoaded()
            {
                if (_tried) return;
                _tried = true;
                if (_unavailableForTest)
                {
                    LastError = "自检：`RemnantBodyTable.SetUnavailableForTest(true)` —— 表被强制当成没载进来";
                    return;
                }
                var asset = Resources.Load<TextAsset>(ResourcePath);
                if (asset == null)
                {
                    LastError = "`Resources/" + ResourcePath + ".json` **没载到** ⇒ 残骸体退回旧关键词链"
                              + "（`Remnant`→Necrons / `Waystone`→Aeldari）并计数。补法：跑一次 "
                              + "`python -I -X utf8 d:/4/Unity/工具/gen_remnant_body_table.py`";
                    Debug.LogWarning("[残骸体] " + LastError);
                    return;
                }
                FileDto dto;
                try { dto = JsonUtility.FromJson<FileDto>(asset.text); }
                catch (System.Exception e)
                {
                    LastError = "`Resources/" + ResourcePath + ".json` 解析失败：" + e.Message
                              + " ⇒ 残骸体退回旧关键词链";
                    Debug.LogError("[残骸体] " + LastError);
                    return;
                }
                // 版本守卫：schema 必须带前缀（`remnant_body_by_card/v1+rt`）。不认就**不当它是这张表**。
                if (dto == null || string.IsNullOrEmpty(dto.schema)
                    || !dto.schema.StartsWith(SchemaPrefix, System.StringComparison.Ordinal))
                {
                    LastError = "`Resources/" + ResourcePath + ".json` 的 schema 不对（期望 `"
                              + SchemaPrefix + "…`，实得 `" + (dto != null ? dto.schema : "null")
                              + "`）⇒ 残骸体退回旧关键词链";
                    Debug.LogError("[残骸体] " + LastError);
                    return;
                }
                var cards = dto.cards ?? new EntryDto[0];
                if (cards.Length == 0)
                {
                    LastError = "`Resources/" + ResourcePath + ".json` 里 `cards[]` 是空的 ⇒ 残骸体退回旧关键词链";
                    Debug.LogError("[残骸体] " + LastError);
                    return;
                }
                // 字段守卫：`count` 与数组长度不一致只**出声**（表还能用），逐条缺 `id`/`name`/`prefab` 的跳过。
                if (dto.count > 0 && dto.count != cards.Length)
                    Debug.LogWarning($"[残骸体] `Resources/{ResourcePath}.json` 的 `count`={dto.count} 与 "
                                   + $"`cards.Length`={cards.Length} 不一致（表照用，但请重跑生成器看一眼）");
                _byId = new Dictionary<string, EntryDto>(cards.Length, System.StringComparer.Ordinal);
                _byName = new Dictionary<string, EntryDto>(cards.Length, System.StringComparer.Ordinal);
                int skipped = 0;
                foreach (var c in cards)
                {
                    if (c == null || (string.IsNullOrEmpty(c.id) && string.IsNullOrEmpty(c.name))) { skipped++; continue; }
                    if (!string.IsNullOrEmpty(c.id)) _byId[c.id] = c;
                    if (!string.IsNullOrEmpty(c.name)) _byName[c.name] = c;
                }
                if (skipped > 0)
                    Debug.LogWarning($"[残骸体] `Resources/{ResourcePath}.json` 有 {skipped} 条缺 `id`/`name`，已跳过");
                _loaded = true;
                LastError = null;                 // 载成功就把上次那条「没载到」清掉（自检可能先故意造过一次）
                Debug.Log($"[残骸体] `Resources/{ResourcePath}.json` 载进来了：**{_byId.Count} 张卡**"
                        + $"（schema `{dto.schema}`，source `{dto.source}`）");
            }
        }

        /// <summary>
        /// 手牌同步：**引擎的手牌顺序是权威**，视图跟着走。
        /// 先按顺序把现有的视图和引擎手牌一一配对（同名的多个也逐个配），
        /// 配不上的（被打出/超上限弃掉的）销毁，缺的新建。
        /// </summary>
        void SyncHand()
        {
            var h = Ctx.Players[_me].Hand;

            var pool = new List<CardView>(_handViews);
            var ordered = new List<CardView>(h.Count);
            _dealt.Clear();                     // 这一轮新进来的牌（发牌入场要用，见下面）

            foreach (var inst in h)
            {
                var card = inst.Card;
                // 🔴 第 7 行第 4 步：**先按实例身份配对**（手里两张同名卡时才分得开谁是谁），
                //    配不上再退回按卡名（老行为：新建的视图 / 换过 def 的那些）。
                CardView match = null;
                for (int i = 0; i < pool.Count; i++)
                {
                    if (pool[i] != null && ReferenceEquals(pool[i].Inst, inst)) { match = pool[i]; pool.RemoveAt(i); break; }
                }
                if (match == null)
                {
                    for (int i = 0; i < pool.Count; i++)
                    {
                        if (pool[i] != null && pool[i].Data.id == card.Name) { match = pool[i]; pool.RemoveAt(i); break; }
                    }
                }
                if (match == null)
                {
                    // 🔴 **2026-10-17（D1）**：**手牌是【唯一】不印阵营行的场景**（另一个是场上）。
                    //    ——「手牌 + 场上不印，其余都印」（**用户 2026-09-22 裁定**，2026-10-17 由他指认
                    //    实拍复核过：`点击卡片查看详情的参考.png` 里卡名下的**橙字 `萨姆-罕` 就是阵营行**；
                    //    `战斗截图参考.png` 里手牌、场上都没有那一行）。
                    //    ⇒ 这里是**手牌卡的唯一创建入口**，必须显式传 `CardFace.Hand`
                    //      （`CardView.Create` 的缺省档是 `Full`，而 `Full` **带**阵营行 ⇒ 不传就是印）。
                    //    判据收口在 `CardView.FaceShowsArmy` 一处；断言在 `Editor/CardBaseDemo.cs` 的
                    //    `AssertArmyLine()`（⚠️ 它**不在** `_run_8_checks.sh` 那 11 条里 ⇒ 见 `项目任务.md`）。
                    match = CardView.Create(transform, ToCardData(card, _myFaction), "Hand_" + card.Name,
                                            CardFace.Hand);
                    _dealt.Add(match);
                }
                match.Inst = inst;             // 这一份 = 这张视图（第 7 行第 4 步）
                ordered.Add(match);
            }

            foreach (var dead in pool) if (dead != null) Kill(dead.gameObject);

            _handViews.Clear();
            _handViews.AddRange(ordered);
            // 🔴 **2026-10-22（W63 · 换牌那排卡是斜的）**：换牌期**不让手牌布局走带补间的重排** ——
            //   这几张牌这一档的位姿归 `MulliganPanel`（`BuildCardButtons` / `ReapplyRowPoses`：
            //   **平 0°** 横排，判据 = 原版 `MB_4881` `m_useRotation=0` + `GetRotation` 直接返回
            //   `Quaternion.identity`）。而 `HandLayout.Place` 在实机上（`animateRelayout == 1`）开的是
            //   **0.2 s 带旋转的重排补间**、算的是**手牌扇形角** ⇒ 它的旋转尾巴会在 0.2 s 末尾落盘，
            //   把换牌区那一行带斜（位置/尺度会被面板当场改回，**只有角度不会**）。
            //   `relayout:false` = **算而无补间**（位姿要算：`_lastPose` 与面板 `Close()` 的复位都靠它，
            //   见 `CardInteraction.SetCards` 的 doc），补间**一条都不开**。
            //   ⛔ 别退回「每轮 `SetCards` 之后靠 `ReapplyRowPoses` 补一下」—— 那只盖住位置/尺度，
            //   盖不住「补间还没跑完」这件事（补间还在，0.2 s 后照样写旋转）。
            interaction.SetCards(new List<CardView>(_handViews), relayout: !Ctx.MulliganOpen);

            // ---- 「临时卡」角标（规则书 :183/:229）--------------------------------
            // **判据来自引擎**（`BattleContext.IsEphemeral` —— 它同时管「卡自己带关键词」和
            // 「造出来的复制被标记成临时」两条路），表现层不自己算。
            // ⚠️ 这一句**必须在 `SetCards` 之后、`RefreshHandPlayable` 附近**：
            //    `match` 可能是**复用**的旧视图（`pool` 里捞出来的），它的角标状态是**上一轮的**
            //    —— 不每轮重刷的话，一张临时卡打出去之后，接手它那个视图的普通卡会**一直带着角标**。
            for (int i = 0; i < _handViews.Count && i < h.Count; i++)
                if (_handViews[i] != null) _handViews[i].ShowEphemeral(Ctx.IsEphemeral(h[i]));

            // ---- 🆕 2026-10-18（`A985④`）「由谁造出来的」（原版 `BattleCardUI.DisplayCreatedByText`）----
            // **判据来自引擎**（`BattleContext.CreatedByOf`；它记的是「效果造这张牌时正在结算的那张卡」，
            //   与原版 `CardScript.createdBy` 那三处写点同义 —— 见 `BattleContext._createdBy` 那一段），
            //   表现层不自己算。
            // ⚠️ 与上面那条角标**同一条理由**（也同一点位）：`match` 可能是**复用**来的旧视图，
            //   那行字是**上一轮的** —— 不每轮重推的话，「造出来的」那张打出去之后，接手它那个视图的
            //   普通卡会**一直带着这行字**。`SetCreatedBy` 内部按「名字 + 状态都没变就不动手」去重。
            // 🔴 **2026-10-22（`W62/D5①`）：显隐门由 `PushCreatedByStates` 一处算**（原版那 18 档
            //   状态表的对应物；⛔ 别在这儿再拼一遍「悬停 == 展示档」）。原来这里**无条件**
            //   `SetCreatedBy(来源)` ⇒ 静置手牌的每一张「被造出来的」都挂着那行字（真机 `W62` 抓到的就是它）。
            PushCreatedByStates();

            RefreshHandPlayable();

            // 🔴 `A1540`：**先把新牌的位姿当场落实** —— 这一步与「发不发牌」无关，**无条件**做：
            //    换牌阶段那一帧不发牌，但牌也必须已经在**真牌位**上（`OpenMulligan()` 建的「换」钮
            //    是贴卡读位置的）。详见 `CommitDealtPoses`。
            CommitDealtPoses();
            // **发牌入场** —— 见 `PlayDealAnimation`（含 `A1540` 的全部判据）。
            // 🔴 换牌阶段这一帧**先不发**：`OpenMulligan()` 排在 `RefreshAll()` **之后**，而它建的「换」钮
            //    是**贴卡读位置**的（`MulliganPanel.Open` 里的 `c.transform.position`）——
            //    发牌会把卡先挪到牌堆，钮就全落到牌堆上（实拍 `_tmp_view/ui_1019/17_battle.png` 右下角那颗）。
            //    ⇒ 交给 `Begin` 的换牌分支，在 `OpenMulligan()` **之后**再放。
            if (!Ctx.MulliganOpen) PlayDealAnimation();

            // 🆕 **2026-10-25（`X19/P1`）手牌文字运行期探针** —— 见 `ProbeHandText` 的 doc。
            //    **纯只读、不改任何行为**：读全部在 `CardView` 的公开口径上
            //    （`TitleText` / `KeywordsText` / `NameFontSize` / `InkBoxLocal` / `TextNeedsRefit`）。
            ProbeHandText();
        }

        // ==================================================================
        //  手牌文字运行期探针（`X19/P1` · 2026-10-25）
        // ==================================================================
        //  🔴 **为什么要它**（证据链 → `_tmp_view/shots/2026-10-25_第七十五会话/findings.md` F3++）：
        //     · **卡池**的「卡名越框」已经有解释（拟合早于描边 + 裸 `ForceMeshUpdate` 在未激活父链上早退，
        //       见 `CardView.BuildTextLayers` / `Relayout` 那两段）—— 但 **手牌**是「卡名**和**正文**都**越框」
        //       （`b14_B_hand_zoom.png`：「圣典：恢复 3 点生命值」整行冲出右边框压到隔壁卡）；
        //     · 而自检里按 `CardFace.Hand` + 0.35 缩放 + `SetData` 复现**不出来**（全绿）
        //       ⇒ **真机手牌另有运行期来源**，且那条路自检的结构里没有。
        //  ⇒ 这行日志就是用来「一眼判死」是哪一支的：每张手牌逐层打
        //     `fontSize vs 名义 fontSize` · `字墨宽(文字自己系) vs 版面框宽` · `TextNeedsRefit` ·
        //     脸档(`CardFace`) · 是否被别的入口重刷过（`refit` / `dataChanged`）。
        //
        //  🔑 **判读口径**（照 `X19` 简报）：
        //     · `fs == 名义`              ⇒ **拟合没跑** —— 嫌疑在「别的建卡入口 / 文字态切换 / 语言重刷」；
        //     · `fs < 名义` 而墨仍超框     ⇒ **还有第二条「量的比画的小」的通道**
        //       （拟合量到的那份比实际画出来的小 ⇒ 看 `needsRefit` / `active` / `wrap`）；
        //     · `needsRefit=1`            ⇒ 拟合路自报「这一次量不到可用版面」（`X17`）；
        //     · `builtInactive=1`         ⇒ 这张卡是在**未激活父链**下建的（`ForceMeshUpdate` 早退的已知入口）。
        //
        //  ⚠️ **只在 Debug/Editor 或 `WF_HAND_PROBE=1` 时出声**（真机 player 是 release 档 ⇒ 要显式开环境变量：
        //     `WF_HAND_PROBE=1 <player 路径>`）。
        //  ⚠️ **节流**：整段日志的「组合」（卡名/字号/字墨/框/标志位）没变就不打 —— `SyncHand` 每轮引擎事件都会跑。
        //  ⛔ **它不许改任何状态**：只读 `CardView` 已有的公开口径（⛔ 尤其别在这里 `RefitTextForTest`
        //     —— 那会把「没跑拟合」这个现场抹掉）。
        static int _handTextProbeState;                                  // 0 = 还没判过 · 1 = 开 · -1 = 关
        static string _handTextProbeSig = "";
        /// <summary>视图 → 上一次探针看到的 `title|keywords`（用来判「有没有别的入口把数据换掉了」）。
        /// ⚠️ **实例字段**（不是 static）：视图会随对局销毁，static 的话会跨局累积成泄漏。</summary>
        readonly Dictionary<CardView, string> _handTextProbeData = new Dictionary<CardView, string>();

        /// <summary>见上面那段注释。**⛔ 只读诊断，不含任何行为。**</summary>
        void ProbeHandText()
        {
            if (_handTextProbeState == 0)
                _handTextProbeState = (System.Environment.GetEnvironmentVariable("WF_HAND_PROBE") == "1"
                                       || Debug.isDebugBuild || Application.isEditor) ? 1 : -1;
            if (_handTextProbeState < 0 || Ctx == null) return;

            var h = Ctx.Players[_me].Hand;
            var sb = new System.Text.StringBuilder();
            sb.Append("[HANDTEXT] turn=").Append(Ctx.Turn)
              .Append(" mulligan=").Append(Ctx.MulliganOpen ? 1 : 0)
              .Append(" hand=").Append(h.Count)
              .Append(" views=").Append(_handViews.Count)
              .Append(" fmt=").Append(CardView.HandTextFormat)
              .Append(" tmps=").Append(TmpFont.Available ? 1 : 0);

            for (int i = 0; i < _handViews.Count && i < h.Count; i++)
            {
                var v = _handViews[i];
                if (v == null) continue;
                var d = v.Data;
                string dataKey = (d.title ?? "") + "|" + (d.keywords ?? "");
                string prevKey;
                bool dataChanged = _handTextProbeData.TryGetValue(v, out prevKey) && prevKey != dataKey;
                _handTextProbeData[v] = dataKey;

                bool simplified = CardView.IsSimplifiedTextState(v.TextState);
                sb.Append("\n  #").Append(i).Append(" `").Append(d.title ?? "?").Append('`')
                  .Append(" face=").Append(v.Face)
                  .Append(" state=").Append(v.TextState)
                  .Append(" new=").Append(_dealt.Contains(v) ? 1 : 0)
                  .Append(" refit=").Append(v.TextRefitCount)
                  .Append(" builtInactive=").Append(v.BuiltInactive ? 1 : 0)
                  .Append(" needsRefit=").Append(v.TextNeedsRefit ? 1 : 0)
                  .Append(" dataChanged=").Append(dataChanged ? 1 : 0)
                  .Append(" unit=").Append(d.isUnit ? 1 : 0);

                // 卡名：**不折行**那一档 ⇒ `sizeDelta.x` 不是框宽（`Relayout` 只在 wrap 时写它）
                //   ⇒ 框宽走生产同一个判据 `UiNameBoxWidth`（⚠️ 态 2「单位·无 desc」原版用的是另一颗
                //   节点 `UnitNameNoDescW`（私有）⇒ 那一档这里标出来，别把它的 `越框` 当真）。
                float nameBox = HandLayerBoxWidth(v, desc: false);
                AppendHandTextLayer(sb, "title", v.TitleText,
                                    simplified ? -1f : v.NameFontSize, nameBox,
                                    v.TextState == CardTextState.MinionWithoutDescription);

                float descBox = HandLayerBoxWidth(v, desc: true);
                AppendHandTextLayer(sb, "desc ", v.KeywordsText,
                                    simplified ? -1f
                                               : (d.isUnit ? CardView.KeywordFontSize : CardView.TacticKeywordFontSize),
                                    descBox, false);
            }

            string sig = sb.ToString();
            if (sig == _handTextProbeSig) return;      // 节流：组合没变就不打
            _handTextProbeSig = sig;
            Debug.Log(sig);
        }

        /// <summary>🆕 **2026-10-25（`X19` 修复 · `H2` 假绿）**：手牌某层的**版面框宽**（卡单位）
        /// —— 探针与自检**共用的唯一取框口**（⛔ 别在别处再写一份，那正是「两处写同一条规则」）。
        ///
        /// <para>🔴 **为什么不能读 `TextMeshPro.rectTransform.sizeDelta.x` 了事**：TMP **出厂就是
        /// `sizeDelta = (20, 5)`**，而**不折行**那几层（卡名 / 阵营 / 兵种）**从来没被写过折行宽**
        /// ⇒ 读到的是 **20**（出厂哨兵），不是卡名框 1.6。按 20 判「没越框」= **恒真**
        /// （`X19` 的 H2 灭自证就是这么假绿的：`墨 2.46 vs 框 20` 必然「没越框」）。</para>
        ///
        /// <para>判据（**与生产同源**）：
        /// · **效果文字**（折行层）→ `Fill` 走 `Relayout` → `TmpFont.SetWrapWidth` 把
        ///   `sizeDelta = (width, 0)` ⇒ 那里的 `sizeDelta.x` **就是**生产用的框；只有没折行时才回 `DescBoxSize`。
        /// · **卡名**（不折行层）→ 生产传给 `FitToWidth` 的 `maxWidth` 就是 `CardView.UiNameBoxWidth(isUnit)`
        ///   ⇒ 直接取同一个常量。⚠️ 文字态 2（单位·无 desc）原版用的是另一颗节点 `UnitNameNoDescW`（私有）
        ///   ⇒ 那一档只能是**近似**（调用方自己标出来）。</para></summary>
        public static float HandLayerBoxWidth(CardView v, bool desc)
        {
            if (v == null) return 0f;
            var d = v.Data;
            if (desc)
            {
                var t = v.KeywordsText;
                bool wrap = t != null && t.textWrappingMode == TMPro.TextWrappingModes.Normal;
                if (wrap && t.rectTransform != null && t.rectTransform.sizeDelta.x > 0f)
                    return t.rectTransform.sizeDelta.x;
                return CardView.DescBoxSize(d.isUnit).x;
            }
            return CardView.UiNameBoxWidth(d.isUnit);
        }

        /// <summary>探针的一层（只读）。<paramref name="nominal"/> &lt; 0 = 简化文字态（`Big` 档字号另算，别比较）。</summary>
        static void AppendHandTextLayer(System.Text.StringBuilder sb, string label, TMPro.TextMeshPro t,
                                        float nominal, float boxW, bool boxIsApprox)
        {
            if (t == null) { sb.Append("\n    ").Append(label).Append("=<无此层>"); return; }
            Vector2 ink, c;
            bool inkOk = CardView.InkBoxLocal(t, out ink, out c);
            sb.Append("\n    ").Append(label)
              .Append(" fs=").Append(t.fontSize.ToString("F4"))
              .Append(" 名义=").Append(nominal < 0f ? "简化态另算" : nominal.ToString("F4"))
              .Append(" 墨宽=").Append(inkOk ? ink.x.ToString("F4") : "n/a")
              .Append(" 墨高=").Append(inkOk ? ink.y.ToString("F4") : "n/a")
              .Append(" 框=").Append(boxW.ToString("F4")).Append(boxIsApprox ? "(近似档)" : "")
              .Append(" 越框=").Append(inkOk && boxW > 0f && ink.x > boxW * 1.001f ? 1 : 0)
              .Append(" wrap=").Append(t.textWrappingMode == TMPro.TextWrappingModes.Normal ? 1 : 0)
              .Append(" active=").Append(t.gameObject.activeInHierarchy ? 1 : 0);
        }

        /// <summary>上一次推给手牌的那一档悬停（`CardInteraction.HoveredIndex`）—— 只在它变了时重推。</summary>
        int _createdByHover = int.MinValue;

        /// <summary>自检用（`W62/D5①`）：手牌视图（**只读副本**，按手牌序）。
        /// ⛔ 产品代码别拿它改状态 —— 视图的归属由 `SyncHand` 管。</summary>
        public IReadOnlyList<CardView> HandViewsForTest { get { return _handViews; } }

        /// <summary>
        /// 🆕 **2026-10-22（`W62/D5①`）**「由谁造出来的」**带原版状态门**推给手牌的每一张视图。
        ///
        /// <para>**原版判据**（逐条见 `CardView.SetCreatedBy` 那张 18 档表）：`CreatedByText` 只在
        /// `CardStateOptions ∈ {inHandShowing = 8, inHandPlaying = 10}` 且 `createdBy != null` 时点亮；
        /// 静置手牌是 `inHand = 1` ⇒ **原版不印**（`BattleCardUI__DisplayCreatedByText.c:9-50`）。</para>
        ///
        /// <para>**我们的对应物**（如实标着：我们没有 `CardStateOptions` 状态机，所以按**已有的等价状态**映射）：
        /// · `inHandShowing(8)` = **手牌悬停** —— 原版那一档就是 `CardScript__OnTouchEnter.c:30`
        ///   → `ShowCardInHand`（指针进入自己的手牌、把牌放大展示）置的；我们的 `HandLayout` 悬停时
        ///   **抬 30 px、放大 1.3 倍**（`HandLayout.Refresh(hoveredIndex)`）= 同一件事；
        /// · `inHandPlaying(10)` = 打出的飞行段 —— 我们的手牌视图**不走这一档**（原版那一档只点亮
        ///   **对手**那张，见 `isPlayer(+0x40)` 闸）；对手那张在 `DisplayEnemyCardInCenter` 的临时卡上推。
        /// · 其余（场上 / 牌堆 / 墓地 / 换牌 / 详情窗 / 静置手牌）⇒ `InHand` 或 `Hidden`，一律不印。</para>
        ///
        /// ⚠️ 判据只此一处 —— `SyncHand`（引擎事件驱动）与 `TickCreatedByHover`（每帧跟悬停）都调它。
        /// </summary>
        void PushCreatedByStates()
        {
            if (Ctx == null) return;
            var h = Ctx.Players[_me].Hand;
            int hover = interaction != null ? interaction.HoveredIndex : -1;
            _createdByHover = hover;
            for (int i = 0; i < _handViews.Count && i < h.Count; i++)
            {
                var v = _handViews[i];
                if (v == null) continue;
                v.SetCreatedBy(Ctx.CreatedByOf(h[i]),
                               hover == i ? CardView.CreatedByState.InHandShowing
                                          : CardView.CreatedByState.InHand,
                               isLocalPlayer: true);
            }
        }

        /// <summary>🆕 2026-10-22（`W62/D5①`）：**每帧跟一次悬停**。
        /// 为什么要单独一条：`SyncHand` 只在**引擎事件**上跑（`RefreshAll`），而悬停进出是**纯输入**、
        /// 不产生任何引擎事件 ⇒ 不跟的话「展示档」永远停在 `SyncHand` 那一刻的值上
        /// （= 悬停放大了一张卡、那行字却不跟着亮）。批处理没有帧循环 ⇒ 自检里由断言直接调
        /// `PushCreatedByStates` 或 `CardView.SetCreatedBy` 验，⛔ 不依赖这一条被调用。</summary>
        void TickCreatedByHover()
        {
            if (Ctx == null || interaction == null) return;
            if (interaction.HoveredIndex == _createdByHover) return;
            PushCreatedByStates();
        }

        /// <summary>把这一轮新进手牌的牌（`_dealt`）按 `HandLayout` 刚算出来的位姿**当场落实**。
        ///
        /// 🔴 **2026-10-11（`A1540`）**：`HandLayout.Place` 在 `animateRelayout == true` 时
        /// **只开一条 0.2 s 补间、不当场落位**（`Hand/HandLayout.cs` 的 `Place`）⇒ 不落实的话，
        /// 这一帧读到的 `transform.position` 还是**父级原点**（画布正中 960,540）。
        /// ⚠️ 手牌那一档**只有存盘场景里 `animateRelayout == 1`**（批处理出厂 `false`）
        /// ⇒ 这个 bug **在自检里结构上复现不出来**（夹具要显式打开，见 `Editor/BattleScene.cs` 第 17 节）。
        ///
        /// 落实 = ① 掐掉那条重排补间（免得它与后面的发牌补间抢同一批属性）
        ///       ② `SetPose` 按真位姿当场落位。
        /// </summary>
        void CommitDealtPoses()
        {
            var hl = interaction != null ? interaction.hand : null;
            if (hl == null) return;
            for (int i = 0; i < _dealt.Count; i++)
            {
                var v = _dealt[i];
                if (v == null) continue;
                Vector3 p; float ang, sc;
                // 🔴 换牌期这几张的「真牌位」= **换牌区那一行**（`MulliganRowLocalPose`），
                //    不是手牌位 —— 见那个函数的 doc。⚠️ `SetPose` 吃**局部**位，所以这里要 `…Local…`。
                if (!MulliganRowLocalPose(v, out p, out ang, out sc)
                    && !hl.TryLastPose(v, out p, out ang, out sc)) continue;
                v.transform.DOKill();
                v.SetPose(p, ang, sc);
            }
            // 🔴 **2026-10-13：换牌期【最后】再摆一遍换牌区** —— 上面那一跳只管**发牌那一帧**，
            //    而 `interaction.SetCards`（本函数上面几行）**每一轮**都会按**手牌位**重排这几张
            //    ⇒ 不补这一下，牌会被拉回屏幕底部那排（**只有实机看得见**，批处理 `animateRelayout`
            //    是关的 ⇒ 自检结构上测不出来）。判据仍只有 `MulliganPanel.RowWorldPosAt` 一处。
            if (Ctx.MulliganOpen && _mulligan != null) _mulligan.ReapplyRowPoses();
        }

        /// <summary>换牌期这几张牌该落到**哪一行**（**世界**位姿）—— 给「飞牌动画」那条路用
        /// （`CardFeel.DealInPose` → `DOMove` 收的是世界位）。
        /// ⛔ **判据只此一处**（`PlayDealAnimation` 与 `MulliganRowLocalPose` 都问它）。
        ///
        /// **为什么要有它**：原版换牌期把起手牌**搬进 `MulliganAnchor` 那一行**
        /// （`PlayerHand.MoveCardToMulliganPos.c`：位 = 它的 `CardsHorizontalLayout.GetPosition(i,n)`），
        /// 手牌位**根本不是它们该待的地方**。而 `HandLayout.TryLastPose` 给的是**手牌位**
        /// （0.73 倍、屏幕底部那排）⇒ 换牌期照它走，发牌动画会把牌**从换牌区拉回手牌位**，
        /// 把 `MulliganPanel` 刚摆好的那一行拆掉（症状：换牌期牌又跑回屏幕底部）。
        ///
        /// 返回 `false` = **不在换牌期**（调用方照旧用 `TryLastPose`）。</summary>
        bool MulliganRowPose(CardView v, out Vector3 worldPos, out float scale)
        {
            worldPos = Vector3.zero; scale = 1f;
            if (Ctx == null || !Ctx.MulliganOpen || _mulligan == null) return false;
            if (!_mulligan.HasCard(v)) return false;
            worldPos = _mulligan.RowWorldPos(v);
            scale = MulliganPanel.RowCardScale;
            return true;
        }

        /// <summary>同上的**父空间局部位**（`CardView.SetPose` 吃局部位）。
        ///
        /// 🔴 **2026-10-13（实机才暴露）**：`SetPose` 写的是 `transform.localPosition`，而
        ///    `RowWorldPos` 给的是**世界**位 —— 批处理里两者恰好相等（父链单位变换 ⇒ 自检全绿），
        ///    **实机里不等** ⇒ 牌被摆到别处（「替换」钮留在换牌区、牌落到右下角那一带）。
        ///    ⇒ 喂 `SetPose` 的一律走这一条，喂 `DOMove` 的一律走 `MulliganRowPose`。</summary>
        bool MulliganRowLocalPose(CardView v, out Vector3 localPos, out float ang, out float scale)
        {
            ang = 0f;
            Vector3 w;
            if (!MulliganRowPose(v, out w, out scale)) { localPos = Vector3.zero; return false; }
            var parent = v.transform.parent;
            localPos = parent != null ? parent.InverseTransformPoint(w) : w;
            return true;
        }

        /// <summary>
        /// 发牌入场：这一轮新进手牌的牌（`_dealt`）从**牌堆**飞进手里。
        ///
        /// 🔴 **2026-10-11（`A1540`）** —— 这一整段原来是内联在 `SyncHand` 末尾的一行
        /// （`foreach (var v in _dealt) CardFeel.DealIn(v, deck);`），实测两个症状：
        ///   ① 起手牌**堆在画布正中**（= 父级原点 (0,0,0)）；
        ///   ② 「换」钮全落在**牌堆**上。
        /// 根因（诊断正本 → `资料/普查产出_第十八会话/D1_开局换牌与进攻卡.md` 问题 A）：
        ///   `HandLayout.Place` 在 `animateRelayout == true` 时**只开补间、不当场落位**，
        ///   而老写法是「**读当时的位置**当落点」（`CardFeel.DealIn` 里的 `Vector3 to = tr.position;`）
        ///   ⇒ 补间还没跑过一帧，读到的是父级原点。
        /// 修法两半（对应两个症状）：
        ///   · **落点** —— 用 `HandLayout.TryLastPose` 取真位姿（`CommitDealtPoses` 已落实），
        ///     再把它**显式**交给 `CardFeel.DealInPose`；
        ///   · **时机** —— 换牌阶段整段**推后**到 `OpenMulligan()` 之后（见 `Begin` 的换牌分支）。
        ///
        /// ⚠️ `animateFeel` 关着时**什么都不做**（批处理自检靠它拿当场精确的坐标）。
        /// </summary>
        /// <summary>换牌/发牌**逐张错开**的间隔系数 = **0.5**。
        ///
        /// <para>**判据**（🆕 2026-10-24 · `A19` · `C1-A01`）：原版 `PlayerHand._AddCardsToMulligan_d__41__MoveNext.c:119-127`
        /// —— 每放好一张就 `WaitForSeconds(get_timeToDraw(lVar3) × DAT_1834b2bb4)`；
        /// `DAT_1834b2bb4` 用 `工具/read_literal.py` 现读 = **0.5**（4 字节 float，上下文是 `float × float`
        /// 喂给 `WaitForSeconds`）。⇒ 间隔 = 我方 `timeToDrawPlayerCard(0.3) × 0.5` = **0.15 s/张**、
        /// 敌方 `timeToDrawEnemyCard(0.15) × 0.5` = **0.075 s/张**。</para>
        ///
        /// <para>⚠️ **第 0 张不延时**（原版循环里是「先 `MoveCardToMulliganPos` 再等」⇒ 第一张 t=0 就落位）；
        /// 最后一张之后那一次等待**不落到任何补间上**，只体现为「整条链 ≈ N × 步长」
        /// （`DealChainSeconds` 就是这条口径的只读口）。</para></summary>
        public const float DealStaggerFrac = 0.5f;

        /// <summary>第 <paramref name="i"/> 张发牌的**起始延迟**（秒）—— 判据见 <see cref="DealStaggerFrac"/>。
        /// <para>⚠️ <paramref name="i"/> = **这一轮新进手牌里的序号**（`_dealt` / `_foeDealt` 的下标），
        /// 不是手牌最终位置 —— 换牌期两者恰好同序（整手都是新牌），常规抽牌一轮只有 1~2 张。</para></summary>
        public static float DealStaggerDelay(bool mine, int i)
        {
            if (i <= 0) return 0f;
            return i * CardFeel.DealSeconds(mine) * DealStaggerFrac;
        }

        /// <summary>N 张牌**整条发牌链**的长度（秒）= `N × 步长` —— 原版最后一张之后**也等一次**
        /// （判据见 <see cref="DealStaggerFrac"/>）。自检用它核「链长 ≈ N × 0.15」。</summary>
        public static float DealChainSeconds(bool mine, int n)
        {
            if (n <= 0) return 0f;
            return n * CardFeel.DealSeconds(mine) * DealStaggerFrac;
        }

        void PlayDealAnimation()
        {
            if (!animateFeel || _dealt.Count == 0) return;
            var deck = LayoutSpace.ToWorld(MyDeckX01, MyDeckY01);
            var hl = interaction != null ? interaction.hand : null;
            for (int i = 0; i < _dealt.Count; i++)
            {
                var v = _dealt[i];
                if (v == null) continue;
                // 🔴 2026-10-24（`A19` · `C1-A01`）：**逐张错开** —— 原版每放好一张就
                //   `WaitForSeconds(timeToDraw × 0.5)`（判据全在 `DealStaggerFrac` 的 doc）。
                //   ⇒ 第 i 张在 `i × 0.15 s`（我方）才起飞；第 0 张 t=0 立即。
                //   ⚠️ 延时**不缩短 `DealDuration`**（0.3 s 是 `W63` 换牌角度兜底的前提，⛔ 别动）。
                float dealDelay = DealStaggerDelay(true, i);
                Vector3 p; float ang, sc;
                // 🔴 换牌期落点 = **换牌区那一行**，而且是**世界**位（`DealInPose` 走 `DOMove`）。
                if (MulliganRowPose(v, out p, out sc))
                {
                    var deal = CardFeel.DealInPose(v, deck, p, 0f, sc, dealDelay,
                                                   back: CardArt.CardBack(_myFaction));
                    // 🔴 **2026-10-22（W63 · 换牌那排卡是斜的）**：**确定性兜底** —— 这条发牌补间
                    //   是这一帧**最后结束**的那一条（`CardFeel.DealDuration = 0.3 s`；
                    //   它内嵌的翻面只占两段 `× 0.25` = **0.15 s**，那 0.15 s 之后**没人再写旋转**）。
                    //   ⇒ 收尾那一刻把位姿**显式**写成换牌区那一行（**平 0°**）。这样就算将来又有谁
                    //   开了一条比 0.3 s 短的带旋转补间（手牌重排 = 0.2 s 那一档），最后落盘的也是这一句。
                    //   ⚠️ 这里**不** `DOKill`：补间已经完成、没有「自己杀自己」的必要；
                    //      而 `0.3 s > 0.2 s` 正是这条兜底能赢的**前提**，⛔ 别把 DealDuration 调短。
                    Vector3 rowLocal; float rowAng, rowSc;
                    if (deal != null && MulliganRowLocalPose(v, out rowLocal, out rowAng, out rowSc))
                        deal.OnComplete(() => { if (v != null) v.SetPose(rowLocal, 0f, rowSc); });
                }
                else if (hl != null && hl.TryLastPose(v, out p, out ang, out sc))
                {
                    // ⛔ 不能退回 `CardFeel.DealIn`：它把 rot 收 0、scale 收 1，牌会停在**原尺寸**
                    //   （226 设计 px，手牌档应是 165 —— 实拍 `_tmp_view/ui_1019/17_battle.png` 量得）。
                    // 🆕 2026-10-16：`back:` = **翻面前半段那颗卡背**（判据 → `CardView.SetBackVisible`）。
                    //   贴图走**与牌堆/敌方手牌同一个口** —— `CardArt.CardBack(_myFaction)`
                    //   （`CardBackSprite` 就是拿它 `Sprite.Create` 出来的，同一张图；
                    //     卡背层要的是 `Texture2D` ⇒ 直接取源头那一支，判据仍只此一处，⛔ 别另挑一张）。
                    CardFeel.DealInPose(v, deck, p, ang, sc, dealDelay,
                                         back: CardArt.CardBack(_myFaction));
                }
                else
                {
                    // 排布表里没有它（理论上到不了）—— 退回老写法，并**出声**（⛔ 别静默）
                    Debug.LogWarning("[SyncHand] 新牌不在 HandLayout 最近一趟的排布表里，发牌落点退回读当时位置");
                    CardFeel.DealIn(v, deck, dealDelay);
                }
            }
        }

        /// <summary>这一轮新进手牌的视图（`SyncHand` 每轮重填）。自检断言用</summary>
        readonly List<CardView> _dealt = new List<CardView>();
        public int DealtCount { get { return _dealt.Count; } }
        public CardView DealtView(int i) { return i >= 0 && i < _dealt.Count ? _dealt[i] : null; }

        // ==================================================================
        //  敌方手牌 —— 原版 `PlayerHand` MB 4350 + `CardsHorizontalLayout` MB 4053
        //
        //  🔴 **2026-09-17 新加**：之前**这一整件都没有** —— 所以 `VarsGlobal.timeToDrawEnemyCard`
        //     一直没有落点（不是「单机用不上」，是**缺件**）。原版规格：`资料/敌方手牌_原版规格.md`。
        //
        //  原版那排牌**显示的是卡背**（`PlayerHand__SetupCardInHand.c:45` → `ShowCardBack(!isPlayer)`），
        //  所以我们这边用 `ImageQuad` 画卡背、**不建 `CardView`**（省掉立绘/卡框/文字那一整套）。
        //  🔴 **2026-10-16 订正**（原文：「原版抽牌那一瞬还会绕 Y 翻 180°（`TurnCardAround`）；
        //     我们是 2D，**没做那一下**」—— **两半都不准**）：
        //     ① 原版**敌方这一档【不翻】**：`CardScript__DrawCard.c:52-59` 判的是 `EntityScript.isPlayer`，
        //        `TurnCardAround` 只在 `isPlayer == true`（抽自己的牌）那一支；
        //     ② 我方那一下**已经补上了** —— `CardFeel.TurnCardAround`（两段各 90°、各占抽牌时长 0.25，
        //        判据与出处全在那个方法上面的头注里）。
        //     判据正本 → `资料/普查产出_1016战斗/W4_抽牌翻转与进墓地.md` §A。
        // ==================================================================

        /// <summary>敌方手牌区（原版 MB 4053 那一份）。由 `BattleScene` 建好接上；没有就不建敌方手牌</summary>
        public HandLayout foeHand;

        readonly List<ImageQuad> _foeHandViews = new List<ImageQuad>();
        readonly List<ImageQuad> _foeDealt = new List<ImageQuad>();

        /// <summary>敌方手牌视图数（自检断言用）</summary>
        public int FoeHandCount { get { return _foeHandViews.Count; } }
        /// <summary>这一轮新进敌方手牌的视图数（发牌入场用）</summary>
        public int FoeDealtCount { get { return _foeDealt.Count; } }
        public ImageQuad FoeHandViewAt(int i) { return i >= 0 && i < _foeHandViews.Count ? _foeHandViews[i] : null; }

        /// <summary>敌方手牌那张卡的屏幕高度（世界单位）= 卡高 × `m_scale 0.54` × 分辨率缩放</summary>
        static float FoeCardWorldH
        {
            get { return CardView.Height * HandLayout.EnemyCardScale * LayoutSpace.Scale; }
        }

        /// <summary>敌方手牌那张**卡背**（不是卡身）的屏幕高度（世界单位）——
        /// = 卡背节点自己那个 rect 的高 × `m_scale 0.54` × 分辨率缩放。
        ///
        /// <para>🔴 **2026-10-19（A1150）**：原版敌方手牌露出来的是 **卡背节点**
        /// （`2DCard/Cardback Container/Cardback` = `CardbackNodeRectW × CardbackNodeRectH`，
        /// 见那个常量的注释），而我们原来把它画成了**卡身**那个矩形
        /// （`FoeCardWorldH` / `CardView.Width ÷ CardView.Height`）—— 两个不是同一个矩形：
        /// 卡身比卡背节点**窄 3.74%**（2.0927 vs 2.1739）、**高 6.21%**（3.3313 vs 3.1364）；
        /// 再加上第二段 `padding` 内缩，两边的画心差得更多。</para>
        ///
        /// <para>⚠️ **手牌那一层的 px 桥是「1 卡单位 = 1 世界单位」**（`CardView.Width × cardScale`
        /// = 手牌卡宽 165 px @108 px/单位；见 `HandLayout` 文件头）—— 与**牌堆**那一层
        /// （`DeckCardPx` 的 ×100）**不是同一个桥**，⛔ 别混用（铁律 5·c）。</para></summary>
        static float FoeCardBackNodeWorldH
        {
            get { return CardbackNodeRectH * HandLayout.EnemyCardScale * LayoutSpace.Scale; }
        }

        /// <summary>敌方手牌卡背的**几何**（两段式）—— 尺寸与画心偏置都出自它。
        /// 框 = 卡背节点自己那个 rect（高 `FoeCardBackNodeWorldH`、宽 = 高 × `CardbackRectAspect`），
        /// 算法 → `Core/CardbackFace.cs`（**本仓唯一一份口径**，⛔ 别在这里另写一套）。
        /// 返回 `false` = 没有可用的几何（贴图为 null / 框非正）⇒ 调用方**不改几何、不挪位**
        /// （此时四个出参是 `Fit` 给的退化值：`w=boxW`、`h=boxH`、偏置 0）。</summary>
        static bool FoeHandBackGeom(Texture2D tex, out float w, out float h, out float dx, out float dyUp)
        {
            float boxH = FoeCardBackNodeWorldH;
            return CardbackFace.Fit(tex, boxH * CardbackRectAspect, boxH, out w, out h, out dx, out dyUp);
        }

        /// <summary>🆕 2026-10-19（B3 · 偏差 8 的载体）：敌方手牌卡背**画出来的世界宽度**
        /// （`CardbackFace.Fit` 第二段之后；0 = 还没量到 / 没卡背图）。
        /// 用途 = `StartAiDeployFlight` 换算「卡背要缩放到多大才和场上那张卡一样宽」——
        /// 那个比例只能由**这一份**几何算（⛔ 别在飞行那边再抄一遍 `CardbackFace.Fit` 的两段式）。</summary>
        float _foeBackWorldW;
        /// <summary>敌方手牌卡背画心的**槽位偏置**（世界单位；`CardbackFace.Fit` 给的那两个）。
        /// 🔴 **2026-10-22（E-C）**：从 `SyncFoeHand` 的局部变量提成字段 —— 换牌动画那 1 s 内要能**只重摆位姿**
        /// （`ReapplyFoeHandPoses`），而 `SyncFoeHand` 那一刻不会重跑。</summary>
        float _foeBackDx, _foeBackDyUp;

        void SyncFoeHand()
        {
            if (foeHand == null) return;
            var h = Ctx.Players[1 - _me].Hand;
            _foeDealt.Clear();

            // 🔴 **2026-10-19（A1150）**：卡背那一格的**尺寸 / 比例 / 画心偏置**一律出自
            //   `CardbackFace.Fit`（两段式，本仓唯一一份口径 → `Core/CardbackFace.cs`）；
            //   取图仍走 `CardArt.CardBack`（缺图那边会出声），本处不再自己 `SetAspect(卡身比例)`。
            //   ⚠️ 一把牌里每张用的都是**同一张**卡背（按 `_foeFaction` 取）⇒ 几何算**一次**就够。
            var backTex = CardArt.CardBack(_foeFaction);
            float backW, backH, backDx, backDyUp;
            bool backGeom = FoeHandBackGeom(backTex, out backW, out backH, out backDx, out backDyUp);
            _foeBackWorldW = backGeom ? backW : 0f;      // 🆕 B3：飞行载体用它算落点缩放（判据见那个字段）

            // 卡背视图按需增减（手牌只会一张张长；打到上限就停）
            while (_foeHandViews.Count < h.Count)
            {
                // 给的是**卡背节点**的高（`FoeCardBackNodeWorldH`）—— `A1150` 之前给的是卡身的高。
                var q = ImageQuad.Create(foeHand.transform, backTex, Vector3.zero,
                                         backGeom ? backH : FoeCardWorldH, new Vector2(0.5f, 0.5f),
                                         "FoeHand_" + _foeHandViews.Count);
                if (q == null) break;                       // 没卡背图就整个不建（别静默建一半）
                // 画心**不是**「铺满节点」：节点比例 == 该 sprite 的 `m_Rect` 比例 ⇒ 第一段（定框）
                // 是空操作，真正起作用的是第二段（按 `padding` 内缩 + 挪位）。
                if (backGeom) q.SetAspect(backW / backH);
                _foeHandViews.Add(q);
                _foeDealt.Add(q);
            }
            while (_foeHandViews.Count > h.Count)
            {
                var q = _foeHandViews[_foeHandViews.Count - 1];
                _foeHandViews.RemoveAt(_foeHandViews.Count - 1);
                if (q != null) Kill(q.gameObject);
            }

            int n = _foeHandViews.Count;
            _foeBackDx = backDx;
            _foeBackDyUp = backDyUp;
            ReapplyFoeHandPoses();

            // 🔴 **2026-10-21（第六十一会话 · 换牌残余 ①）**：换牌期**敌方手牌整排收起来** ——
            //   判据与做法**只在** `ApplyMulliganHudVisibility()` 一处（`UpdateHud` 每帧调的那个整层开关；
            //   这一排是世界空间 quad，`_hudLayer` 够不着它 ⇒ 那里单独扫 `_foeHandViews`）。
            //   ⛔ 别在这里再写一遍显隐（同一条规则的第二次实现）。

            // 发牌入场：从**敌方牌堆**飞进手牌，时长 = `VarsGlobal.timeToDrawEnemyCard` = 0.15
            if (animateFeel && _foeDealt.Count > 0)
            {
                var deck = LayoutSpace.ToWorld(FoeDeckX01, FoeDeckY01);
                // 🔴 2026-10-24（`A19` · `C1-A01`）：**逐张错开** —— 敌方步长 = `0.15 × 0.5`
                //   = **0.075 s/张**（判据全在 `DealStaggerFrac` 的 doc，⛔ 别在这里另写一份）。
                for (int i = 0; i < _foeDealt.Count; i++)
                {
                    var q = _foeDealt[i];
                    if (q == null) continue;
                    CardFeel.DealInQuad(q, deck, DealStaggerDelay(false, i));
                }
            }
        }

        /// <summary>敌方手牌那一排的**位姿**（槽位 + 卡背 `padding` 偏置；判据/注释 → `SyncFoeHand` 里原来那一段）。
        /// <para>🔴 **2026-10-22（E-C）拆出来**：换牌期补间那 1 s 内**没人会调 `SyncFoeHand`**（它只跟着
        /// `RefreshAll` 跑），而 `HandLayout.areaOffsetY` 每帧在变 ⇒ 动画泵那边要能**只重摆不改其它**
        /// （⛔ 别在那边抄一遍这段式子 —— 同一个口径只留这一处）。</para></summary>
        void ReapplyFoeHandPoses()
        {
            if (foeHand == null) return;
            int n = _foeHandViews.Count;
            for (int i = 0; i < n; i++)
            {
                var q = _foeHandViews[i];
                if (q == null) continue;
                var tr = q.transform;
                var rot = Quaternion.Euler(0f, 0f, foeHand.RotationAt(i, n));
                // 画心 = 槽位 + 偏置。🔴 偏置要**跟着张角转进卡自己的局部系**：原版那一跳是那颗
                // `Image` 的**网格**在自己的 rect 里按 `padding` 内缩 —— 网格当然跟着节点一起转；
                // 直接加在父件系里（不转）会让偏置与卡的姿态不一致（`A1150`）。
                // ⚠️ `rot * (dx, dyUp, 0)`：`dyUp` 向上为正（uGUI 的方向）—— 手牌这一层的世界坐标
                //    y 也是**向上**为正（`HandLayout.SlotPosition` → `LayoutSpace.ToWorld(nx, yFromBottom)`）
                //    ⇒ 这里**直接加**，⛔ 别反号（同 `FitDeckPile` 那条）。
                tr.localPosition = foeHand.SlotPosition(i, n) + rot * new Vector3(_foeBackDx, _foeBackDyUp, 0f);
                tr.localRotation = rot;
                tr.localScale = Vector3.one;
            }
        }

        /// <summary>手牌的「能不能打」高亮 —— **判据全部来自引擎**，这里不自己算费用。
        ///
        /// <para>🔴 **2026-10-21（第六十会话 · 真机缺陷：手牌被整片灰掉）**：原版战斗里**打不出 ≠ 变灰** ——
        /// 原版只是**不亮绿描边**，卡面照样全彩（判据：原版实拍 `桌面/warpforge参考图/战斗截图参考.png`
        /// 里 0 张灰卡；反编译 `PlayerHand__LightPlayableHand` → `BattleManager__CanPlayCard` →
        /// `CardScript__ActivateCard` 只走 `ToggleHighlight(false)` / `ChangeToHighlightColor`，
        /// **`_GreyScale` 的调用点只在收藏/菜单**）。我们原来把 `Unplayable` 一律 `SetGrey(1)`
        /// ⇒ 战术/防御卡（`IsUnit` 为假）**永远**被灰、敌方回合整手全灰。
        /// ⇒ 这里在 `SetHighlight` 之后**显式把手牌灰度清零**（`State` 仍保留 `Unplayable`，
        /// 描边/自检口径不动）；灰化本身别改 —— 换牌/选牌/卡池那三处是**故意**用它的。</para>
        /// <para>🔴 同批：`playable` 原来要求 `card.IsUnit` ⇒ 战术/防御卡**永远没有绿描边**（与原版不符）。
        /// 原版按「付得起 + 有可用目标/格位」亮，静态手牌那一眼**付得起就亮**（参考图里费用 3/5 两张
        /// 不亮、其余亮的判据就是费用）⇒ 非单位卡改成「`Cost >= 0` 且付得起」；单位卡仍要求有空格位。</para></summary>
        void RefreshHandPlayable()
        {
            bool myTurn = Ctx.Active == _me && !Ctx.IsOver;
            var p = Ctx.Players[_me];
            bool hasSlot = p.HasFreeSlot();

            for (int i = 0; i < _handViews.Count && i < p.Hand.Count; i++)
            {
                if (_handViews[i] == null) continue;
                var inst = p.Hand[i];              // 第 7 行第 2 步：手牌存实例
                var card = inst.Card;
                // `Cost < 0` = 原版 `manaCost = -1` 的哨兵（附魔模板）⇒ 不可直接打出（判据同 `RuleCore.CanPlayCard`）。
                bool playable = myTurn && card.Cost >= 0 && card.Cost <= p.Energy
                                && (card.IsUnit ? hasSlot : true);
                _handViews[i].SetHighlight(playable ? CardHighlightState.Normal
                                                    : CardHighlightState.Unplayable);
                // 🔴 原版手牌不灰：`Unplayable` 只表达「没描边」，不是去饱和。
                _handViews[i].SetGrey(0f);
                // 🆕 2026-09-19：原版卡面那圈 **`_Outline` 高亮描边**（打得出去才有，按 trait 分色、补间 0.2s）。
                //    判据只在 `CardHighlight.OutlineOf` 一处；这里把**只有引擎知道的**两样算好传进去：
                //      · `inst.DrawnThisTurn` —— 这一**份**是不是本回合从牌库抽到的（`Teleport` 那条要用它）；
                //      · `oathOk` —— 原版判据是 `manaLeft >= cost + oath值`（`CardDef.OathCost` 就是我们这边那个 N）。
                bool oathOk = card.OathCost > 0 && p.Energy >= card.Cost + card.OathCost;
                _handViews[i].SetOutline(CardHighlight.OutlineOf(card, playable, inst.DrawnThisTurn, oathOk));
            }
        }

        /// <param name="isPlayer">🆕 2026-10-24（`W20`）· **这张卡是不是我方的**（原版 `card+0x40`）。
        /// 场上徽标有一道闸只认它：敌方 + `ambush` ⇒ **整排一枚都不画**
        /// （`BattleCardUI__UpdateTraitIcons.c:40-46` → `Badges.For(..., isPlayer)`）。
        /// ⚠️ 默认 `true` 是给「不判断途」的调用点（卡面预览 / 牌堆视图那些）—— 它们本来就不该被这道闸管。
        /// 场上卡的两条路（`ToBoardCardData` / `ToggleUnitCard`）**必须显式传**。</param>
        CardData ToCardData(UnitState u, string faction, bool isPlayer = true)
        {
            var fb = u.Card != null ? FaceTextFull(u.Card) : new FaceBody(DescribeKeywords(u), "desc");
            // 🆕 场上的 buff/debuff 徽标（原版 `BattleCardUI.UpdateTraitIcons`）——
            //    喂的是**当前**关键词表（加/减益、光环、限时增益到期全跟着变），
            //    顺序用卡面效果文字当提示（玩家在卡上读到的词序），判据与出处见 `Core/Badges.cs`。
            //    另外两样（角标的「带不带数值」、图标的「激活/未激活」）也都照原版那两条判据传进去。
            //    🆕 2026-10-24（`W20`）：第四样 `isPlayer`（敌方伏击整排不画）由调用方给。
            var badges = Badges.For(u.Keywords, fb.body,
                                    u.Card != null ? u.Card.NumericKeywords : null,
                                    key => KeywordActive(u, key),
                                    isPlayer);
            return new CardData
            {
                // `id` 保持英文 —— 它兼着**显示名 / 配对**的活（`SyncHand` 按它对名字），**别拿它取图**
                id = u.Name,
                // 立绘/抠图清单的文件键：**引擎卡 id**（2026-09-15 起立绘按 id 命名）
                artId = u.Card != null ? ArtKey(u.Card) : null,
                // 🆕 2026-10-17（`N42`）：有 `CardDef` 就走按卡 id 取的那一口（非中英语档才是官方 13 语言卡名）
                title = u.Card != null ? CardText.Name(u.Card) : CardText.Name(u.Name),
                cost = -1,
                melee = u.Attack,
                ranged = u.RangedAttack,
                health = u.Health,
                armor = u.Armor,          // 场上是**当前**护甲（会被效果改），原版卡面显示的也是当前值
                keywords = fb.body,
                badges = badges,
                isUnit = true,
                frame = FactionColor(faction),
                faction = faction,
                rarity = u.Card != null ? u.Card.Rarity : null,   // 卡框按稀有度分四档
                subtype = u.Card != null ? u.Card.Subtype : "",     // 卡面下方的兵种行（`RaceText`）
            };
        }

        /// <summary>
        /// 立绘 / 抠图清单的**文件键**。
        /// · **原版卡**：引擎卡 id（`UM82` 这种）—— 2026-09-15 起立绘按 id 命名
        ///   （原来按卡名，同名跨阵营会互相覆盖，见 `CardData.artId`）。
        /// · **我们自己设计的那 26 张**：没有引擎 id（也不在卡表里），`import_original_art.py`
        ///   的 `PORTRAITS` 就是按**卡名**导的 ⇒ 用卡名。
        /// ⚠️ 判据只有 `FromOriginalPool` **一处**，别在别处再写第二份。
        /// </summary>
        public static string ArtKey(CardDef c)
        {
            if (c == null) return null;
            return c.FromOriginalPool ? c.Id : c.Name;
        }

        /// <summary>
        /// 🆕 2026-09-29 **徽标的「激活 / 未激活」**（原版 `CardTrait.IsActive(card)`，
        /// 就是 `BoardTraitIcon.Initialize` 的第 4 个参数）。
        ///
        /// 🔴 **原版只有两个子类覆写了它**（`d:/2/tools/decomp_full/`，逐个读过）：
        /// · `CardTraitDuty__IsActive.c:19` = `return *(char *)(card + 0x4c) == 0;`
        ///   —— `0x4C` = `EntityScript.usedActiveAbility`（`dump.cs` 字段表）
        ///   ⇒ **本回合用过主动能力 ⇒ Duty 变灰**。
        /// · `CardTraitOath__IsActive.c:26` = `CardScript.CanUseOathAbility(card)`
        ///   ⇒ **当前激活不了誓约（次数用完 / 不是本回合上场 / 付不起那 N 点能量）⇒ Oath 变灰**。
        /// · 其余**全部恒 true** —— `CardTrait__IsActive.c` 的符号被 Ghidra 撞到了别的函数上
        ///   （正文是 `return 1;`），基类返回 false 是不可能的（那会让**所有**徽标都变灰）⇒ 按 true 落地。
        ///   ⚠️ `CardTraitFerocity__IsActive.c` **同一个撞击符号**，所以 `Ferocity` 那一条**判不了**，
        ///   我们按「基类恒 true」处理，如实记在这儿（不猜）。
        ///
        /// ⚠️ **别拿 `Exhausted` 顶替 `Duty` 那一条** —— 攻击也会置 `Exhausted`，而原版只认「主动能力」。
        /// </summary>
        bool KeywordActive(UnitState u, string key)
        {
            if (key == KeywordTable.Duty) return !u.UsedActiveAbilityThisTurn;
            if (key == "oath")
            {
                int ow, sl;
                if (!FindOnBoard(u, out ow, out sl)) return true;   // 不在场上 ⇒ 原版「非 CardScript ⇒ true」
                return RuleCore.CanUseOathAbility(Ctx, ow, sl) == RuleCodes.OK;
            }
            return true;
        }

        /// <summary>在棋盘上找这个单位，拿它的 owner / slot（徽标判据要问引擎）。
        /// 同一个 `UnitState` 在场上只会出现一次（引擎的实例身份），所以按引用比就够，不必比名字。</summary>
        bool FindOnBoard(UnitState u, out int owner, out int slot)
        {
            for (int p = 0; p < 2; p++)
            {
                var b = Ctx.Players[p].Board;
                for (int s = 0; s < b.Length; s++)
                    if (ReferenceEquals(b[s], u)) { owner = p; slot = s; return true; }
            }
            owner = -1; slot = -1;
            return false;
        }

        /// <summary>⚠️ public static 是给 `CardFaceProbe`（单卡渲染量尺）用的：卡面数据必须**只有这一条路**。</summary>
        public static CardData ToCardData(CardDef c, string faction)
        {
            return new CardData
            {
                id = c.Name,                       // 同上：显示名/配对用它
                // 🆕 2026-10-17（`N42`）：同上 —— 按 `CardDef` 取（非中英语档 = 官方 `Card_Name/<id>`）
                title = CardText.Name(c),
                cost = c.Cost,
                melee = c.Attack,
                ranged = c.RangedAttack,
                health = c.Health,
                armor = c.KwValue(KeywordTable.Armour),   // 手牌里显示的是卡面印的护甲
                keywords = FaceTextFull(c).body,          // 记号已换成 `<sprite …>`
                artId = ArtKey(c),
                isUnit = c.IsUnit,
                frame = FactionColor(faction),
                faction = faction,
                rarity = c.Rarity,                 // 卡框按稀有度分四档
                subtype = c.Subtype,               // 卡面下方的兵种行（**印不印由 CardView.SubtypeLine 判**）
                type = c.Type,                     // 判「印不印兵种行」要用它（`hero`/`defence` 也印）
            };
        }

        /// <summary>卡面效果正文 + 它出自哪个字段 + 卡表稳定 id（**图标计划表按 id 查**）。</summary>
        public struct FaceBody
        {
            public string body;
            /// <summary>`"descZh"` 或 `"desc"`（空正文时是 `"desc"`）</summary>
            public string field;
            public FaceBody(string b, string f) { body = b; field = f; }
            /// <summary>⚠️ 故意留的隐式转换：调用方（自检里那些字符串断言）当它是 string 用。</summary>
            public static implicit operator string(FaceBody f) { return f.body; }
        }

        /// <summary>
        /// 卡面那行小字 —— **卡面文案只有这一条路**（`CardFaceProbe` 也走它，另写一份迟早不一致）。
        /// · **原版卡**（`FromOriginalPool`）：写**它自己的效果原文**
        ///   （🆕 2026-10-19 `A1945` 方案 A 起：**中/英两档优先取官方 `Card_Description/<id>`**，
        ///   取不到才回 `DescZh` / `Desc`；其余 10 种语言仍走 `Loc.Lang13Current`）
        ///   —— 原版卡面上印的就是这段字。`desc` / `descZh` 数据与解析路径**一字节不动**。
        /// · **我们自己设计的 26 张**：写**引擎结算得到的关键词**（`Desc` 对我们那 26 张是风味文字，不是效果）。
        /// 两边都**把引擎结算不了的部分打 `*` 附在后面**（红线：不许静默失败）。
        ///
        /// 🔴 **卡面图标就在这一处换掉**（`card_icon_plan.json` 按**稳定 id + 字段名**查，
        /// 见 `资料/卡面图标_现状与缺口.md` §二之三）。为什么放在这里：
        /// **所有**画这段文字的地方（卡面 / 放大展示窗 / 单卡探针）都经过 `CardData.keywords` ——
        /// 分散到各个渲染器里做，迟早漏一处，变成「有的地方有图标有的地方没有」。
        /// 查不到 / 计划表里记的是缺口 ⇒ **原样返回**（红线：宁可难看，不给错图标）。
        /// </summary>
        /// <summary>🆕 2026-10-19（`A1945` · 方案 A，用户当天拍板）：**卡面显示文本不取官方表的白名单（非缺陷）**。
        /// <para>🔴 **2026-10-19 写手现核新发现 4 张（全部拿 PnP 成品卡亲读裁定，⛔ 不是猜）** ——
        /// 与 `ASH48` / `SOR25` 同类：**官方文本缺句 / 换了关键词**，直接采用会静默少一条效果。
        /// 逐条判据 → `资料/普查产出_1019/W_卡牌线_A1945官方显示_1019b.md`。</para>
        /// <para>· `ASH48 Cosmic Serpent` —— 官方 EN/ZH **后半句整段缺失**（`2 [Spirit Stone]: Repeat this effect`
        /// 在 I2 表里没有；PnP `Aeldari/4计策/Warpforge_52_Cosmic-Serpent.png` 有）⇒ 照旧用我们的。</para>
        /// <para>· `SAU58 Implacable Conqueror` —— 官方 EN/ZH 都缺 `Draw a troop` / `抽一张军队牌`
        /// （PnP `Necron/4计策/Warpforge_58_Implacable-Conqueror.png` 印着这句）。</para>
        /// <para>· `SAU15 Deathmark` —— 官方 EN/ZH 都缺 `Rally: If you control no other troops, gain Stealth`
        /// （PnP `Necron/3部队/Warpforge_21_Deathmark.png` 印着这句）。</para>
        /// <para>· `TAU65 War Shaper` —— 官方 EN/ZH 都缺 `Strike: Heals 1` / `猛击：治疗 1`
        /// （PnP `Tau/1督军/Warpforge_01_War-Shaper.png` 印着这句）。</para>
        /// <para>· `AM72 Vitus Gryf` —— 官方写 `[[slay]]: Deploy a $$AM71$$`，PnP
        /// `Astra Militarum/3部队/Warpforge_08_Vitus-Gryf.png` 印的是 `Strike: Deploy a Tempestus Aquilon`
        /// ⇒ **关键词分歧**；⚠️ **2026-10-21 第六十会话亲读 PnP 复核**：卡面印的就是 `Strike`（与 `TAU65` 同一颗红骷髅图标），
        /// 官方的 `[[slay]]` 是错的 ⇒ 沿用我们的。</para>
        /// <para>· `SOR25 Imagifier` —— 官方只写 `flank`，我们多 `+1 [Attack], +1 [Ranged]`
        /// （**2026-10-21 第六十会话亲读 PnP 已裁**：`Sorotitas/3部队/Warpforge_29_Imagifier.png` 印着
        /// `+1 [近战], +1 [远程] and Flank to a friendly troop` ⇒ **我们是对的、官方表缺**）⇒ 照旧用我们的。</para>
        /// <para>⛔ **不在这张表里的卡一律优先取官方**；`desc` / `descZh` 数据与解析路径一字节不动。
        /// 加卡必须有判据 + 日期，逐条清单见
        /// `资料/普查产出_1019/W_卡牌线_A1945官方显示_1019b.md`。</para></summary>
        static readonly HashSet<string> OfficialFaceTextWhitelist =
            new HashSet<string> { "ASH48", "SAU58", "SAU15", "TAU65", "AM72", "SOR25" };

        /// <summary>自检用（`A1945`）：这张卡是不是「不取官方显示文本」的白名单卡（⛔ 不改任何状态）。</summary>
        public static bool IsOfficialFaceTextWhitelisted(string id)
        {
            return !string.IsNullOrEmpty(id) && OfficialFaceTextWhitelist.Contains(id);
        }

        public static FaceBody FaceTextFull(CardDef c)
        {
            if (c == null) return new FaceBody("", "desc");
            if (!c.FromOriginalPool) return new FaceBody(DescribeKeywords(c), "desc");

            // 🔴 **2026-10-18（同批顺带修，铁律 5）**：原来写 `bool zh = !string.IsNullOrEmpty(c.DescZh);`
            //   —— 那是「**这张卡有没有中文**」，**不是**「**当前语档是不是中文**」⇒ **绕过 `CardText.Zh`**：
            //   切成 English 之后卡名（`ToCardData` 走 `CardText.Name`）变英文、而**卡面正文仍印中文**
            //   （半中半英）。这是 `Core/CardText.cs` 那一族缺陷的**第三处**，见 `CardDisplayName` 的 doc。
            //   ⚠️ `zh` 同时决定 `CardIcons.Rewrite` 取哪一份图标计划（`descZh` / `desc`）——
            //   英文档下本来就该用英文那一份 ⇒ 这一改**顺带把图标也对齐**。
            bool zh = CardText.Zh && !string.IsNullOrEmpty(c.DescZh);
            string body = zh ? c.DescZh : c.Desc;
            // 🆕 2026-10-19（`A1945` · 方案 A，用户当天拍板）：**中/英两档的卡面正文也优先取官方表** ——
            //   `Loc.OfficialCurrent("Card_Description/<卡 id>")`（中文档取官方 zh 列、该列为空则回退 en 列；
            //   英文档取 en 列），取不到才回落到上面那两行（`DescZh` / `Desc`）。
            //   ⛔ **`desc` / `descZh` 数据与解析路径一字节不动**：引擎唯一的解析输入仍是 `CardDef.Desc`
            //     （`EffectText.Parse` / `IsFullyParsed` 那些）；本处只换【渲染出来的串】——
            //     与 `CardIcons.Rewrite` 的「只改渲染、`CardDef.Desc` 原样」是同一条纪律。
            //   🔴 **两个白名单（非缺陷，⛔ 别当缺口「修」掉）**：见 `OfficialFaceTextWhitelist`
            //     （`ASH48` 官方后半句截断 · `SOR25` 内容分歧待 PnP 裁）。
            //   ⚠️ 官方文本里的 `[[..]]` / `((..))` / `$$..$$` 记号**不在这里处理**：下面 `CardIcons.Rewrite`
            //     那一行按 `HasOfficialMarks` 分流到 `RewriteMarks`（原版四支），⛔ 不会把原始 XML 印到卡面。
            //   ⚠️ **中文档但中文字体资产缺失**（`CardText.Zh == false`）⇒ 取**英文列**
            //     （`Loc.OfficialEnglish`，与 `CardText.TermOr` 那条字体闸同一口径），⛔ 否则会印方块。
            //   ⚠️ 其余 10 种语言不走这里（`OfficialCurrent` 对它们恒 null）—— 仍旧走下面那条 `Lang13Current`。
            if (!string.IsNullOrEmpty(c.Id) && !OfficialFaceTextWhitelist.Contains(c.Id))
            {
                string off = null;
                if (zh) off = Loc.OfficialCurrent("Card_Description/" + c.Id);
                else if (Loc.Current == AvailableLanguages.Chinese)
                    off = Loc.OfficialEnglish("Card_Description/" + c.Id);
                else if (Loc.Current == AvailableLanguages.English)
                    off = Loc.OfficialCurrent("Card_Description/" + c.Id);
                if (!string.IsNullOrEmpty(off)) body = off;
            }
            // 🆕 2026-10-17（`N42`）：**非中英语档 ⇒ 官方 `Card_Description/<卡 id>` 的当前那一列**
            //   （中/英两档 `Loc.Lang13Current` 恒 null ⇒ 这两档由上面 `A1945` 那段 official 优先处理）。
            //   缺键 / 缺列 ⇒ 回退英文 `c.Desc`（`Loc.Lang13Current` 已出声一次，⛔ 不静默、⛔ 不印键名）。
            if (!zh && Loc.Current != AvailableLanguages.Chinese && Loc.Current != AvailableLanguages.English)
            {
                string v13 = string.IsNullOrEmpty(c.Id) ? null : Loc.Lang13Current("Card_Description/" + c.Id);
                if (!string.IsNullOrEmpty(v13)) body = v13;
            }
            string notes = string.Join(" ", UnimplementedNotes(c).ToArray());
            // 🔴 **2026-10-12（第二十三会话新立 `A1687`）：关键词段必须在【空正文早退】之前算。**
            //   原来这一行排在上面 ⇒ **正文为空的卡整段关键词行被吞掉**（`KeywordSegment` 在它下面）。
            //   **原版卡面确实有这种卡**：`GOF8 Hornhelmz' Boy`（`desc`/`descZh` 双空、`keywords:["Tide 2"]`；
            //   卡面**主对话 2026-10-12 亲读**（`d:/2/Warpforge部队卡片/Orks/3部队/Warpforge_12_Hornhelmz-Boy.png`，900×1200）：效果区**只有 `〔骷髅〕Tide 2`**、没有别的效果文字
            //   （⚠️ 那张印刷卡把卡名印成 `Hornhelmz' Boy`、带撇号。**2026-10-18（`W28`）起我们的卡名也照官方显示名改成 `Hornhelmz' Boy`** —— 用户当天改判：「卡名一个字不动」那条 PnP 时代口径**作废**；授权键表 `数据/本地化/i18n/zh_CN.csv:1693` 仍写 `Hornhelmz Boy`（**键表不改**）。）
            //   现扫全池 1126 张：`desc`/`descZh` 双空 **6 张**（`ASH12` `BL11` `BL43` `GOF12` `TL12` `UM14`），
            //   **只有 `GOF12` 带关键词** ⇒ 今天影响面 = 1 张，但形状是坏的（铁律 11 要做）。
            //   ⚠️ **其余 1125 张输出一字不变**：关键词为空的卡 `seg == ""` ⇒ 与改前逐字相同；
            //     而且 `KeywordSegment` 自己吃得下空正文（`hay = body ?? ""`、`DeclaredInBody("")` 恒假）。
            string seg = CardText.KeywordSegment(c.Keywords, zh, body, c.NumericKeywords);
            if (string.IsNullOrEmpty(body)) return new FaceBody(seg + notes, "desc");

            // 🔴 **图标就在这一处换掉**（`card_icon_plan.json` 按**稳定 id + 字段名**查）。
            //    查不到 / 计划表里记的是缺口 ⇒ **原样返回**（红线：宁可难看，不给错图标）。
            string core = CardIcons.Rewrite(c.Id, zh ? "descZh" : "desc",
                                            string.IsNullOrEmpty(notes) ? body : body + "  " + notes);
            // 🆕 **关键词段补在最前面**（原版卡面就是「关键词 → 效果文字」这个顺序，
            //    见 `资料/PnP卡图_逐张对账_0915.md` §四·E：1130 张里 306 张的关键词
            //    在 `desc` 里一个字都没有）。
            //    ⚠️ 判据用**原始 body**，不能用 `core` —— 那里面已经多了 `<sprite …>` 标签，
            //       会把它自己补的那一段又判成「已经印过」。
            //    🔴 **`c.NumericKeywords` 必须传**（`A1341`）：`KeywordSegment` 判「这个词印不印数字」
            //       走 `Badges.CarriesValue` 的三档并集，其中**「卡面原文里写了数字」那一档的来源就是这个
            //       `c.NumericKeywords`** —— 不传（吃默认的 `null`）⇒ 那一档**静默失效**、
            //       与徽标（`Badges.For`）那一路裂开。⛔ 只改 `KeywordSegment` 的签名而不改这一行
            //       = 静默偏一半（`A1332` 立的账，`A1341` 两处同批改）。
            return new FaceBody(seg + core, zh ? "descZh" : "desc");
        }

        /// <summary>关键词 → 卡面上那行小字（只列**引擎真的会结算**的）。
        /// 文案走 `CardText`：拿得到中文字体就是中文，拿不到就是大写英文。</summary>
        static string DescribeKeywords(UnitState u)
        {
            var parts = new List<string>();
            if (u.Has(KeywordTable.Vanguard)) parts.Add(CardText.Keyword(KeywordTable.Vanguard));
            if (u.Has(KeywordTable.Flying)) parts.Add(CardText.Keyword(KeywordTable.Flying));
            if (u.Has(KeywordTable.Stealth)) parts.Add(CardText.Keyword(KeywordTable.Stealth));
            if (u.Has(KeywordTable.LongRange)) parts.Add(CardText.Keyword(KeywordTable.LongRange));
            if (u.Armor > 0) parts.Add(CardText.Keyword(KeywordTable.Armour) + " " + u.Armor);
            if (u.HasShield) parts.Add(CardText.Keyword(KeywordTable.Shield));
            parts.AddRange(EffectNotes(u.Card));
            parts.AddRange(UnimplementedNotes(u));
            return string.Join(" ", parts.ToArray());
        }

        static string DescribeKeywords(CardDef c)
        {
            var parts = new List<string>();
            if (c.Has(KeywordTable.Vanguard)) parts.Add(CardText.Keyword(KeywordTable.Vanguard));
            if (c.Has(KeywordTable.Flying)) parts.Add(CardText.Keyword(KeywordTable.Flying));
            if (c.Has(KeywordTable.Stealth)) parts.Add(CardText.Keyword(KeywordTable.Stealth));
            if (c.Has(KeywordTable.LongRange)) parts.Add(CardText.Keyword(KeywordTable.LongRange));
            if (c.Has(KeywordTable.Armour)) parts.Add(CardText.Keyword(KeywordTable.Armour) + " " + c.KwValue(KeywordTable.Armour));
            if (c.Has(KeywordTable.Shield)) parts.Add(CardText.Keyword(KeywordTable.Shield));
            parts.AddRange(EffectNotes(c));
            parts.AddRange(UnimplementedNotes(c));
            return string.Join(" ", parts.ToArray());
        }

        /// <summary>
        /// 触发类关键词 + 主动技能 → 卡面小字（`RALLY DMG1 FOE` / `ABILITY HEAL2 OWN`）。
        ///
        /// ⚠️ 带了关键词但**效果原文解析不出来**的，照样列出来、但打成 `*`
        ///    （`RALLY*`）。「关键词实现了」和「这张卡的效果能跑」是两件事 ——
        ///    不标的话玩家会以为它有作用，那比不显示更不诚实。
        /// </summary>
        static List<string> EffectNotes(CardDef c)
        {
            var list = new List<string>();
            if (c == null) return list;

            string[] triggers =
            {
                KeywordTable.Rally, KeywordTable.Strike, KeywordTable.Slay,
                KeywordTable.Backlash, KeywordTable.Penitence,
            };
            foreach (var kw in triggers)
            {
                if (!c.Has(kw)) continue;
                var spec = c.Effect(kw);
                list.Add(spec != null ? CardText.Keyword(kw) + " " + CardText.Effect(spec)
                                      : CardText.Keyword(kw) + "*");
            }

            if (c.Has(KeywordTable.Ability))
                list.Add(c.Ability != null
                         ? CardText.Keyword(KeywordTable.Ability) + " " + CardText.Effect(c.Ability)
                         : CardText.Keyword(KeywordTable.Ability) + "*");

            return list;
        }

        /// <summary>
        /// 卡上带了但**本版引擎不结算**的关键词，用 `*` 标出来。
        /// 不标的话玩家会以为它有作用 —— 这比直接不显示更诚实。
        /// </summary>
        static List<string> UnimplementedNotes(UnitState u)
        {
            var list = new List<string>();
            foreach (var kv in u.Card.Keywords)
                if (!KeywordTable.Implemented.Contains(kv.Key))
                    list.Add(CardText.Keyword(kv.Key) + "*");
            return list;
        }

        static List<string> UnimplementedNotes(CardDef c)
        {
            var list = new List<string>();
            foreach (var kv in c.Keywords)
                if (!KeywordTable.Implemented.Contains(kv.Key))
                    list.Add(CardText.Keyword(kv.Key) + "*");
            // 战术卡的**效果文字**能不能结算，和「关键词实现了没有」是两件事：
            // 关键词全实现了，效果照样可能解析不出来（原版卡面是英文自然语言）。
            // 解析不了的就在卡面打 `*` 说明白 —— 红线：不许静默失败。
            // 判据共用 `EffectText.IsFullyParsed`（和 `CanPlayTactic` / `DeckBuilder.TacticPlayable` 同一份）。
            //
            // 🔴 **2026-09-16：不再只判战术卡**（原来是 `if (c.Type == "tactic")`）——
            //    单位卡 / 督军卡 / 防御卡的问题**卡面永远看不见**，而那正是红线要挡的东西。
            //    实测（`_tmp_view/willrun_mechanism.md`）：改之后多出的 `*` 落在
            //    **unit 7 张 + defence 3 张**（hero 56/56 全通），面很小、值得。
            //    ⚠️ 判据同时换成 `EffectText.WillRunOps`（**按卡类型问对的层**，见那边的注释）——
            //       单位卡/督军卡**不许走 `IsFullyParsed(c.Desc)`**：它们的 `desc` 带
            //       `Rally:` / `When <事件>,` 前缀，主解析器永远判不「完全解析」，
            //       那是**问错了层**（2026-09-16 中文对账那轮 12 条假阳性的来源）。
            if (c.Type == "tactic" || c.Type == "defence")
            {
                // ⚠️ 两条**合成一句**（别打两个 `*`）—— 有的卡两样都占
                //    （`Mekaniak` 那种：解析得出来、载荷没机制）。
                bool parsed = EffectText.IsFullyParsed(c.Desc);
                if (!parsed) list.Add("效果本版结算不了*");
                else if (MechanismFails(c)) list.Add("效果本版没作用*");
            }
            else if (MechanismFails(c))
            {
                // `unit` / `hero`：只判「会执行的那一层有没有机制」，
                // **不判** `IsFullyParsed`（理由见上）。
                list.Add("效果本版没作用*");
            }
            return list;
        }

        // ── 「解析得出来、但载荷没有机制」那一条（2026-09-15 补）

        /// <summary>
        /// 🔴 **卡面那个 `*` 原来只看「解析得出来没有」，不看「载荷有没有机制」**
        /// ⇒ ③ 栏那几张（能打出去、但打了什么也不会发生，如 `Mekaniak`）**卡面不打 `*`**，
        /// 只有覆盖率报表看得见 —— 正是红线禁止的「玩家以为它有作用」。
        /// 判据转调 <see cref="EffectText.OpHasMechanism"/>（**与覆盖率报表同源，不写第二份**）。
        ///
        /// ⚠️ 判据源换成了 **`EffectText.WillRunOps`**（2026-09-16）——
        ///    原来是 `EffectText.Parse(c.Desc)`，那对**单位卡是问错了层**
        ///    （它们的正文在事件层/触发层里，主解析器的输出是没人执行的残渣）。
        ///    对 `tactic`/`defence` 两者**是同一份东西**（`WillRunOps` 内部就走主解析器）。
        /// ⚠️ `createPool` 传**全卡池** —— 覆盖率报表也是这么传的
        /// （`RuleEngineTest.cs` 三处 `EffectText.Coverage(pool, t, pool)`），两边必须一致。
        /// ⚠️ 结果**按卡 id 缓存**：卡面每次刷新都会问一遍，而解析一段自然语言不便宜。
        /// </summary>
        static readonly Dictionary<string, bool> _mechFail = new Dictionary<string, bool>();

        /// <summary>🆕 **2026-10-18（T09）**：`MechanismFails` 用的卡池 —— **只读、进程级存一份**。
        /// 🔴 原来每张卡都调一次 `CardDatabase.Load()`；本函数是**逐卡**调的，而 `Load()` 当时**没有缓存**
        /// ⇒ 每张卡都要 `JsonUtility.FromJson` 重解析 1127 张（实测 **2.4 s/卡**）——
        /// 这就是 T09「首次开窗 48.9 s」的根因（探针：`UnimplementedNotes` 单卡首次 2,477 ms / 暖 0.23 ms）。
        /// `Load()` 现在自带缓存（并返回浅拷贝）；这里再存一份**引用**，避免逐卡浅拷贝。
        /// ⚠️ 本函数只读这个列表（`OpHasMechanism` 的形参是 `IReadOnlyList`）⇒ 存引用安全。</summary>
        static List<CardDef> _mechPool;

        static bool MechanismFails(CardDef c)
        {
            if (c == null || string.IsNullOrEmpty(c.Id)) return false;
            bool fail;
            if (_mechFail.TryGetValue(c.Id, out fail)) return fail;

            var pool = _mechPool;
            if (pool == null)
            {
                pool = CardDatabase.Load();
                // 🔴 **2026-10-18（RV 复核·低）**：`Load()` 在**资源缺失**时返回空表且明确**不缓存**那一档
                //   （`CardDatabase.cs` 的 `Load`）；这里若把空表存进 `_mechPool` 就把它**锁死**了 ⇒
                //   之后所有卡的机制判定都拿空 createPool（多标 `*` 且无声）。空表**不缓存**。
                if (pool.Count > 0) _mechPool = pool;
            }
            var ops = EffectText.WillRunOps(c);
            fail = false;
            foreach (var op in ops)
            {
                string why; bool imprecise;
                if (!EffectText.OpHasMechanism(op, c.Faction, pool, out why, out imprecise))
                { fail = true; break; }
            }
            _mechFail[c.Id] = fail;
            return fail;
        }

        // ==================================================================
        //  HUD
        // ==================================================================

        void BuildHud()
        {
            // ⚠️ **只能建一次**：HUD 的结构不随对局变，变的只是字。
            //    重开一局（「按 R 重开」）会再走一遍 `Begin()` → `BuildHud()`，
            //    再建一份的话屏幕上会**叠两层 HUD**，而且**旧的那个结算面板成了孤儿**——
            //    `_endPanel` 已经指向新建的那个，旧面板再也没人 `Hide()`，就一直挂在画面上
            //    （2026-09-12 接「再来一局」时截图抓到的：新一局已经开打，上一局的
            //     「对局结束 / 三个骷髅 / 2/3」还压在战场上）。
            if (_hudBuilt) return;
            _hudBuilt = true;

            // 🔴 **2026-10-11（A218）判「不改」**（这一处**故意**保持**裸 `Transform`**）：
            //    判据 = 原版这一件就是裸 `Transform` —— `bundle_scenes_scenes_battlearena1` 实读：
            //    `BattleHud`（go_pid 239）= **`Transform`**（HUD 那一整棵树是它的孙辈，uGUI 的 `Canvas`
            //    才在它下面），而不是 `RectTransform`。
            //    ⚠️ 它与「窗口根」不同族：我们的 `HudRoot` 就是原版 `BattleHud` 那一级（**不是** `Canvas`）
            //    ⇒ 补 `RectTransform` + 编一个尺寸 = 造一个**与原版相反**的类型（铁律 3：查不到就别编）。
            var hudGo = new GameObject("HudRoot");
            hudGo.transform.SetParent(transform, false);
            hudRoot = hudGo.transform;
            var root = hudRoot;      // 下面所有 HUD 件都挂这个根（原来直接挂 `transform`）

            // ---- 🔴 2026-10-21（第六十一会话 · 换牌残余 ①）：战斗 HUD 那一整层的容器 ----------------
            // 判据与「原版是隐藏不是压暗」的逐条出处 → `_hudLayer` 的 doc。这里只做两件事：
            //   ① 在根画布下建一块**铺满**的 `RectTransform`（归一化锚点与画布逐位同尺 ⇒ 建件口
            //      照旧用 `x01/y01`，几何一个数都不变）；② 换牌期整层 `SetActive(false)`（见 `UpdateHud`）。
            // ⚠️ 建不出来（根画布没立）⇒ `_hudLayer` 留 null ⇒ `Hud()`/`HudImageTex()` 退回**根画布**
            //   （与加这一层之前逐位相同）—— 但那条路上换牌期的 HUD 就藏不掉，所以要出声。
            {
                var cvRoot = HudCanvas.Ensure(cam);
                if (cvRoot != null)
                {
                    var lgo = new GameObject("BattleHudLayer", typeof(RectTransform));
                    lgo.transform.SetParent(cvRoot, false);
                    _hudLayer = (RectTransform)lgo.transform;
                    HudCanvas.FillParent(_hudLayer);
                    // 🔴 收起/放回用 **`CanvasGroup`**（不是 `SetActive`）—— 理由见 `ApplyMulliganHudVisibility`。
                    _hudGroup = lgo.AddComponent<CanvasGroup>();
                    // 🔴 **必须把这一层也登记进根画布那本 z 账**（2026-10-21 现核）：
                    //   `HudCanvas.Group.Add` 的下标是**只在登记过的子件之间**算的
                    //   （`rt.SetSiblingIndex(i)`，`i` 不含未登记的兄弟）⇒ 不登记的话，之后每建一颗
                    //   登记件都会把它从 index 0 **往后挤一格**，最后整层 HUD 反而排到
                    //   **等待横幅（z −0.45）/ 黑边填充（z 5）之后** ⇒ HUD 盖住等待横幅（静默、只在运行时现形）。
                    //   🔴 **2026-10-21（第六十一会话 · `G2`）就地订正**：本行原来写「取一个**远大于所有 HUD 件**
                    //   的 z（填充件最大 5）⇒ 本层恒排最前」并传 **1000** —— **不成立**：那会把两枚黑边件
                    //   （`ZFiller = 5f`）从子件序 0/1 挤到 1/2，而原版它们是 `BattleHud/Canvas` 的
                    //   `m_Children[0]/[1]`（画在所有 UI **之下**）⇒ 黑边反而盖在整层 HUD 之上（1 条红）。
                    //   ⇒ 取 **(0.6, 5) 之间 = 4.9**：> 底板 0.6 / 字 0（HUD 件都在本层内部，与外层兄弟序无关），
                    //   < 5（两枚黑边件仍在**本层之下**）；其余根画布直子件（等待横幅 −0.45 / 回放条 0.3 /
                    //   排次表（`SubCanvasRank`）里的子画布排末尾）都比它小 ⇒ 相对次序与加这一层之前一致。
                    //   判据 → `资料/普查产出_1021/W61_战斗线_BattleScene47红诊断.md` §3·G2。
                    HudCanvas.Add(_hudLayer, 4.9f);
                }
                else
                {
                    Debug.LogWarning("[Battle] 根画布没建起来 ⇒ 战斗 HUD 那一层容器 `BattleHudLayer` 不建"
                                   + "（HUD 仍建在根画布下；**换牌期整层隐藏**这一条会失效）");
                }
            }
            CardArt.Load();

            // 🆕 **2026-10-24（执行代理 `W20`）**：把「拖拽起手就点亮合法目标 + 准星」接到选择器上。
            //   `AttackSelector.Show()` 展开完成的最后一刻会**幂等**地打一次这个回调
            //   （`RequestPreviewTargets`；一次展开只发一次）—— 判据 = 原版
            //   `BattleManager__StartAttackFrom.c:20-40`（`Toggle(true)` → `ToggleCrosshair(true)` →
            //   `ShowPotentialTargets`，三步同一个方法、**玩家还没选打法**）。
            //   ⚠️ 回调为 `null` ⇒ 选择器什么都不做（= 与接线之前逐位相同）⇒ 这一句必须在**选到单位之前**挂上。
            //   ⚠️ `selector` 由宿主（`Editor/BattleScene.cs:42419`）在 `Begin()` 之前赋值 ⇒ 这里一定非空，
            //      但仍然判空（删掉宿主那一句时不至于 NPE）。
            if (selector != null) selector.PreviewTargets = PreviewTargetsFromDrag;
            // 🆕 2026-10-01（§三 第 26 条 · ⑥ 的接线那半）：**把补间钩子挂上** ——
            //   原来 `WFModuleTween.OnInvoke` 全仓没人赋值 ⇒ 138 个 `AnimFXModuleTween` 的请求**全落在
            //   `DroppedRequests` 里**（不静默，但也没人接）。判据与契约 → `Core/UnitTweenRuntime.cs`。
            // 🔴 **2026-10-13（A515）**：那两个解析口（`UnitTweenRuntime.HeroBySeat` / `SeatOf`）
            //   原来就挂在这一行附近 —— **已挪进 `Begin()`**（`HookUnitTweenResolvers()`）。
            //   原因：`BuildHud` 被上面那个 `_hudBuilt` 闩住 ⇒ 挂在这儿只对**第一次** `Begin()` 生效，
            //   而 `DetachStaticHooks()` 会把它们置 null ⇒ 重开一局 / 重连重建时那两个口是 null。
            //   它们要的只是「驱动知道视图」，与 HUD 结构无关 ⇒ 归到 `HookAnimFx*` 那一族。
            // ⚠️ `Install()` **留在这儿**：它装的两条不指着 driver（理由见 `ForEachStaticHook` 的 ③ 段）。
            UnitTweenRuntime.Install();

            // 🔴 **2026-10-22（用户口径「原版没有的设计不要」）**：中上那行「第 N 回合　你的回合」
            //    **已删** —— 它是我们自加的（原版 `BattleHud` 树里没有这个节点；判据 →
            //    `资料/普查产出_1022/W62_战斗非原版元素审计.md` C 表第 1 行）。原来这里建 `_turnLabel`，
            //    它的 `0.965 → 0.810` 那两次挪位也就一并没了（让位问题随节点一起消失）。

            // ---- 等待提示（原版 `WaitText`）----
            // 位置/尺寸照原版字段（锚 (0.5,1) + (7,−175.1)、1344×79.4），理由与两处「我们挑的」见 `WaitBanner.cs` 文件头。
            // 🔴 **2026-10-16（第四十二会话 · `T09` 块 6）：登记 uGUI 宿主（本件是那一波唯一有画面可验的）。**
            //   原版 `WaitText` @ `BackCanvas/Safe area BackCanvas`（**`Default` 层 / order 0 / 兄弟序 6/7 —— 最后一格**、
            //   `overrideSorting = false`）⇒ 忠实做法 = **直接挂根画布 + `HudCanvas.Add(rt, z)`**，
            //   ⛔ **不建 `Default` 子画布**（那会落进一个本仓无先例、且 Unity 内部键判不了的并列；
            //   裁定 → `资料/普查产出_1016并行/S6S9_卡体与残件_施工方案.md` §2·1 / §3·2）。
            //   ⚠️ 本件**不进 `SubCanvasRank`**（它没有自己的子画布）⇒ ⛔ 别改用 `EnsureRankedSubCanvas`。
            //   ⚠️ `HudCanvas.Ensure(cam)` 幂等（同 `Hud()` / `EnsureRankedSubCanvas` 那一族的前置）。
            //   ⚠️ 拿不到根画布（`cam` 为空？）⇒ 传 `null` ⇒ 本件**留在世界档**（本件的双模式契约就是
            //     「宿主为 null ⇒ 与改之前逐位相同」）—— 但那要**出声**，⛔ 不许静默半迁移。
            var waitHost = HudCanvas.Ensure(cam);            // 幂等

            // 🔴 **2026-10-19（W57 · 战斗线 `T09` 步骤 A1）：建 uGUI 事件系统**（`EventSystem` +
            //    `InputSystemUIInputModule`）。判据/坑位 → `Battle/BattleEventSystem.cs` 文件头 +
            //    `资料/普查产出_1019/W57_战斗线_T09迁移计划.md` §2 A1。
            //    · `Ensure()` **幂等**（同场景重复调用只建一只；场景里已有一只就收养它）。
            //    · ⚠️ `activeInputHandler = 1`（New-only）⇒ 模块**必须是** `InputSystemUIInputModule`
            //      （挂 `StandaloneInputModule` = 一个事件都收不到且不报错，判据 → `T09` §1·1）。
            //    · 放在这里：本句之前根 canvas 已经立好（`HudCanvas.Ensure`），之后的每一颗可点件
            //      （`BuildHudExtras` 里的进攻卡钮 = 第一批）都能直接吃它。
            BattleEventSystem.Ensure();
            _waitBanner = WaitBanner.Create(root, waitHost);
            if (waitHost == null)
                Debug.LogError("[Battle] uGUI 层建不起来（`cam` 为空？）⇒ 等待提示（原版 `WaitText`）"
                             + "**留在世界空间档**（非 16:9 下它的位置与「压暗盖住名牌一族」都不对，见 `T09` 块 6）");

            // 🔴 **2026-09-27：回放控制条的显隐改对了** —— 原版 `ReplayHud.Setup()` 只做一件事：
            //    `objHolder.SetActive(BattleManager.matchType == 0xA0)`（`0xA0 = 160 = MatchType.Replay`）。
            //    默认关：**那 4 颗钮在普通对局里【不该出现】**（原来一直摆着，是错的）。
            //    🔴 **2026-10-24（`W1` · 铁律 5 就地订正）**：本行原文「我们**从不进回放局**」**不成立** ——
            //    回放局里由 `PlayReplay` 打开（`Setup(true)`），见那里与 `ReplayBar.cs` 文件头。
            //    判据 → `资料/普查产出_0927/回放_界面真值.md` §B/§C 与 `ReplayBar.cs` 文件头。
            //    ⚠️ 我们原来那套「本局时间控制」（暂停/单步/重开）**挪到键盘**了，见 `Update` 里的按键段。

            // ---- 名牌：原版左上是对手、左下是自己 ----
            // ⚠️ **2026-09-13 更正：原来这两个位置是错的**。旧值（`EnemyInfo (157,108)` / `PlayerInfo (32,977)`）
            //    抄的是 `FrontCanvas/Alliance Panel` 底下**另一份** `EnemyInfo`/`PlayerInfo`（`activeInHierarchy=False`）
            //    的实例，**不是** `LeftArea` 下 HUD 那一份 —— 两份实例不是一个东西。错出来的后果：
            //    我方名牌**偏右 44 px、偏高 37 px**，敌方名牌**偏右 ~168 px**（截图一量就看得出来），
            //    而且我方那个高度正好让里程碑骷髅压住「生命 N」那行字。
            //
            // 🔴🆕 **2026-10-18（第十五轮 · `G5`）：`FrontCanvas/Alliance Panel` 那块【要不要建】本批核了 ——
            //   结论：要做，但**不是本地化**那一档，本笔只记判据（⛔ 没动手建整扇窗）。**
            //   · 它**不是「单机下永远不显示」**：`(inactive)` 只是**出厂默认**，真正控制它的是
            //     `BattleHud.AlliancePanelOpenButton`（`BattleHud__AlliancePanelOpenButton.c`）——
            //     HUD 上那颗钮点了就 `BattleAlliancePanel.Open(name, allianceName, avatar, …)`，
            //     里面 `GameObject.SetActive(true)` + `CanvasGroup` `DOFade` + `DOScale`（判据逐句读过）。
            //   · 它显示的是**对手的档案**：`BattleManager.matchData`（`+0x10` 名字 / `+0x50` 联盟名 /
            //     `+0x40`、`+0x48` 头像 id …）。**无联盟**那一支才是 `Battle/AlliancePanel/NotInAnAlliance`：
            //     节点 `NotInaAllianceText`（`bundle_scenes_scenes_battlearena1/MonoBehaviour_4475.json`，
            //     TMP 静态原文 = **`This player is is still not part of an Alliance`**，注意原版那个 `is is` 重复）；
            //     有联盟时走 `Alliance Name` / `Alliance Badge Drawer` / `Alliance Rating Display`。
            //   · ⇒ **我们单机的 bot 对手没有档案（没有头像/联盟）**，接上去就**恒走 `NotInAnAlliance` 那一支**
            //     ——那正是原版单机情境下的形态，所以**该建**；但整扇窗（815×475 · Background/BGFrame/
            //     EnemyInfo/Avatar Item Small/Alliance 一组/关闭钮）是**一件新的 UI 活**，
            //     ⛔ 不属本笔「本地化剩余」，已如实记进交件报告。
            //   · 面板的节点判据已就位：`资料/说明书/01_战斗_对战/2D层_battlearena1全树.md:756-779`
            //     （`Alliance Panel (inactive) [-107,1022 815x475]`，13 个战场同构）。
            // 正确的绝对 rect（出处：`资料/战斗规格/战斗重建_0827/子代理读报_back左区_0827.md:46,56,57,69`）：
            //   `NameBackground` 435.7×126.3、`PreserveAspect=1` → 实绘 382.3×126.3（**居中于 rect**）：
            //     我方 rect x[−38.1,397.6] y[951.4,1077.7] → 实绘左缘 −11.4、中心 y(从上) 1014.55
            //     敌方 rect x[−37.9,397.9] y[ 15.6, 141.9] → 实绘左缘 −11.2、中心 y(从上)   78.75
            //   ⇒ **两边都贴着屏幕左缘、还各自出血 11 px（原版就长这样）**，不是我们原来那样离左边 33/157 px。
            //   `PlayerNameText` 文本框 x[112.6,361.9] y[977.0,1021.9]、**H=居中**、fs 35 →
            //     文字中心 (237.25, 999.45)；`EnemyNameText` x[72,435.7] y[40.9,86.9]（左右 margin 43.26/70.58）
            //     → 有效文字中心 (240.19, 63.9)。所以文字**要按中心摆**，不是左对齐。
            var dim = new Color(0.86f, 0.88f, 0.93f);
            // 名牌尺寸：原版 `NameBackground` 的**屏幕框 = 348.56×101.04**（= 裸 `m_SizeDelta` 435.7×126.3
            // × 父 `EnemyName`/`PlayerName` 的 `m_LocalScale` **0.8**，见 `HudPlateScale`）。
            // 🔴 **2026-10-19（A1512 + A1254 同批）**：这里原来写 `435.7×126.3` —— 那是**裸 `m_SizeDelta`、
            //    整条父链的 0.8 一次都没乘** ⇒ **名牌大 25%**（`A1254`；`A1512` 是它的整条子树的版本）。
            //    真值出处 = `工具/menu_dump.py bundle_scenes_scenes_battlearena2 --rt 3042`：
            //      敌 `NameBackground` x[5.71999,354.28001] y[28.23257,129.27257] · 我 x[5.42019,353.98020] y[963.98515,1065.02516]
            // 贴图 `UI_Player_Frame` 是 442×146（比例 3.0274），框比例 348.56/101.04 = 3.45 > 3.0274
            // ⇒ PreserveAspect 按**高**受限 ⇒ **实绘 305.8882×101.04** → worldHeight = 101.04/108。
            // ⚠️ 中心**没变**（`m_AnchoredPosition = (0,0)` + 锚 (0.5,0.5) ⇒ 就在名牌中心）：敌 (180.0, 78.75) ·
            //    我 (179.70, 1014.5) —— 变的只是**尺寸**。`HudImage` 的锚是 `(0,0.5)` ⇒ 这里传的是**左缘**：
            //    敌 180 − 305.8882/2 = 27.0559 · 我 179.700195 − 152.9441 = 26.7561。
            _enemyPlate = HudImage(root, "UI_Player_Frame", 27.0559f / 1920f, 0.927083f,
                                   new Vector2(0f, 0.5f), 101.04f / 108f, "EnemyPlate");
            // 🔴 **2026-10-10（A1213①）**：框/四格 ← 原版 `LeftArea/EnemyInfo/EnemyName/EnemyNameText`
            //    （`RectTransform/RectTransform_3568.json`；框 290.94×36.84 是**解算后**的屏幕矩形
            //     —— 那颗的父 `EnemyName`（`RectTransform_3083.json`）自带 `m_LocalScale = 0.8`，
            //     见 `Hud` 的 doc 那张表）。
            // 🔴 **2026-10-19（A1512）：框早就乘过 0.8 了，可【中心】没有** —— 原来那个 `0.125099`
            //    = 240.19 px 是 **0827 报告里「没乘 0.8」的文本框中心**（x[72.0,435.7] 的 margin 修正值），
            //    它离名牌中心 60.19 px、真值只该离 **48.15**（×0.8）⇒ 文字整体**偏右 ~12 px**。
            //    真值（`menu_dump` 绝对框）：框 x[93.63085,384.56834] y[48.46395,85.30133]、框心 **(239.099595, 66.88264)**；
