            //    （截图放大才看出来：`x0` 在、骷髅没了）。见 `HudImageZ` 的注释。
            _skullIcon = HudImageTex(root, CardArt.Ui("40k_battle_Win_Skull"), SkullIconX01, SkullIconY01,
                                     new Vector2(0.5f, 0.5f), Px(SkullIconPx), "MatchSkullsIcon",
